local w0 = shr(a0, 28) + shl(a1, 4)
local x0 = shr(a1, 2) + shl(a0, 30)
local x1 = shr(a0, 2) + shl(a1, 30)
local y0 = shr(a1, 7) + shl(a0, 25)
local y1 = shr(a0, 7) + shl(a1, 25)
