local function initWithTiming()
mixHwSeed()
assert(os.epoch("utc") ~= 0)

local f = assert(load("local e=os.epoch return{" .. ("e'utc',"):rep(256) .. "}"))

do
local t = f()
while t[256] - t[1] > 1 do t = f() end
end


local buf = {}
for i = 1, 512 do
local t = f()
while t[256] == t[1] do t = f() end
for j = 1, 256 do
if t[j] ~= t[1] then
buf[i] = j - 1
break
end
end
end


local hist = {}
for i = 0, 255 do hist[i] = 0 end
for i = 1, #buf do hist[buf[i]] = hist[buf[i]] + 1 end
for i = 0, 255 do assert(hist[i] < 20) end

init(string.char(table.unpack(buf)))
end





local function initAuto()
mixHwSeed()
if not hwMixed then initWithTiming() end
initialized = true
end



local function mix(data)
expect(1, data, "string")
mixHwSeed()
state = blake3.digestKeyed(state, data)
end




local function random(len)
len = math.max(0, expect(1, len, "number"))
lassert(initialized, "attempt to use an uninitialized random generator", 2)
local ok, out = hw.random(len)
if ok then return out end

mixHwSeed()
local msg = ("\0"):rep(len + 32)
local nonce = ("\0"):rep(12)
local out = chacha20.crypt(state, nonce, msg, 8, 0)
state = out:sub(1, 32)
return out:sub(33)
end

return {
init = init,
isInit = isInit,
initWithTiming = initWithTiming,
initAuto = initAuto,
mix = mix,
random = random,
}
]=],
["ccryptolib/sha256.lua"] = [[


local expect = require "cc.expect".expect
local lassert = require "ccryptolib.internal.util".lassert
local packing = require "ccryptolib.internal.packing"
local hw = require "ccryptolib.internal.hw"

local rol = bit32.lrotate
local shr = bit32.rshift
local bxor = bit32.bxor
local bnot = bit32.bnot
local band = bit32.band
local unpack = unpack or table.unpack
local p1x8, fmt1x8 = packing.compilePack(">I8")
local p16x4, fmt16x4 = packing.compilePack(">I4I4I4I4I4I4I4I4I4I4I4I4I4I4I4I4")
local u16x4 = packing.compileUnpack(fmt16x4)
local p8x4, fmt8x4 = packing.compilePack(">I4I4I4I4I4I4I4I4")
local u8x4 = packing.compileUnpack(fmt8x4)

local function primes(n, exp)
local out = {}
local p = 2
for i = 1, n do
out[i] = bxor(p ^ exp % 1 * 2 ^ 32)
repeat p = p + 1 until 2 ^ p % p == 2
end
return out
end

local K = primes(64, 1 / 3)

local h0 = primes(8, 1 / 2)

local function compress(h, w)
local h0, h1, h2, h3, h4, h5, h6, h7 = unpack(h)
local K = K


for j = 17, 64 do
local wf = w[j - 15]
local w2 = w[j - 2]
local s0 = bxor(rol(wf, 25), rol(wf, 14), shr(wf, 3))
local s1 = bxor(rol(w2, 15), rol(w2, 13), shr(w2, 10))
w[j] = w[j - 16] + s0 + w[j - 7] + s1
end


local a, b, c, d, e, f, g, h = h0, h1, h2, h3, h4, h5, h6, h7
for j = 1, 64 do
local s1 = bxor(rol(e, 26), rol(e, 21), rol(e, 7))
local ch = bxor(band(e, f), band(bnot(e), g))
local temp1 = h + s1 + ch + K[j] + w[j]
local s0 = bxor(rol(a, 30), rol(a, 19), rol(a, 10))
local maj = bxor(band(a, b), band(a, c), band(b, c))
local temp2 = s0 + maj

h = g
g = f
f = e
e = d + temp1
d = c
c = b
b = a
a = temp1 + temp2
end

return {
(h0 + a) % 2 ^ 32,
(h1 + b) % 2 ^ 32,
(h2 + c) % 2 ^ 32,
(h3 + d) % 2 ^ 32,
(h4 + e) % 2 ^ 32,
(h5 + f) % 2 ^ 32,
(h6 + g) % 2 ^ 32,
(h7 + h) % 2 ^ 32,
}
end




local function digest(data)
expect(1, data, "string")
local ok, out = hw.sha256(data)
if ok then return out end


local bitlen = #data * 8
local padlen = -(#data + 9) % 64
data = data .. "\x80" .. ("\0"):rep(padlen) .. p1x8(fmt1x8, bitlen)


local h = h0
for i = 1, #data, 64 do
h = compress(h, {u16x4(fmt16x4, data, i)})
end

return p8x4(fmt8x4, unpack(h))
end


local PBKDF2_CB_ITERATIONS = 50







local function pbkdf2(password, salt, iter, progress)
expect(1, password, "string")
expect(2, salt, "string")
expect(3, iter, "number")
lassert(iter % 1 == 0, "iteration number must be an integer", 2)
lassert(iter > 0, "iteration number must be positive", 2)
expect(4, progress, "function", "nil")


if #password > 64 then password = digest(password) end
password = {u16x4(fmt16x4, password .. ("\0"):rep(64), 1)}


local ikp = {}
local okp = {}
for i = 1, 16 do
ikp[i] = bxor(password[i], 0x36363636)
okp[i] = bxor(password[i], 0x5c5c5c5c)
end

local hikp = compress(h0, ikp)
local hokp = compress(h0, okp)


local pad96 = {2 ^ 31, 0, 0, 0, 0, 0, 0, 0x300}


local pre = p16x4(fmt16x4, unpack(ikp))
local hs = {u8x4(fmt8x4, digest(pre .. salt .. "\0\0\0\1"), 1)}
for i = 1, 8 do hs[i + 8] = pad96[i] end
hs = compress(hokp, hs)


local out = {unpack(hs)}
for i = 2, iter do
for j = 1, 8 do hs[j + 8] = pad96[j] end
hs = compress(hikp, hs)
for j = 1, 8 do hs[j + 8] = pad96[j] end
hs = compress(hokp, hs)
for j = 1, 8 do out[j] = bxor(out[j], hs[j]) end
if progress and i % PBKDF2_CB_ITERATIONS == 0 then progress(i) end
end

return p8x4(fmt8x4, unpack(out))
end

return {
digest = digest,
pbkdf2 = pbkdf2,
}
]],
["ccryptolib/util.lua"] = [[


local expect = require "cc.expect".expect
local random = require "ccryptolib.random"
local poly1305 = require "ccryptolib.poly1305"




local function toHex(str)
expect(1, str, "string")
return ("%02x"):rep(#str):format(str:byte(1, -1))
end




local function fromHex(hex)
expect(1, hex, "string")
local out = {}
local n = 0
for c in hex:gmatch("%x%x") do
n = n + 1
out[n] = tonumber(c, 16)
end
if 2 * n == #hex then return string.char(table.unpack(out)) end
end





local function compare(a, b)
expect(1, a, "string")
expect(2, b, "string")
if #a ~= #b then return false end
local kaux = random.random(32)
return poly1305.mac(kaux, a) == poly1305.mac(kaux, b)
end

return {
toHex = toHex,
fromHex = fromHex,
compare = compare,
}
]],
["ccryptolib/x25519.lua"] = [[


local expect = require "cc.expect".expect
local lassert = require "ccryptolib.internal.util".lassert
local hw = require "ccryptolib.internal.hw"
local util = require "ccryptolib.internal.util"
local c25 = require "ccryptolib.internal.curve25519"




local function publicKey(sk)
expect(1, sk, "string")
assert(#sk == 32, "secret key length must be 32")
local ok, out = hw.x25519PublicKey(sk)
if ok then return out end
return c25.encode(c25.scale(c25.mulG(util.bits(sk))))
end





local function exchange(sk, pk)
expect(1, sk, "string")
lassert(#sk == 32, "secret key length must be 32", 2)
expect(2, pk, "string")
lassert(#pk == 32, "public key length must be 32", 2)
local ok, out = hw.x25519Exchange(sk, pk)
if ok then return out end
return c25.encode(c25.scale(c25.ladder8(c25.decode(pk), util.bits8(sk))))
end

return {
publicKey = publicKey,
exchange = exchange,
}
]],
["ccryptolib/x25519c.lua"] = [[
local expect = require "cc.expect".expect
local lassert = require "ccryptolib.internal.util".lassert
local hw = require "ccryptolib.internal.hw"
local fq = require "ccryptolib.internal.fq"
local fp = require "ccryptolib.internal.fp"
local c25 = require "ccryptolib.internal.curve25519"
local sha512 = require "ccryptolib.internal.sha512"
local random = require "ccryptolib.random"




local function mask(sk)
expect(1, sk, "string")
lassert(#sk == 32, "secret key length must be 32", 2)
local mask = random.random(32)
local x = fq.decodeClamped(sk)
local r = fq.decodeClamped(mask)
local xr = fq.sub(x, r)
return fq.encode(xr) .. mask
end




local function maskS(sk)
expect(1, sk, "string")
lassert(#sk == 32, "secret key length must be 32", 2)
return mask(sha512.digest(sk):sub(1, 32))
end




local function remask(msk)
expect(1, msk, "string")
lassert(#msk == 64, "masked secret key length must be 64", 2)
local newMask = random.random(32)
local xr = fq.decode(msk:sub(1, 32))
local r = fq.decodeClamped(msk:sub(33))
local s = fq.decodeClamped(newMask)
local xs = fq.add(xr, fq.sub(r, s))
return fq.encode(xs) .. newMask
end







local function ephemeralSk(msk)
expect(1, msk, "string")
lassert(#msk == 64, "masked secret key length must be 64", 2)
return msk:sub(33)
end




local function hwExchangeOnPoint(sk, P)
local ok1, rP = hw.x25519Exchange(sk:sub(33), P)
if not ok1 then return end

local xr = fq.decode(sk:sub(1, 32))
local r = fq.decodeClamped(sk:sub(33))
local x = fq.add(xr, r)

local ok2, xP = hw.x25519Exchange(fq.encodeClamped(x), P)
if not ok2 then return end

return true, xP, rP
end

local function exchangeOnPoint(sk, P)
local xr = fq.decode(sk:sub(1, 32))
local r = fq.decodeClamped(sk:sub(33))
local rP, xrP, dP = c25.prac(P, fq.makeRuleset(fq.eighth(r), fq.eighth(xr)))


if not rP then
local out = fp.encode(fp.num(0))
return out, out
end

local xP = c25.dadd(dP, rP, xrP)


local Px, Pz = P[1], P[2]
local xPx, xPz = xP[1], xP[2]
local rPx, rPz = rP[1], rP[2]


Px, Pz = fp.mul(Px, Pz), fp.square(Pz)
xPx, xPz = fp.mul(xPx, xPz), fp.square(xPz)
rPx, rPz = fp.mul(rPx, rPz), fp.square(rPz)









local Px2 = fp.square(Px)
local Pz2 = fp.square(Pz)
local Pxz = fp.mul(Px, Pz)
local APxz = fp.kmul(Pxz, 486662)
local rhs = fp.mul(Px, fp.add(Px2, fp.carry(fp.add(APxz, Pz2))))







local root = fp.sqrtDiv(fp.num(1), fp.mul(fp.mul(xPz, rPz), rhs))
if not root then
local out = fp.encode(fp.num(0))
return out, out
end


local xPzrPzInv = fp.mul(fp.square(root), rhs)
local xPzInv = fp.mul(xPzrPzInv, rPz)
local rPzInv = fp.mul(xPzrPzInv, xPz)


return fp.encode(fp.mul(xPx, xPzInv)), fp.encode(fp.mul(rPx, rPzInv))
end

local G_ENC = fp.encode(fp.num(9))



local function publicKey(msk)
expect(1, msk, "string")
lassert(#msk == 64, "masked secret key length must be 64", 2)
local ok, xP, rP = hwExchangeOnPoint(msk, G_ENC)
if ok then return xP, rP end
return (exchangeOnPoint(msk, c25.G))
end














local function exchange(sk, pk)
expect(1, sk, "string")
lassert(#sk == 64, "masked secret key length must be 64", 2)
expect(2, pk, "string")
lassert(#pk == 32, "public key length must be 32", 2)
local ok, xP, rP = hwExchangeOnPoint(sk, pk)
if ok then return xP, rP end
return exchangeOnPoint(sk, c25.decode(pk))
end

return {
mask = mask,
remask = remask,
publicKey = publicKey,
ephemeralSk = ephemeralSk,
exchange = exchange,
}
]],
["cryptobench.lua"] = [[





local ITERATIONS = 5

local YIELD_BUDGET_MS = 7000

local ok, random = pcall(require, "ccryptolib.random")
if not ok then
printError("ccryptolib not found")
print("copy the 'ccryptolib' folder to this computer's root, so that")
print("/ccryptolib/x25519.lua exists")
return
end
local x25519 = require("ccryptolib.x25519")

local function ms()
return os.epoch("utc")
end

local function report(label, elapsed, note)
local pct = elapsed / YIELD_BUDGET_MS * 100
print(("%-22s %6dms  %5.1f%%%s"):format(label, elapsed, pct, note or ""))
end

print("acknet crypto bench")
print(("yield budget assumed ~%dms"):format(YIELD_BUDGET_MS))
print()



if random.isInit() then
print("generator already initialised this boot")
else
local t = ms()

random.initWithTiming()
report("initWithTiming", ms() - t, "  (collects 512ms by design)")
end


local t = ms()
local sk = random.random(32)
report("random(32)", ms() - t)


t = ms()
local pk = x25519.publicKey(sk)
report("publicKey", ms() - t)


local peerSk = random.random(32)
local peerPk = x25519.publicKey(peerSk)

local total, worst = 0, 0
for _ = 1, ITERATIONS do
t = ms()
x25519.exchange(sk, peerPk)
local e = ms() - t
total = total + e
if e > worst then worst = e end
end
report("exchange (avg)", math.floor(total / ITERATIONS))
report("exchange (worst)", worst)


local a = x25519.exchange(sk, peerPk)
local b = x25519.exchange(peerSk, pk)
print()
if a == b then
print("shared secrets agree -- exchange is correct")
else
printError("MISMATCH -- exchange is wrong, timings are meaningless")
return
end

print()
if worst > YIELD_BUDGET_MS * 0.5 then
printError("too close to the yield limit; a handshake does several of these")
elseif worst > 500 then
print("workable, but a multi-exchange handshake will be noticeably slow")
else
print("comfortable -- go ahead with M1.1")
print("(this fast almost certainly means hardware acceleration is active)")
end
]],
["handshake.lua"] = [[


















local random = require("ccryptolib.random")
local x25519 = require("ccryptolib.x25519")
local blake3 = require("ccryptolib.blake3")
local aead = require("ccryptolib.aead")

local handshake = {}



local PROTOCOL_NAME = "acknet handshake XK 25519 ChaChaPoly BLAKE3 v1"

local TAG = 16
local KEY = 32



local function nonce(n)
local b = {}
for i = 1, 8 do
b[i] = string.char(n % 256)
n = math.floor(n / 256)
end
return ("\0"):rep(4) .. table.concat(b)
end


local function kdf2(ck, ikm)
local temp = blake3.digestKeyed(ck, ikm)
local o1 = blake3.digestKeyed(temp, "\1")
local o2 = blake3.digestKeyed(temp, o1 .. "\2")
return o1, o2
end




local function mixHash(st, data)
st.h = blake3.digest(st.h .. data)
end

local function mixKey(st, ikm)
st.ck, st.k = kdf2(st.ck, ikm)
st.n = 0
end

local function encryptAndHash(st, plaintext)
local out
if st.k then
local ct, tag = aead.encrypt(st.k, nonce(st.n), plaintext, st.h)
st.n = st.n + 1
out = ct .. tag
else
out = plaintext
end
mixHash(st, out)
return out
end

local function decryptAndHash(st, data)
local pt
if st.k then
if #data < TAG then return nil end
local ct = data:sub(1, #data - TAG)
local tag = data:sub(#data - TAG + 1)
pt = aead.decrypt(st.k, nonce(st.n), tag, ct, st.h)
if not pt then return nil end
st.n = st.n + 1
else
pt = data
end
mixHash(st, data)
return pt
end

local function newEphemeral()
local sk = random.random(32)
return {sk = sk, pk = x25519.publicKey(sk)}
end

local function newState(responderStaticPk)
local st = {
h = blake3.digest(PROTOCOL_NAME),
k = nil,
n = 0,
}
st.ck = st.h


mixHash(st, responderStaticPk)
return st
end



local function split(st)
local k1, k2 = kdf2(st.ck, "")
return k1, k2
end




function handshake.startInitiator(serverStaticPk, payload)
local st = newState(serverStaticPk)
st.rs = serverStaticPk
st.e = newEphemeral()

mixHash(st, st.e.pk)
mixKey(st, x25519.exchange(st.e.sk, serverStaticPk))

local body = encryptAndHash(st, payload or "")
return st, st.e.pk .. body
end


function handshake.initiatorReadMsg2(st, msg2)
if #msg2 < KEY then return nil end
st.re = msg2:sub(1, KEY)

mixHash(st, st.re)
mixKey(st, x25519.exchange(st.e.sk, st.re))

return decryptAndHash(st, msg2:sub(KEY + 1))
end


function handshake.initiatorFinish(st, ourStaticPk, staticExchange, payload)
local encStatic = encryptAndHash(st, ourStaticPk)
mixKey(st, staticExchange(st.re))

local body = encryptAndHash(st, payload or "")
local k1, k2 = split(st)
return encStatic .. body, k1, k2
end



function handshake.startResponder(ourStaticPk)
local st = newState(ourStaticPk)
return st
end


function handshake.responderReadMsg1(st, msg1, staticExchange)
if #msg1 < KEY then return nil end
st.re = msg1:sub(1, KEY)

mixHash(st, st.re)
mixKey(st, staticExchange(st.re))

return decryptAndHash(st, msg1:sub(KEY + 1))
end


function handshake.responderWriteMsg2(st, payload)
st.e = newEphemeral()

mixHash(st, st.e.pk)
mixKey(st, x25519.exchange(st.e.sk, st.re))

local body = encryptAndHash(st, payload or "")
return st.e.pk .. body
end


function handshake.responderReadMsg3(st, msg3)
local encLen = KEY + TAG
if #msg3 < encLen then return nil, "message 3 too short" end

local peerStatic = decryptAndHash(st, msg3:sub(1, encLen))
if not peerStatic or #peerStatic ~= KEY then
return nil, "static key failed authentication"
end

mixKey(st, x25519.exchange(st.e.sk, peerStatic))

local payload = decryptAndHash(st, msg3:sub(encLen + 1))
if not payload then return nil, "payload failed authentication" end

local k1, k2 = split(st)

return peerStatic, payload, k2, k1
end











local LINK_CONTEXT = "acknet hopnet link secret v1"

function handshake.linkSecret(k1, k2)
return blake3.deriveKey(LINK_CONTEXT)(k1 .. k2, 32)
end





function handshake.seal(key, counter, plaintext)
local ct, tag = aead.encrypt(key, nonce(counter), plaintext, "")
return ct .. tag
end

function handshake.open(key, counter, data)
if #data < TAG then return nil end
local ct = data:sub(1, #data - TAG)
local tag = data:sub(#data - TAG + 1)
return aead.decrypt(key, nonce(counter), tag, ct, "")
end

return handshake
]],
["hopnet.lua"] = [[




















local blake3 = require("ccryptolib.blake3")
local band = require("band")

local hopnet = {}

hopnet.messageEvent = "hopnet_message"

local BROADCAST_CHANNEL = 65535


local CHANNEL_SPACE = 65533

local HOP_INTERVAL = 15
local CHANNEL_CONTEXT = "acknet hopnet channel v1"

local modems = {}
local running = false
local keyProvider = nil
local hopChannels = {}









local bands = {}
local defaultBand = nil





function hopnet.setKeyProvider(fn)
keyProvider = fn
end




function hopnet.setBands(map, fallback)
bands = map or {}
defaultBand = fallback
end

function hopnet.bandFor(modem)
return (modem and bands[modem]) or defaultBand
end





local linkCache = nil

local function links()
if linkCache then return linkCache end
if not keyProvider then return {} end

local ok, map = pcall(keyProvider)
if ok and type(map) == "table" then
linkCache = map
return map
end

return {}
end



local function u64le(n)
local b = {}
for i = 1, 8 do
b[i] = string.char(n % 256)
n = math.floor(n / 256)
end
return table.concat(b)
end

local function slotNow()
return math.floor(os.epoch("utc") / (HOP_INTERVAL * 1000))
end

local function msToNextSlot()
local period = HOP_INTERVAL * 1000
return period - (os.epoch("utc") % period)
end







local function channelForSlot(secret, slot, within)
local out = blake3.deriveKey(CHANNEL_CONTEXT)(secret .. u64le(slot), 4)
local n = ((out:byte(1) * 256 + out:byte(2)) * 256 + out:byte(3)) * 256
+ out:byte(4)





if not within then return n % CHANNEL_SPACE end

return within.base + (n % within.size)
end

hopnet.slotNow = slotNow



function hopnet.init()
modems = {}
for _, name in ipairs(peripheral.getNames()) do
if peripheral.getType(name) == "modem" then
modems[#modems + 1] = name


peripheral.call(name, "open", os.getComputerID())
peripheral.call(name, "open", BROADCAST_CHANNEL)
end
end
return #modems > 0
end

function hopnet.isOpen()
for _, name in ipairs(modems) do
if peripheral.call(name, "isOpen", os.getComputerID()) then return true end
end
return false
end

function hopnet.open()
return hopnet.init()
end

function hopnet.close()
for _, name in ipairs(modems) do
peripheral.call(name, "closeAll")
end
end

function hopnet.modems()
return modems
end



function hopnet.localAddress()
return os.getComputerID()
end













local fixedProtocols = {
["acknet_hs"] = true,
["acknet_peer"] = true,
["acknet_dns"] = true,
}

function hopnet.setFixedProtocols(set)
fixedProtocols = set
end




function hopnet.channelFor(peerId, protocol, modem)
if protocol and fixedProtocols[protocol] then return peerId end

local secret = links()[peerId]


if not secret then return peerId end
return channelForSlot(secret, slotNow(), hopnet.bandFor(modem))
end














local function activeBands()
local seen, out = {}, {}
local function add(b)
if not b then return end
local key = b.base .. ":" .. b.size
if not seen[key] then
seen[key] = true
out[#out + 1] = b
end
end
for _, b in pairs(bands) do add(b) end
add(defaultBand)


if #out == 0 then out[1] = false end
return out
end

local function refreshWindow()
local slot = slotNow()
local wanted = {}
local listening = activeBands()

for peerId, secret in pairs(links()) do
for _, within in ipairs(listening) do
for offset = -1, 1 do
local channel = channelForSlot(secret, slot + offset, within or nil)

if channel ~= os.getComputerID() and channel ~= BROADCAST_CHANNEL then
wanted[channel] = true
end
end
end
end

for channel in pairs(wanted) do
if not hopChannels[channel] then
for _, name in ipairs(modems) do
peripheral.call(name, "open", channel)
end
hopChannels[channel] = true
end
end

for channel in pairs(hopChannels) do
if not wanted[channel] then
for _, name in ipairs(modems) do
peripheral.call(name, "close", channel)
end
hopChannels[channel] = nil
end
end
end






local function transmitAll(channel, frame, only)
local sent = false
for _, name in ipairs(modems) do
if not only or name == only then
peripheral.call(name, "transmit", channel, os.getComputerID(), frame)
sent = true
end
end
return sent
end

function hopnet.send(peerId, message, protocol, modem)


if peerId == os.getComputerID() then
os.queueEvent(hopnet.messageEvent, peerId, message, protocol)
return true
end




return transmitAll(hopnet.channelFor(peerId, protocol, modem), {
src = os.getComputerID(),
dst = peerId,
protocol = protocol,
body = message,
}, modem)
end

function hopnet.broadcast(message, protocol)

return transmitAll(BROADCAST_CHANNEL, {
src = os.getComputerID(),
bcast = true,
protocol = protocol,
body = message,
})
end



local function daemonLoop()
refreshWindow()
local slotTimer = os.startTimer(msToNextSlot() / 1000 + 0.05)



while true do
local event, p1, p2, p3, p4 = os.pullEvent()

if event == "modem_message" then
local frame = p4



if type(frame) == "table" and type(frame.src) == "number" then
local mine = frame.bcast == true or frame.dst == os.getComputerID()
if mine and frame.src ~= os.getComputerID() then



os.queueEvent(hopnet.messageEvent,
frame.src, frame.body, frame.protocol, p1)
end
end

elseif event == "timer" and p1 == slotTimer then
refreshWindow()
slotTimer = os.startTimer(msToNextSlot() / 1000 + 0.05)




elseif event == "net_link_changed" then
linkCache = nil
refreshWindow()




elseif event == "hopnet_status" then
local channels, count = {}, 0
for channel in pairs(hopChannels) do channels[#channels + 1] = channel end
table.sort(channels)
for _ in pairs(links()) do count = count + 1 end
os.queueEvent("hopnet_status_reply", slotNow(), count, channels,
defaultBand and defaultBand.base or nil,
defaultBand and defaultBand.size or nil)
end
end
end

function hopnet.runtime()
if running then
error("hopnet: daemon already running", 0)
end
running = true

local ok, err = pcall(daemonLoop)

running = false
if not ok then error(err, 0) end
end

function hopnet.isRunning()
return running == true
end



function hopnet.shutdown()
running = false
linkCache = nil
bands = {}
defaultBand = nil
hopChannels = {}
hopnet.close()
end

return hopnet
]],
["hopstat.lua"] = [[






local netkeys = require("netkeys")

local BROADCAST_CHANNEL = 65535
local HOP_INTERVAL = 15

local id = os.getComputerID()
local substrate = netkeys.substrate()

print(("computer %d   substrate: %s"):format(id, substrate))

for _, name in ipairs(peripheral.getNames()) do
if peripheral.getType(name) == "modem" then
local wireless = peripheral.call(name, "isWireless")
local own = peripheral.call(name, "isOpen", id)
local bcast = peripheral.call(name, "isOpen", BROADCAST_CHANNEL)
print(("%s (%s)  fallback %s  broadcast %s"):format(
name, wireless and "wireless" or "wired",
own and "open" or "CLOSED", bcast and "open" or "CLOSED"))
end
end

if substrate ~= "hopnet" then
print()
print("not hopping -- every link uses channel = computer id")
return
end

print()
os.queueEvent("hopnet_status")

local timer = os.startTimer(2)
while true do
local event, p1, p2, p3, p4, p5 = os.pullEvent()

if event == "hopnet_status_reply" then
local slot, linkCount, channels, bandBase, bandSize = p1, p2, p3, p4, p5



print(("slot %d   %d link(s)   %d hop channel(s)"):format(
slot, linkCount, #channels))





if bandBase then
print(("band %d..%d (%d wide)"):format(
bandBase, bandBase + bandSize - 1, bandSize))
else
print("band: unbounded (whole channel space)")
end
print(("next hop in %.1fs"):format(
(HOP_INTERVAL * 1000 - os.epoch("utc") % (HOP_INTERVAL * 1000)) / 1000))

if #channels > 0 then
print()

print("listening on: " .. table.concat(channels, " "))
elseif linkCount == 0 then
print()
print("no links yet -- nothing has a shared schedule to hop on")
end
return

elseif event == "timer" and p1 == timer then
printError("no reply from the hopnet daemon -- is netstart running?")
return
end
end
