["icmp.lua"] = [[
























local ipnet = require("ipnet")
local ip = require("ip")

local icmp = {}

icmp.PROTOCOL = "icmp"

icmp.ECHO_REQUEST = "echo_request"
icmp.ECHO_REPLY = "echo_reply"



icmp.MAX_PAYLOAD = 64





icmp.MAX_REPLIES_PER_WINDOW = 20
icmp.WINDOW_MS = 1000

local running = false
local replies = {}

local function allowed(source)
local now = os.epoch("utc")
local bucket = replies[source]

if not bucket or now - bucket.windowStart > icmp.WINDOW_MS then
replies[source] = {count = 1, windowStart = now}
return true
end

if bucket.count >= icmp.MAX_REPLIES_PER_WINDOW then
return false
end
bucket.count = bucket.count + 1
return true
end

icmp.allowed = allowed

local function truncate(payload)
if type(payload) ~= "string" then return "" end
if #payload > icmp.MAX_PAYLOAD then
return payload:sub(1, icmp.MAX_PAYLOAD)
end
return payload
end













icmp.REQUEST_EVENT = "icmp_send"
icmp.REPLY_EVENT = "icmp_reply"





function icmp.request(target, id, seq, payload)
local address = target
if type(target) == "string" then
address = ip.parse(target)
if not address then return false, "not an address: " .. target end
end

os.queueEvent(icmp.REQUEST_EVENT, address, id, seq, truncate(payload))
return true
end



local function transmit(address, id, seq, payload)
return ipnet.send(address, {
icmp = icmp.ECHO_REQUEST,
id = id,
seq = seq,
payload = truncate(payload),
sent = os.epoch("utc"),
}, icmp.PROTOCOL)
end








function icmp.runtime()
if running then error("icmp: daemon already running", 0) end
running = true

local ok, err = pcall(function()
while true do
local event, a, b, c, d = os.pullEvent()

if event == ipnet.messageEvent then

local source, message, protocol = a, b, c
if protocol == icmp.PROTOCOL and type(message) == "table" then
if message.icmp == icmp.ECHO_REQUEST then
if allowed(source) then




ipnet.send(source, {
icmp = icmp.ECHO_REPLY,
id = message.id,
seq = message.seq,
payload = truncate(message.payload),
sent = message.sent,
}, icmp.PROTOCOL)
end
elseif message.icmp == icmp.ECHO_REPLY then

os.queueEvent(icmp.REPLY_EVENT, source,
message.id, message.seq, message.payload)
end
end

elseif event == icmp.REQUEST_EVENT then
transmit(a, b, c, d)
end
end
end)

running = false
if not ok then error(err, 0) end
end

function icmp.isRunning()
return running
end

function icmp.shutdown()
running = false
replies = {}
end









function icmp.ping(target, opts)
opts = opts or {}
local timeout = opts.timeout or 2
local id = opts.id or os.getComputerID()
local seq = opts.seq or 1

local address = target
if type(target) == "string" then
address = ip.parse(target)
if not address then return nil, "not an address: " .. tostring(target) end
end

local startedAt = os.epoch("utc")
local sent, sendErr = icmp.request(address, id, seq, opts.payload or "")
if not sent then return nil, tostring(sendErr) end

local deadline = os.startTimer(timeout)
while true do
local event, a, b, c, d = os.pullEvent()

if event == icmp.REPLY_EVENT and b == id and c == seq then
os.cancelTimer(deadline)
return (os.epoch("utc") - startedAt) / 1000,
{id = b, seq = c, payload = d, src = a}

elseif event == "timer" and a == deadline then



return nil, "timed out"
end
end
end







function icmp.reachable(target, opts)
opts = opts or {}
local attempts = opts.attempts or 2

for seq = 1, attempts do
local rtt = icmp.ping(target, {
timeout = opts.timeout or 2,
seq = seq,
id = opts.id,
})
if rtt then return true, rtt end
end
return false
end

return icmp
]],
["ip.lua"] = [[









local ip = {}

local OCTET = 256
local SPACE = 4294967296





local LINK_LOCAL = 169 * 16777216 + 254 * 65536
local LINK_LOCAL_HOSTS = 65536

ip.BROADCAST = SPACE - 1
ip.ANY = 0
ip.SPACE = SPACE




function ip.parse(text)
if type(text) ~= "string" then return nil end

local a, b, c, d = text:match("^%s*(%d+)%.(%d+)%.(%d+)%.(%d+)%s*$")
if not a then return nil end

a, b, c, d = tonumber(a), tonumber(b), tonumber(c), tonumber(d)
if a > 255 or b > 255 or c > 255 or d > 255 then return nil end

return ((a * OCTET + b) * OCTET + c) * OCTET + d
end

function ip.format(addr)
if type(addr) ~= "number" or addr < 0 or addr >= SPACE then
return "?" .. tostring(addr)
end

local n = math.floor(addr)
local d = n % OCTET; n = math.floor(n / OCTET)
local c = n % OCTET; n = math.floor(n / OCTET)
local b = n % OCTET; n = math.floor(n / OCTET)
return ("%d.%d.%d.%d"):format(n, b, c, d)
end





function ip.parseCidr(text)
if type(text) ~= "string" then return nil, "expected a string" end

local addr, prefix = text:match("^%s*([%d%.]+)%s*/%s*(%d+)%s*$")
if not addr then
return nil, ("'%s' is not <address>/<prefix>"):format(text)
end

local n = ip.parse(addr)
if not n then return nil, ("'%s' is not a dotted quad"):format(addr) end

prefix = tonumber(prefix)
if prefix < 0 or prefix > 32 then return nil, "prefix must be 0-32" end

return n, prefix
end

function ip.formatCidr(addr, prefix)
return ("%s/%d"):format(ip.format(addr), prefix)
end



local function hostSpan(prefix)
return 2 ^ (32 - prefix)
end


function ip.network(addr, prefix)
local span = hostSpan(prefix)
return addr - (addr % span)
end

function ip.contains(network, prefix, addr)
if type(addr) ~= "number" then return false end
return ip.network(addr, prefix) == ip.network(network, prefix)
end




function ip.within(inner, innerPrefix, outer, outerPrefix)
if type(innerPrefix) ~= "number" or type(outerPrefix) ~= "number" then
return false
end
if innerPrefix < outerPrefix then return false end
return ip.network(inner, outerPrefix) == ip.network(outer, outerPrefix)
end



function ip.broadcastOf(network, prefix)
return ip.network(network, prefix) + hostSpan(prefix) - 1
end

function ip.hostCount(prefix)
return hostSpan(prefix)
end





function ip.linkLocal(computerId)
if type(computerId) ~= "number" or computerId < 0
or computerId >= LINK_LOCAL_HOSTS then
error(("ip.linkLocal: computer id %s does not fit in 169.254.0.0/16")
:format(tostring(computerId)), 2)
end
return LINK_LOCAL + computerId
end

function ip.isLinkLocal(addr)
return type(addr) == "number"
and addr >= LINK_LOCAL and addr < LINK_LOCAL + LINK_LOCAL_HOSTS
end



function ip.computerIdFor(addr)
if not ip.isLinkLocal(addr) then return nil end
return addr - LINK_LOCAL
end

return ip
]],
["ipnet.lua"] = [[




































local ip = require("ip")

local ipnet = {}

ipnet.messageEvent = "ipnet_message"

local VERSION = 4
local TTL_DEFAULT = 64



local ARP_PROTOCOL = "ipnet_arp"
local ARP_TTL = 120


local ARP_INTERVAL = 1

local config = _G.__ipnet
if not config then
config = {}
_G.__ipnet = config
end


config.interfaces = config.interfaces or {}

config.routes = config.routes or {}

local substrate = nil
local debug = false













local neighbours = {}
local asked = {}








local ingress = {}




local stats = {
delivered = 0, forwarded = 0, dropped = 0,
pending = 0, expired = 0, arp = 0,
}



local linkLocal = nil

local function ourLinkLocal()
if not linkLocal then linkLocal = ip.linkLocal(os.getComputerID()) end
return linkLocal
end

local function log(...)
if debug then os.queueEvent("ipnet_debug", ...) end
end

function ipnet.setDebug(enabled)
debug = enabled
end



function ipnet.setSubstrate(mod)
substrate = mod
end

function ipnet.substrate()
return substrate
end

function ipnet.init()
return substrate.init()
end

function ipnet.isOpen(modem)
return substrate.isOpen(modem)
end

function ipnet.open(modem)
return substrate.open(modem)
end

function ipnet.close(modem)
return substrate.close(modem)
end




function ipnet.setKeyProvider(fn)
if substrate.setKeyProvider then substrate.setKeyProvider(fn) end
end








function ipnet.setBands(map, fallback)
if substrate.setBands then substrate.setBands(map, fallback) end
end



function ipnet.applyBands()
local map, fallback = {}, config.band
for _, iface in ipairs(config.interfaces) do
if iface.band and iface.modem then map[iface.modem] = iface.band end
if iface.band and not iface.modem then fallback = iface.band end
end
ipnet.setBands(map, fallback)
end

function ipnet.band()
return config.band
end












function ipnet.setInterfaces(list)
config.interfaces = {}
config.gateway = nil
config.routes = {}
config.declared = #list > 0

for _, iface in ipairs(list) do
config.interfaces[#config.interfaces + 1] = {
modem = iface.modem,
address = iface.address,
prefix = iface.prefix,


band = iface.band,
}
end

ipnet.applyBands()
end








function ipnet.configure(address, prefix, gateway, assignedBand)
config.gateway = gateway






if assignedBand then
config.band = assignedBand
log("band", assignedBand.base, assignedBand.size)
end

if config.declared then
log("gateway only", gateway and ip.format(gateway))
ipnet.applyBands()
return
end

config.interfaces = {{modem = nil, address = address, prefix = prefix,
band = assignedBand}}
log("configured", ip.format(address), prefix, gateway and ip.format(gateway))
ipnet.applyBands()
end

function ipnet.setGateway(address)
config.gateway = address
end

function ipnet.setRoutes(routes)
config.routes = routes or {}
end

function ipnet.interfaces()
return config.interfaces
end

function ipnet.routes()
return config.routes
end

function ipnet.gateway()
return config.gateway
end




function ipnet.localAddress()
local first = config.interfaces[1]
return first and first.address or ourLinkLocal()
end

function ipnet.prefix()
local first = config.interfaces[1]
return first and first.prefix or nil
end


function ipnet.addresses()
local all = {}
for _, iface in ipairs(config.interfaces) do all[#all + 1] = iface.address end
all[#all + 1] = ourLinkLocal()
return all
end

local function isOurs(addr)
if addr == ip.BROADCAST then return true end
if addr == ourLinkLocal() then return true end
for _, iface in ipairs(config.interfaces) do
if addr == iface.address then return true end
end
return false
end

ipnet.isOurs = isOurs


local function ifaceFor(addr)
local best, bestPrefix = nil, -1
for _, iface in ipairs(config.interfaces) do
if iface.prefix > bestPrefix and ip.contains(iface.address, iface.prefix, addr) then
best, bestPrefix = iface, iface.prefix
end
end
return best
end







function ipnet.setForwarding(enabled)
config.forwarding = enabled and true or false
end

local function forwards()
if config.forwarding ~= nil then return config.forwarding end
return #config.interfaces > 1
end

function ipnet.forwarding()
return forwards()
end






local function remember(addr, id, modem)
local known = neighbours[addr]
neighbours[addr] = {id = id, modem = modem, at = os.epoch("utc")}




if not known or known.id ~= id then
log("learned", ip.format(addr), id)
os.queueEvent("net_link_changed")
end
end

local function lookupNeighbour(addr)
local id = ip.computerIdFor(addr)
if id then return id, nil end

local hit = neighbours[addr]
if hit and os.epoch("utc") - hit.at < ARP_TTL * 1000 then
return hit.id, hit.modem
end
return nil
end





local function arpFrame(src, dst, kind, target)
return {
v = VERSION,
src = src,
dst = dst,
ttl = 1,
proto = ARP_PROTOCOL,
arp = kind,
target = target,
}
end



local function askFor(addr)
local now = os.epoch("utc")
if asked[addr] and now - asked[addr] < ARP_INTERVAL * 1000 then return end
asked[addr] = now

stats.arp = stats.arp + 1
log("arp who", ip.format(addr))

local iface = ifaceFor(addr)
local src = iface and iface.address or ipnet.localAddress()
substrate.broadcast(arpFrame(src, ip.BROADCAST, "who", addr), ARP_PROTOCOL)
end

function ipnet.neighbours()
return neighbours
end



function ipnet.ingressOf(addr)
return ingress[addr]
end





function ipnet.linkFor(addr)
local id = lookupNeighbour(addr)
return id
end












local function pathTo(dst)


local id = ip.computerIdFor(dst)
if id then return id, nil, ourLinkLocal() end

local direct = ifaceFor(dst)
if direct then
local hop, modem = lookupNeighbour(dst)
if not hop then
askFor(dst)
return nil, "no neighbour for " .. ip.format(dst) .. " yet", nil, true
end
return hop, modem or direct.modem, direct.address
end


local via, bestPrefix = nil, -1
for _, route in ipairs(config.routes) do
if route.prefix > bestPrefix and ip.contains(route.network, route.prefix, dst) then
via, bestPrefix = route.via, route.prefix
end
end
via = via or config.gateway
if not via then return nil, "no route to " .. ip.format(dst) end



local gwId = ip.computerIdFor(via)
if gwId then return gwId, nil, ourLinkLocal() end

local gwIface = ifaceFor(via)
if not gwIface then
return nil, ("next hop %s is not on any link"):format(ip.format(via))
end

local hop, modem = lookupNeighbour(via)
if not hop then
askFor(via)
return nil, "no neighbour for " .. ip.format(via) .. " yet", nil, true
end
return hop, modem or gwIface.modem, gwIface.address
end

ipnet.pathTo = pathTo



function ipnet.send(dst, message, protocol)
if type(dst) ~= "number" then
log("bad destination", tostring(dst))
return false
end




if isOurs(dst) then
os.queueEvent(ipnet.messageEvent, ipnet.localAddress(), message, protocol)
return true
end

local nextHop, modem, src, resolving = pathTo(dst)
if not nextHop then




if resolving then
stats.pending = stats.pending + 1
else
stats.dropped = stats.dropped + 1
end
log("no path", ip.format(dst), tostring(modem))
return false
end



return substrate.send(nextHop, {
v = VERSION,
src = src,
dst = dst,
ttl = TTL_DEFAULT,
proto = protocol,
body = message,
}, protocol, modem)
end




function ipnet.broadcast(message, protocol)
return substrate.broadcast({
v = VERSION,
src = ourLinkLocal(),
dst = ip.BROADCAST,
ttl = 1,
proto = protocol,
body = message,
}, protocol)
end



local function handleArp(frame, sender, modem)
if frame.arp == "who" then
if not isOurs(frame.target) then return end
log("arp is", ip.format(frame.target))




substrate.send(sender,
arpFrame(frame.target, frame.src, "is", frame.target),
ARP_PROTOCOL, modem)
end


end

local function forward(frame, protocol)
if not forwards() then
stats.dropped = stats.dropped + 1
log("not a router", ip.format(frame.dst))
return
end

local ttl = (tonumber(frame.ttl) or 0) - 1
if ttl <= 0 then
stats.expired = stats.expired + 1
log("ttl expired", ip.format(frame.src), ip.format(frame.dst))
return
end

local nextHop, modem, _, resolving = pathTo(frame.dst)
if not nextHop then
if resolving then
stats.pending = stats.pending + 1
else
stats.dropped = stats.dropped + 1
end
log("cannot forward", ip.format(frame.dst), tostring(modem))
return
end



stats.forwarded = stats.forwarded + 1
log("forward", ip.format(frame.dst), nextHop, ttl)

substrate.send(nextHop, {
v = VERSION,
src = frame.src,
dst = frame.dst,
ttl = ttl,
proto = frame.proto,
body = frame.body,
}, protocol, modem)
end

local function handleFrame(sender, frame, protocol, modem)



if type(frame) ~= "table" or frame.v ~= VERSION then return end
if type(frame.src) ~= "number" or type(frame.dst) ~= "number" then return end

ingress[frame.src] = modem





if not ip.isLinkLocal(frame.src) and ifaceFor(frame.src) then
remember(frame.src, sender, modem)
end

if frame.arp then
handleArp(frame, sender, modem)
return
end

if isOurs(frame.dst) then
stats.delivered = stats.delivered + 1
os.queueEvent(ipnet.messageEvent, frame.src, frame.body, frame.proto)
return
end

forward(frame, protocol)
end



local function daemonLoop()
while true do


local event, p1, p2, p3, p4 = os.pullEvent()

if event == substrate.messageEvent then
handleFrame(p1, p2, p3, p4)



elseif event == "ipnet_status" then
local seen = {}
for addr, entry in pairs(neighbours) do
seen[#seen + 1] = {address = addr, id = entry.id, modem = entry.modem}
end
os.queueEvent("ipnet_status_reply", {
linkLocal = ourLinkLocal(),
interfaces = config.interfaces,
routes = config.routes,
gateway = config.gateway,
forwarding = forwards(),
neighbours = seen,
stats = stats,
})
end
end
end

function ipnet.runtime()
if config.running then
error("ipnet: daemon already running", 0)
end
if not substrate then
error("ipnet: no substrate -- call setSubstrate before runtime", 0)
end
config.running = true

local ok, err = pcall(daemonLoop)

config.running = false
if not ok then error(err, 0) end
end

function ipnet.isRunning()
return config.running == true
end



function ipnet.shutdown()
config.running = false
neighbours = {}
asked = {}
ingress = {}
end

return ipnet
]],
["iproute.lua"] = [[







local ip = require("ip")

local TIMEOUT = 2

os.queueEvent("ipnet_status")
local timer = os.startTimer(TIMEOUT)

local function show(snapshot)
print("link-local " .. ip.format(snapshot.linkLocal))

local interfaces = snapshot.interfaces or {}
if #interfaces == 0 then
print("no address assigned yet")
end
for _, iface in ipairs(interfaces) do
print(("%-18s %s"):format(
ip.formatCidr(iface.address, iface.prefix),
iface.modem or "(all modems)"))
end

print(("gateway %s   forwarding %s"):format(
snapshot.gateway and ip.format(snapshot.gateway) or "none",
snapshot.forwarding and "ON" or "off"))

local routes = snapshot.routes or {}
if #routes > 0 then
print()
print("routes")
for _, route in ipairs(routes) do
print(("  %-18s via %s"):format(
ip.formatCidr(route.network, route.prefix), ip.format(route.via)))
end
end




local neighbours = snapshot.neighbours or {}
print()
if #neighbours == 0 then
print("no neighbours resolved")
else
print("neighbours")
table.sort(neighbours, function(a, b) return a.address < b.address end)
for _, entry in ipairs(neighbours) do
print(("  %-18s computer %-4d %s"):format(
ip.format(entry.address), entry.id, entry.modem or ""))
end
end

local stats = snapshot.stats or {}
print()



print(("delivered %d   forwarded %d   pending %d"):format(
stats.delivered or 0, stats.forwarded or 0, stats.pending or 0))
print(("dropped %d   ttl expired %d   arp sent %d"):format(
stats.dropped or 0, stats.expired or 0, stats.arp or 0))
end

while true do
local event, p1 = os.pullEvent()

if event == "ipnet_status_reply" then
show(p1)
return

elseif event == "timer" and p1 == timer then
printError("no reply from the ipnet daemon -- is netstart running?")
return
end
end
]],
["mfg/boot/apply.lua"] = [[






















local firmware = require("mfg.common.firmware")
local config = require("mfg.common.config")
local state = require("mfg.common.state")

local apply = {}

local function P(root, path) return fs.combine(root or "/", path) end

local loaderLib
local function loader()
if not loaderLib then
local fn, err = loadfile("/mfg/boot/loader.lua", nil, _ENV)
if not fn then error("cannot load stage 0 as a library: " .. tostring(err), 0) end
loaderLib = fn("--lib")
end
return loaderLib
end
apply.loader = loader



function apply.stageZero()
local text = state.readText("/mfg/boot/loader.lua")
if not text then return nil, "no stage 0 at /mfg/boot/loader.lua" end
local fn, err = load(text, "=startup", "t", {})
if not fn then return nil, "stage 0 does not compile: " .. tostring(err) end
return text
end

local function writeBytes(path, bytes)
return state.writeText(path, bytes, true)
end



local function fetch(source, f)
local ok, bytes = pcall(source, f.path, f.sha256)
if not ok then return nil, ("%s: %s"):format(f.path, tostring(bytes)) end
if type(bytes) ~= "string" then return nil, f.path .. ": the source returned nothing" end
if #bytes ~= f.size or firmware.hashBytes(bytes) ~= f.sha256 then
return nil, f.path .. ": does not match the manifest"
end
return bytes
end


function apply.localSource(from)
return function(path)
local bytes = state.readText(P(from or "/", path), true)
if not bytes then error("not on this computer", 0) end
return bytes
end
end


local function newRecord(m, doc, extra)
local record = {active = m.id, rev = doc.rev, role = doc.role, state = "trial", tries = 0}
for k, v in pairs(extra or {}) do record[k] = v end
return record
end





function apply.install(root, m, envelope, source, opts)
opts = opts or {}
local doc, why = config.decode(envelope)
if not doc then return nil, why end
if doc.firmware ~= m.id then
return nil, ("the config requires firmware %s, not %s"):format(tostring(doc.firmware), m.id)
end
local zero, zeroWhy = apply.stageZero()
if not zero then return nil, zeroWhy end

local tick = firmware.yielder()
for _, f in ipairs(m.files) do
local bytes, bad = fetch(source, f)
if not bytes then return nil, bad end
if not writeBytes(P(root, f.path), bytes) then return nil, "could not write " .. f.path end
tick()
end

local L = loader()
firmware.write(P(root, "boot/firmware"), m)
L.writeTable(P(root, "boot/config"), envelope)
if opts.signer then
writeBytes(P(root, "boot/signer"), require("ccryptolib.util").toHex(opts.signer) .. "\n")
end
L.writeRecord(root, newRecord(m, doc, {origin = opts.origin or "mint"}))


if opts.startup ~= false then writeBytes(P(root, "startup.lua"), zero) end
return {files = #m.files, firmware = m.id, rev = doc.rev}
end





function apply.stage(root, m, envelope, source)
local doc, why = config.decode(envelope)
if not doc then return nil, why end
if doc.firmware ~= m.id then
return nil, ("the config requires firmware %s, not %s"):format(tostring(doc.firmware), m.id)
end
if doc.role ~= m.role then
return nil, ("a %s config cannot boot %s firmware"):format(doc.role, m.role)
end

local active = firmware.read(P(root, "boot/firmware"))
local have = {}
for _, f in ipairs(active and active.files or {}) do have[f.path] = f.sha256 end

local staging = P(root, "boot/stage")
if fs.exists(staging) then fs.delete(staging) end

local tick, fetched = firmware.yielder(), 0
for _, f in ipairs(m.files) do
if have[f.path] ~= f.sha256 or not fs.exists(P(root, f.path)) then
local bytes, bad = fetch(source, f)
if not bytes then fs.delete(staging) return nil, bad end
writeBytes(fs.combine(staging, "files/" .. f.path), bytes)
fetched = fetched + 1
end
tick()
end
firmware.write(fs.combine(staging, "firmware"), m)
loader().writeTable(fs.combine(staging, "config"), envelope)
return {fetched = fetched, files = #m.files, firmware = m.id, rev = doc.rev}
end



function apply.activate(root, opts)
opts = opts or {}
local L = loader()
local staging = P(root, "boot/stage")
local new, why = firmware.read(fs.combine(staging, "firmware"))
if not new then return nil, "nothing staged: " .. tostring(why) end
local newDoc, docWhy = config.decode(L.readTable(fs.combine(staging, "config")))
if not newDoc then return nil, docWhy end

local oldPaths = L.manifestPaths(P(root, "boot/firmware")) or {}
local oldEnvelope = L.readTable(P(root, "boot/config"))
local oldDoc = oldEnvelope and config.decode(oldEnvelope) or nil
local oldRecord = L.record(root) or {}

local newPaths = {}
for _, f in ipairs(new.files) do newPaths[f.path] = true end

local steps = {{"delete", "boot/prev"}}

for _, rel in ipairs(L.listFiles(fs.combine(staging, "files"))) do
if fs.exists(P(root, rel)) then steps[#steps + 1] = {"move", rel, "boot/prev/files/" .. rel} end
steps[#steps + 1] = {"move", "boot/stage/files/" .. rel, rel}
end



local pruned = {}
for path in pairs(oldPaths) do
if not newPaths[path] and fs.exists(P(root, path)) then pruned[#pruned + 1] = path end
end
table.sort(pruned)
for _, path in ipairs(pruned) do
steps[#steps + 1] = {"move", path, "boot/prev/files/" .. path}
end


if oldDoc and oldDoc.role ~= newDoc.role then
for _, rel in ipairs(L.listFiles(P(root, "mfg/state"))) do
if rel ~= "actions" and rel ~= "actions.new" then
steps[#steps + 1] = {"move", "mfg/state/" .. rel, "boot/prev/state/" .. rel}
end
end
end

for _, name in ipairs({"firmware", "config"}) do
if fs.exists(P(root, "boot/" .. name)) then
steps[#steps + 1] = {"move", "boot/" .. name, "boot/prev/" .. name}
end
steps[#steps + 1] = {"move", "boot/stage/" .. name, "boot/" .. name}
end

L.writeTable(fs.combine(staging, "record"), newRecord(new, newDoc, {
prev = oldRecord.active, prev_rev = oldRecord.rev, origin = opts.origin or "update",
}))
if fs.exists(P(root, "boot/record")) then
steps[#steps + 1] = {"move", "boot/record", "boot/prev/record"}
end
steps[#steps + 1] = {"move", "boot/stage/record", "boot/record"}
steps[#steps + 1] = {"delete", "boot/stage"}

L.writeJournal(root, steps, "activate")
L.replay(root, opts.limit)
return #steps
end

function apply.rollback(root, why)
return loader().rollback(root, why)
end

return apply
]],
["mfg/boot/init.lua"] = [[





























local state = require("mfg.common.state")
local firmware = require("mfg.common.firmware")
local config = require("mfg.common.config")
local signed = require("mfg.common.signed")
local equipment = require("mfg.common.equipment")
local services = require("mfg.common.services")

local boot = {}

boot.COMMIT_WINDOW = 60



local CHECKIN_TRIES, CHECKIN_GAP = 6, 10

local function P(root, path) return fs.combine(root or "/", path) end






function boot.commit(root)
local path = P(root, "boot/record")
local record = state.readFile(path)
if type(record) ~= "table" or record.state ~= "trial" then return false end
record.state = "committed"
record.tries = 0
record.committed_at = os.epoch("utc")
state.writeFile(path, record)
return true
end











local function resolveIntent(root, m, record)
local path = P(root, "boot/intent")
local text = state.readText(path) or ""
local role = text:match("role%s+(%S+)")
if not role then error("boot/intent names no role", 0) end
local roles = require("mfg.common.roles")
if not roles[role] then error("boot/intent names a role this firmware does not know: " .. role, 0) end

local overrides = {}
for line in text:gmatch("[^\n]+") do
local name, value = line:match("^%s*set%s+(%S+)%s+(.-)%s*$")
if name then overrides[name] = value end
end

local node = text:match("node%s+(%S+)") or os.getComputerLabel()
or ("computer-" .. os.getComputerID())
local doc, why = config.resolve({
roles = roles, node = node, role = role, rev = (record.rev or 0) + 1,
overrides = overrides, firmware = m.id,
})
if not doc then error("could not resolve this node's config: " .. tostring(why), 0) end

require("mfg.boot.apply").loader().writeTable(P(root, "boot/config"), config.unsealed(doc))
record.rev = doc.rev
record.role = role
state.writeFile(P(root, "boot/record"), record)
fs.delete(path)
end

function boot.stageConfig(ctx)
local root = ctx.root
local record = state.readFile(P(root, "boot/record"))
if type(record) ~= "table" then error("no boot record", 0) end

local m, why = firmware.read(P(root, "boot/firmware"))
if not m then error("firmware: " .. tostring(why), 0) end

if fs.exists(P(root, "boot/intent")) then resolveIntent(root, m, record) end

local envelope = state.readFile(P(root, "boot/config"))
local doc, docWhy = config.decode(envelope)
if not doc then error("config: " .. tostring(docWhy), 0) end



if envelope.sig then
local anchor, anchorWhy = signed.anchor(P(root, "boot/signer"))
if not anchor then error("config is signed but " .. tostring(anchorWhy), 0) end
local ok, bad = config.verify(envelope, {anchor})
if not ok then error("config: " .. tostring(bad), 0) end
if m.sig then
local fok, fbad = firmware.verify(m, {anchor})
if not fok then error("firmware: " .. tostring(fbad), 0) end
end
elseif envelope.origin ~= "disk" then
error("config is neither signed nor written to this disk", 0)
end



if doc.firmware ~= m.id then
error(("config requires firmware %s but %s is installed"):format(
tostring(doc.firmware):sub(1, 16), m.id:sub(1, 16)), 0)
end
if doc.role ~= m.role then
error(("config says %s but the firmware is %s's"):format(doc.role, m.role), 0)
end
if record.active ~= m.id then
error(("boot record names firmware %s but %s is installed"):format(
tostring(record.active):sub(1, 16), m.id:sub(1, 16)), 0)
end





local profile = require("mfg.common.roles")[doc.role]
if not profile then error("this firmware has no profile for " .. tostring(doc.role), 0) end

ctx.record, ctx.manifest, ctx.doc, ctx.profile = record, m, doc, profile
end














function boot.stageAliases(ctx)
local aliases = ctx.doc.aliases
if type(aliases) ~= "table" or next(aliases) == nil then return end
local sh = ctx.shell or shell
if not sh or not sh.setAlias then error("no shell to set aliases in", 0) end

local carried = {}
for _, f in ipairs(ctx.manifest.files or {}) do carried[f.path] = true end

local names, skipped = {}, {}
for name in pairs(aliases) do names[#names + 1] = name end
table.sort(names)
ctx.aliases = {}
for _, name in ipairs(names) do
local target = aliases[name]
local path = target:sub(2)
if not path:match("%.lua$") then path = path .. ".lua" end
if carried[path] then
sh.setAlias(name, target)
ctx.aliases[name] = target
else
skipped[#skipped + 1] = ("%s (%s is not in this firmware)"):format(name, target)
end
end
if #skipped > 0 then error("aliases not set: " .. table.concat(skipped, ", "), 0) end
end













local function onTurtle(ctx)
return ctx.doc ~= nil and ctx.doc.platform == "turtle"
end

function boot.stageEquipment(ctx)
local record = ctx.record
local hw = ctx.hal or require("mfg.common.hal").turtle()
local fitted, why = equipment.read(hw)
local missing = fitted and equipment.missing(ctx.doc.equipment, fitted) or nil

local before = record.equipment_missing
record.equipment_missing = (missing and #missing > 0) and missing or nil
if textutils.serialize(before) ~= textutils.serialize(record.equipment_missing) then
state.writeFile(P(ctx.root, "boot/record"), record)
end

if not fitted then error("cannot read equipment: " .. tostring(why), 0) end
ctx.fitted, ctx.missing = fitted, missing
if #missing > 0 then
printError("unequipped: missing " .. table.concat(missing, ", "))
end
end




local function isPorted(ctx)
return ctx.profile ~= nil and ctx.profile.services ~= nil
end

local function isLegacy(ctx)
return ctx.profile ~= nil and ctx.profile.startup ~= nil and ctx.profile.services == nil
end









function boot.stageIdentity(ctx)
if ctx.profile.authority then
ctx.enrollment = {admitted = true, why = "the authority enrolls others, not itself"}
return
end
local join = require("mfg.common.join")
local cfg, why = join.config({spent = true})
if not cfg and fs.exists(join.CONFIG) then
error(("%s is unreadable: %s"):format(join.CONFIG, tostring(why)), 0)
end
ctx.identity = cfg
end










function boot.stageActions(ctx)
local actions = require("mfg.common.actions")
actions.reset()
local loaded, failed, withheld = actions.load(ctx.doc.actions or {}, {fitted = ctx.fitted})
if not loaded then error("actions: " .. tostring(failed), 0) end
for _, why in ipairs(withheld or {}) do printError("withheld: " .. why) end
if #failed > 0 then
error("actions failed to load: " .. table.concat(failed, "; "), 0)
end
ctx.actions = loaded
end







function boot.bind(names)
local net = require("net")
local bound, failed = {}, {}
for _, name in ipairs(names) do
local ok, why = net.serve(name)
if ok or tostring(why):find("already bound") then
bound[#bound + 1] = ("%s %d"):format(name, net.port(name) or -1)
else
failed[#failed + 1] = ("%s (%s)"):format(name, tostring(why))
end
end
if #failed > 0 then error("could not bind: " .. table.concat(failed, ", "), 0) end
print("bound: " .. table.concat(bound, ", "))
end



function boot.report(ctx)
local record = state.readFile(P(ctx.root, "boot/record")) or {}
local lastError = state.readFile(P(ctx.root, "boot/last_error"))
local missing = record.equipment_missing
local degraded = {}
for _, entry in ipairs(ctx.degraded or {}) do
degraded[#degraded + 1] = ("%s: %s"):format(entry.stage, entry.why)
end
return {
kind = "checkin",
node = ctx.doc.node,
role = ctx.doc.role,
firmware = record.active,
config_rev = record.rev,
boot_state = (type(missing) == "table" and #missing > 0) and "unequipped" or record.state,
committed = record.state == "committed",
equipment_missing = missing,
degraded = degraded,
last_error = type(lastError) == "table" and lastError.error or nil,
}
end





function boot.checkIn(ctx)
local body = boot.report(ctx)
if ctx.sendReport then return ctx.sendReport(body) end
if ctx.profile.authority then
require(ctx.profile.services).observeSelf(body)
return true
end
local host = (ctx.doc.settings or {}).controller or "mfg"
local lastWhy
for attempt = 1, CHECKIN_TRIES do
local ok, why = require("net").send(host, "mfg-report", body)
if ok then return true end
lastWhy = why
if attempt < CHECKIN_TRIES then sleep(CHECKIN_GAP) end
end
return false, ("could not check in with %s: %s"):format(host, tostring(lastWhy))
end




local function fingerprint(manager)
local out = {}
for _, name in ipairs(manager.order) do
if name ~= "commit" and name ~= "console" then
local r = manager.list[name]
out[#out + 1] = ("%s:%d:%d:%s"):format(name, r.restarts, r.failures,
r.state == services.HALTED and "halted" or "")
end
end
return table.concat(out, " ")
end




local function declareBase(manager, ctx)
local profile = ctx.profile




local peer = ""
if profile.authority then
peer = tostring((ctx.doc.settings or {}).parent or "")
else
peer = require("mfg.common.join").bootstrapPeer()
end
services.declare(manager, {
name = "netstack",
critical = true,
start = function() ctx.shell.run("/netstart", peer) end,
})






if not profile.authority then
services.declare(manager, {
name = "enroll",
requires = {"netstack"},
restart = false,
ready = function()
if require("acknet").isRunning() then return true end
return false, "waiting for acknet, which enrollment rides"
end,
start = function()
local join = require("mfg.common.join")
local ok, admitted, why = pcall(join.bootstrap)
if not ok then admitted, why = false, tostring(admitted) end
ctx.enrollment = {admitted = admitted, why = why}
print(("enrollment: %s"):format(tostring(why)))
if not admitted then printError("not admitted -- this node cannot reach the controller") end
end,
})
end

services.declare(manager, {
name = "checkin",
requires = profile.authority and {} or {"netstack"},
restart = false,
ready = (not profile.authority) and ctx.admitted or nil,
start = function()
local ok, why = boot.checkIn(ctx)
print(ok and "checked in" or ("check-in: " .. tostring(why)))
end,
})
end






local function declareCommit(manager, ctx)
services.declare(manager, {
name = "commit",
restart = false,
start = function()
local record = state.readFile(P(ctx.root, "boot/record"))
if type(record) ~= "table" or record.state ~= "trial" then return end
local window = (ctx.commitWindow or boot.COMMIT_WINDOW) * 1000
local since, seen = os.epoch("utc"), fingerprint(manager)
while not manager.halted do
sleep(math.min(1, window / 4000))
local now = fingerprint(manager)
if now ~= seen then
since, seen = os.epoch("utc"), now
elseif os.epoch("utc") - since >= window then
if boot.commit(ctx.root) then
print("boot set committed")
boot.checkIn(ctx)
end
return
end
end
end,
})
end






function boot.stageServices(ctx)
ctx.shell = ctx.shell or shell
if not ctx.shell then error("no shell to run the netstack in", 0) end


ctx.admitted = ctx.admitted or function()
if not ctx.enrollment then return false, "enrollment has not finished" end
if not require("net").ready() then return false, "the netstack has not come up" end
return true
end
ctx.bind = ctx.bind or boot.bind

local manager = services.new({name = ctx.doc.role})
ctx.manager = manager
if ctx.declareBase ~= false then declareBase(manager, ctx) end
require(ctx.profile.services).declare(manager, ctx)
declareCommit(manager, ctx)



if ctx.console ~= false and not services.terminalOwner(manager) then
require("mfg.common.console").declare(manager, {prompt = ctx.doc.role})
end

if ctx.onRun then ctx.onRun(manager, ctx) end
local halted = services.run(manager)
error(halted or "every service stopped", 0)
end






function boot.stageLegacy(ctx)
local program = ctx.profile.startup
local sh = ctx.shell or shell
if not sh then error("no shell to run " .. program .. " in", 0) end
parallel.waitForAny(
function()
sh.run(program)
error(program .. " exited", 0)
end,
function()
sleep(ctx.commitWindow or boot.COMMIT_WINDOW)
if boot.commit(ctx.root) then print("boot set committed") end
while true do os.pullEvent("boot_idle_forever") end
end
)
end



boot.stages = {
{name = "config", run = boot.stageConfig, onFail = "rollback"},
{name = "aliases", run = boot.stageAliases, onFail = "degrade"},
{name = "equipment", run = boot.stageEquipment, onFail = "degrade", when = onTurtle},
{name = "identity", run = boot.stageIdentity, onFail = "halt", when = isPorted},
{name = "actions", run = boot.stageActions, onFail = "rollback", when = isPorted},
{name = "services", run = boot.stageServices, onFail = "rollback", when = isPorted},
{name = "legacy", run = boot.stageLegacy, onFail = "rollback", when = isLegacy},
}






function boot.run(root, opts)
opts = opts or {}
local ctx = {root = root or "/", shell = opts.shell, commitWindow = opts.commitWindow,
hal = opts.hal, console = opts.console, declareBase = opts.declareBase,
sendReport = opts.sendReport, onRun = opts.onRun, degraded = {}}
for _, stage in ipairs(opts.stages or boot.stages) do
if not stage.when or stage.when(ctx) then
local ok, err = pcall(stage.run, ctx)
if not ok then
if stage.onFail == "degrade" then
ctx.degraded[#ctx.degraded + 1] = {stage = stage.name, why = tostring(err)}
else
error(("stage %s: %s"):format(stage.name, tostring(err)), 0)
end
end
end
if opts.stopAfter == stage.name then return ctx end
end
if not isPorted(ctx) and not isLegacy(ctx) then

error(("the %s profile names neither services nor a startup program"):format(
tostring(ctx.doc and ctx.doc.role)), 0)
end
return ctx
end

return boot
]],
["mfg/boot/loader.lua"] = [[



















local L = {}

L.MAX_TRIES = 3
L.JOURNAL_VERSION = 1

local function P(root, path) return fs.combine(root or "/", path) end






function L.readTable(path)
if not fs.exists(path) then
local temp = path .. ".new"
if not fs.exists(temp) then return nil end
fs.move(temp, path)
end
local handle = fs.open(path, "r")
if not handle then return nil end
local text = handle.readAll()
handle.close()
local ok, value = pcall(textutils.unserialize, text)
if ok then return value end
return nil
end

function L.writeTable(path, value)
local dir = fs.getDir(path)
if dir ~= "" and not fs.exists(dir) then fs.makeDir(dir) end
local temp = path .. ".new"
if fs.exists(temp) then fs.delete(temp) end
local handle = fs.open(temp, "w")
handle.write(textutils.serialize(value))
handle.close()
if fs.exists(path) then fs.delete(path) end
fs.move(temp, path)
end

function L.record(root) return L.readTable(P(root, "boot/record")) end
function L.writeRecord(root, record) L.writeTable(P(root, "boot/record"), record) end



function L.manifestPaths(path)
local set = {}
if not fs.exists(path) then return nil end
local handle = fs.open(path, "r")
if not handle then return nil end
for line in handle.readAll():gmatch("[^\r\n]+") do
local file = line:match("^file%s+(%S+)")
if file then set[file] = true end
end
handle.close()
return set
end

local function listFiles(dir, prefix, out)
out = out or {}
if not fs.isDir(dir) then return out end
for _, name in ipairs(fs.list(dir)) do
local full = fs.combine(dir, name)
local rel = prefix and (prefix .. "/" .. name) or name
if fs.isDir(full) then listFiles(full, rel, out) else out[#out + 1] = rel end
end
table.sort(out)
return out
end
L.listFiles = listFiles



















local function journalPath(root) return P(root, "boot/journal") end
local function progressPath(root) return P(root, "boot/journal.at") end

function L.writeJournal(root, steps, kind)
L.writeTable(journalPath(root), {v = L.JOURNAL_VERSION, kind = kind, steps = steps})
if fs.exists(progressPath(root)) then fs.delete(progressPath(root)) end
end

function L.hasJournal(root)
return fs.exists(journalPath(root)) or fs.exists(journalPath(root) .. ".new")
end

local function doStep(root, step, notes)
local op = step[1]
if op == "move" then
local from, to = P(root, step[2]), P(root, step[3])
if fs.exists(from) then
local dir = fs.getDir(to)
if dir ~= "" and not fs.exists(dir) then fs.makeDir(dir) end
if fs.exists(to) then fs.delete(to) end
fs.move(from, to)
elseif not fs.exists(to) then
notes[#notes + 1] = "nothing to move: " .. step[2]
end
elseif op == "delete" then
local path = P(root, step[2])
if fs.exists(path) then fs.delete(path) end
else
error("journal step this stage 0 does not understand: " .. tostring(op), 0)
end
end



function L.replay(root, limit)
local journal = L.readTable(journalPath(root))
if not journal then return true, {} end
if journal.v ~= L.JOURNAL_VERSION then
error(("journal version %s; this stage 0 understands %d"):format(
tostring(journal.v), L.JOURNAL_VERSION), 0)
end
local at = L.readTable(progressPath(root)) or 0
local notes, done = {}, 0
for i = at + 1, #journal.steps do
if limit and done >= limit then return false, notes end
doStep(root, journal.steps[i], notes)
L.writeTable(progressPath(root), i)
done = done + 1
end
fs.delete(journalPath(root))
if fs.exists(progressPath(root)) then fs.delete(progressPath(root)) end
return true, notes
end




function L.canRollBack(root)
return fs.exists(P(root, "boot/prev/record"))
end





function L.rollbackSteps(root, why)
local prevRecord = L.readTable(P(root, "boot/prev/record"))
if not prevRecord then return nil, "no previous generation to roll back to" end
local current = L.record(root) or {}
local steps = {}

local active = L.manifestPaths(P(root, "boot/firmware")) or {}
local previous = L.manifestPaths(P(root, "boot/prev/firmware"))
if previous then
local added = {}
for path in pairs(active) do
if not previous[path] then added[#added + 1] = path end
end
table.sort(added)
for _, path in ipairs(added) do steps[#steps + 1] = {"delete", path} end
end

for _, rel in ipairs(listFiles(P(root, "boot/prev/files"))) do
steps[#steps + 1] = {"move", "boot/prev/files/" .. rel, rel}
end

if fs.isDir(P(root, "boot/prev/state")) then
for _, rel in ipairs(listFiles(P(root, "mfg/state"))) do
if rel ~= "actions" and rel ~= "actions.new" then
steps[#steps + 1] = {"delete", "mfg/state/" .. rel}
end
end
for _, rel in ipairs(listFiles(P(root, "boot/prev/state"))) do
steps[#steps + 1] = {"move", "boot/prev/state/" .. rel, "mfg/state/" .. rel}
end
end

for _, name in ipairs({"firmware", "config"}) do
if fs.exists(P(root, "boot/prev/" .. name)) then
steps[#steps + 1] = {"move", "boot/prev/" .. name, "boot/" .. name}
end
end

prevRecord.state = "committed"
prevRecord.tries = 0
prevRecord.rolled_back_from = current.active
prevRecord.rolled_back_because = why
L.writeTable(P(root, "boot/rollback.record"), prevRecord)
steps[#steps + 1] = {"move", "boot/rollback.record", "boot/record"}
steps[#steps + 1] = {"delete", "boot/prev"}
return steps
end

function L.rollback(root, why)
local steps, bad = L.rollbackSteps(root, why)
if not steps then return nil, bad end
L.writeJournal(root, steps, "rollback")
return L.replay(root)
end



local function lastError(root, text)
L.writeTable(P(root, "boot/last_error"), {at = os.epoch("utc"), error = text})
end






function L.boot(root, hooks)
hooks = hooks or {}
local say = hooks.say or print
local warn = hooks.warn or printError
local reboot = hooks.reboot or function() sleep(3) os.reboot() end
local run = hooks.run or function()
return require("mfg.boot").run(root, {shell = shell})
end

if L.hasJournal(root) then
local ok, finished = pcall(L.replay, root)
if not ok then
lastError(root, "journal: " .. tostring(finished))
warn("could not finish the boot journal: " .. tostring(finished))
return "recovery"
end
end

local record = L.record(root)
if not record then
warn("no boot record: this computer is not managed by the bootloader")
return "unmanaged"
end

if record.state == "trial" then
record.tries = (record.tries or 0) + 1
L.writeRecord(root, record)
if record.tries > L.MAX_TRIES then



local prior = L.readTable(P(root, "boot/last_error"))
local why = ("boot set failed %d trial boots"):format(record.tries - 1)
local cause = type(prior) == "table" and type(prior.error) == "string" and prior.error or nil


if cause and cause:find("trial boots", 1, true) then cause = cause:match("%(last: (.*)%)") end
if cause then why = why .. " (last: " .. cause .. ")" end
if not L.canRollBack(root) then
lastError(root, why .. ", and there is nothing to roll back to")
warn(why .. ", and there is nothing to roll back to -- recovery")
return "recovery"
end
warn(why .. " -- rolling back to the previous generation")
local ok, err = pcall(L.rollback, root, why)
if not ok then
lastError(root, "rollback: " .. tostring(err))
warn("rollback failed: " .. tostring(err))
return "recovery"
end
reboot()
return "rolledback"
end
say(("boot set on trial, attempt %d of %d"):format(record.tries, L.MAX_TRIES))
end

local ok, err = pcall(run, root)





if not ok and tostring(err):find("Terminated$") then
say("stopped by operator -- run /startup to boot again")
return "stopped"
end

local why = ok and "the boot stages returned; the node stopped" or tostring(err)
lastError(root, why)


record = L.record(root) or record
if record.state == "trial" then
warn("boot failed on trial: " .. why)
reboot()
return "reboot"
end
warn("boot failed on a COMMITTED boot set -- recovery: " .. why)
warn("see /boot/last_error. The previous generation is kept in /boot/prev.")
return "recovery"
end

if select(1, ...) == "--lib" then return L end

if not package.path:find("^/%?") then
package.path = "/?.lua;/?/init.lua;" .. package.path
end
L.boot("/")
]],
["mfg/common/actions/init.lua"] = [[

































local rpc = require("mfg.common.rpc")
local roles = require("mfg.common.roles")
local validate = require("mfg.common.actions.validate")
local requires = require("mfg.common.actions.requires")
local journal = require("mfg.common.actions.journal")
local equipment = require("mfg.common.equipment")

local actions = {}

actions.journal = journal
actions.requires = requires
actions.validate = validate

local registry = {}




local function moduleName(path)
return (path:gsub("%.lua$", ""):gsub("/", "."))
end





function actions.register(decl)
local ok, errors = validate.declaration(decl)
if not ok then
return false, table.concat(errors, "; ")
end
if registry[decl.name] then


return false, ("two actions are called %s"):format(decl.name)
end
registry[decl.name] = decl
return true, decl
end






















function actions.load(roleOrList, opts)
opts = opts or {}
local list
if type(roleOrList) == "table" then
list = roleOrList
elseif type(roleOrList) == "string" then
local spec = roles[roleOrList]
if not spec then
return nil, ("unknown role: %s"):format(roleOrList)
end
list = spec.actions or {}
else
return nil, "actions.load needs a role or a list of action files"
end

local loaded, failed, withheld = {}, {}, {}

for _, path in ipairs(list) do
local name = moduleName(path)
local ok, decl = pcall(require, name)
local permitted, short = true, nil
if ok and opts.fitted then permitted, short = equipment.permits(decl, opts.fitted) end
if not ok then
failed[#failed + 1] = ("%s: %s"):format(path, tostring(decl))
elseif not permitted then
withheld[#withheld + 1] = ("%s: needs %s"):format(tostring(decl.name), short)
else
local registered, why = actions.register(decl)
if registered then
loaded[#loaded + 1] = decl.name
else
failed[#failed + 1] = ("%s: %s"):format(path, tostring(why))
end
end
end

return loaded, failed, withheld
end

function actions.get(name)
return registry[name]
end














function actions.list(opts)
opts = opts or {}
local out = {}
for _, decl in pairs(registry) do
local wanted = opts.base or not decl.base
if wanted and decl.tier == "service" and not opts.services then
wanted = false
end
if wanted and opts.role and decl.role and decl.role ~= opts.role then
wanted = false
end
if wanted and opts.tier and decl.tier ~= opts.tier then
wanted = false
end
if wanted then out[#out + 1] = decl end
end
table.sort(out, function(a, b) return a.name < b.name end)
return out
end


function actions.reset()
registry = {}
end









function actions.finish(ctx, entry, status, fields)
fields = fields or {}

local record = {
action = entry.action,
params = entry.params,
status = status,
reason = fields.reason,
by = ctx.by,
at = os.epoch("utc"),
steps = (entry.steps and #entry.steps > 0) and entry.steps or nil,
}

if type(ctx.steps) == "table" then
ctx.steps[#ctx.steps + 1] = record
elseif not entry.quiet then




journal.record(record)
end

return status, fields
end















function actions.invoke(name, params, ctx)
ctx = ctx or {}

local decl = registry[name]
if not decl then


print(("actions: rejected unknown action %s from %s"):format(
tostring(name), tostring(ctx.by or "local")))
return actions.finish(ctx, {action = name}, rpc.REJECTED,
{reason = "unknown action: " .. tostring(name)})
end



















if decl.manual and not (ctx.operator or ctx.policy) then
return actions.finish(ctx, {action = name, params = params}, rpc.REJECTED,
{reason = ("%s is a manual action -- an operator or a policy wrapper "
.. "must ask for it"):format(name), manual = true})
end

local checked, why, errors = validate.check(decl, params)
if not checked then
return actions.finish(ctx, {action = name, params = params, quiet = decl.quiet},
rpc.REJECTED, {reason = why, errors = errors})
end




local available, blocked, evaluated = requires.evaluate(decl, ctx.snapshot)
if evaluated and not available then
return actions.finish(ctx, {action = name, params = checked, quiet = decl.quiet},
rpc.REJECTED, {reason = blocked, blocked = true})
end








local children = {}
local childCtx = {
by = ctx.by, snapshot = ctx.snapshot, packet = ctx.packet,
operator = ctx.operator,



policy = (decl.policy and decl.name) or ctx.policy,



legacy = ctx.legacy,
steps = children,
}

local lived, status, fields = pcall(decl.run, checked, childCtx)

if not lived then

print(("actions: %s failed: %s"):format(name, tostring(status)))
return actions.finish(ctx,
{action = name, params = checked, steps = children, quiet = decl.quiet},
rpc.REJECTED, {reason = tostring(status)})
end

if not status then



return actions.finish(ctx,
{action = name, params = checked, steps = children, quiet = decl.quiet},
rpc.REJECTED, {reason = ("%s returned no status"):format(name)})
end

return actions.finish(ctx,
{action = name, params = checked, steps = children, quiet = decl.quiet},
status, fields)
end

return actions
]],
["mfg/common/actions/journal.lua"] = [[



















local state = require("mfg.common.state")

local journal = {}

local FILE = "actions"




journal.LIMIT = 64





function journal.record(entry)
local all = state.read(FILE, nil)
if type(all) ~= "table" or type(all.entries) ~= "table" then
all = {entries = {}, nextSeq = 1}
end

local record = {
seq = all.nextSeq or 1,
action = entry.action,
params = entry.params,
status = entry.status,
reason = entry.reason,
by = entry.by,
at = entry.at or os.epoch("utc"),
steps = entry.steps,
}

all.entries[#all.entries + 1] = record
all.nextSeq = record.seq + 1

while #all.entries > journal.LIMIT do
table.remove(all.entries, 1)
end

state.write(FILE, all)
return record
end


function journal.recent(count)
local all = state.read(FILE, nil)
if type(all) ~= "table" or type(all.entries) ~= "table" then return {} end

local out = {}
local entries = all.entries
local first = math.max(1, #entries - (count or journal.LIMIT) + 1)
for index = #entries, first, -1 do
out[#out + 1] = entries[index]
end
return out
end

function journal.reset()
state.clear(FILE)
end

return journal
]],
["mfg/common/actions/receive.lua"] = [[





















local rpc = require("mfg.common.rpc")
local net = require("net")



local function library()
return require("mfg.common.actions")
end













local function dispatch(body, packet, legacy)
local actions = library()
local command = body.command

if actions.get(command) then
return actions.invoke(command, body, {
by = packet and packet.src,
packet = packet,
operator = body.operator == true or nil,
policy = type(body.policy) == "string" and body.policy or nil,
})
end




if type(legacy) == "function" then
return legacy(body, packet)
end



print(("receive: rejected unknown command %s from %s"):format(
tostring(command), tostring(packet and packet.src)))
return rpc.REJECTED, {reason = "unknown command: " .. tostring(command)}
end

return {
name        = "receive",
label       = "Receive",
tier        = "service",
base        = true,
quiet       = true,
destructive = false,

parameters = {
{name = "protocol", label = "Protocol", type = "choice", required = true,
choices = {"mfg-control", "mfg-scada", "mfg-order", "mfg-report"},
help = "Which service to listen on. A wrapper fills this; an operator "
.. "never picks it."},

{name = "once", label = "Serve once", type = "flag", default = false,
help = "Serve at most one request and return. The shape an operating loop "
.. "wants; without it, loop until stopped."},

{name = "timeout", label = "Timeout", type = "number", min = 0.1, max = 60,
default = 1,
help = "Seconds to wait for a request before giving the loop back."},
},

returns = {served = "number"},

run = function(params, ctx)



local bound, why = net.serve(params.protocol)
if not bound and not tostring(why):find("already bound") then
return rpc.REJECTED, {reason = tostring(why)}
end

local served = 0
repeat
local handled = rpc.serveOnce(params.protocol, function(body, packet)
return dispatch(body, packet, ctx.legacy)
end, params.timeout)
if handled then served = served + 1 end
until params.once

return rpc.COMPLETED, {served = served}
end,
}
]],
["mfg/common/actions/requires.lua"] = [[


















local requires = {}










function requires.evaluate(decl, snapshot)
local rules = decl and decl.requires
if type(rules) ~= "table" or next(rules) == nil then
return true, nil, true
end
if type(snapshot) ~= "table" then
return true, nil, false
end

for point, expected in pairs(rules) do
local actual = snapshot[point]

if type(expected) == "table" then
local matched = false
for _, allowed in ipairs(expected) do
if actual == allowed then matched = true end
end
if not matched then
return false, ("%s is %s, needs one of %s"):format(
point, tostring(actual),
table.concat(requires.render(expected), ", ")), true
end
elseif actual ~= expected then



return false, ("%s is %s, needs %s"):format(
point, tostring(actual), tostring(expected)), true
end
end

return true, nil, true
end

function requires.render(expected)
local out = {}
for _, value in ipairs(expected) do out[#out + 1] = tostring(value) end
return out
end

return requires
]],
["mfg/common/actions/transmit.lua"] = [[

























local rpc = require("mfg.common.rpc")

return {
name        = "transmit",
label       = "Transmit",
tier        = "node",
base        = true,
destructive = false,

parameters = {
{name = "target", label = "Target", type = "node", required = true,
help = "The hostname to send to. A derived action usually fills this "
.. "from a node it has already resolved."},




{name = "protocol", label = "Protocol", type = "choice", required = true,
choices = {"mfg-control", "mfg-scada", "mfg-order", "mfg-report"},
help = "Which service on the target. mfg-control is a node, mfg-scada "
.. "an operator surface, mfg-order a counterparty."},

{name = "content", label = "Content", type = "text", required = true,
help = "The body, serialised. A derived action pre-fills this and the "
.. "operator never sees it."},

{name = "timeout", label = "Timeout", type = "number", min = 1, max = 60,
default = rpc.DEFAULT_TIMEOUT,
help = "Seconds to wait for each attempt."},

{name = "attempts", label = "Attempts", type = "number", integer = true,
min = 1, max = 5, default = rpc.DEFAULT_ATTEMPTS,
help = "Bounded, and the rpc id is stable across them, so a duplicate "
.. "reaching a handler that already ran is recognisable as a "
.. "repeat rather than a second command."},
},

returns = {
status = "text",
reply = "text",
},






run = function(params)
local body = params.content
if body:sub(1, 1) == "{" then
local parsed = textutils.unserialize(body)
if type(parsed) ~= "table" then
return rpc.REJECTED, {reason = "content is not a readable table"}
end
body = parsed
else
body = {command = body}
end

local answer = rpc.request(params.target, params.protocol, body, {
timeout = params.timeout,
attempts = params.attempts,
})




return answer.status, {
reason = answer.reason,
reply = answer,
attempts = answer.attempts,
}
end,
}
]],
["mfg/common/actions/types.lua"] = [[




















local types = {}






local function choiceList(param)
local choices = param.choices
if type(choices) ~= "table" then return nil end
if choices.source then return nil end
return choices
end



local function choiceValues(choices)
local values = {}
for _, entry in ipairs(choices) do
if type(entry) == "table" then
values[#values + 1] = entry.value
else
values[#values + 1] = entry
end
end
return values
end

local function inChoices(value, choices)
for _, allowed in ipairs(choiceValues(choices)) do
if allowed == value then return true end
end
return false
end




local function isToken(value)
return type(value) == "string" and value ~= "" and not value:find("%s")
end

types.number = {
coerce = function(value)
if type(value) == "number" then return value end
if type(value) ~= "string" then return nil end
return tonumber(value)
end,
check = function(value, param)
if type(value) ~= "number" then return false, "not a number" end
if value ~= value then return false, "not a number" end
if param.integer and math.floor(value) ~= value then
return false, "must be a whole number"
end
if param.min and value < param.min then
return false, ("must be at least %s"):format(tostring(param.min))
end
if param.max and value > param.max then
return false, ("must be at most %s"):format(tostring(param.max))
end
return true
end,
}

types.text = {
coerce = function(value)
if type(value) == "string" then return value end
return nil
end,
check = function(value, param)
if type(value) ~= "string" then return false, "not text" end
if param.maxLength and #value > param.maxLength then
return false, ("must be at most %d characters"):format(param.maxLength)
end
if param.pattern and not value:find(param.pattern) then
return false, "does not match the expected form"
end
return true
end,
}

types.choice = {
coerce = function(value)
if type(value) == "string" or type(value) == "number" then return value end
return nil
end,
check = function(value, param)
local choices = choiceList(param)
if not choices then



return true
end
if not inChoices(value, choices) then
return false, ("not one of: %s"):format(
table.concat(choiceValues(choices), ", "))
end
return true
end,
}




types.flag = {
coerce = function(value)
if type(value) == "boolean" then return value end
if value == "true" then return true end
if value == "false" then return false end
return nil
end,
check = function(value)
if type(value) ~= "boolean" then return false, "not true or false" end
return true
end,
}

types.item = {
coerce = types.text.coerce,
check = function(value, param)
if not isToken(value) then return false, "not an item id" end
local choices = choiceList(param)
if choices and not inChoices(value, choices) then
return false, "not an item this cluster holds"
end
return true
end,
}

types.node = {
coerce = types.text.coerce,
check = function(value, param)
if not isToken(value) then return false, "not a node name" end
local choices = choiceList(param)
if choices and not inChoices(value, choices) then
return false, "not a node this controller knows"
end
return true
end,
}




types.path = {
coerce = types.text.coerce,
check = function(value, param)
if not isToken(value) then return false, "not a path" end
if value:sub(1, 1) ~= "/" then return false, "a path starts with /" end
local choices = choiceList(param)
if choices and not inChoices(value, choices) then
return false, "not a declared mount point"
end
return true
end,
}


















types.pattern = {
coerce = function(value)
if type(value) == "table" then return value end
return nil
end,
check = function(value)
if next(value) == nil then return false, "the pattern is empty" end
for slot, item in pairs(value) do
if type(slot) ~= "number" or slot < 1 or math.floor(slot) ~= slot then
return false, ("%s is not a slot number"):format(tostring(slot))
end
if not isToken(item) then
return false, ("slot %d does not name an item"):format(slot)
end
end
return true
end,
}


types.items = {
coerce = function(value)
if type(value) == "table" then return value end
return nil
end,
check = function(value)
for item, count in pairs(value) do
if not isToken(item) then
return false, ("%s is not an item id"):format(tostring(item))
end
if type(count) ~= "number" or count < 0
or math.floor(count) ~= count then
return false, ("%s: %s is not a count"):format(
item, tostring(count))
end
end
return true
end,
}






types.table = {
coerce = function(value)
if type(value) == "table" then return value end
return nil
end,
check = function(value)
if type(value) ~= "table" then return false, "not a table" end
return true
end,
}

function types.get(name)
return types[name]
end

function types.names()
return {"number", "text", "choice", "flag", "item", "node", "path",
"pattern", "items", "table"}
end

return types
]],
["mfg/common/actions/validate.lua"] = [[



















local types = require("mfg.common.actions.types")

local validate = {}




function validate.declaration(decl)
if type(decl) ~= "table" then return false, {"not a table"} end

local errors = {}
if type(decl.name) ~= "string" or decl.name == "" then
errors[#errors + 1] = "an action needs a name"
end
if type(decl.run) ~= "function" then
errors[#errors + 1] = ("%s: a declaration with no handler is an action "
.. "that fails when picked"):format(tostring(decl.name))
end

local seen = {}
for index, param in ipairs(decl.parameters or {}) do
local where = ("%s parameter %d"):format(tostring(decl.name), index)
if type(param) ~= "table" then
errors[#errors + 1] = where .. ": not a table"
else
if type(param.name) ~= "string" or param.name == "" then
errors[#errors + 1] = where .. ": needs a name"
elseif seen[param.name] then
errors[#errors + 1] = where .. ": duplicates " .. param.name
else
seen[param.name] = true
end
if not types.get(param.type) then
errors[#errors + 1] = ("%s: unknown type '%s' -- one of %s")
:format(where, tostring(param.type),
table.concat(types.names(), ", "))
end
end
end



if decl.needs ~= nil then
local good = type(decl.needs) == "table"
for _, id in ipairs(good and decl.needs or {}) do
if type(id) ~= "string" or id == "" then good = false end
end
if not good then
errors[#errors + 1] = ("%s: needs is a list of item ids"):format(tostring(decl.name))
end
end

if #errors > 0 then return false, errors end
return true
end








function validate.parameters(decl, supplied)
supplied = supplied or {}
local out, errors = {}, {}
local declared = {}

for _, param in ipairs(decl.parameters or {}) do
declared[param.name] = true
local value = supplied[param.name]

if value == nil and param.default ~= nil then
value = param.default
end

if value == nil then
if param.required then
errors[#errors + 1] = ("%s is required"):format(
param.label or param.name)
end
else
local kind = types.get(param.type)
local coerced = kind.coerce(value)
if coerced == nil then
errors[#errors + 1] = ("%s: %s is not a %s"):format(
param.label or param.name, tostring(value), param.type)
else
local ok, why = kind.check(coerced, param)
if ok then
out[param.name] = coerced
else
errors[#errors + 1] = ("%s: %s"):format(
param.label or param.name, why)
end
end
end
end












local transport = {command = true, rpc = true, action = true,
status = true, from = true, src = true, encrypted = true,
attempts = true, reason = true,


operator = true, policy = true}

for name in pairs(supplied) do
if not declared[name] and not transport[name] then
errors[#errors + 1] = ("unknown parameter: %s"):format(tostring(name))
end
end

if #errors > 0 then return nil, errors end
return out
end


function validate.check(decl, supplied)
local params, errors = validate.parameters(decl, supplied)
if not params then
return nil, table.concat(errors, "; "), errors
end
return params
end

return validate
]],
["mfg/common/bootinfo.lua"] = [[







local state = require("mfg.common.state")

local bootinfo = {}

bootinfo.DIR = "/boot"
bootinfo.RECORD = "/boot/record"

function bootinfo.record()
local record = state.readFile(bootinfo.RECORD)
if type(record) == "table" then return record end
return nil
end




function bootinfo.points()
local record = bootinfo.record()
if not record then return {boot_state = "unmanaged"} end





local missing, bootState = nil, record.state
if type(record.equipment_missing) == "table" and #record.equipment_missing > 0 then
missing = table.concat(record.equipment_missing, ",")
bootState = "unequipped"
end
return {
firmware = record.active,
config_rev = record.rev,
boot_state = bootState,
equipment_missing = missing,
}
end

return bootinfo
]],
["mfg/common/config/init.lua"] = [[




























local signed = require("mfg.common.signed")
local state = require("mfg.common.state")
local validate = require("mfg.common.actions.validate")
local schema = require("mfg.common.config.schema")

local config = {}

config.SCHEMA = 1
config.CONTEXT = "mfg-config-v1|"
config.PATH = "/boot/config"

local byName = {}
for _, param in ipairs(schema.parameters) do byName[param.name] = param end


function config.declared(name)
return byName[name]
end





local function checkDoc(doc)
if type(doc) ~= "table" then return nil, "the config is not a document" end
if doc.schema ~= config.SCHEMA then
return nil, ("config schema %s; this software understands %d"):format(
tostring(doc.schema), config.SCHEMA)
end
if type(doc.rev) ~= "number" or doc.rev < 1 then return nil, "the config carries no rev" end
for _, field in ipairs({"node", "role", "platform"}) do
if type(doc[field]) ~= "string" or doc[field] == "" then
return nil, "the config names no " .. field
end
end
if type(doc.actions) ~= "table" then return nil, "the config lists no actions" end
if type(doc.equipment) ~= "table" then return nil, "the config lists no equipment" end
if type(doc.settings) ~= "table" then return nil, "the config carries no settings" end
if doc.aliases ~= nil then
local ok, why = config.checkAliases(doc.aliases)
if not ok then return nil, why end
end
return doc
end


function config.decode(envelope)
if type(envelope) ~= "table" or type(envelope.doc) ~= "string" then
return nil, "not a config envelope"
end
local ok, doc = pcall(textutils.unserialize, envelope.doc)
if not ok or doc == nil then return nil, "the config document does not parse" end
return checkDoc(doc)
end


function config.verify(envelope, anchors)
if type(envelope) ~= "table" or not envelope.sig then
return nil, "the config is not signed"
end
return signed.verify(config.CONTEXT, envelope.doc, envelope.signer, envelope.sig, anchors)
end


function config.seal(doc)
local text = textutils.serialize(doc)
local signer, sig = signed.sign(config.CONTEXT, text)
return {doc = text, signer = signer, sig = sig}
end


function config.unsealed(doc)
return {doc = textutils.serialize(doc), origin = "disk"}
end





function config.current(path)
local envelope, why = state.readFile(path or config.PATH)
if envelope == nil then return nil, why or "no config at " .. (path or config.PATH) end
return config.decode(envelope)
end





function config.setting(name, path)
local param = byName[name]
if not param then error("no setting called " .. tostring(name), 2) end

local doc = config.current(path)
local value = doc and doc.settings[name]
if value ~= nil then return value end
return param.default
end









config.TURTLE_SLOTS = 2




local function isModemEntry(entry)
if #entry == 0 then return false end
for _, id in ipairs(entry) do
if not tostring(id):find("wireless_modem", 1, true) then return false end
end
return true
end






function config.checkAliases(aliases)
if type(aliases) ~= "table" then return nil, "aliases is not a table" end
for name, target in pairs(aliases) do
if type(name) ~= "string" or not name:match("^[%w_%-]+$") then
return nil, ("alias %s is not a plain command name"):format(tostring(name))
end
if type(target) ~= "string" or not target:match("^/[%w_%-/%.]+$") or target:find("%.%.") then
return nil, ("alias %s must name an absolute program path"):format(name)
end
end
return true
end

function config.checkProfile(name, spec)
if type(spec) ~= "table" then return nil, "no role called " .. tostring(name) end
if spec.aliases ~= nil then
local ok, why = config.checkAliases(spec.aliases)
if not ok then return nil, name .. ": " .. why end
end
local equipment = spec.equipment or {}

if spec.platform == "turtle" then
if #equipment > config.TURTLE_SLOTS then
return nil, ("%s needs %d pieces of equipment and a turtle has %d upgrade slots"):format(
name, #equipment, config.TURTLE_SLOTS)
end
local pinned = false
for _, entry in ipairs(equipment) do
if type(entry) ~= "table" or #entry == 0 then
return nil, name .. " has an equipment entry naming no item"
end
if entry.pinned then
if not isModemEntry(entry) then
return nil, name .. " pins equipment that is not a wireless modem"
end
pinned = true
end
end


if not pinned then return nil, name .. " has no pinned wireless modem" end
elseif spec.platform == "computer" then
if #equipment > 0 then
return nil, name .. " runs on a computer, which has no upgrade slots"
end
else
return nil, ("%s declares no platform (turtle or computer)"):format(name)
end
return true
end





function config.resolve(args)
local roles = args.roles or require("mfg.common.roles")
local spec = roles[args.role]
local ok, why = config.checkProfile(args.role, spec)
if not ok then return nil, why end

local settings, bad = config.settingsFor(spec.settings, args.overrides)
if not settings then return nil, bad end

local actions = {}
for i, path in ipairs(spec.actions or {}) do actions[i] = path end
local aliases = {}
for name, target in pairs(spec.aliases or {}) do aliases[name] = target end
local equipment = {}
for i, entry in ipairs(spec.equipment or {}) do
local copy = {pinned = entry.pinned}
for j, id in ipairs(entry) do copy[j] = id end
equipment[i] = copy
end

return {
schema = config.SCHEMA,
rev = args.rev,
node = args.node,
role = args.role,
platform = spec.platform,
firmware = args.firmware,
actions = actions,
equipment = equipment,
settings = settings,
aliases = aliases,
issued = os.epoch("utc"),
}
end






function config.settingsFor(names, values)
local params, takes = {}, {}
for _, name in ipairs(names or {}) do
local param = byName[name]
if not param then return nil, ("the role takes a setting nobody declared: %s"):format(name) end
params[#params + 1] = param
takes[name] = true
end
for name in pairs(values or {}) do
if not byName[name] then return nil, ("no setting called %s"):format(name) end
if not takes[name] then return nil, ("this role does not take %s"):format(name) end
end
local out, why = validate.check({parameters = params}, values or {})
if not out then return nil, why end
return out
end

return config
]],
