["mfg/common/console.lua"] = [[
















local services = require("mfg.common.services")

local console = {}

local function usage()
print("svc                 list services")
print("svc log <name>      recent output from one")
print("svc stop|start <name>")
print("anything else runs as a program, e.g. mfgctl stock")
end


local function svc(manager, args)
local action = args[2]

if not action then
for _, entry in ipairs(services.status(manager)) do
local line = ("%-10s %-11s"):format(entry.name, entry.state)
if entry.restarts > 0 then
line = line .. ("x%d"):format(entry.restarts)
end
if entry.blockedOn then
line = line .. "  " .. entry.blockedOn
end
print(line)



if entry.lastError then
printError("           last: " .. entry.lastError)
end
end
local halted = services.halted(manager)
if halted then printError("NODE HALTED: " .. halted) end
return
end

if action == "log" then
local name = args[3]
if not name then printError("usage: svc log <name>") return end
local lines = services.logs(manager, name, 30)
if #lines == 0 then print("(nothing logged)") return end
for _, line in ipairs(lines) do
print(("%s  %s"):format(
os.date("%H:%M:%S", math.floor(line.at / 1000)), line.text))
end
return
end

if action == "stop" or action == "start" then
local fn = (action == "stop") and services.stop or services.start
local ok, err = fn(manager, args[3] or "")
if not ok then printError(tostring(err)) return end
print(action .. "ed " .. tostring(args[3]))
return
end

printError("unknown: svc " .. tostring(action))
usage()
end




function console.run(manager, opts)
opts = opts or {}
local prompt = (opts.prompt or manager.name) .. "> "

print("console ready -- 'svc' for services, 'exit' to leave")

while true do
write(prompt)
local line = read()
if line == nil then return end

local args = {}
for word in tostring(line):gmatch("%S+") do args[#args + 1] = word end

if #args == 0 then

elseif args[1] == "exit" then
return
elseif args[1] == "help" then
usage()
elseif args[1] == "svc" then
local ok, err = pcall(svc, manager, args)


if not ok then printError(tostring(err)) end
else
local ok, err = pcall(shell.run, line)
if not ok then printError(tostring(err)) end
end
end
end


function console.declare(manager, opts)
return services.declare(manager, {
name = "console",
critical = false,
start = function() console.run(manager, opts) end,
restart = true,
})
end

return console
]],
["mfg/common/enrollment.lua"] = [[




























local blake3 = require("ccryptolib.blake3")
local ccutil = require("ccryptolib.util")

local enrollment = {}

enrollment.PROTOCOL = "mfg_enroll"




local MAC_CONTEXT = "mfg enrollment v1"

enrollment.SECRET_BYTES = 32
enrollment.DEFAULT_LEASE_SECONDS = 60 * 60

local toHex = ccutil.toHex



function enrollment.fromHex(h)
if type(h) ~= "string" or #h % 2 ~= 0 or h:find("%X") then return nil end
return ccutil.fromHex(h)
end

enrollment.toHex = toHex









function enrollment.mac(secret, instanceId, publicKeyHex)
if type(secret) ~= "string" or #secret ~= enrollment.SECRET_BYTES then
return nil, "secret must be 32 bytes"
end
local message = ("%s|%s|%s"):format(MAC_CONTEXT, tostring(instanceId),
tostring(publicKeyHex))
return toHex(blake3.digestKeyed(secret, message))
end





function enrollment.macEquals(a, b)
if type(a) ~= "string" or type(b) ~= "string" or #a ~= #b then return false end
local diff = 0
for i = 1, #a do
diff = bit32.bor(diff, bit32.bxor(a:byte(i), b:byte(i)))
end
return diff == 0
end

return enrollment
]],
["mfg/common/equipment.lua"] = [[











local equipment = {}

equipment.SIDES = {"left", "right"}


function equipment.fittedSet(fitted)
local set = {}
for _, side in ipairs(equipment.SIDES) do
local id = fitted and fitted[side]
if type(id) == "string" then set[id] = (set[id] or 0) + 1 end
end
return set
end







function equipment.missing(required, fitted)
local items = {}
for _, side in ipairs(equipment.SIDES) do
local id = fitted and fitted[side]
if type(id) == "string" then items[#items + 1] = id end
end

local function accepts(entry, id)
for _, want in ipairs(entry) do
if want == id then return true end
end
return false
end


local function unmet(order)
local used, out = {}, {}
for _, entry in ipairs(required or {}) do
local found = false
for _, i in ipairs(order) do
if not used[i] and accepts(entry, items[i]) then
used[i], found = true, true
break
end
end
if not found then out[#out + 1] = entry[1] or "?" end
end
return out
end

local best = unmet({1, 2})
if #best > 0 and #items == 2 then
local other = unmet({2, 1})
if #other < #best then best = other end
end
return best
end




function equipment.permits(decl, fitted)
if type(decl) ~= "table" or decl.needs == nil then return true end
local set = equipment.fittedSet(fitted)
for _, id in ipairs(decl.needs) do
if not set[id] then return false, id end
end
return true
end



function equipment.read(hw)
if type(hw) ~= "table" or type(hw.equipment) ~= "function" then
return nil, "this HAL cannot report equipment"
end
local ok, fitted = pcall(hw.equipment)
if not ok then return nil, tostring(fitted) end
if type(fitted) ~= "table" then return nil, "the HAL returned no equipment table" end
return fitted
end

return equipment
]],
["mfg/common/firmware.lua"] = [[



























local sha256 = require("ccryptolib.sha256")
local ccutil = require("ccryptolib.util")
local signed = require("mfg.common.signed")
local state = require("mfg.common.state")

local firmware = {}

firmware.VERSION = 2
firmware.CONTEXT = "mfg-firmware-v1|"





firmware.MAX_FILE = 131072




firmware.PROTECTED = {"net", "mfg/state", "boot", "startup.lua", "mfg/enroll.cfg"}

function firmware.isProtected(path)
local p = fs.combine(path)
for _, guard in ipairs(firmware.PROTECTED) do
if p == guard or p:sub(1, #guard + 1) == guard .. "/" then return true end
end
return false
end

local function fileLine(f)
return ("file %s %d %s"):format(f.path, f.size, f.sha256)
end


function firmware.idOf(files)
local lines = {}
for i, f in ipairs(files) do lines[i] = fileLine(f) .. "\n" end
return ccutil.toHex(sha256.digest(table.concat(lines)))
end




function firmware.parse(text)
if type(text) ~= "string" then return nil, "no manifest" end
local m = {files = {}}
local seen = {}
local n = 0
for line in text:gmatch("[^\r\n]+") do
n = n + 1
local key, rest = line:match("^(%S+)%s*(.*)$")
if n == 1 then
if key ~= "manifest" then return nil, "not a manifest" end
local v = tonumber(rest)
if v ~= firmware.VERSION then
return nil, ("manifest version %s; this software understands %d"):format(
tostring(rest), firmware.VERSION)
end
m.version = v
elseif key == "file" then
local path, size, sum = rest:match("^(%S+)%s+(%d+)%s+(%x+)$")
if not path or #sum ~= 64 then return nil, "malformed file line: " .. line end
if firmware.isProtected(path) then return nil, "manifest names a protected path: " .. path end
if seen[path] then return nil, "manifest names a file twice: " .. path end
seen[path] = true
m.files[#m.files + 1] = {path = path, size = tonumber(size), sha256 = sum:lower()}
elseif key == "role" or key == "source" or key == "built" or key == "id"
or key == "signer" or key == "sig" then
if m[key] then return nil, "manifest repeats `" .. key .. "`" end
m[key] = rest
elseif key then
return nil, "manifest line this software does not understand: " .. line
end
end
if not m.version then return nil, "empty manifest" end
if not m.role or m.role == "" then return nil, "manifest names no role" end
if not m.id or #m.id ~= 64 then return nil, "manifest carries no id" end
local computed = firmware.idOf(m.files)
if computed ~= m.id:lower() then
return nil, ("manifest id %s does not match its files (%s)"):format(m.id, computed)
end
m.id = computed
return m
end

function firmware.render(m)
local out = {
"manifest " .. firmware.VERSION,
"role " .. m.role,
}
if m.source then out[#out + 1] = "source " .. m.source end
if m.built then out[#out + 1] = "built " .. m.built end
out[#out + 1] = "id " .. m.id
for _, f in ipairs(m.files) do out[#out + 1] = fileLine(f) end
if m.signer then out[#out + 1] = "signer " .. m.signer end
if m.sig then out[#out + 1] = "sig " .. m.sig end
return table.concat(out, "\n") .. "\n"
end

function firmware.read(path)
local text, why = state.readText(path)
if not text then return nil, why or ("no manifest at " .. path) end
return firmware.parse(text)
end

function firmware.write(path, m)
return state.writeText(path, firmware.render(m))
end




local function signable(m)
return m.role .. "|" .. m.id
end


function firmware.sign(m)
m.signer, m.sig = signed.sign(firmware.CONTEXT, signable(m))
return m
end


function firmware.verify(m, anchors)
if not m.sig then return nil, "manifest is not signed -- it has not been published" end
return signed.verify(firmware.CONTEXT, signable(m), m.signer, m.sig, anchors)
end



function firmware.hashFile(path)
if not fs.exists(path) or fs.isDir(path) then return nil, "missing" end
local data = state.readText(path, true)
if not data then return nil, "unreadable" end
return firmware.hashBytes(data), #data
end


function firmware.hashBytes(data)
return ccutil.toHex(sha256.digest(data))
end





function firmware.yielder()
local last = os.epoch("utc")
return function()
if os.epoch("utc") - last > 250 then
sleep(0)
last = os.epoch("utc")
end
end
end

return firmware
]],
["mfg/common/hal/init.lua"] = [[



































if not package.path:find("^/%?") then
package.path = "/?.lua;/?/init.lua;" .. package.path
end

local hal = {}

local CONFIG = "/mfg/hal.cfg"

local function configured()
local text = require("mfg.common.state").readText(CONFIG)
if not text then return nil end
local mode = text:match("^%s*([%a]+)")
if mode == "real" or mode == "mock" then return mode end
return nil
end

function hal.mode()
return configured() or (turtle and "real" or "real")
end





function hal.turtle()
if hal.mode() == "mock" then return require("mfg.common.hal.turtle_mock") end
return require("mfg.common.hal.turtle_real")
end

















function hal.redstone()
if hal.mode() == "mock" then return require("mfg.common.hal.rs_mock") end
return require("mfg.common.hal.rs_real")
end

local INVENTORY_BACKENDS = {
mock = "mfg.storage.hal.inv_mock",
real = "mfg.storage.hal.inv_real",
}

function hal.inventory()
local name = INVENTORY_BACKENDS[hal.mode()] or INVENTORY_BACKENDS.real
local ok, backend = pcall(require, name)
if ok then return backend end

error("no inventory backend on this node: " .. name .. " is not installed. "
.. "A turtle deliberately does not carry mfg/storage (N4.3, R9.13) -- "
.. "addressing inventories by name is the controller's job.", 2)
end

return hal
]],
["mfg/common/hal/rs_real.lua"] = [[










local backend = {}

backend.name = "real"

local function call(dev, method, ...)
if dev == "local" then return redstone[method](...) end
return peripheral.call(dev, method, ...)
end



function backend.isPresent(dev)
if dev == "local" then return true end
if not peripheral.isPresent(dev) then return false end
for _, method in ipairs(peripheral.getMethods(dev) or {}) do
if method == "getAnalogInput" then return true end
end
return false
end

function backend.getInput(dev, face)
return call(dev, "getInput", face) == true
end

function backend.getAnalogInput(dev, face)
return call(dev, "getAnalogInput", face) or 0
end

function backend.getOutput(dev, face)
return call(dev, "getOutput", face) == true
end

function backend.getAnalogOutput(dev, face)
return call(dev, "getAnalogOutput", face) or 0
end

function backend.setOutput(dev, face, on)
call(dev, "setOutput", face, on and true or false)
end

function backend.setAnalogOutput(dev, face, level)
call(dev, "setAnalogOutput", face, level)
end

return backend
]],
["mfg/common/hal/turtle_real.lua"] = [[







local backend = {}

backend.name = "real"

function backend.slots()
local out = {}
for slot = 1, 16 do
local detail = turtle.getItemDetail(slot)
if detail then
out[slot] = {name = detail.name, count = detail.count}
end
end
return out
end

function backend.select(slot)
return turtle.select(slot)
end

function backend.itemCount(slot)
return turtle.getItemCount(slot)
end

function backend.transferTo(slot, count)
return turtle.transferTo(slot, count)
end





function backend.suckInput(count)
return turtle.suck(count)
end














































local feedMode, feedSide = nil, nil

local function feedConfig()
if feedMode then return feedMode, feedSide end
local config = require("mfg.common.config")

feedMode, feedSide = config.setting("feed.mode"), config.setting("feed.side")
return feedMode, feedSide
end

function backend.feedMode()
local mode = feedConfig()
return mode
end








function backend.lockFeed(locked)
local _, side = feedConfig()
if not side then return true end
redstone.setOutput(side, locked and true or false)
return true
end

function backend.feedLocked()
local _, side = feedConfig()
if not side then return false end
return redstone.getOutput(side) == true
end

function backend.hasInput()
return peripheral.hasType("front", "inventory") == true
end

function backend.hasOutput()
return peripheral.hasType("bottom", "inventory") == true
end






function backend.held()
local totals = {}
for _, stack in pairs(backend.slots()) do
totals[stack.name] = (totals[stack.name] or 0) + stack.count
end
return totals
end










function backend.adjacent()
local out = {}
for _, side in ipairs({"front", "top", "bottom"}) do
if peripheral.hasType(side, "inventory") == true then
local wrapped = peripheral.wrap(side)
local ok, listing = pcall(wrapped.list)
if ok and listing then
local totals = {}
for _, stack in pairs(listing) do
totals[stack.name] = (totals[stack.name] or 0) + stack.count
end
out[side] = totals
end
end
end
return out
end


function backend.surroundings()
local out = {}
for _, side in ipairs({"front", "top", "bottom", "left", "right"}) do
local kind = peripheral.getType(side)
out[side] = {
peripheral = kind,
inventory = kind and peripheral.hasType(side, "inventory") == true,
}
end
local ok, block = turtle.inspect()
out.blockInFront = ok and block.name or "nothing (air)"
local okDown, below = turtle.inspectDown()
out.blockBelow = okDown and below.name or "nothing (air)"
return out
end

function backend.dropOutput(count)
return turtle.dropDown(count)
end








function backend.dropInput(count)
return turtle.drop(count)
end







function backend.craft(limit)
if not turtle.craft then return false, "no crafting table fitted" end
return turtle.craft(limit)
end

function backend.fuelLevel()
return turtle.getFuelLevel()
end





















local UPGRADE_TYPES = {
workbench = "minecraft:crafting_table",
}

local function inferred(side)
local kind = peripheral.getType(side)
if kind == nil then return nil end
if kind == "modem" then


local ok, wireless = pcall(peripheral.call, side, "isWireless")
if ok and wireless then return "computercraft:wireless_modem_normal" end
return "peripheral:modem"
end
return UPGRADE_TYPES[kind] or ("peripheral:" .. kind)
end

function backend.equipment()
if turtle.getEquippedLeft and turtle.getEquippedRight then
local left, right = turtle.getEquippedLeft(), turtle.getEquippedRight()
return {left = left and left.name, right = right and right.name, how = "equipped"}
end
return {left = inferred("left"), right = inferred("right"), how = "peripheral"}
end












function backend.forward()
return turtle.forward()
end

function backend.back()
return turtle.back()
end

function backend.up()
return turtle.up()
end

function backend.down()
return turtle.down()
end

function backend.turnLeft()
return turtle.turnLeft()
end

function backend.turnRight()
return turtle.turnRight()
end



local function looked(ok, data)
if not ok then return nil end
return {name = data.name, state = data.state, tags = data.tags}
end

function backend.inspect()
return looked(turtle.inspect())
end





function backend.inspectDown()
return looked(turtle.inspectDown())
end

function backend.inspectUp()
return looked(turtle.inspectUp())
end











function backend.peer(side)
local kind = peripheral.getType(side)
if kind ~= "computer" and kind ~= "turtle" then return nil end

local wrapped = peripheral.wrap(side)
if not wrapped then return nil end

local ok, label = pcall(wrapped.getLabel)
local gotId, id = pcall(wrapped.getID)
return {
kind = kind,
label = ok and label or nil,
id = gotId and id or nil,
side = side,
}
end



function backend.rebootPeer(side)
local kind = peripheral.getType(side)
if kind ~= "computer" and kind ~= "turtle" then
return false, ("nothing rebootable on %s"):format(tostring(side))
end
local wrapped = peripheral.wrap(side)
if not wrapped then return false, "could not wrap " .. tostring(side) end

local ok, err = pcall(wrapped.reboot)
if not ok then return false, tostring(err) end
return true
end

return backend
]],
["mfg/common/join.lua"] = [[













local enrollment = require("mfg.common.enrollment")

local acknet = require("acknet")
local netkeys = require("netkeys")
local ip = require("ip")
local random = require("ccryptolib.random")
local state = require("mfg.common.state")

local join = {}

local CONFIG = "/mfg/enroll.cfg"



join.CONFIG = CONFIG






function join.config(opts)
opts = opts or {}
local text, why = state.readText(CONFIG)
if not text then return nil, why or ("no enrollment config at " .. CONFIG) end

local cfg = {
instance = text:match("instance%s+(%S+)"),
secret = text:match("secret%s+(%x+)"),
controller = tonumber(text:match("controller%s+(%d+)")),
name = text:match("name%s+(%S+)"),
role = text:match("role%s+(%S+)"),
}
if not cfg.instance then return nil, "config has no instance id" end
if not cfg.secret then
if opts.spent and text:match("secret%s+%(spent%)") then
cfg.spent = true
else
return nil, "config has no secret"
end
end





if not cfg.controller then return nil, "config has no controller computer id" end
return cfg
end






function join.clearSecret()
local text = state.readText(CONFIG)
if not text then return end
state.writeText(CONFIG, (text:gsub("secret%s+%x+", "secret (spent)")))
end




function join.enroll(cfg, attempts, gap)
attempts = attempts or 20
gap = gap or 3

if not netkeys.publicKey() then
return nil, "this computer has no keypair"
end

local pk = netkeys.toHex(netkeys.publicKey())
local secret = enrollment.fromHex(cfg.secret)
if not secret or #secret ~= enrollment.SECRET_BYTES then
return nil, "secret is not 32 bytes of hex"
end

local tag, macErr = enrollment.mac(secret, cfg.instance, pk)
if not tag then return nil, tostring(macErr) end

local target = ip.linkLocal(cfg.controller)
local request = {kind = "enroll", instance = cfg.instance, pk = pk, mac = tag}

local lastReason = "no reply from the controller"
for _ = 1, attempts do
acknet.send(target, request, enrollment.PROTOCOL)

local deadline = os.epoch("utc") + gap * 1000
while os.epoch("utc") < deadline do
local packet = acknet.receive(enrollment.PROTOCOL, 1)
if packet and type(packet.body) == "table" then
local reply = packet.body

if reply.kind ~= "enroll" then
if reply.ok then
join.clearSecret()
return reply
end
lastReason = tostring(reply.reason)


if lastReason:find("consumed") or lastReason:find("verify")
or lastReason:find("no lease") then
return nil, lastReason
end
end
end
end
end

return nil, lastReason
end















function join.bootstrap(opts)
opts = opts or {}
local waitFor = opts.wait or 60

local cfg, cfgErr = join.config({spent = true})
if not cfg then


return true, "no enrollment config -- not a minted node (" .. tostring(cfgErr) .. ")"
end

if not (cfg.secret and cfg.secret ~= "(spent)") then
return true, "lease already spent -- already admitted"
end

local acknet = require("acknet")
for _ = 1, waitFor do
if acknet.isRunning() then break end
sleep(1)
end
if not acknet.isRunning() then
return false, "the acknet daemon did not come up, so enrollment cannot be sent"
end

require("netkeys").init()
local reply, why = join.enroll(cfg, opts.attempts or 30, opts.gap or 2)
if not reply then
return false, "enrollment refused: " .. tostring(why)
end
return true, "admitted as " .. tostring(reply.name)
end




function join.bootstrapPeer()
local cfg = join.config()
if cfg and cfg.controller then return tostring(cfg.controller) end
return ""
end

return join
]],
["mfg/common/pattern.lua"] = [[





















local pattern = {}


pattern.MAX_DEPTH = 64












pattern.GRID = {1, 2, 3, 5, 6, 7, 9, 10, 11}

local GRID_SET = {}
for _, slot in ipairs(pattern.GRID) do GRID_SET[slot] = true end



function pattern.inGrid(want)
local outside = nil
for slot in pairs(want) do
if not GRID_SET[slot] and (not outside or slot < outside) then outside = slot end
end
if outside then
return false, ("slot %d is outside the 3x3 crafting grid"):format(outside)
end
return true
end





function pattern.id(want)
local slots = {}
for slot in pairs(want) do slots[#slots + 1] = slot end
table.sort(slots)
local parts = {}
for _, slot in ipairs(slots) do
parts[#parts + 1] = ("%d=%s"):format(slot, want[slot])
end
return table.concat(parts, ",")
end











function pattern.occurrences(want)
local counts = {}
for _, item in pairs(want) do
counts[item] = (counts[item] or 0) + 1
end
return counts
end












function pattern.depth(held, want, limits)
limits = limits or {}
local ceiling = math.min(limits.depth or pattern.MAX_DEPTH,
limits.stack or pattern.MAX_DEPTH)

local occurrences = pattern.occurrences(want)
if next(occurrences) == nil then
return 0, {reason = "the pattern is empty"}
end

local depth, short = ceiling, nil
for item, slots in pairs(occurrences) do
local have = held[item] or 0
local possible = math.floor(have / slots)
if possible < depth then
depth = possible
short = {item = item, have = have, perSet = slots,
needed = (possible + 1) * slots}
end
end

if depth >= ceiling then return ceiling, nil end
return depth, short
end





function pattern.target(want, depth)
local target = {}
for slot, item in pairs(want) do
target[slot] = {name = item, count = depth}
end
return target
end

























function pattern.plan(current, target, opts)
opts = opts or {}

local keeps, spare = {}, {}

for slot, stack in pairs(current) do
local wanted = target[slot]
if wanted and wanted.name == stack.name then
local kept = math.min(stack.count, wanted.count)
keeps[slot] = kept
if stack.count > kept then
spare[#spare + 1] = {slot = slot, name = stack.name,
count = stack.count - kept}
end
else




spare[#spare + 1] = {slot = slot, name = stack.name,
count = stack.count, wrongSlot = target[slot] ~= nil}
end
end


local wants = {}
for slot, wanted in pairs(target) do
local have = keeps[slot] or 0
if have < wanted.count then
wants[#wants + 1] = {slot = slot, name = wanted.name,
count = wanted.count - have}
end
end



table.sort(wants, function(a, b) return a.slot < b.slot end)
table.sort(spare, function(a, b) return a.slot < b.slot end)

local moves, evict = {}, {}





local staging = {}
for _, slot in ipairs(opts.staging or {}) do
if not target[slot] then staging[#staging + 1] = slot end
end

for _, chunk in ipairs(spare) do
if chunk.wrongSlot then
local parked = table.remove(staging, 1)
if parked then
moves[#moves + 1] = {from = chunk.slot, to = parked,
count = chunk.count, name = chunk.name, why = "evict"}
chunk.slot = parked
else



evict[#evict + 1] = {slot = chunk.slot, name = chunk.name,
count = chunk.count}
chunk.count = 0
end
end
end


local missing = {}
for _, want in ipairs(wants) do
local outstanding = want.count
for _, chunk in ipairs(spare) do
if outstanding <= 0 then break end
if chunk.count > 0 and chunk.name == want.name
and chunk.slot ~= want.slot then
local moved = math.min(chunk.count, outstanding)
moves[#moves + 1] = {from = chunk.slot, to = want.slot,
count = moved, name = want.name, why = "place"}
chunk.count = chunk.count - moved
outstanding = outstanding - moved
end
end
if outstanding > 0 then
missing[want.name] = (missing[want.name] or 0) + outstanding
end
end


for _, chunk in ipairs(spare) do
if chunk.count > 0 then
evict[#evict + 1] = {slot = chunk.slot, name = chunk.name,
count = chunk.count}
end
end

return {moves = moves, evict = evict, missing = missing, keeps = keeps}
end







function pattern.matches(current, target)
for slot, wanted in pairs(target) do
local stack = current[slot]
if not stack then
return false, ("slot %d is empty, wants %d %s"):format(
slot, wanted.count, wanted.name)
end
if stack.name ~= wanted.name then
return false, ("slot %d holds %s, wants %s"):format(
slot, stack.name, wanted.name)
end
if stack.count ~= wanted.count then
return false, ("slot %d holds %d %s, wants %d"):format(
slot, stack.count, stack.name, wanted.count)
end
end
for slot, stack in pairs(current) do
if not target[slot] then
return false, ("slot %d holds %d %s and nothing wants it"):format(
slot, stack.count, stack.name)
end
end
return true
end



function pattern.totals(current)
local held = {}
for _, stack in pairs(current) do
held[stack.name] = (held[stack.name] or 0) + stack.count
end
return held
end

return pattern
]],
