["mfg/common/rpc.lua"] = [[

















local net = require("net")

local rpc = {}

rpc.ACCEPTED = "accepted"
rpc.COMPLETED = "completed"
rpc.REJECTED = "rejected"
rpc.TIMED_OUT = "timed_out"

rpc.DEFAULT_TIMEOUT = 4
rpc.DEFAULT_ATTEMPTS = 3

local counter = 0




function rpc.newId()
counter = counter + 1
return ("%d:%d"):format(os.getComputerID(), counter)
end

local function reply(id, status, fields)
local out = fields or {}
out.rpc = id
out.status = status
return out
end

rpc.reply = reply







function rpc.request(target, service, body, opts)
opts = opts or {}
local timeout = opts.timeout or rpc.DEFAULT_TIMEOUT
local attempts = opts.attempts or rpc.DEFAULT_ATTEMPTS

local id = opts.id or rpc.newId()
local message = {}
for k, v in pairs(body or {}) do message[k] = v end
message.rpc = id

local lastError = nil

for attempt = 1, attempts do
local sent, sendErr = net.send(target, service, message)
if not sent then



return {status = rpc.REJECTED, reason = tostring(sendErr),
rpc = id, attempts = attempt}
end

local deadline = os.epoch("utc") + timeout * 1000
while os.epoch("utc") < deadline do
local packet = net.receive(service, 1)
if packet and type(packet.body) == "table"
and packet.body.rpc == id then
local answer = packet.body
answer.from = packet.from
answer.src = packet.src
answer.encrypted = packet.encrypted
answer.attempts = attempt
return answer
end
end
lastError = ("no reply within %ds"):format(timeout)
end




return {status = rpc.TIMED_OUT, reason = lastError, rpc = id,
attempts = attempts}
end







function rpc.serveOnce(service, handler, timeout)
local packet = net.receive(service, timeout or 1)
if not packet then return false end
if type(packet.body) ~= "table" or not packet.body.rpc then return false end

local id = packet.body.rpc
local ok, status, fields = pcall(handler, packet.body, packet)

if not ok then
net.send(packet.src, service,
reply(id, rpc.REJECTED, {reason = "handler error: " .. tostring(status)}))
return true
end

if not status then
net.send(packet.src, service,
reply(id, rpc.REJECTED, {reason = "unhandled command"}))
return true
end

net.send(packet.src, service, reply(id, status, fields))
return true
end

return rpc
]],
["mfg/common/script/check.lua"] = [[























local parse = require("mfg.common.script.parse")
local validate = require("mfg.common.actions.validate")

local check = {}

check.LIMITS = {
level = 15,
repeatMax = 64,
supplyMax = 3456,
everyMin = 20,
pulseMax = 200,
waitMax = 12000,
withinMin = 20,
textMax = 80,
slotMax = 256,
}


check.VERBS = {supply = "supply", stock = "supply", collect = "collect",
move = "move", set = "set_signal", pulse = "pulse"}

local VALUE_KINDS = {level = "level", flag = "flag"}



local function new(script, env)
return {script = script, env = env or {}, errors = {}, warnings = {},
ports = {}, footprint = {supplies = {}, collects = {}, writes = {}, drives = {},
reads = {}}}
end

local function err(c, n, message)
local span = n and n.span or {}
c.errors[#c.errors + 1] = {line = span.line, col = span.col, node = n and n.id,
message = message}
return nil
end

local function warn(c, n, message)
local span = n and n.span or {}
c.warnings[#c.warnings + 1] = {line = span.line, col = span.col,
node = n and n.id, message = message}
end

local function mark(set, value) set[value] = true end

local function knownItem(c, n, item)
local items = c.env.items
if items and not items[item] then
warn(c, n, ("the pool does not hold %s -- is it spelt right?"):format(item))
end
end


local function portOf(c, n, name)
local port = c.ports[name]
if not port then
return err(c, n, ("%s is not one of %s's ports"):format(tostring(name),
tostring(c.script.machine)))
end
return port
end

local function pathOf(c, name)
return "/" .. tostring(c.script.machine) .. "/" .. tostring(name)
end

local function describePort(port)
return ("an %s %s"):format(port.direction, port.type)
end




local function lookup(scope, name)
while scope do
if scope.names[name] then return scope.names[name] end
scope = scope.parent
end
end



local exprType

local function operand(c, e, scope)
local t = exprType(c, e, scope)
return t
end

local function cmpType(c, e, scope)
local lt = operand(c, e.left, scope)
local rt = operand(c, e.right, scope)
if not lt or not rt then return nil end

local function literal(t) return t == "number" end
if literal(lt) and literal(rt) then
return err(c, e, "compares two numbers: one side should be a reading")
end


local numeric, typed = nil, nil
if literal(lt) then numeric, typed = e.left, rt
elseif literal(rt) then numeric, typed = e.right, lt end
if numeric then
if typed ~= "level" and typed ~= "count" then
return err(c, e, ("a number cannot be compared with a %s"):format(typed))
end
local limit = typed == "level" and check.LIMITS.level or math.huge
if numeric.value > limit then
return err(c, numeric, ("%d is out of range for a level (0-15)")
:format(numeric.value))
end
lt, rt = typed, typed
end

if lt ~= rt then
local hint = ""
if (lt == "level" and rt == "count") or (lt == "count" and rt == "level") then
hint = " -- a comparator level is not an item count (E4.2); read the "
.. "volume with `count` for that"
end
return err(c, e, ("compares a %s with a %s%s"):format(lt, rt, hint))
end
if e.op ~= "=" and e.op ~= "!=" and lt ~= "level" and lt ~= "count" then
return err(c, e, ("%s only compares levels and counts; a %s is = or !=")
:format(e.op, lt))
end
if lt ~= "level" and lt ~= "count" and lt ~= "flag" then
return err(c, e, ("a %s cannot be compared"):format(lt))
end
return "bool"
end

exprType = function(c, e, scope)
local k = e.kind
if k == "num" then return "number"
elseif k == "onoff" then return "flag"
elseif k == "dur" then
return err(c, e, "a duration is not a value here")
elseif k == "item" then
return err(c, e, ("%s is an item, not a value -- `count %s in <port>` or "
.. "`free %s` reads one"):format(e.value, e.value, e.value))
elseif k == "text" then
return err(c, e, "text is only for alarms")
elseif k == "paren" then
return exprType(c, e.expr, scope)
elseif k == "name" then
local bound = lookup(scope, e.name)
if bound then return bound end
local port = c.ports[e.name]
if not port then
return err(c, e, ("%s is not a port or a name"):format(e.name))
end
if port.type == "volume" then
return err(c, e, ("%s is a volume, not a value -- read it with "
.. "`count <item> in %s`"):format(e.name, e.name))
end
mark(c.footprint.reads, pathOf(c, e.name))
return VALUE_KINDS[port.type]
elseif k == "count" then
local port = portOf(c, e, e.port)
if not port then return nil end
if port.type ~= "volume" then
return err(c, e, ("%s is a %s signal, not a volume"):format(e.port, port.type))
end
knownItem(c, e, e.item)
mark(c.footprint.reads, pathOf(c, e.port))
return "count"
elseif k == "free" then
knownItem(c, e, e.item)
return "count"
elseif k == "cmp" then
return cmpType(c, e, scope)
elseif k == "and" or k == "or" then
local lt = exprType(c, e.left, scope)
local rt = exprType(c, e.right, scope)
if lt and lt ~= "bool" then err(c, e.left, ("`%s` joins conditions, not a %s")
:format(k, lt == "number" and "number" or lt)) end
if rt and rt ~= "bool" then err(c, e.right, ("`%s` joins conditions, not a %s")
:format(k, rt == "number" and "number" or rt)) end
if lt == "bool" and rt == "bool" then return "bool" end
return nil
elseif k == "not" then
local t = exprType(c, e.expr, scope)
if t and t ~= "bool" then
return err(c, e, ("`not` takes a condition, not a %s"):format(t))
end
return t and "bool" or nil
end
return err(c, e, "not an expression: " .. tostring(k))
end

local function condition(c, e, scope, where)
local t = exprType(c, e, scope)
if t and t ~= "bool" then


local hint = ""
if t == "flag" then
hint = (" -- write `%s = on`"):format(e.kind == "name" and e.name or "it")
end
err(c, e, ("%s needs a condition, not a %s%s"):format(where, t, hint))
end
end



local function verb(c, s, params)
local decls = c.env.decls
if not decls then return end


for _, e in ipairs(c.errors) do
if e.node == s.id then return end
end
local action = check.VERBS[s.kind]
local decl = decls[action]
if not decl then
return err(c, s, ("the controller does not offer %s, which `%s` needs")
:format(action, s.kind))
end
local ok, why = validate.check(decl, params)
if not ok then
err(c, s, ("%s would refuse this: %s"):format(action, tostring(why)))
end
end

local function durationIn(c, s, d, low, high, what)
local ticks = parse.ticks(d)
if ticks < low or ticks > high then
local function show(t)
if t % 1200 == 0 then return math.floor(t / 1200) .. "m" end
if t % 20 == 0 then return math.floor(t / 20) .. "s" end
return t .. "t"
end
err(c, s, ("%s must be %s to %s"):format(what, show(low), show(high)))
end
return ticks
end



local block

local function volume(c, s, name, direction, verbName)
local port = portOf(c, s, name)
if not port then return nil end
if port.type ~= "volume" then
return err(c, s, ("`%s` takes a volume, and %s is a %s signal"):format(verbName,
name, port.type))
end
if direction and port.direction ~= direction then
return err(c, s, ("`%s` takes an %s volume, and %s is %s"):format(verbName,
direction, name, describePort(port)))
end
return port
end

local function outputSignal(c, s, name, verbName)
local port = portOf(c, s, name)
if not port then return nil end
if port.type == "volume" then
return err(c, s, ("`%s` drives a signal, and %s is a volume"):format(verbName,
name))
end
if port.direction ~= "output" then
return err(c, s, ("%s is an input -- it is read, not driven"):format(name))
end
return port
end

local function amount(c, s, n, low, high, what)
if n < low or n > high then
err(c, s, ("%s must be %d to %d"):format(what, low, high))
end
end

local function statement(c, s, scope)
local k = s.kind
if k == "if" then
condition(c, s.cond, scope, "`if`")
block(c, s.body, scope)
if s.orelse then block(c, s.orelse, scope) end
elseif k == "repeat" then
amount(c, s, s.n, 1, check.LIMITS.repeatMax, "repeat")
block(c, s.body, scope)
elseif k == "supply" or k == "stock" then
amount(c, s, s.n, 1, check.LIMITS.supplyMax, "the count")
knownItem(c, s, s.item)
if volume(c, s, s.port, "input", k) then
mark(c.footprint.writes, pathOf(c, s.port))
mark(c.footprint.supplies, s.item)
verb(c, s, {port = pathOf(c, s.port), item = s.item, count = s.n,
upto = k == "stock"})
end
elseif k == "collect" then
if volume(c, s, s.port, "output", k) then
mark(c.footprint.collects, pathOf(c, s.port))
verb(c, s, {port = pathOf(c, s.port)})
end
elseif k == "move" then
amount(c, s, s.n, 1, check.LIMITS.supplyMax, "the count")
local from = volume(c, s, s.from, nil, "move")
local to = volume(c, s, s.to, "input", "move ... to")
if from and to then
if s.from == s.to then err(c, s, "moves from a port to itself") end
mark(c.footprint.writes, pathOf(c, s.to))
verb(c, s, {from = pathOf(c, s.from), to = pathOf(c, s.to), item = s.item,
count = s.n})
end
elseif k == "set" then
local port = outputSignal(c, s, s.port, "set")
if port then
local v = s.value
local level
if port.type == "flag" then
if v.kind ~= "onoff" then
return err(c, s, ("%s is a flag: set it to on or off"):format(s.port))
end
level = v.value and 15 or 0
else
if v.kind ~= "num" then
return err(c, s, ("%s is a level: set it to 0-15"):format(s.port))
end
if v.value > check.LIMITS.level then
return err(c, s, ("%d is out of range for a level (0-15)")
:format(v.value))
end
level = v.value
end
mark(c.footprint.drives, pathOf(c, s.port))
verb(c, s, {signal = pathOf(c, s.port), level = level})
end
elseif k == "pulse" then
local ticks = durationIn(c, s, s.length, 1, check.LIMITS.pulseMax, "a pulse")
if outputSignal(c, s, s.port, "pulse") then
mark(c.footprint.drives, pathOf(c, s.port))
verb(c, s, {signal = pathOf(c, s.port), length = ticks})
end
elseif k == "wait" then
durationIn(c, s, s.length, 1, check.LIMITS.waitMax, "a wait")
elseif k == "waituntil" then
condition(c, s.cond, scope, "`wait until`")
durationIn(c, s, s.within, check.LIMITS.withinMin, check.LIMITS.waitMax,
"`within`")
elseif k == "let" then
if c.ports[s.name] then
return err(c, s, ("%s is a port; a let needs its own name"):format(s.name))
end
if lookup(scope, s.name) then
return err(c, s, ("%s is already a name here"):format(s.name))
end
local t = exprType(c, s.value, scope)
if t == "number" or t == "flag" and s.value.kind == "onoff" then
return err(c, s, "a let names a reading, not a constant")
end
if t then scope.names[s.name] = t end
elseif k == "alarm" then
if #s.text == 0 or #s.text > check.LIMITS.textMax then
err(c, s, ("an alarm's text is 1 to %d characters"):format(check.LIMITS.textMax))
end
elseif k == "clearalarm" or k == "stop" then

else
err(c, s, "not a statement: " .. tostring(k))
end
end

block = function(c, list, parent)
local scope = {names = {}, parent = parent}
for _, s in ipairs(list or {}) do statement(c, s, scope) end
end



local function sorted(set)
local out = {}
for key in pairs(set) do out[#out + 1] = key end
table.sort(out)
return out
end












function check.check(script, env)
local c = new(script, env)

if script.lang ~= parse.LANG then
err(c, script, ("this is language version %s, and this controller knows %d")
:format(tostring(script.lang), parse.LANG))
return check.report(c)
end
if type(script.machine) ~= "string" then
err(c, script, "a script starts with `machine <name>`")
return check.report(c)
end
if #(script.ports or {}) == 0 then
err(c, script, "a machine needs at least one port")
end

local declared = {}
local slotOwner = {}
for _, port in ipairs(script.ports or {}) do
if c.ports[port.name] then
err(c, port, ("%s is declared twice"):format(port.name))
else
c.ports[port.name] = port
local safe = nil
if port.safe then
if port.type == "volume" or port.direction ~= "output" then
err(c, port, "only an output signal has a safe value")
elseif port.type == "flag" and port.safe.kind ~= "onoff" then
err(c, port, "a flag is safe on or off")
elseif port.type == "level" and port.safe.kind ~= "num" then
err(c, port, "a level is safe at 0-15")
elseif port.safe.kind == "num" and port.safe.value > check.LIMITS.level then
err(c, port, "a level is safe at 0-15")
end
if port.safe.kind == "onoff" then safe = port.safe.value and 15 or 0
else safe = port.safe.value end
end

if port.slots then
if port.type ~= "volume" then
err(c, port, "only a volume has slots")
end
for _, slot in ipairs(port.slots) do
if slot < 1 or slot > check.LIMITS.slotMax then
err(c, port, ("slot %d is out of range (1-%d)"):format(slot,
check.LIMITS.slotMax))
elseif slotOwner[slot] then
err(c, port, ("slot %d is already %s's"):format(slot,
slotOwner[slot]))
else
slotOwner[slot] = port.name
end
end
end


local slots = nil
if port.slots then
slots = {}
for i, slot in ipairs(port.slots) do slots[i] = slot end
end
declared[#declared + 1] = {name = port.name, kind = port.type,
direction = port.direction, safe = safe, slots = slots}
end
end

if #(script.handlers or {}) == 0 then
err(c, script, "a script needs at least one handler: every, when or on")
end
local seen = {}
for _, h in ipairs(script.handlers or {}) do
if h.kind == "every" then
durationIn(c, h, h.every, check.LIMITS.everyMin, 24 * 72000, "`every`")
elseif h.kind == "when" then
condition(c, h.cond, nil, "`when`")
elseif h.kind == "on" then
if seen[h.event] then err(c, h, ("`on %s` is written twice"):format(h.event)) end
seen[h.event] = true
end
block(c, h.body, nil)
end

c.declared = declared
return check.report(c)
end

function check.report(c)
local function order(list)
table.sort(list, function(a, b)
if (a.line or 0) ~= (b.line or 0) then return (a.line or 0) < (b.line or 0) end
return (a.col or 0) < (b.col or 0)
end)
return list
end
return {
ok = #c.errors == 0,
errors = order(c.errors),
warnings = order(c.warnings),
ports = c.declared or {},
footprint = {
supplies = sorted(c.footprint.supplies),
writes = sorted(c.footprint.writes),
collects = sorted(c.footprint.collects),
drives = sorted(c.footprint.drives),
reads = sorted(c.footprint.reads),
},
}
end




function check.source(source, env)
local tree, errors = parse.parse(source)
if #errors > 0 then
return {ok = false, errors = errors, warnings = {}, ports = {},
footprint = {supplies = {}, writes = {}, collects = {}, drives = {},
reads = {}}, tree = tree}
end
local report = check.check(tree, env)
report.tree = tree
return report
end

return check
]],
["mfg/common/script/format.lua"] = [[











local format = {}

local PRECEDENCE = {["or"] = 1, ["and"] = 2, ["not"] = 3, cmp = 4}

local function dur(d)
return tostring(d.n) .. d.unit
end

local expr

local function wrapped(e, above)
local text = expr(e)
local mine = PRECEDENCE[e.kind]
if mine and mine < above then return "(" .. text .. ")" end
return text
end

expr = function(e)
local k = e.kind
if k == "num" then return tostring(e.value)
elseif k == "onoff" then return e.value and "on" or "off"
elseif k == "dur" then return dur(e)
elseif k == "item" then return e.value
elseif k == "text" then return '"' .. e.value .. '"'
elseif k == "name" then return e.name
elseif k == "count" then return ("count %s in %s"):format(e.item, e.port)
elseif k == "free" then return "free " .. e.item
elseif k == "paren" then return "(" .. expr(e.expr) .. ")"
elseif k == "not" then return "not " .. wrapped(e.expr, PRECEDENCE.cmp)
elseif k == "cmp" then
return ("%s %s %s"):format(wrapped(e.left, 5), e.op, wrapped(e.right, 5))
elseif k == "and" then
return wrapped(e.left, 2) .. " and " .. wrapped(e.right, 3)
elseif k == "or" then
return wrapped(e.left, 1) .. " or " .. wrapped(e.right, 2)
end
error("format: not an expression: " .. tostring(k), 0)
end

format.expr = expr


function format.slots(list)
local parts, i = {}, 1
while i <= #list do
local j = i
while j < #list and list[j + 1] == list[j] + 1 do j = j + 1 end
if j > i then
parts[#parts + 1] = list[i] .. "-" .. list[j]
else
parts[#parts + 1] = tostring(list[i])
end
i = j + 1
end
return table.concat(parts, ",")
end


local function head(s)
local k = s.kind
if k == "if" then return "if " .. expr(s.cond)
elseif k == "repeat" then return "repeat " .. tostring(s.n)
elseif k == "supply" then return ("supply %d %s to %s"):format(s.n, s.item, s.port)
elseif k == "stock" then return ("stock %s with %d %s"):format(s.port, s.n, s.item)
elseif k == "collect" then return "collect " .. s.port
elseif k == "move" then
return ("move %d %s from %s to %s"):format(s.n, s.item, s.from, s.to)
elseif k == "set" then return ("set %s to %s"):format(s.port, expr(s.value))
elseif k == "pulse" then return ("pulse %s for %s"):format(s.port, dur(s.length))
elseif k == "wait" then return "wait " .. dur(s.length)
elseif k == "waituntil" then
return ("wait until %s within %s"):format(expr(s.cond), dur(s.within))
elseif k == "let" then return ("let %s = %s"):format(s.name, expr(s.value))
elseif k == "alarm" then return ('alarm "%s"'):format(s.text)
elseif k == "clearalarm" then return "clear alarm"
elseif k == "stop" then return "stop"
elseif k == "every" then return "every " .. dur(s.every)
elseif k == "when" then return "when " .. expr(s.cond)
elseif k == "on" then return "on " .. s.event
end
error("format: not a statement: " .. tostring(k), 0)
end

local function emit(out, indent, text, comment, notes)
local pad = string.rep("\t", indent)
for _, note in ipairs(notes or {}) do out[#out + 1] = pad .. "--" .. note end
if comment then text = text .. "  --" .. comment end
out[#out + 1] = pad .. text
end

local block

block = function(out, list, indent)
for _, s in ipairs(list) do
emit(out, indent, head(s), s.comment, s.notes)
if s.body then block(out, s.body, indent + 1) end
if s.orelse then
emit(out, indent, "else", s.elseComment, s.elseNotes)
block(out, s.orelse, indent + 1)
end
end
end

function format.format(script)
local out = {}
emit(out, 0, "machine " .. tostring(script.machine), script.comment, script.notes)

local nameWidth = 0
for _, port in ipairs(script.ports or {}) do
nameWidth = math.max(nameWidth, #port.name)
end
for _, port in ipairs(script.ports or {}) do
local text = ("%-6s %-" .. nameWidth .. "s : %s"):format(port.direction,
port.name, port.type)
if port.slots then text = text .. " slots " .. format.slots(port.slots) end
if port.safe then text = text .. " safe " .. expr(port.safe) end
emit(out, 1, text, port.comment, port.notes)
end

for _, h in ipairs(script.handlers or {}) do
out[#out + 1] = ""
emit(out, 0, head(h), h.comment, h.notes)
block(out, h.body or {}, 1)
end

if script.trailing then
out[#out + 1] = ""
for _, note in ipairs(script.trailing) do out[#out + 1] = "--" .. note end
end
return table.concat(out, "\n") .. "\n"
end


function format.same(a, b)
if type(a) ~= type(b) then return false end
if type(a) ~= "table" then return a == b end
for key, value in pairs(a) do
if key ~= "span" and not format.same(value, b[key]) then return false end
end
for key in pairs(b) do
if key ~= "span" and a[key] == nil then return false end
end
return true
end

return format
]],
["mfg/common/script/interp.lua"] = [[

























local parse = require("mfg.common.script.parse")

local interp = {}

interp.BUDGET = 500
interp.POLL = 1

local OK = "completed"
local FAULTED = "faulted"
local ABORTED = "aborted"

local Run = {}
Run.__index = Run



function interp.new(tree, host, name)
local self = setmetatable({tree = tree, host = host, ports = {}, handlers = {},
budget = 0}, Run)
local base = "/" .. (name or tree.machine)
for _, port in ipairs(tree.ports or {}) do
self.ports[port.name] = {path = base .. "/" .. port.name,
type = port.type, direction = port.direction}
end
for index, node in ipairs(tree.handlers or {}) do
self.handlers[index] = {index = index, node = node, pending = false,
prev = false, nextAt = nil}
end
return self
end



local function fault(node, reason)
error({script = FAULTED, reason = reason, line = node and node.span and node.span.line},
0)
end

local function stepOn(self, node)
self.budget = self.budget + 1
if self.budget > interp.BUDGET then
fault(node, ("ran %d steps without waiting -- the step budget (X6.2)")
:format(interp.BUDGET))
end
end

local function yielded(self)
self.budget = 0
if self.host.stopping() then error({script = ABORTED}, 0) end
end



local eval

local function compare(op, a, b)
if op == "=" then return a == b
elseif op == "!=" then return a ~= b
elseif op == "<" then return a < b
elseif op == "<=" then return a <= b
elseif op == ">" then return a > b
elseif op == ">=" then return a >= b end
end

eval = function(self, e, scope)
stepOn(self, e)
local k = e.kind
if k == "num" then return e.value
elseif k == "onoff" then return e.value
elseif k == "paren" then return eval(self, e.expr, scope)
elseif k == "name" then
local s = scope
while s do
if s.values[e.name] ~= nil then return s.values[e.name] end
s = s.parent
end
local port = self.ports[e.name]
local value, why = self.host.read(port.path, port.type)
if value == nil then fault(e, why or ("could not read " .. port.path)) end
return value
elseif k == "count" then
local port = self.ports[e.port]
local n, why = self.host.count(port.path, e.item)
if n == nil then fault(e, why or ("could not read " .. port.path)) end
return n
elseif k == "free" then
local n, why = self.host.free(e.item)
if n == nil then fault(e, why or "could not read the pool") end
return n
elseif k == "cmp" then
return compare(e.op, eval(self, e.left, scope), eval(self, e.right, scope))
elseif k == "and" then
return eval(self, e.left, scope) and eval(self, e.right, scope)
elseif k == "or" then
return eval(self, e.left, scope) or eval(self, e.right, scope)
elseif k == "not" then
return not eval(self, e.expr, scope)
end
fault(e, "cannot evaluate " .. tostring(k))
end





local function waitUntil(self, deadline, until_)
while true do
if until_ and until_() then return true end
local now = self.host.now()
if now >= deadline then return false end
self.host.sleep(math.min(interp.POLL, (deadline - now) / 1000))
yielded(self)
self:watch()
end
end



local exec

local function invoke(self, s, action, params)
local status, fields = self.host.invoke(action, params)
yielded(self)
if status ~= OK then
fault(s, ("%s: %s"):format(s.kind, tostring(fields and fields.reason or status)))
end
return fields
end

local function statement(self, s, scope)
stepOn(self, s)
local k = s.kind
local port = s.port and self.ports[s.port]
if k == "if" then
if eval(self, s.cond, scope) then
exec(self, s.body, scope)
elseif s.orelse then
exec(self, s.orelse, scope)
end
elseif k == "repeat" then
for _ = 1, s.n do exec(self, s.body, scope) end
elseif k == "supply" or k == "stock" then
invoke(self, s, "supply", {port = port.path, item = s.item, count = s.n,
upto = k == "stock"})
elseif k == "collect" then
invoke(self, s, "collect", {port = port.path})
elseif k == "move" then
invoke(self, s, "move", {from = self.ports[s.from].path,
to = self.ports[s.to].path, item = s.item, count = s.n})
elseif k == "set" then
local level = s.value.kind == "onoff" and (s.value.value and 15 or 0)
or s.value.value
invoke(self, s, "set_signal", {signal = port.path, level = level})
elseif k == "pulse" then
invoke(self, s, "pulse", {signal = port.path, length = parse.ticks(s.length)})
elseif k == "wait" then
waitUntil(self, self.host.now() + parse.ticks(s.length) * 50)
elseif k == "waituntil" then
local within = parse.ticks(s.within) * 50
local met = waitUntil(self, self.host.now() + within,
function() return eval(self, s.cond, scope) end)
if not met then
fault(s, ("waited %s and it did not happen"):format(
tostring(s.within.n) .. s.within.unit))
end
elseif k == "let" then
scope.values[s.name] = eval(self, s.value, scope)
elseif k == "alarm" then
self.host.alarm(s.text)
elseif k == "clearalarm" then
self.host.clearAlarm()
elseif k == "stop" then
error({script = OK, stopped = true}, 0)
else
fault(s, "cannot run " .. tostring(k))
end
end

exec = function(self, list, parent)
local scope = {values = {}, parent = parent}
for _, s in ipairs(list or {}) do statement(self, s, scope) end
end






function interp.beat(now, period)
return (math.floor(now / period) + 1) * period
end


function Run:start(now)
for _, h in ipairs(self.handlers) do
if h.node.kind == "every" then
h.nextAt = interp.beat(now, parse.ticks(h.node.every) * 50)
end
end
end




function Run:skip(now)
for _, h in ipairs(self.handlers) do
h.pending = false
if h.node.kind == "every" and h.nextAt and h.nextAt <= now then
h.nextAt = interp.beat(now, parse.ticks(h.node.every) * 50)
end
end
end


function Run:on(event)
for _, h in ipairs(self.handlers) do
if h.node.kind == "on" and h.node.event == event then return h end
end
end




function Run:watch()
local faults = {}
for _, h in ipairs(self.handlers) do
if h.node.kind == "when" and not self.watching then
self.watching = true
local saved = self.budget
self.budget = 0
local ok, result = pcall(eval, self, h.node.cond, nil)
self.budget = saved
self.watching = false
if ok then
local now = result and true or false
if now and not h.prev then h.pending = true end
h.prev = now
elseif type(result) == "table" and result.script == ABORTED then
error(result, 0)
else
faults[#faults + 1] = {handler = h,
reason = type(result) == "table" and result.reason or tostring(result)}
end
end
end
return faults
end



function Run:due(now)
for _, h in ipairs(self.handlers) do
if h.pending then return h end
if h.node.kind == "every" and h.nextAt and h.nextAt <= now then return h end
end
end


function Run:nextAt()
local soonest = nil
for _, h in ipairs(self.handlers) do
if h.nextAt and (not soonest or h.nextAt < soonest) then soonest = h.nextAt end
end
return soonest
end





function Run:runHandler(h)
local began = self.host.now()
h.pending = false
if h.node.kind == "every" then
h.nextAt = interp.beat(began, parse.ticks(h.node.every) * 50)
end
self.budget = 0
local ok, result = pcall(exec, self, h.node.body, nil)
if ok then return {status = OK} end
if type(result) == "table" and result.script then
return {status = result.script, reason = result.reason, line = result.line,
stopped = result.stopped}
end
return {status = FAULTED, reason = tostring(result)}
end

interp.COMPLETED = OK
interp.FAULTED = FAULTED
interp.ABORTED = ABORTED

return interp
]],
["mfg/common/script/lex.lua"] = [=[















local lex = {}

lex.KEYWORDS = {}
for word in ([[machine input output volume level flag safe every when on start stop
    if else supply stock collect move set pulse wait until within repeat let alarm
    clear to with from for in count free and or not off slots]]):gmatch("%S+") do
lex.KEYWORDS[word] = true
end

local OPS = {"<=", ">=", "!=", "<", ">", "=", "(", ")", ":", ",", "-"}


local function splitComment(text)
local inString = false
for i = 1, #text do
local c = text:sub(i, i)
if c == '"' then
inString = not inString
elseif not inString and text:sub(i, i + 1) == "--" then
return text:sub(1, i - 1), text:sub(i + 2)
end
end
return text, nil
end


local function tokens(code, lineNo)
local out = {}
local i = 1
while i <= #code do
local c = code:sub(i, i)
if c == " " or c == "\t" then
i = i + 1
elseif c == '"' then
local close = code:find('"', i + 1, true)
if not close then
return nil, {line = lineNo, col = i, message = "text is not closed with \""}
end
out[#out + 1] = {t = "text", v = code:sub(i + 1, close - 1), col = i}
i = close + 1
else
local item = code:match("^[a-z0-9_.%-]+:[a-z0-9_./%-]+", i)
local dur = code:match("^%d+[tsm]", i)
local num = code:match("^%d+", i)
local word = code:match("^[a-z_][a-z0-9_]*", i)
if item then
out[#out + 1] = {t = "item", v = item, col = i}
i = i + #item
elseif dur and not code:sub(i + #dur, i + #dur):match("[%w_]") then
out[#out + 1] = {t = "dur", v = tonumber(dur:sub(1, -2)),
unit = dur:sub(-1), col = i}
i = i + #dur
elseif num then
if code:sub(i + #num, i + #num):match("[%a_]") then
return nil, {line = lineNo, col = i,
message = "a number runs into letters: " .. code:match("^%S+", i)}
end
out[#out + 1] = {t = "num", v = tonumber(num), col = i}
i = i + #num
elseif word then
out[#out + 1] = {t = "word", v = word, col = i}
i = i + #word
else
local op = nil
for _, candidate in ipairs(OPS) do
if code:sub(i, i + #candidate - 1) == candidate then
op = candidate
break
end
end
if not op then
local what = code:match("^%S+", i)
local message = what:match("%u")
and ("keywords and names are lowercase: %s"):format(what)
or ("not something a script can say: %s"):format(what)
return nil, {line = lineNo, col = i, message = message}
end
out[#out + 1] = {t = "op", v = op, col = i}
i = i + #op
end
end
end
return out
end



function lex.steps(lead)
local _, tabs = lead:gsub("\t", "")
local spaces = #lead - tabs
if spaces % 4 ~= 0 then return nil end
return tabs + math.floor(spaces / 4)
end




function lex.lines(source)
local out, errors = {}, {}
local lineNo = 0
source = (source or ""):gsub("\r\n", "\n")
if source:sub(-1) ~= "\n" then source = source .. "\n" end
for text in source:gmatch("([^\n]*)\n") do
lineNo = lineNo + 1
local lead = text:match("^[ \t]*")
local steps = lex.steps(lead)
local record = {line = lineNo, indent = steps or 0, tokens = {}}
if not steps and text:find("%S") then
errors[#errors + 1] = {line = lineNo, col = 1,
message = "indent with tabs, one per step (four spaces also count as one)"}
record.bad = true
else
local code, comment = splitComment(text:sub(#lead + 1))
record.comment = comment
local toks, err = tokens(code, lineNo)
if toks then
for _, tok in ipairs(toks) do tok.col = tok.col + #lead end
record.tokens = toks
else
err.col = err.col + #lead
errors[#errors + 1] = err
record.bad = true
end
end
record.blank = (not record.bad) and #record.tokens == 0 and record.comment == nil
out[#out + 1] = record
end
return out, errors
end

return lex
