["mfg/common/script/parse.lua"] = [[













local lex = require("mfg.common.script.lex")

local parse = {}

parse.LANG = 1

local DIRECTIONS = {input = true, output = true}
local PORT_KINDS = {volume = true, level = true, flag = true}



local Cursor = {}
Cursor.__index = Cursor

local function cursor(line, p)
return setmetatable({line = line, toks = line.tokens, i = 1, p = p}, Cursor)
end

function Cursor:peek() return self.toks[self.i] end

function Cursor:col()
local tok = self.toks[self.i] or self.toks[#self.toks]
if not tok then return 1 end
return self.toks[self.i] and tok.col or (tok.col + #tostring(tok.v))
end

function Cursor:fail(message)
error({parse = true, line = self.line.line, col = self:col(), message = message}, 0)
end

function Cursor:take() local tok = self.toks[self.i]; self.i = self.i + 1; return tok end

function Cursor:isWord(word)
local tok = self:peek()
return tok ~= nil and tok.t == "word" and tok.v == word
end

function Cursor:isOp(op)
local tok = self:peek()
return tok ~= nil and tok.t == "op" and tok.v == op
end

function Cursor:word(word)
if not self:isWord(word) then
local tok = self:peek()
self:fail(("expected `%s`%s"):format(word,
tok and (", found " .. tostring(tok.v)) or " at the end of the line"))
end
return self:take()
end

function Cursor:op(op)
if not self:isOp(op) then self:fail(("expected `%s`"):format(op)) end
return self:take()
end


function Cursor:name(what)
local tok = self:peek()
if not tok or tok.t ~= "word" then
self:fail(("expected %s"):format(what))
end
if lex.KEYWORDS[tok.v] then
self:fail(("`%s` is a keyword and cannot be %s"):format(tok.v, what))
end
return self:take().v
end

function Cursor:kind(t, what)
local tok = self:peek()
if not tok or tok.t ~= t then self:fail(("expected %s"):format(what)) end
return self:take()
end

function Cursor:finish()
local tok = self:peek()
if tok then self:fail(("unexpected %s at the end of the line"):format(tostring(tok.v))) end
end



local function node(p, kind, line, col, fields)
p.nextId = p.nextId + 1
fields = fields or {}
fields.kind = kind
fields.id = p.nextId
fields.span = {line = line, col = col}
return fields
end



local parseCond

local function primary(c)
local tok = c:peek()
if not tok then c:fail("expected a value") end
local line = c.line.line
if tok.t == "num" then
c:take()
return node(c.p, "num", line, tok.col, {value = tok.v})
elseif tok.t == "dur" then
c:take()
return node(c.p, "dur", line, tok.col, {n = tok.v, unit = tok.unit})
elseif tok.t == "item" then
c:take()
return node(c.p, "item", line, tok.col, {value = tok.v})
elseif tok.t == "text" then
c:take()
return node(c.p, "text", line, tok.col, {value = tok.v})
elseif tok.t == "op" and tok.v == "(" then
c:take()
local inner = parseCond(c)
c:op(")")
return node(c.p, "paren", line, tok.col, {expr = inner})
elseif tok.t == "word" then
if tok.v == "on" or tok.v == "off" then
c:take()
return node(c.p, "onoff", line, tok.col, {value = tok.v == "on"})
elseif tok.v == "count" then
c:take()
local item = c:kind("item", "an item, like minecraft:coal").v
c:word("in")
local port = c:name("a port")
return node(c.p, "count", line, tok.col, {item = item, port = port})
elseif tok.v == "free" then
c:take()
local item = c:kind("item", "an item, like minecraft:coal").v
return node(c.p, "free", line, tok.col, {item = item})
end
local name = c:name("a value")
return node(c.p, "name", line, tok.col, {name = name})
end
c:fail(("expected a value, found %s"):format(tostring(tok.v)))
end

local RELOPS = {["<"] = true, ["<="] = true, [">"] = true, [">="] = true,
["="] = true, ["!="] = true}

local function rel(c)
local left = primary(c)
local tok = c:peek()
if tok and tok.t == "op" and RELOPS[tok.v] then
c:take()
local right = primary(c)
return node(c.p, "cmp", left.span.line, left.span.col,
{op = tok.v, left = left, right = right})
end
return left
end

local function neg(c)
if c:isWord("not") then
local tok = c:take()
return node(c.p, "not", c.line.line, tok.col, {expr = rel(c)})
end
return rel(c)
end

local function conj(c)
local left = neg(c)
while c:isWord("and") do
c:take()
left = node(c.p, "and", left.span.line, left.span.col, {left = left, right = neg(c)})
end
return left
end

parseCond = function(c)
local left = conj(c)
while c:isWord("or") do
c:take()
left = node(c.p, "or", left.span.line, left.span.col, {left = left, right = conj(c)})
end
return left
end

local function duration(c, what)
local tok = c:kind("dur", what or "a duration, like 5s, 4t or 2m")
return {n = tok.v, unit = tok.unit}
end

local function literal(c)
local tok = c:peek()
local line = c.line.line
if tok and tok.t == "num" then
c:take()
return node(c.p, "num", line, tok.col, {value = tok.v})
elseif tok and tok.t == "word" and (tok.v == "on" or tok.v == "off") then
c:take()
return node(c.p, "onoff", line, tok.col, {value = tok.v == "on"})
end
c:fail("expected a level (0-15) or on/off")
end





local function tree(lines, errors)
local root = {children = {}, level = -1}
local stack = {root}
local notes = {}
for _, line in ipairs(lines) do
if line.bad then

line.skip = true
end
if line.blank then

elseif #line.tokens == 0 and not line.bad then
notes[#notes + 1] = line.comment
else
local level = line.indent
while stack[#stack].level >= level do table.remove(stack) end
local parent = stack[#stack]
if level > parent.level + 1 and not line.bad then
errors[#errors + 1] = {line = line.line, col = 1,
message = "indented too far: one step (one tab) more than "
.. "the line it belongs to"}
line.skip = true
end
local entry = {line = line, children = {}, level = level, notes = notes}
notes = {}
parent.children[#parent.children + 1] = entry
stack[#stack + 1] = entry
end
end
return root.children, notes
end

local function attach(n, entry)
if #entry.notes > 0 then n.notes = entry.notes end
if entry.line.comment then n.comment = entry.line.comment end
return n
end

local parseBlock


local function statement(p, entry)
local c = cursor(entry.line, p)
local tok = c:peek()
local line, col = entry.line.line, tok.col
local function done(n)
c:finish()
return attach(n, entry)
end
local function needsBlock(n)
if #entry.children == 0 then c:fail(("`%s` needs an indented block under it")
:format(tok.v)) end
c:finish()
attach(n, entry)
n.body = parseBlock(p, entry.children)
return n
end
local function noBlock()
if #entry.children > 0 then
error({parse = true, line = entry.children[1].line.line, col = 1,
message = ("nothing may be indented under `%s`"):format(tok.v)}, 0)
end
end

if tok.t ~= "word" then c:fail("a line starts with a keyword") end
local word = tok.v
c:take()

if word == "if" then
return needsBlock(node(p, "if", line, col, {cond = parseCond(c)}))
elseif word == "repeat" then
return needsBlock(node(p, "repeat", line, col,
{n = c:kind("num", "how many times, 1-64").v}))
end

noBlock()
if word == "supply" then
local n = c:kind("num", "how many").v
local item = c:kind("item", "an item, like minecraft:coal").v
c:word("to")
return done(node(p, "supply", line, col, {n = n, item = item, port = c:name("a port")}))
elseif word == "stock" then
local port = c:name("a port")
c:word("with")
local n = c:kind("num", "how many").v
local item = c:kind("item", "an item, like minecraft:coal").v
return done(node(p, "stock", line, col, {port = port, n = n, item = item}))
elseif word == "collect" then
return done(node(p, "collect", line, col, {port = c:name("a port")}))
elseif word == "move" then
local n = c:kind("num", "how many").v
local item = c:kind("item", "an item, like minecraft:coal").v
c:word("from")
local from = c:name("a port")
c:word("to")
return done(node(p, "move", line, col, {n = n, item = item, from = from,
to = c:name("a port")}))
elseif word == "set" then
local port = c:name("a port")
c:word("to")
return done(node(p, "set", line, col, {port = port, value = literal(c)}))
elseif word == "pulse" then
local port = c:name("a port")
c:word("for")
return done(node(p, "pulse", line, col, {port = port, length = duration(c)}))
elseif word == "wait" then
if c:isWord("until") then
c:take()
local cond = parseCond(c)
if not c:isWord("within") then
c:fail("`wait until` needs `within <duration>`: how long before it "
.. "gives up")
end
c:take()
return done(node(p, "waituntil", line, col, {cond = cond,
within = duration(c)}))
end
return done(node(p, "wait", line, col, {length = duration(c)}))
elseif word == "let" then
local name = c:name("a name")
c:op("=")
return done(node(p, "let", line, col, {name = name, value = parseCond(c)}))
elseif word == "alarm" then
return done(node(p, "alarm", line, col,
{text = c:kind("text", "the alarm's text, in double quotes").v}))
elseif word == "clear" then
c:word("alarm")
return done(node(p, "clearalarm", line, col))
elseif word == "stop" then
return done(node(p, "stop", line, col))
elseif word == "else" then
c:fail("`else` without an `if` just above it")
end
c:fail(("`%s` does not start a statement"):format(word))
end


parseBlock = function(p, entries)
local out = {}
for _, entry in ipairs(entries) do
if entry.line.skip then

else
local first = entry.line.tokens[1]
local ok, result = pcall(function()
if first and first.t == "word" and first.v == "else"
and #entry.line.tokens == 1 then
local prev = out[#out]
if not prev or prev.kind ~= "if" or prev.orelse then
error({parse = true, line = entry.line.line, col = first.col,
message = "`else` without an `if` just above it"}, 0)
end
if #entry.children == 0 then
error({parse = true, line = entry.line.line, col = first.col,
message = "`else` needs an indented block under it"}, 0)
end
if #entry.notes > 0 then prev.elseNotes = entry.notes end
prev.elseComment = entry.line.comment
prev.orelse = parseBlock(p, entry.children)
return nil
end
return statement(p, entry)
end)
if not ok then
if type(result) == "table" and result.parse then
p.errors[#p.errors + 1] = {line = result.line, col = result.col,
message = result.message}
else
error(result, 0)
end
elseif result then
out[#out + 1] = result
end
end
end
return out
end



local function port(p, entry)
local c = cursor(entry.line, p)
local tok = c:peek()
if not tok or tok.t ~= "word" or not DIRECTIONS[tok.v] then
c:fail("a port starts with `input` or `output`")
end
c:take()
local name = c:name("a port name")
c:op(":")
local kindTok = c:kind("word", "volume, level or flag")
if not PORT_KINDS[kindTok.v] then
c.i = c.i - 1
c:fail("a port is a volume, a level or a flag")
end
local n = node(p, "port", entry.line.line, tok.col,
{direction = tok.v, name = name, type = kindTok.v})


if c:isWord("slots") then
c:take()
local list, seen = {}, {}
repeat
if #list > 0 then c:op(",") end
local from = c:kind("num", "a slot number").v
local to = from
if c:isOp("-") then
c:take()
to = c:kind("num", "the last slot of the range").v
if to < from then c:fail("a slot range runs upwards: 1-3, not 3-1") end
end
for slot = from, to do
if not seen[slot] then list[#list + 1] = slot; seen[slot] = true end
end
until not c:isOp(",")
table.sort(list)
n.slots = list
end
if c:isWord("safe") then
c:take()
n.safe = literal(c)
end
c:finish()
if #entry.children > 0 then
error({parse = true, line = entry.children[1].line.line, col = 1,
message = "nothing may be indented under a port"}, 0)
end
return attach(n, entry)
end

local function handler(p, entry)
local c = cursor(entry.line, p)
local tok = c:peek()
local line, col = entry.line.line, tok and tok.col or 1
local n
if c:isWord("every") then
c:take()
n = node(p, "every", line, col, {every = duration(c)})
elseif c:isWord("when") then
c:take()
n = node(p, "when", line, col, {cond = parseCond(c)})
elseif c:isWord("on") then
c:take()
local event = c:peek()
if not event or event.t ~= "word" or (event.v ~= "start" and event.v ~= "stop") then
c:fail("`on start` or `on stop`")
end
c:take()
n = node(p, "on", line, col, {event = event.v})
else
c:fail("a handler starts with `every`, `when` or `on`")
end
c:finish()
if #entry.children == 0 then
c:fail("a handler needs an indented block under it")
end
attach(n, entry)
n.body = parseBlock(p, entry.children)
return n
end



function parse.parse(source)
local lines, errors = lex.lines(source)
local p = {nextId = 0, errors = errors}
local entries, trailing = tree(lines, errors)

local script = {kind = "script", lang = parse.LANG, id = 0, span = {line = 1, col = 1},
ports = {}, handlers = {}}

local function guard(fn)
local ok, err = pcall(fn)
if not ok then
if type(err) == "table" and err.parse then
errors[#errors + 1] = {line = err.line, col = err.col, message = err.message}
else
error(err, 0)
end
end
end

local first = entries[1]
if not first then
errors[#errors + 1] = {line = 1, col = 1,
message = "a script starts with `machine <name>`"}
elseif not first.line.skip then
guard(function()
local c = cursor(first.line, p)
c:word("machine")
script.machine = c:name("the machine's name")
c:finish()
script.span = {line = first.line.line, col = 1}
attach(script, first)
for _, child in ipairs(first.children) do
if not child.line.skip then
guard(function() script.ports[#script.ports + 1] = port(p, child) end)
end
end
end)
end

for i = 2, #entries do
local entry = entries[i]
if not entry.line.skip then
guard(function() script.handlers[#script.handlers + 1] = handler(p, entry) end)
end
end

if #trailing > 0 then script.trailing = trailing end
script.nextId = p.nextId
table.sort(errors, function(a, b)
if a.line ~= b.line then return a.line < b.line end
return (a.col or 0) < (b.col or 0)
end)
return script, errors
end


function parse.ticks(d)
if not d then return 0 end
if d.unit == "t" then return d.n end
if d.unit == "s" then return d.n * 20 end
if d.unit == "m" then return d.n * 1200 end
return 0
end

return parse
]],
["mfg/common/services.lua"] = [[



















local services = {}

services.STOPPED = "stopped"
services.WAITING = "waiting"
services.RUNNING = "running"
services.RESTARTING = "restarting"
services.HALTED = "halted"



local BACKOFF = {1, 2, 4, 8, 15, 30}
local GIVE_UP_AFTER = 8




local STABLE_AFTER = 60 * 1000




local LOG_LINES = 80



function services.new(opts)
opts = opts or {}
return {
name = opts.name or "node",
list = {},
order = {},
halted = nil,
clock = opts.clock,
sleeper = opts.sleeper,
}
end

local function now(manager)
if manager.clock then return manager.clock() end
return os.epoch("utc")
end

local function pause(manager, seconds)
if manager.sleeper then return manager.sleeper(seconds) end
sleep(seconds)
end





function services.declare(manager, spec)
if type(spec) ~= "table" or not spec.name then
return nil, "a service needs a name"
end
if type(spec.start) ~= "function" then
return nil, ("service %s needs a start function"):format(spec.name)
end
if manager.list[spec.name] then
return nil, ("service %s is already declared"):format(spec.name)
end

local record = {
name = spec.name,
start = spec.start,
critical = spec.critical or false,
requires = spec.requires or {},
ready = spec.ready,
restart = spec.restart ~= false,


terminal = spec.terminal or false,
state = services.STOPPED,
restarts = 0,
attempts = 0,
failures = 0,
lastError = nil,
startedAt = nil,
log = {},
}
manager.list[spec.name] = record
manager.order[#manager.order + 1] = spec.name
return record
end

function services.get(manager, name)
return manager.list[name]
end






function services.log(manager, name, line)
local record = manager.list[name]
if not record then return end

record.log[#record.log + 1] = {at = now(manager), text = tostring(line)}
while #record.log > LOG_LINES do table.remove(record.log, 1) end
end

function services.logs(manager, name, count)
local record = manager.list[name]
if not record then return {} end
local out = {}
local from = math.max(1, #record.log - (count or LOG_LINES) + 1)
for i = from, #record.log do out[#out + 1] = record.log[i] end
return out
end






function services.capture(manager, name, target)
local buffer = ""

local function flush()
if #buffer > 0 then
services.log(manager, name, buffer)
buffer = ""
end
end

local proxy = {}
setmetatable(proxy, {__index = target})

proxy.write = function(text)
buffer = buffer .. tostring(text)
if target and target.write then target.write(text) end
end
proxy.blit = function(text, fg, bg)
buffer = buffer .. tostring(text)
if target and target.blit then target.blit(text, fg, bg) end
end


proxy.setCursorPos = function(x, y)
flush()
if target and target.setCursorPos then target.setCursorPos(x, y) end
end
proxy.clear = function()
flush()
if target and target.clear then target.clear() end
end
proxy.flush = flush

return proxy
end







local function ready(manager, record)
for _, name in ipairs(record.requires) do
local dependency = manager.list[name]
if not dependency or dependency.state ~= services.RUNNING then
return false, ("waiting for %s"):format(name)
end
end
if record.ready then
local ok, why = record.ready()
if not ok then return false, why or "not ready" end
end
return true
end

services.ready = ready









local function backoffFor(attempt)
local index = math.min(math.max(tonumber(attempt) or 1, 1), #BACKOFF)
return BACKOFF[index]
end

services.backoffFor = backoffFor





local function supervise(manager, record)
while true do
if manager.halted then return end

local isReady, why = ready(manager, record)
if not isReady then
if record.state ~= services.WAITING then
record.state = services.WAITING
record.blockedOn = why
services.log(manager, record.name, why)
end
pause(manager, 1)
else
record.state = services.RUNNING
record.blockedOn = nil
record.startedAt = now(manager)
services.log(manager, record.name, "started")

local ok, err = pcall(record.start)




if not ok and tostring(err) == "Terminated" then
manager.halted = manager.halted or "Terminated"
return
end

if manager.halted then return end

local ranFor = now(manager) - (record.startedAt or now(manager))

if ok then

services.log(manager, record.name,
("exited after %ds"):format(math.floor(ranFor / 1000)))
else
record.failures = record.failures + 1
record.lastError = tostring(err)



services.log(manager, record.name, "ERROR " .. tostring(err))
end







if ranFor >= STABLE_AFTER then
record.attempts = 0
else
record.attempts = (record.attempts or 0) + 1
end

if not record.restart then
record.state = services.STOPPED
return
end

if record.attempts >= GIVE_UP_AFTER then
record.state = services.HALTED
services.log(manager, record.name,
("gave up after %d short-lived start(s), %d of them errors")
:format(record.attempts, record.failures))


if record.critical then
manager.halted = ("critical service %s gave up after %d "
.. "short-lived starts: %s"):format(record.name,
record.attempts,
tostring(record.lastError or "it kept exiting"))
end
return
end

record.restarts = record.restarts + 1
record.state = services.RESTARTING



local wait = backoffFor(record.restarts)
services.log(manager, record.name,
("restarting in %ds (attempt %d)"):format(wait, record.restarts))
pause(manager, wait)
end
end
end

services.supervise = supervise





function services.stop(manager, name)
local record = manager.list[name]
if not record then return false, "no such service: " .. tostring(name) end
record.restart = false
record.state = services.STOPPED
services.log(manager, name, "stopped by operator")
return true
end

function services.start(manager, name)
local record = manager.list[name]
if not record then return false, "no such service: " .. tostring(name) end
record.restart = true
record.failures = 0
record.attempts = 0
record.state = services.WAITING
services.log(manager, name, "started by operator")
return true
end






function services.status(manager)
local out = {}
for _, name in ipairs(manager.order) do
local record = manager.list[name]
out[#out + 1] = {
name = record.name,
state = record.state,
critical = record.critical,
restarts = record.restarts,
attempts = record.attempts,
failures = record.failures,
lastError = record.lastError,
blockedOn = record.blockedOn,
uptime = record.startedAt and (now(manager) - record.startedAt) or nil,
}
end
return out
end

function services.halted(manager)
return manager.halted
end



function services.terminalOwner(manager)
for _, name in ipairs(manager.order) do
if manager.list[name].terminal then return name end
end
return nil
end



















local INPUT = {key = true, key_up = true, char = true, paste = true,
mouse_click = true, mouse_up = true, mouse_drag = true, mouse_scroll = true}




local function sink(manager, name)
local native = term.native()
local width, height = native.getSize()
return services.capture(manager, name,
window.create(native, 1, 1, width, height, false))
end



local function schedule(manager, tasks)
local owner = services.terminalOwner(manager)
local ownerRecord = owner and manager.list[owner]
local routines, filters, alive = {}, {}, 0
for i, task in ipairs(tasks) do
routines[i] = coroutine.create(task.fn)
if not task.ends then alive = alive + 1 end
end

local event = {n = 0}
local function isOwned()
return ownerRecord ~= nil and ownerRecord.state == services.RUNNING
end
while true do
local name = event[1]


local ownedAtEvent = isOwned()
for i, task in ipairs(tasks) do


local owned = isOwned()
local routine = routines[i]
local hears = not (ownedAtEvent and INPUT[name] and task.name ~= owner)
if routine and hears and (filters[i] == nil or filters[i] == name
or name == "terminate") then
local redirect = owned and task.sink and task.name ~= owner
local previous
if redirect then previous = term.redirect(task.sink) end
local ok, param = coroutine.resume(routine, table.unpack(event, 1, event.n))
if redirect then

task.sink = term.current()
term.redirect(previous)
end
if not ok then error(param, 0) end
filters[i] = param
if coroutine.status(routine) == "dead" then
routines[i] = nil
if task.ends then return end
alive = alive - 1
if alive == 0 then return end
end
end
end
event = table.pack(os.pullEventRaw())
end
end





function services.run(manager)
local owner = services.terminalOwner(manager)
local tasks = {}
for _, name in ipairs(manager.order) do
local record = manager.list[name]
tasks[#tasks + 1] = {name = name,
sink = (owner and name ~= owner) and sink(manager, name) or nil}
tasks[#tasks].fn = function()







local ok, err = pcall(supervise, manager, record)
if not ok then
services.log(manager, record.name,
"SUPERVISOR ERROR " .. tostring(err))
record.state = services.HALTED
record.lastError = tostring(err)
if record.critical then
manager.halted = ("the supervisor for critical service %s "
.. "failed: %s"):format(record.name, tostring(err))
end
end
end
end
if #tasks == 0 then return end





tasks[#tasks + 1] = {name = "(halt)", ends = true, fn = function()
while not manager.halted do sleep(0.5) end
end}
schedule(manager, tasks)
return manager.halted
end

return services
]],
["mfg/common/signed.lua"] = [[



















local ed25519 = require("ccryptolib.ed25519")
local ccutil = require("ccryptolib.util")

local signed = {}









signed.ANCHOR = "/boot/signer"

local function isHexKey(hex, bytes)
return type(hex) == "string" and #hex == bytes * 2 and not hex:find("%X")
end



function signed.sign(context, data)
local netkeys = require("netkeys")





local random = require("ccryptolib.random")
if not random.isInit() then random.initWithTiming() end
local sig = netkeys.sign(context, data)
return ccutil.toHex(netkeys.signingKey()), ccutil.toHex(sig)
end



function signed.verify(context, data, signerHex, sigHex, anchors)
if not isHexKey(signerHex, 32) then return nil, "no signer, or a malformed one" end
if not isHexKey(sigHex, 64) then return nil, "no signature, or a malformed one" end

local signer = ccutil.fromHex(signerHex)
local trusted = false
for _, anchor in ipairs(anchors or {}) do
if anchor == signer then trusted = true break end
end
if not trusted then return nil, "signed by a key this node does not trust: " .. signerHex end

if not ed25519.verify(signer, context .. data, ccutil.fromHex(sigHex)) then
return nil, "bad signature"
end
return true
end


function signed.anchor(path)
path = path or signed.ANCHOR
local hex = require("mfg.common.state").readText(path)
if not hex then return nil, "no firmware anchor at " .. path end
hex = hex:gsub("%s", "")
if not isHexKey(hex, 32) then return nil, "the firmware anchor at " .. path .. " is corrupt" end
return ccutil.fromHex(hex)
end

return signed
]],
["mfg/common/state.lua"] = [[






























local state = {}

local ROOT = "/mfg/state"


local SCHEMA_KEY = "~schema"

local function pathFor(name)
return fs.combine(ROOT, name)
end

local function slurp(path, binary)
local handle = fs.open(path, binary and "rb" or "r")
if not handle then return nil, "could not open " .. path end
local text = handle.readAll() or ""
handle.close()
return text
end






function state.readText(path, binary)
if fs.exists(path) then return slurp(path, binary) end
local temp = path .. ".new"
if not fs.exists(temp) then return nil end
local text, why = slurp(temp, binary)
if text == nil then return nil, why end
fs.move(temp, path)
return text
end



function state.writeText(path, text, binary)
local dir = fs.getDir(path)
if dir ~= "" and not fs.exists(dir) then fs.makeDir(dir) end

local temp = path .. ".new"
if fs.exists(temp) then fs.delete(temp) end

local handle = fs.open(temp, binary and "wb" or "w")
if not handle then return false, "could not write " .. temp end
handle.write(text)
handle.close()

if fs.exists(path) then fs.delete(path) end
fs.move(temp, path)
return true
end



function state.readFile(path)
local text, why = state.readText(path)
if text == nil then return nil, why end
local ok, parsed = pcall(textutils.unserialize, text)
if not ok or parsed == nil then return nil, "unreadable state at " .. path end
return parsed
end

function state.writeFile(path, value)
return state.writeText(path, textutils.serialize(value))
end

local function stamped(value)
return type(value) == "table" and value[SCHEMA_KEY] ~= nil
end










function state.read(name, fallback, opts)
local path = pathFor(name)
local parsed, why = state.readFile(path)
if parsed == nil then return fallback, why end

local version, value = 0, parsed
if stamped(parsed) then version, value = parsed[SCHEMA_KEY], parsed.value end

local want = opts and opts.schema
if not want then return value end

if version > want then
return fallback, ("state %s is schema %d; this software understands %d"):format(
name, version, want)
end
if version < want then
if not opts.migrate then
return fallback, ("state %s is schema %d and nothing migrates it to %d"):format(
name, version, want)
end
local ok, migrated = pcall(opts.migrate, value, version)
if not ok then
return fallback, ("state %s: migrating from schema %d failed: %s"):format(
name, version, tostring(migrated))
end
value = migrated
end
return value
end

function state.write(name, value, opts)
if opts and opts.schema then
value = {[SCHEMA_KEY] = opts.schema, value = value}
end
return state.writeFile(pathFor(name), value)
end

function state.clear(name)
local path = pathFor(name)
if fs.exists(path) then fs.delete(path) end
if fs.exists(path .. ".new") then fs.delete(path .. ".new") end
end





function state.update(name, fields, opts)
local current, why = state.read(name, {}, opts)


if why and opts and opts.schema then return false, why end
if type(current) ~= "table" then current = {} end
for k, v in pairs(fields) do current[k] = v end
return state.write(name, current, opts)
end

return state
]],
