["mfg/controller/actions/withdraw.lua"] = [[
local rpc = require("mfg.common.rpc")
local actions = require("mfg.common.actions")
local store = require("mfg.storage")
local ports = require("mfg.controller.ports")
local supervisor = require("mfg.controller.supervisor")












return {
name        = "withdraw",
label       = "Withdraw from the pool",
tier        = "orchestrated",
uses        = {"move"},
policy      = true,
destructive = false,

parameters = {
{name = "item", label = "Item", type = "item", required = true,
choices = {source = "items"}},
{name = "count", label = "Count", type = "number", integer = true,
min = 1, max = 3456, required = true,
help = "How many. At most what no queued job has been promised."},
},

returns = {moved = "number", short = "number"},

run = function(params, ctx)
if not store.isBound(ports.OUT) then
return rpc.REJECTED, {reason = ("%s is not bound -- mfgctl bind %s "
.. "<chest>"):format(ports.OUT, ports.OUT)}
end

local pool = require("mfg.common.config").setting("source")
local available, breakdown = supervisor.available(pool)
if not available then return rpc.REJECTED, {reason = tostring(breakdown)} end

local free = available[params.item] or 0
if params.count > free then
local held = breakdown.stock[params.item] or 0
local promised = {}
for _, claim in ipairs(breakdown.byJob[params.item] or {}) do
promised[#promised + 1] = ("%d to job %d"):format(
math.floor(claim.count), claim.job)
end
return rpc.REJECTED, {free = free, reason = ("only %d %s free: the pool "
.. "holds %d%s"):format(free, params.item, held,
#promised > 0 and (", " .. table.concat(promised, ", ") .. " promised")
or "")}
end

local status, fields = actions.invoke("move", {from = pool, to = ports.OUT,
item = params.item, count = params.count}, ctx)
if status ~= rpc.COMPLETED then
return rpc.REJECTED, {reason = tostring(fields.reason)}
end
local moved = fields.moved or 0
local short = params.count - moved
return rpc.COMPLETED, {moved = moved, item = params.item,
short = short > 0 and short or nil,
reason = short > 0 and ("%s is full: %d of %d moved"):format(ports.OUT,
moved, params.count) or nil}
end,
}
]],
["mfg/controller/alarms.lua"] = [[




















local state = require("mfg.common.state")
local tagsmod = require("mfg.controller.tags")
local pointlist = require("mfg.common.points")

local alarms = {}

local STATE_FILE = "alarms"

alarms.UNACKED = "active-unacked"
alarms.ACKED = "active-acked"
alarms.CLEARED = "cleared"


local REARM_AFTER = 30 * 1000



function alarms.all()
local stored = state.read(STATE_FILE, {})
if type(stored) ~= "table" then return {} end
return stored
end

local function put(all)
state.write(STATE_FILE, all)
end





function alarms.raise(key, message, opts)
opts = opts or {}
local all = alarms.all()
local now = opts.now or os.epoch("utc")
local existing = all[key]

if existing and existing.state ~= alarms.CLEARED then
existing.message = message
existing.lastSeen = now
existing.count = (existing.count or 1)
put(all)
return existing
end

if existing and existing.state == alarms.CLEARED then


if (now - (existing.clearedAt or 0)) < (opts.rearm or REARM_AFTER) then
existing.lastSeen = now
existing.flapping = true
put(all)
return existing
end
existing.count = (existing.count or 1) + 1
end

all[key] = {
key = key,
message = message,
severity = opts.severity or "fault",
source = opts.source,
state = alarms.UNACKED,
firstSeen = (existing and existing.firstSeen) or now,
lastSeen = now,
clearedAt = nil,
count = (existing and existing.count) or 1,
flapping = existing and existing.flapping or false,
}
put(all)
return all[key]
end



function alarms.clear(key, now)
local all = alarms.all()
local alarm = all[key]
if not alarm then return false end
if alarm.state == alarms.CLEARED then return false end

alarm.clearedAt = now or os.epoch("utc")
if alarm.state == alarms.ACKED then

all[key] = nil
else
alarm.state = alarms.CLEARED
end
put(all)
return true
end

function alarms.ack(key, now)
local all = alarms.all()
local alarm = all[key]
if not alarm then return false, "no such alarm" end

if alarm.state == alarms.CLEARED then

all[key] = nil
else
alarm.state = alarms.ACKED
alarm.ackedAt = now or os.epoch("utc")
end
put(all)
return true
end

function alarms.ackAll(now)
local acked = 0
for key, alarm in pairs(alarms.all()) do
if alarm.state ~= alarms.ACKED then
alarms.ack(key, now)
acked = acked + 1
end
end
return acked
end

function alarms.unackedCount()
local n = 0
for _, alarm in pairs(alarms.all()) do
if alarm.state == alarms.UNACKED or alarm.state == alarms.CLEARED then
n = n + 1
end
end
return n
end


function alarms.list()
local out = {}
for _, alarm in pairs(alarms.all()) do out[#out + 1] = alarm end
local rank = {[alarms.UNACKED] = 1, [alarms.CLEARED] = 2, [alarms.ACKED] = 3}
table.sort(out, function(a, b)
if rank[a.state] ~= rank[b.state] then
return (rank[a.state] or 9) < (rank[b.state] or 9)
end
return (a.lastSeen or 0) > (b.lastSeen or 0)
end)
return out
end











function alarms.evaluate(snapshot, opts)
opts = opts or {}
local now = opts.now or os.epoch("utc")
local seen = {}

local function condition(key, wrong, message, meta)
seen[key] = true
if wrong then
alarms.raise(key, message, {
now = now, source = meta and meta.source,
severity = meta and meta.severity, rearm = opts.rearm,
})
else
alarms.clear(key, now)
end
end

for source, points in pairs(snapshot or {}) do

if points.state then
local faulted = points.state.value == "faulted"
condition(("node.%s.faulted"):format(source), faulted,
("%s faulted: %s"):format(source,
tostring(points.fault and points.fault.value or "no reason given")),
{source = source})
end



if points.comms then
local condition_ = points.comms.value
condition(("node.%s.comms"):format(source),
condition_ ~= "ok" and condition_ ~= nil,
("%s is %s -- the network cannot reach it or its program is not "
.. "answering"):format(source, tostring(condition_)),
{source = source})
end





if points.points_version then
local version = points.points_version.value or 1
condition(("node.%s.outdated"):format(source),
pointlist.outdated(version),
("%s runs point list v%s -- older than this controller, so probe "
.. "and confirmed-arrival delivery are unavailable to it")
:format(source, tostring(version)),
{source = source, severity = "version"})
end



if points.degraded then
condition(("volume.%s.degraded"):format(source),
points.degraded.value == true,
("%s DEGRADED, missing %s -- stock is counted from present devices "
.. "only"):format(source,
tostring(points.missing and points.missing.value or "a device")),
{source = source})
end



if points.offManifest then
condition(("order.%s.offmanifest"):format(source),
(points.offManifest.value or 0) > 0,
("%s OFF MANIFEST: %s held and unspendable"):format(source,
tostring(points.offManifestDetail
and points.offManifestDetail.value
or points.offManifest.value)),
{source = source, severity = "discrepancy"})


condition(("order.%s.blocked"):format(source),
points.state and points.state.value == "blocked",
("%s blocked -- awaiting declared material"):format(source),
{source = source, severity = "hold"})
end
end




return alarms.list()
end

function alarms.reset()
state.clear(STATE_FILE)
end

return alarms
]],
["mfg/controller/configs.lua"] = [[












local state = require("mfg.common.state")
local config = require("mfg.common.config")

local configs = {}

local STORE = "configs"
local OPTS = {schema = 1}

local function load()
local data, why = state.read(STORE, {nodes = {}}, OPTS)
if why then error("the config store is unreadable: " .. why, 0) end
if type(data) ~= "table" or type(data.nodes) ~= "table" then data = {nodes = {}} end
return data
end

local function save(data)
return state.write(STORE, data, OPTS)
end




configs.checkProfile = config.checkProfile


function configs.get(node)
return load().nodes[node]
end




function configs.assign(node, role, opts)
opts = opts or {}
local roles = opts.roles or require("mfg.common.roles")
if type(node) ~= "string" or node == "" then return nil, "no node named" end
local ok, why = configs.checkProfile(role, roles[role])
if not ok then return nil, why end

local data = load()
local record = data.nodes[node] or {overrides = {}, rev = 0}
local takes = {}
for _, name in ipairs(roles[role].settings or {}) do takes[name] = true end
for name in pairs(record.overrides) do
if not takes[name] then record.overrides[name] = nil end
end
record.role = role
record.rev = record.rev + 1
data.nodes[node] = record
save(data)
return record
end



function configs.set(node, name, value, opts)
opts = opts or {}
local roles = opts.roles or require("mfg.common.roles")
if not config.declared(name) then return nil, ("no setting called %s"):format(tostring(name)) end
local data = load()
local record = data.nodes[node]
if not record then return nil, ("%s has no role yet -- assign one first"):format(tostring(node)) end

local overrides = {}
for k, v in pairs(record.overrides) do overrides[k] = v end
overrides[name] = value
local _, why = config.settingsFor(roles[record.role].settings, overrides)
if why then return nil, why end


if value ~= nil then
local checked = config.settingsFor({name}, {[name] = value})
overrides[name] = checked[name]
end
record.overrides = overrides
record.rev = record.rev + 1
save(data)
return record
end






function configs.resolve(node, opts)
opts = opts or {}
local roles = opts.roles or require("mfg.common.roles")
local record = opts.record or load().nodes[node]
if not record then return nil, ("no intent recorded for %s"):format(tostring(node)) end

local fw = opts.firmware
if fw == nil then


local ok, published = pcall(require("mfg.controller.repository").published, record.role)
fw = ok and published and published.id or nil
end

return config.resolve({roles = roles, node = node, role = record.role,
rev = record.rev, overrides = record.overrides, firmware = fw})
end



function configs.issue(node, opts)
local doc, why = configs.resolve(node, opts)
if not doc then return nil, why end
if not doc.firmware then
return nil, ("the %s firmware has not been published -- run publish first"):format(doc.role)
end
return config.seal(doc), doc
end







local OBSERVED = {"node", "role", "firmware", "config_rev", "boot_state", "committed",
"equipment_missing", "degraded", "last_error"}


function configs.observe(name, report, opts)
opts = opts or {}
if type(name) ~= "string" or name == "" then return nil, "no node named" end
if type(report) ~= "table" then return nil, "no report" end
local seen = {}
for _, field in ipairs(OBSERVED) do seen[field] = report[field] end
seen.verified = opts.verified and true or false
seen.at = os.epoch("utc")

local data = load()
data.observed = data.observed or {}
data.observed[name] = seen
save(data)
return seen
end


function configs.observed(name)
local observed = load().observed or {}
if name == nil then return observed end
return observed[name]
end

return configs
]],
["mfg/controller/dispatch.lua"] = [[







local recipes = require("mfg.controller.recipes")
local state = require("mfg.common.state")

local dispatch = {}

local QUEUE_FILE = "queue"



dispatch.KEEP_FINISHED = 10

local FINISHED = {done = true, failed = true, cancelled = true}

function dispatch.isOpen(job)
return not FINISHED[job.state]
end

local function sortedKeys(t)
local keys = {}
for key in pairs(t) do keys[#keys + 1] = key end
table.sort(keys)
return keys
end













local explode


local function need(item, quantity, available, seen, out)
local have = available[item] or 0
local taken = math.min(have, quantity)
if taken > 0 then
available[item] = have - taken
out.draws[item] = (out.draws[item] or 0) + taken
end
local rest = quantity - taken
if rest <= 0 then return true end

local def = recipes.producing(item)
if not def then
out.short[item] = (out.short[item] or 0) + rest
return true
end
return explode(def, math.ceil(rest / def.output.count), available, seen, out)
end




explode = function(def, sets, available, seen, out)
if seen[def.id] then
return nil, "recipe cycle through " .. def.output.item
end
seen[def.id] = true

local inputs = {}
for _, item in ipairs(sortedKeys(def.inputs)) do
inputs[item] = def.inputs[item] * sets
local ok, why = need(item, inputs[item], available, seen, out)
if not ok then return nil, why end
end

out.steps[#out.steps + 1] = {
recipe = def.id,
label = def.label,
sets = sets,
produces = def.output.item,
count = def.output.count * sets,
inputs = inputs,
}
seen[def.id] = nil
return true
end








function dispatch.plan(recipeOrId, quantity, available)
local def = type(recipeOrId) == "table" and recipeOrId or recipes.get(recipeOrId)
if not def then return nil, "no such recipe: " .. tostring(recipeOrId) end
if type(quantity) ~= "number" or quantity < 1 then
return nil, "a quantity of at least 1 is needed"
end

local sets, yield = recipes.setsFor(def, quantity)
local out = {steps = {}, draws = {}, short = {}}
local ok, why = explode(def, sets, dispatch.copy(available or {}), {}, out)
if not ok then return nil, why end

return {
recipe = def.id, label = def.label, product = def.output.item,
sets = sets, yield = yield,
steps = out.steps, draws = out.draws, short = out.short,
}
end

function dispatch.copy(t)
local out = {}
for k, v in pairs(t) do out[k] = v end
return out
end

















function dispatch.claims(q)
q = q or dispatch.queue()
local total, byJob = {}, {}
for _, job in ipairs(q.jobs) do
if dispatch.isOpen(job) then
local net = {}
for index = job.position, #job.steps do
local step = job.steps[index]
local remaining = step.sets
if index == job.position then
remaining = step.sets - (job.stepDone or 0)
end
for item, count in pairs(step.inputs or {}) do
net[item] = (net[item] or 0) + count / step.sets * remaining
end
net[step.produces] = (net[step.produces] or 0)
- step.count / step.sets * remaining
end
for item, count in pairs(net) do
if count > 0 then
total[item] = (total[item] or 0) + count
byJob[item] = byJob[item] or {}
byJob[item][#byJob[item] + 1] = {job = job.id, count = count}
end
end
end
end
return total, byJob
end



function dispatch.queue()
local q = state.read(QUEUE_FILE, {jobs = {}, nextId = 1})
if type(q) ~= "table" or type(q.jobs) ~= "table" then q = {jobs = {}, nextId = 1} end
return q
end


local function prune(q)
local finished = 0
for index = #q.jobs, 1, -1 do
if not dispatch.isOpen(q.jobs[index]) then
finished = finished + 1
if finished > dispatch.KEEP_FINISHED then table.remove(q.jobs, index) end
end
end
end






function dispatch.commit(plan, meta)
meta = meta or {}
local q = dispatch.queue()
local id = q.nextId or 1
prune(q)
q.jobs[#q.jobs + 1] = {
id = id,
order = meta.order,
by = meta.by,
recipe = plan.recipe,
label = plan.label,
product = plan.product,
requested = meta.requested,
sets = plan.sets,
yield = plan.yield,
steps = plan.steps,
position = 1,
stepDone = 0,
state = "queued",
committed = os.epoch("utc"),
}
q.nextId = id + 1
state.write(QUEUE_FILE, q)
return id
end

function dispatch.job(id)
for _, job in ipairs(dispatch.queue().jobs) do
if job.id == id then return job end
end
return nil
end


function dispatch.jobs()
return dispatch.queue().jobs
end






function dispatch.next(now)
now = now or os.epoch("utc")
for _, job in ipairs(dispatch.queue().jobs) do
if dispatch.isOpen(job) and not (job.retryAt and job.retryAt > now) then
local step = job.steps[job.position]
if step then return job, step end
end
end
return nil
end




local function change(jobId, fn)
local q = dispatch.queue()
for _, job in ipairs(q.jobs) do
if job.id == jobId then
local result, why = fn(job)
if result == nil then return nil, why end
state.write(QUEUE_FILE, q)
return job
end
end
return nil, "no such job: " .. tostring(jobId)
end

local function finishStep(job, result)
job.history = job.history or {}
job.history[#job.history + 1] = result
job.position = job.position + 1
job.stepDone = 0
job.lastError, job.retryAt = nil, nil
if job.position > #job.steps then
job.state = "done"
job.finished = os.epoch("utc")
else
job.state = "running"
end
end



function dispatch.record(jobId, sets, result)
return change(jobId, function(job)
local step = job.steps[job.position]
if not step then return nil, "the job has no step to record against" end
job.stepDone = (job.stepDone or 0) + sets
job.lastError, job.retryAt = nil, nil
if job.stepDone >= step.sets then
finishStep(job, result)
else
job.state = "running"
end
return true
end)
end


function dispatch.advance(jobId, result)
return change(jobId, function(job)
finishStep(job, result)
return true
end)
end





function dispatch.fail(jobId, reason, fatal, retryAt)
return change(jobId, function(job)
job.lastError = reason
job.attempts = (job.attempts or 0) + 1
job.retryAt = (not fatal) and retryAt or nil
job.state = fatal and "failed" or "blocked"
if fatal then job.finished = os.epoch("utc") end
return true
end)
end




function dispatch.cancel(jobId, why)
return change(jobId, function(job)
if not dispatch.isOpen(job) then
return nil, ("job %s is already %s"):format(tostring(jobId), job.state)
end
job.state = "cancelled"
job.lastError = why
job.finished = os.epoch("utc")
return true
end)
end

function dispatch.clear()
state.write(QUEUE_FILE, {jobs = {}, nextId = 1})
end

return dispatch
]],
["mfg/controller/enroll.lua"] = [[






local enrollment = require("mfg.common.enrollment")
local leases = require("mfg.controller.leases")

local acknet = require("acknet")
local netkeys = require("netkeys")

local enroll = {}

local running = false











local function delegated()
if not netkeys.isServer() then return true end






if not netkeys.isClient() then return true end

return #netkeys.chain() > 0
end

local function refuse(reason)
return {ok = false, reason = reason}
end


function enroll.handle(request)
if type(request) ~= "table" or request.kind ~= "enroll" then
return nil
end

local instance = tostring(request.instance or "")
local pk = tostring(request.pk or "")
local tag = tostring(request.mac or "")

if instance == "" or pk == "" or tag == "" then
return refuse("malformed enrollment request")
end
if not enrollment.fromHex(pk) or #pk ~= 64 then
return refuse("public key is not 32 bytes of hex")
end

if not delegated() then



return refuse("controller is not yet delegated -- try again shortly")
end

local lease, why = leases.claimable(instance)
if not lease then return refuse(why) end

local secret = enrollment.fromHex(lease.secret)
if not secret then return refuse("lease secret is corrupt") end

local expected, macErr = enrollment.mac(secret, instance, pk)
if not expected then return refuse(tostring(macErr)) end

if not enrollment.macEquals(expected, tag) then




return refuse("authenticator did not verify")
end




netkeys.allow(pk)
if lease.name then netkeys.setName(pk, lease.name) end
if lease.address then netkeys.setAddress(pk, lease.address) end

leases.consume(instance, pk)

return {
ok = true,
name = lease.name,
address = lease.address,
instance = instance,
}
end

function enroll.runtime()
if running then error("mfg enroll: already running", 0) end
running = true

local ok, err = pcall(function()
while true do
local packet = acknet.receive(enrollment.PROTOCOL, 5)
if packet then
local reply = enroll.handle(packet.body)
if reply then
acknet.send(packet.sender_id, reply, enrollment.PROTOCOL)
if reply.ok then
print(("enrolled instance %s as %s"):format(
tostring(reply.instance), tostring(reply.name)))
else
print(("refused enrollment: %s"):format(
tostring(reply.reason)))
end
end
else



leases.reclaim()
end
end
end)

running = false
if not ok then error(err, 0) end
end

return enroll
]],
