["mfg/controller/leases.lua"] = [[




















local enrollment = require("mfg.common.enrollment")

local leases = {}

local STATE = require("mfg.common.state")

local NAME = "leases"


















local function load()
local out = STATE.read(NAME, {})
if type(out) ~= "table" then out = {} end
return out
end

local function save(state)
return STATE.write(NAME, state or {})
end

function leases.all()
return load()
end

function leases.get(instanceId)
return load()[tostring(instanceId)]
end



function leases.issue(instanceId, secret, address, name, role, ttlSeconds)
local state = load()
local now = os.epoch("utc")
state[tostring(instanceId)] = {
instance = tostring(instanceId),
secret = enrollment.toHex(secret),
address = address,
name = name,
role = role,
issued = now,
expires = now + (ttlSeconds or enrollment.DEFAULT_LEASE_SECONDS) * 1000,
consumed = false,
}
local ok, err = save(state)
if not ok then return nil, err end
return state[tostring(instanceId)]
end

function leases.isExpired(lease, now)
return (now or os.epoch("utc")) > (lease.expires or 0)
end





function leases.claimable(instanceId, now)
local lease = leases.get(instanceId)
if not lease then return nil, "no lease for that instance" end
if lease.consumed then return nil, "lease already consumed" end
if leases.isExpired(lease, now) then return nil, "lease expired" end
return lease
end

function leases.consume(instanceId, publicKeyHex)
local state = load()
local lease = state[tostring(instanceId)]
if not lease then return nil, "no lease for that instance" end
lease.consumed = true
lease.consumedAt = os.epoch("utc")
lease.publicKey = publicKeyHex
local ok, err = save(state)
if not ok then return nil, err end
return lease
end




function leases.reclaim(now)
local state = load()
now = now or os.epoch("utc")
local freed = {}
for id, lease in pairs(state) do
if not lease.consumed and leases.isExpired(lease, now) then
freed[#freed + 1] = id
state[id] = nil
end
end
if #freed > 0 then save(state) end
return freed
end


function leases._reset()
STATE.clear(NAME)
end

return leases
]],
["mfg/controller/machines.lua"] = [[








local mount = require("mfg.storage.mount")
local hal = require("mfg.common.hal")

local machines = {}


function machines.ports(machine)
local out = {}
for _, path in ipairs(mount.list("/" .. machine)) do
local record = mount.get(path)
if record and record.machine == machine then out[#out + 1] = record end
end
return out
end


function machines.all()
local seen, out = {}, {}
for _, record in pairs(mount.all()) do
if record.machine and not seen[record.machine] then
seen[record.machine] = true
out[#out + 1] = record.machine
end
end
table.sort(out)
return out
end




function machines.volume(path, direction)
local record = mount.get(path)
if not record or not record.machine then
return nil, ("%s is not a machine's port"):format(tostring(path))
end
if mount.kindOf(record) ~= mount.VOLUME then
return nil, ("%s is a signal, not a volume"):format(path)
end
if direction and record.direction ~= direction then
return nil, ("%s is an %s, not an %s"):format(path,
tostring(record.direction), direction)
end
if #(record.devices or {}) == 0 then
return nil, ("%s is declared but UNBOUND -- mfgctl bind %s <device>")
:format(path, path)
end
local present, missing = mount.devices(path)
if not present or #present == 0 then
return nil, ("%s: %s is not on the network"):format(path,
table.concat(missing or {}, ", "))
end
return record
end








function machines.declare(machine, ports, script)
local base = "/" .. machine
if not mount.valid(base) then
return nil, ("not a valid machine name: %s"):format(tostring(machine))
end
local existing = mount.get(base)
if existing then
return nil, ("%s is already a volume, so it cannot be a machine"):format(base)
end
for _, path in ipairs(mount.list(base)) do
local record = mount.get(path)
if record and record.machine ~= machine then
return nil, ("%s is already bound, and not as %s's port"):format(path,
machine)
end
end

local wanted = {}
for _, port in ipairs(ports) do
local path = base .. "/" .. port.name
wanted[path] = true
local ok, why = mount.declare(path, {kind = port.kind,
direction = port.direction, safe = port.safe, machine = machine,
script = script})
if not ok then return nil, why end
end




for _, record in ipairs(machines.ports(machine)) do
if not wanted[record.path] and #(record.devices or {}) == 0 then
mount.forget(record.path)
end
end
return true
end






function machines.attach(machine, device, ports)
local base = "/" .. machine
local wanted, highest = {}, 0
for _, port in ipairs(ports) do
if port.kind == mount.VOLUME and port.slots then
wanted[#wanted + 1] = {path = base .. "/" .. port.name, slots = port.slots}
for _, slot in ipairs(port.slots) do highest = math.max(highest, slot) end
end
end
if #wanted == 0 then return {} end

local inv = hal.inventory()
if not inv.isPresent(device) then
return nil, ("%s is not on the network -- is its modem activated?")
:format(tostring(device))
end
local size = inv.size(device) or 0
if highest > size then
return nil, ("%s has %d slots, and the script names slot %d"):format(device,
size, highest)
end
for _, holder in ipairs(mount.holders(device)) do
if holder:sub(1, #base + 1) ~= base .. "/" then
return nil, ("%s is already bound to %s"):format(device, holder)
end
end



for _, record in ipairs(machines.ports(machine)) do
for _, held in ipairs(record.devices or {}) do
if held == device then mount.unbind(record.path) end
end
end

local bound = {}
for _, want in ipairs(wanted) do
local ok, why = mount.bind(want.path, {device}, {slots = want.slots})
if not ok then return nil, why end
bound[#bound + 1] = want.path
end
return bound
end


function machines.unbound(machine)
local out = {}
for _, record in ipairs(machines.ports(machine)) do
if #(record.devices or {}) == 0 then out[#out + 1] = record end
end
return out
end




function machines.forget(machine)
local unbound = {}
for _, record in ipairs(machines.ports(machine)) do
if #(record.devices or {}) > 0 then unbound[#unbound + 1] = record.path end
mount.forget(record.path)
end
return unbound
end

return machines
]],
["mfg/controller/mint.lua"] = [[




























local enrollment = require("mfg.common.enrollment")
local leases = require("mfg.controller.leases")

local netkeys = require("netkeys")
local ip = require("ip")
local random = require("ccryptolib.random")
local state = require("mfg.common.state")

local mint = {}


local writeFile = state.writeText







function mint.nextAddress(network, prefix)
local taken = {}
for _, addr in pairs(netkeys.addresses()) do taken[addr] = true end
for _, lease in pairs(leases.all()) do
if lease.address and not lease.consumed then taken[lease.address] = true end
if lease.consumed and lease.address then taken[lease.address] = true end
end

local base = ip.network(network, prefix)
local hosts = 2 ^ (32 - prefix)


for offset = 100, hosts - 2 do
local candidate = base + offset
if not taken[candidate] then return candidate end
end
return nil, "no free address in " .. ip.formatCidr(base, prefix)
end


function mint.writeIdentity(dest, cfg)
local lines = {
"instance " .. cfg.instance,
"secret " .. cfg.secretHex,



"controller " .. tostring(cfg.controller),
"address " .. ip.format(cfg.address),
"name " .. cfg.name,


}
return writeFile(fs.combine(dest, "mfg/enroll.cfg"),
table.concat(lines, "\n") .. "\n")
end





function mint.writeTrust(dest)
local exchange = netkeys.publicKey()
local anchor = netkeys.signerKey() or netkeys.signingKey()
if not exchange then return false, "this computer has no keypair" end
if not anchor then return false, "this computer has no signing key to anchor to" end

writeFile(fs.combine(dest, "net/server.key"), netkeys.toHex(exchange))
writeFile(fs.combine(dest, "net/signer.key"), netkeys.toHex(anchor))
return true
end





























function mint.writeImage(dest, role, name)
local repository = require("mfg.controller.repository")
local configs = require("mfg.controller.configs")
local apply = require("mfg.boot.apply")

local m, why = repository.published(role)
if not m then
return false, ("the %s firmware is not published (%s) -- run: mfgctl publish %s")
:format(role, tostring(why), role)
end

local intent = configs.get(name)
if not intent or intent.role ~= role then
local assigned, assignErr = configs.assign(name, role)
if not assigned then return false, assignErr end
end
local envelope, doc = configs.issue(name)
if not envelope then return false, doc end

local result, installErr = apply.install(dest, m, envelope, apply.localSource("/"),
{origin = "mint", signer = netkeys.signingKey(), startup = false})
if not result then return false, installErr end
return true, result.files
end







function mint.writeStartup(dest)
local zero, why = require("mfg.boot.apply").stageZero()
if not zero then return false, why end
return writeFile(fs.combine(dest, "startup.lua"), zero)
end

function mint.writeSettings(dest, cfg)
writeFile(fs.combine(dest, "net/role"), "client")
writeFile(fs.combine(dest, "net/hostname"), cfg.name)
writeFile(fs.combine(dest, "net/substrate"), netkeys.substrate() or "hopnet")













local policy = state.readText("/net/ports")
if policy then writeFile(fs.combine(dest, "net/ports"), policy) end

return true
end








function mint.node(dest, opts)
opts = opts or {}
local role = opts.role or "turtle"
local network, prefix = opts.network, opts.prefix
if not network then return nil, "mint needs the subnet to allocate from" end

local address, addrErr = opts.address, nil
if not address then
address, addrErr = mint.nextAddress(network, prefix)
if not address then return nil, addrErr end
end

local instance = opts.instance or
("%d-%d"):format(os.getComputerID(), os.epoch("utc"))








if not random.isInit() then random.initWithTiming() end

local secret = random.random(enrollment.SECRET_BYTES)
local name = opts.name or "craft_turtle"

local lease, leaseErr = leases.issue(instance, secret, address, name, role,
opts.ttl)
if not lease then return nil, leaseErr end

local cfg = {
instance = instance,
secretHex = enrollment.toHex(secret),
controller = opts.controller or os.getComputerID(),
address = address,
name = name,
role = role,
}






local imaged, imageErr = mint.writeImage(dest, role, name)
if not imaged then return nil, imageErr end

if not mint.writeIdentity(dest, cfg) then
return nil, "could not write the enrollment config"
end
local trusted, trustErr = mint.writeTrust(dest)
if not trusted then return nil, trustErr end
mint.writeSettings(dest, cfg)


local started, startErr = mint.writeStartup(dest)
if not started then return nil, startErr end

return lease, cfg
end

return mint
]],
["mfg/controller/orders.lua"] = [[
















local rpc = require("mfg.common.rpc")
local custody = require("mfg.storage.custody")

local orders = {}

local COMMANDS = {}







function COMMANDS.place(body, packet)
local spec = body.order
if type(spec) ~= "table" then
return rpc.REJECTED, {reason = "an order must be supplied"}
end

local accepted, err = custody.accept({
id = spec.id,



from = tostring(packet and packet.src or "unknown"),
product = spec.product,
quantity = spec.quantity,
supplied = spec.supplied,
owed = spec.owed,
})
if not accepted then return rpc.REJECTED, {reason = tostring(err)} end

return rpc.COMPLETED, {order = accepted.id, state = accepted.state}
end





function COMMANDS.receive(body)
local statement, err = custody.receive(body.order or "")
if not statement then return rpc.REJECTED, {reason = tostring(err)} end
return rpc.COMPLETED, {statement = statement}
end



function COMMANDS.statement(body)
local statement, err = custody.statement(body.order or "")
if not statement then return rpc.REJECTED, {reason = tostring(err)} end
return rpc.COMPLETED, {statement = statement}
end




function COMMANDS.settle(body)
local settled, err = custody.settle(body.order or "")
if not settled then return rpc.REJECTED, {reason = tostring(err)} end
return rpc.COMPLETED, {settled = settled}
end

function COMMANDS.cancel(body)
local cancelled, err = custody.cancel(body.order or "",
body.why or "withdrawn by the station")
if not cancelled then return rpc.REJECTED, {reason = tostring(err)} end
return rpc.COMPLETED, {cancelled = cancelled}
end




function COMMANDS.hello()
local recipes = require("mfg.controller.recipes")
local products = {}
for _, def in ipairs(recipes.all()) do
products[#products + 1] = def.output.item
end

local open = 0
for _, order in pairs(custody.orders()) do
if order.state ~= custody.SETTLED and order.state ~= custody.RETURNED then
open = open + 1
end
end

return rpc.COMPLETED, {
kind = "manufacturer",
inbound = custody.IN,
outbound = custody.OUT,
products = products,
ordersOpen = open,
}
end

orders.COMMANDS = COMMANDS

function orders.handle(body, packet)
local name = body and body.command
local handler = COMMANDS[name]

if not handler then
print(("orders: rejected unknown command '%s' from %s"):format(
tostring(name), tostring(packet and packet.src)))
return rpc.REJECTED, {reason = "unknown command: " .. tostring(name)}
end

local ok, status, fields = pcall(handler, body or {}, packet)
if not ok then
print(("orders: %s failed: %s"):format(tostring(name), tostring(status)))
return rpc.REJECTED, {reason = tostring(status)}
end
return status, fields
end






function orders.fulfil()
local delivered = {}
for id, order in pairs(custody.orders()) do
local open = order.state ~= custody.SETTLED
and order.state ~= custody.RETURNED
and order.state ~= custody.FULFILLED
if open then
local sent = custody.deliver(id)
if sent and next(sent.sent or {}) then delivered[id] = sent.sent end
end
end
return delivered
end

return orders
]],
["mfg/controller/ports.lua"] = [[











local store = require("mfg.storage")
local actions = require("mfg.common.actions")
local rpc = require("mfg.common.rpc")

local ports = {}

ports.IN = "/io/in"
ports.OUT = "/io/out"
ports.POLL = 5


function ports.contents(path)
if not store.isBound(path) then return {} end
return store.stock(path) or {}
end






function ports.intake(opts)
opts = opts or {}
if not store.isBound(ports.IN) then return nil end
if next(ports.contents(ports.IN)) == nil then return nil end
local invoke = opts.invoke or actions.invoke
return invoke("take_in", {}, {by = "intake"})
end


function ports.run(opts)
while true do
local ok, status, fields = pcall(ports.intake, opts)
if not ok then
print("intake: " .. tostring(status))
elseif status and status ~= rpc.COMPLETED then
print("intake: " .. tostring(fields and fields.reason))
end
sleep(ports.POLL)
end
end

return ports
]],
["mfg/controller/recipes.lua"] = [[




















local state = require("mfg.common.state")
local pattern = require("mfg.common.pattern")

local recipes = {}

local STORE = "recipes"
local OPTS = {schema = 1}

local function load()
local data, why = state.read(STORE, {recipes = {}, rev = 0, seq = 0}, OPTS)
if why then error("the recipe book is unreadable: " .. why, 0) end
if type(data) ~= "table" or type(data.recipes) ~= "table" then
data = {recipes = {}, rev = 0, seq = 0}
end
return data
end

local function save(data)
data.rev = (data.rev or 0) + 1
return state.write(STORE, data, OPTS)
end


local function view(def)
if not def then return nil end
def.inputs = pattern.occurrences(def.pattern)
return def
end

function recipes.get(id)
return view(load().recipes[id])
end


function recipes.all()
local out = {}
for _, def in pairs(load().recipes) do out[#out + 1] = view(def) end
table.sort(out, function(a, b)
if a.label ~= b.label then return a.label < b.label end
return a.id < b.id
end)
return out
end








function recipes.producing(item)
local best = nil
for _, def in pairs(load().recipes) do
if def.output.item == item and (not best or def.seq < best.seq) then
best = def
end
end
return view(best)
end







function recipes.add(def)
if type(def) ~= "table" or type(def.pattern) ~= "table" or next(def.pattern) == nil then
return nil, "a recipe needs a pattern"
end
local inGrid, why = pattern.inGrid(def.pattern)
if not inGrid then return nil, why end
local output = def.output
if type(output) ~= "table" or type(output.item) ~= "string"
or type(output.count) ~= "number" or output.count < 1 then
return nil, "a recipe needs an output: an item and a count"
end

local id = pattern.id(def.pattern)
local data = load()
local existing = data.recipes[id]
if existing then
return nil, ("that pattern is already registered, as %s"):format(existing.label)
end

data.seq = (data.seq or 0) + 1
data.recipes[id] = {
id = id,
label = def.label or output.item:match("[^:]+$") or output.item,
pattern = def.pattern,
output = {item = output.item, count = output.count},
byproducts = def.byproducts,
registered = def.registered,
seq = data.seq,
}
save(data)
return view(data.recipes[id])
end


function recipes.remove(id)
local data = load()
local existing = data.recipes[id]
if not existing then return nil, "no such recipe: " .. tostring(id) end
data.recipes[id] = nil
save(data)
return existing
end




function recipes.setsFor(def, quantity)
local sets = math.ceil(quantity / def.output.count)
return sets, sets * def.output.count
end

return recipes
]],
["mfg/controller/recovery.lua"] = [[




















local turtles = require("mfg.controller.turtles")
local rpc = require("mfg.common.rpc")

local recovery = {}

recovery.COMMANDED = "commanded"
recovery.REBOOTED = "rebooted"
recovery.DISPATCHED = "dispatched"
recovery.EXHAUSTED = "exhausted"











function recovery.findPeripheral(label, opts)
opts = opts or {}
local names = opts.names
local wrap = opts.wrap

if not names then
names = {}
for _, name in ipairs(peripheral.getNames()) do
local kind = peripheral.getType(name)
if kind == "turtle" or kind == "computer" then
names[#names + 1] = name
end
end
end
wrap = wrap or peripheral.wrap

for _, name in ipairs(names) do
local device = wrap(name)
if device and device.getLabel then
local ok, found = pcall(device.getLabel)
if ok and found == label then return name, device end
end
end
return nil
end




local function commandIt(node, opts)
local answer = turtles.clearFault(node, opts.rpc or {timeout = 3, attempts = 2})
if answer and answer.status == rpc.COMPLETED then
return true, "cleared its fault over the control service"
end
return false, ("did not clear: %s"):format(
tostring(answer and (answer.reason or answer.status) or "no reply"))
end






local function rebootIt(node, opts)
local label = node.label or node.id
if not label then
return false, "no label, so it cannot be found on the network (W8.4)"
end

local name, device = recovery.findPeripheral(label, opts)
if not name then
return false, ("no network peripheral labelled %s -- is it in its bay, and "
.. "is the bay's modem activated?"):format(tostring(label))
end

local ok, err = pcall(device.reboot)
if not ok then return false, ("reboot failed: %s"):format(tostring(err)) end
return true, ("rebooted via %s"):format(name)
end



local function dispatchBuilder(node, opts)
local builder = opts.builder
if not builder then
return false, "no builder registered -- nothing left to try"
end

local answer = rpc.request(builder.host, "mfg-control", {
command = "recover",
target = node.id,
label = node.label or node.id,
}, opts.rpc or {timeout = 5, attempts = 2})

if not answer or answer.status == rpc.TIMED_OUT then
return false, "the builder did not answer"
end
if answer.status == rpc.REJECTED then
return false, ("the builder refused: %s"):format(tostring(answer.reason))
end


return true, "builder dispatched"
end







function recovery.recover(nodeId, opts)
opts = opts or {}

local node = turtles.get(nodeId)
if not node then return nil, ("no such node: %s"):format(tostring(nodeId)) end

local rungs = {
{name = recovery.COMMANDED, run = commandIt},
{name = recovery.REBOOTED, run = rebootIt},
{name = recovery.DISPATCHED, run = dispatchBuilder},
}

local attempts = {}

for _, rung in ipairs(rungs) do



if not (opts.skip and opts.skip[rung.name]) then



local lived, ok, why = pcall(rung.run, node, opts)
if not lived then
ok, why = false, "the rung itself failed: " .. tostring(ok)
end

attempts[#attempts + 1] = {rung = rung.name, ok = ok, why = why}
if ok then
return rung.name, attempts
end
else
attempts[#attempts + 1] = {rung = rung.name, ok = false,
why = "skipped", skipped = true}
end
end

return recovery.EXHAUSTED, attempts
end



















function recovery.verifyDevices(before, opts)
opts = opts or {}
local store = opts.store or require("mfg.storage")
local after = store.audit()

local wasMissing = {}
for _, entry in ipairs((before and before.degraded) or {}) do
for _, device in ipairs(entry.missing) do wasMissing[device] = true end
end

local vanished, alreadyGone = {}, {}
for _, entry in ipairs(after.degraded) do
for _, device in ipairs(entry.missing) do
local record = {path = entry.path, device = device}
if wasMissing[device] then
alreadyGone[#alreadyGone + 1] = record
else
vanished[#vanished + 1] = record
end
end
end

return {
audit = after,
vanished = vanished,
alreadyGone = alreadyGone,
ok = #vanished == 0,



diagnosis = (#vanished > 0)
and "a device vanished during builder movement -- check the wired modem "
.. "is still activated before assuming a broken block (F9.8c)"
or nil,
}
end





function recovery.explain(nodeId, outcome, attempts)
local parts = {}
for _, attempt in ipairs(attempts or {}) do
parts[#parts + 1] = ("%s: %s"):format(attempt.rung, tostring(attempt.why))
end
return ("%s -> %s (%s)"):format(tostring(nodeId), tostring(outcome),
table.concat(parts, "; "))
end

return recovery
]],
["mfg/controller/repository.lua"] = [[

















local firmware = require("mfg.common.firmware")

local repository = {}

repository.DIR = "/mfg/firmware"

function repository.builtPath(role, dir)
return fs.combine(dir or repository.DIR, role .. ".manifest")
end

function repository.publishedPath(role, dir)
return fs.combine(dir or repository.DIR, role .. ".published")
end




function repository.published(role, opts)
opts = opts or {}
local m, why = firmware.read(repository.publishedPath(role, opts.dir))
if not m then return nil, why end
if m.role ~= role then return nil, ("%s.published names role %s"):format(role, tostring(m.role)) end


local anchor = opts.anchor
if not anchor then
if not fs.exists("/net/sign.key") then return nil, "this controller has never signed anything" end
anchor = require("netkeys").signingKey()
end
local ok, bad = firmware.verify(m, {anchor})
if not ok then return nil, bad end
return m
end



function repository.publish(role, opts)
opts = opts or {}
local root = opts.root or "/"

local m, why = firmware.read(repository.builtPath(role, opts.dir))
if not m then return nil, why end
if m.role ~= role then
return nil, ("the manifest for %s names role %s"):format(role, tostring(m.role))
end

local mismatched, oversize, bytes = {}, {}, 0
local tick = firmware.yielder()
for _, f in ipairs(m.files) do
if f.size > firmware.MAX_FILE then oversize[#oversize + 1] = ("%s (%d bytes)"):format(f.path, f.size) end
local sum, size = firmware.hashFile(fs.combine(root, f.path))
if sum ~= f.sha256 or size ~= f.size then
mismatched[#mismatched + 1] = f.path .. (sum and "" or " (missing)")
end
bytes = bytes + f.size
tick()
end

if #oversize > 0 then
return nil, ("%d file(s) larger than %d bytes cannot travel one per message: %s"):format(
#oversize, firmware.MAX_FILE, table.concat(oversize, ", ")), {oversize = oversize}
end
if #mismatched > 0 then
local shown = {}
for i = 1, math.min(#mismatched, 5) do shown[i] = mismatched[i] end
return nil, ("%d file(s) on this controller do not match the %s manifest: %s%s"):format(
#mismatched, role, table.concat(shown, ", "), #mismatched > 5 and ", ..." or ""),
{mismatched = mismatched}
end

firmware.sign(m)
local ok, bad = firmware.write(repository.publishedPath(role, opts.dir), m)
if not ok then return nil, bad end
m.bytes = bytes
return m
end

return repository
]],
["mfg/controller/runner.lua"] = [[















local rpc = require("mfg.common.rpc")
local actions = require("mfg.common.actions")
local dispatch = require("mfg.controller.dispatch")
local recipes = require("mfg.controller.recipes")
local turtles = require("mfg.controller.turtles")
local configs = require("mfg.controller.configs")
local alarms = require("mfg.controller.alarms")

local runner = {}

runner.MAX_SETS = 64
runner.RETRY = 30
runner.RETRY_TIMEOUT = 60
runner.RETRY_DRIFT = 300
runner.IDLE = 2

local CRAFTING_TABLE = "minecraft:crafting_table"









function runner.eligible(patternId)
local holding, others = {}, {}
for id, record in pairs(turtles.all()) do
local fitted = true
local seen = type(record.host) == "string" and configs.observed(record.host)
for _, item in ipairs(seen and seen.equipment_missing or {}) do
if item == CRAFTING_TABLE then fitted = false end
end
if fitted and type(record.host) == "string" and record.host ~= "" then
local list = record.pattern_id == patternId and holding or others
list[#list + 1] = id
end
end
table.sort(holding)
table.sort(others)
for _, id in ipairs(others) do holding[#holding + 1] = id end
return holding
end

local function copy(t)
local out = {}
for k, v in pairs(t) do out[k] = v end
return out
end







function runner.pass(opts)
opts = opts or {}
local invoke = opts.invoke or actions.invoke
local now = opts.now or os.epoch("utc")

local job, step = dispatch.next(now)
if not job then return nil end

local function blocked(reason, retry, alarm)
dispatch.fail(job.id, reason, false, now + retry * 1000)
if alarm then
alarms.raise(("job.%d.%s"):format(job.id, alarm),
("job %d (%s): %s"):format(job.id, tostring(job.label), reason),
{now = now, source = "jobs", severity = "hold"})
end
return {job = job.id, outcome = "blocked", reason = reason}
end



local def = recipes.get(step.recipe)
if not def then
return blocked(("step %d (%s) needs a recipe no longer in the book -- "
.. "register it again"):format(job.position, tostring(step.label)),
runner.RETRY)
end

local amount = math.min(runner.MAX_SETS, step.sets - (job.stepDone or 0))
local nodes = runner.eligible(def.id)
if #nodes == 0 then
return blocked("no crafting node is registered and fitted", runner.RETRY)
end


local ctx = {by = "jobs", policy = ("jobs:%d"):format(job.id)}
local refusals = {}

for _, node in ipairs(nodes) do

local current = dispatch.job(job.id)
if not current or not dispatch.isOpen(current) then
return {job = job.id, outcome = "cancelled"}
end

local status, fields = invoke("run_batch", {
target = node, pattern_id = def.id, pattern = copy(def.pattern),
amount = amount,
}, ctx)
fields = fields or {}

if status == rpc.COMPLETED then
local made = (fields.produced or {})[def.output.item] or 0
local expected = amount * def.output.count
dispatch.record(job.id, amount,
{node = node, sets = amount, produced = fields.produced})
alarms.clear(("job.%d.timeout"):format(job.id), now)
if made < expected then


return blocked(("%s made %d %s from %d sets, the book says %d -- "
.. "recipe drift"):format(node, made, def.output.item, amount,
expected), runner.RETRY_DRIFT, "drift")
end
return {job = job.id, outcome = "ran", node = node, sets = amount}
end

if status == rpc.TIMED_OUT then



return blocked(("%s timed out: %s"):format(node, tostring(fields.reason)),
runner.RETRY_TIMEOUT, "timeout")
end

if fields.short then

return blocked(tostring(fields.reason), runner.RETRY)
end


refusals[#refusals + 1] = ("%s: %s"):format(node, tostring(fields.reason))
end

return blocked("no node could run it -- " .. table.concat(refusals, "; "),
runner.RETRY)
end


function runner.run(opts)
opts = opts or {}
while true do
local ok, result = pcall(runner.pass, opts)
if not ok then
print("jobs: " .. tostring(result))
sleep(runner.RETRY)
elseif result == nil then
sleep(runner.IDLE)
elseif result.outcome ~= "ran" then
print(("jobs: job %d %s: %s"):format(result.job, result.outcome,
tostring(result.reason or "")))

sleep(0)
end
end
end

return runner
]],
["mfg/controller/scada.lua"] = [[















local tags = require("mfg.controller.tags")
local alarms = require("mfg.controller.alarms")

local scada = {}










local latest = nil
local latestAt = nil




scada.EVERY = 30


function scada.refresh(opts)
latest = tags.snapshot(opts or {timeout = 2, attempts = 1}, latest)
latestAt = os.epoch("utc")
return latest, latestAt
end


function scada.refreshDue(now)
if not latestAt then return true end
return ((now or os.epoch("utc")) - latestAt) >= scada.EVERY * 1000
end


function scada._forget()
latest, latestAt = nil, nil
end







function scada.tick(opts)
local snapshot = scada.refresh(opts)
local raised = alarms.evaluate(snapshot)
return snapshot, raised
end

return scada
]],
["mfg/controller/schedules.lua"] = [[














local state = require("mfg.common.state")
local actions = require("mfg.common.actions")

local schedules = {}

local STORE = "schedules"
local OPTS = {schema = 1}



schedules.POLL = 5

local function load()
local data, why = state.read(STORE, {entries = {}}, OPTS)
if why then error("the schedule store is unreadable: " .. why, 0) end
if type(data) ~= "table" or type(data.entries) ~= "table" then data = {entries = {}} end
return data
end

local function save(data)
return state.write(STORE, data, OPTS)
end

function schedules.get(id)
return load().entries[id]
end

function schedules.all()
local out = {}
for _, entry in pairs(load().entries) do out[#out + 1] = entry end
table.sort(out, function(a, b) return a.id < b.id end)
return out
end




function schedules.put(entry, now)
now = now or os.epoch("utc")
local data = load()
data.entries[entry.id] = {
id = entry.id,
action = entry.action,
params = entry.params or {},
every = entry.every,
enabled = entry.enabled ~= false,
next = now + entry.every * 60000,
last = data.entries[entry.id] and data.entries[entry.id].last or nil,
by = entry.by,
}
save(data)
return data.entries[entry.id]
end

function schedules.remove(id)
local data = load()
local entry = data.entries[id]
if not entry then return nil, "no such schedule: " .. tostring(id) end
data.entries[id] = nil
save(data)
return entry
end


function schedules.nextDue()
local soonest = nil
for _, entry in pairs(load().entries) do
if entry.enabled and (not soonest or entry.next < soonest) then
soonest = entry.next
end
end
return soonest
end

local function copy(t)
local out = {}
for k, v in pairs(t) do out[k] = v end
return out
end











function schedules.tick(opts)
opts = opts or {}
local invoke = opts.invoke or actions.invoke
local now = opts.now or os.epoch("utc")

local due = {}
for _, entry in pairs(load().entries) do
if entry.enabled and entry.next <= now then due[#due + 1] = entry end
end
table.sort(due, function(a, b)
if a.next ~= b.next then return a.next < b.next end
return a.id < b.id
end)

local fired = {}
for _, entry in ipairs(due) do


local lived, status, fields = pcall(invoke, entry.action, copy(entry.params),
{by = "scheduler", policy = "schedule:" .. entry.id})
if not lived then status, fields = "rejected", {reason = tostring(status)} end
fields = fields or {}



local data = load()
local stored = data.entries[entry.id]
if stored then
stored.last = {at = now, status = status, reason = fields.reason,
job = fields.job}
stored.next = now + stored.every * 60000
save(data)
end
fired[#fired + 1] = entry.id
end
return fired
end


function schedules.run(opts)
while true do
local ok, why = pcall(schedules.tick, opts)
if not ok then print("scheduler: " .. tostring(why)) end
local wake = schedules.nextDue()
local wait = schedules.POLL
if wake then wait = math.min(wait, (wake - os.epoch("utc")) / 1000) end
sleep(math.max(0.05, wait))
end
end

return schedules
]],
["mfg/controller/scripts.lua"] = [[






















local state = require("mfg.common.state")
local actions = require("mfg.common.actions")
local journal = require("mfg.common.actions.journal")
local rpc = require("mfg.common.rpc")
local check = require("mfg.common.script.check")
local format = require("mfg.common.script.format")
local interp = require("mfg.common.script.interp")
local store = require("mfg.storage")
local mount = require("mfg.storage.mount")
local signals = require("mfg.controller.signals")
local machines = require("mfg.controller.machines")
local alarms = require("mfg.controller.alarms")

local scripts = {}

local STORE = "scripts"

scripts.POLL = 1
scripts.RING = 16
scripts.FAULTS = 3

scripts.STOPPED = "stopped"
scripts.RUNNING = "running"
scripts.FAULTED = "faulted"
scripts.PAUSED = "paused"





local function migrate(value, from)
if from ~= 1 then error("no migration from schema " .. tostring(from), 0) end
local out = {scripts = {}, machines = {}}
for id, old in pairs(value.scripts or {}) do
out.scripts[id] = {name = id, ast = old.ast, source = old.source, rev = old.rev,
ports = old.ports, footprint = old.footprint, registered = old.registered}
out.machines[id] = {name = id, script = id, enabled = old.enabled,
state = old.state, faults = old.faults, lastError = old.lastError,
handlers = old.handlers or {}, runs = old.runs or {}, created = old.registered}
end
return out
end

local OPTS = {schema = 2, migrate = migrate}

local function load()
local data, why = state.read(STORE, {scripts = {}, machines = {}}, OPTS)
if why then error("the script store is unreadable: " .. why, 0) end
if type(data) ~= "table" then data = {} end
data.scripts = type(data.scripts) == "table" and data.scripts or {}
data.machines = type(data.machines) == "table" and data.machines or {}
return data
end

local function save(data)
return state.write(STORE, data, OPTS)
end



local function update(name, fn)
local data = load()
local record = data.machines[name]
if not record then return nil end
if fn(record) ~= false then save(data) end
return record
end

local function sortedValues(map, key)
local out = {}
for _, record in pairs(map) do out[#out + 1] = record end
table.sort(out, function(a, b) return a[key] < b[key] end)
return out
end


function scripts.get(name)
return load().scripts[name]
end


function scripts.all()
return sortedValues(load().scripts, "name")
end


function scripts.machine(name)
return load().machines[name]
end


function scripts.machines(script)
local out = {}
for _, record in ipairs(sortedValues(load().machines, "name")) do
if not script or record.script == script then out[#out + 1] = record end
end
return out
end

function scripts.clear()
state.clear(STORE)
end





function scripts.env()
local decls = {}
for _, action in pairs(check.VERBS) do decls[action] = actions.get(action) end
local items = nil
local ok, stock = pcall(store.stock, require("mfg.common.config").setting("source"))
if ok and type(stock) == "table" then
items = {}
for item in pairs(stock) do items[item] = true end
end
return {decls = decls, items = items}
end



function scripts.check(source)
local report = check.source(source, scripts.env())
if report.tree and report.ok then report.text = format.format(report.tree) end
return report
end





local function refit(machine, script)
local ok, why = machines.declare(machine.name, script.ports, script.name)
if not ok then return nil, why end
if machine.device then
local bound, attachWhy = machines.attach(machine.name, machine.device, script.ports)
if not bound then return nil, attachWhy end
end
return true
end





function scripts.register(source, by)
local report = scripts.check(source)
if not report.ok then return nil, report end
local tree = report.tree
local name = tree.machine

local data = load()
local previous = data.scripts[name]
data.scripts[name] = {
name = name,
ast = tree,
source = source,
rev = (previous and previous.rev or 0) + 1,
ports = report.ports,
footprint = report.footprint,
registered = {at = os.epoch("utc"), by = by},
}
save(data)

local problems = {}
for _, machine in ipairs(scripts.machines(name)) do
local ok, why = refit(machine, data.scripts[name])
if not ok then problems[machine.name] = why end
end
return data.scripts[name], report, problems
end


function scripts.forgetScript(name)
local data = load()
if not data.scripts[name] then return nil, "no script called " .. tostring(name) end
local users = scripts.machines(name)
if #users > 0 then
local names = {}
for _, m in ipairs(users) do names[#names + 1] = m.name end
return nil, ("%s is still used by %s -- forget those machines first")
:format(name, table.concat(names, ", "))
end
data.scripts[name] = nil
save(data)
return true
end







function scripts.addMachine(name, scriptName, device, by)
if type(name) ~= "string" or not name:match("^[a-z0-9_%-]+$") then
return nil, ("a machine's name is one lowercase path segment, like f1, not %s")
:format(tostring(name))
end
local script = scripts.get(scriptName)
if not script then return nil, "no script called " .. tostring(scriptName) end
local existing = scripts.machine(name)
if existing and existing.script ~= scriptName then
return nil, ("%s is already made from %s -- forget it first"):format(name,
existing.script)
end
if not existing then
for _, path in ipairs(mount.list("/" .. name)) do
local record = mount.get(path)
if not record or record.machine ~= name then
return nil, ("/%s is already in use by %s"):format(name, path)
end
end
end

local ok, why = machines.declare(name, script.ports, scriptName)
if not ok then return nil, why end
local bound = {}
if device then
local attached, attachWhy = machines.attach(name, device, script.ports)
if not attached then
if not existing then machines.forget(name) end
return nil, attachWhy
end
bound = attached
end

local data = load()
local record = data.machines[name] or {
name = name, script = scriptName, enabled = false, state = scripts.STOPPED,
faults = 0, handlers = {}, runs = {}, created = {at = os.epoch("utc"), by = by},
}
record.device = device or record.device
data.machines[name] = record
save(data)

local unbound = {}
for _, port in ipairs(machines.unbound(name)) do unbound[#unbound + 1] = port.path end
return record, {bound = bound, unbound = unbound}
end



function scripts.setLimit(name, item, at, resume)
if item and (not at or at < 1) then return nil, "a limit needs a level of at least 1" end
if item and resume and resume > at then
return nil, ("resume (%d) must be at most the limit (%d)"):format(resume, at)
end
local record = update(name, function(record)
record.limit = item and {item = item, at = at, resume = resume or at} or nil
end)
if not record then return nil, "no machine called " .. tostring(name) end
return record
end




function scripts.overLimit(machine, paused)
local limit = machine.limit
if not limit then return false end
local pool = require("mfg.common.config").setting("source")
local stock = store.stock(pool)
if not stock then return false end
local held = stock[limit.item] or 0
if paused then
if held >= limit.resume then
return true, ("%s %d, resumes below %d"):format(limit.item, held, limit.resume)
end
return false
end
if held >= limit.at then
return true, ("%s %d >= %d"):format(limit.item, held, limit.at)
end
return false
end

function scripts.enable(name)
return update(name, function(record)
record.enabled = true
record.faults = 0
if record.state == scripts.FAULTED then record.state = scripts.STOPPED end
end)
end

function scripts.disable(name)
return update(name, function(record) record.enabled = false end)
end



function scripts.forgetMachine(name)
local data = load()
if not data.machines[name] then return nil, "no machine called " .. tostring(name) end
data.machines[name] = nil
save(data)
signals.releaseAll("machine:" .. name)
alarms.clear("machine." .. name)
alarms.clear("machine." .. name .. ".fault")
return machines.forget(name)
end



local function handlerName(node)
if node.kind == "every" then return "every " .. node.every.n .. node.every.unit end
if node.kind == "when" then return "when " .. format.expr(node.cond) end
return "on " .. tostring(node.event)
end


function scripts.record(name, h, result, steps)
local now = os.epoch("utc")
local faulted = result.status == interp.FAULTED
local reason = result.reason
if faulted and result.line then reason = ("line %d: %s"):format(result.line, reason) end
local did = steps and #steps > 0

local record = update(name, function(record)
if not faulted and not did and (record.faults or 0) == 0 then return false end
local last = {at = now, handler = handlerName(h.node), status = result.status,
reason = reason, steps = did and steps or nil}
record.handlers = record.handlers or {}
record.handlers[h.index] = {at = now, status = result.status, reason = reason}
if did or faulted then
record.runs = record.runs or {}
table.insert(record.runs, 1, last)
while #record.runs > scripts.RING do table.remove(record.runs) end
end
if faulted then
record.faults = (record.faults or 0) + 1
record.lastError = reason
if record.faults >= scripts.FAULTS then
record.enabled = false
record.state = scripts.FAULTED
end
else
record.faults = 0
end
end)

if faulted then

journal.record({action = "machine:" .. name,
params = {handler = handlerName(h.node)}, status = rpc.REJECTED,
reason = reason, by = "scripts", at = now, steps = did and steps or nil})
alarms.raise("machine." .. name .. ".fault", ("%s faulted: %s"):format(name,
tostring(reason)), {source = "/" .. name})
elseif record and (record.faults or 0) == 0 then
alarms.clear("machine." .. name .. ".fault")
end
return record
end




function scripts.host(name, opts)
opts = opts or {}
local holder = "machine:" .. name
local host = {steps = {}, finishing = false}

function host.now() return (opts.now or os.epoch)("utc") end

function host.sleep(seconds)
if opts.sleep then return opts.sleep(seconds) end


local timer = os.startTimer(math.max(0.05, seconds))
while true do
local event, arg = os.pullEvent()
if event == "timer" and arg == timer then return end
if event == "redstone" then
os.cancelTimer(timer)
return
end
end
end

function host.stopping()
if host.finishing then return false end
local record = scripts.machine(name)
return not record or not record.enabled
end

function host.read(path, kind)
local level, on = signals.read(path)
if level == nil then return nil, on end
if kind == "flag" then return on end
return level
end

function host.count(path, item)
return store.count(path, item)
end

function host.free(item)
local pool = require("mfg.common.config").setting("source")
local available, why = require("mfg.controller.supervisor").available(pool)
if not available then return nil, why end
return available[item] or 0
end

function host.invoke(action, params)
return actions.invoke(action, params,
{by = holder, policy = holder, steps = host.steps})
end

function host.alarm(text)
alarms.raise("machine." .. name, text, {source = "/" .. name, severity = "hold"})
end

function host.clearAlarm()
alarms.clear("machine." .. name)
end

return host
end




local function claimOutputs(name, script)
local holder = "machine:" .. name
for _, port in ipairs(script.ports or {}) do
if port.kind ~= "volume" and port.direction == "output" then
local path = "/" .. name .. "/" .. port.name
local ok, held = signals.claim(path, holder)
if not ok then
return nil, ("%s is held by %s -- release it first"):format(path, held)
end
end
end
return true
end

local function stopWith(name, fields)
signals.releaseAll("machine:" .. name)
update(name, function(record)
for key, value in pairs(fields) do record[key] = value end
end)
end


local function runOne(name, script, run, host, h)
host.steps = {}
local result = run:runHandler(h)
if result.status == interp.ABORTED then return true end
local record = scripts.record(name, h, result, host.steps)
if result.status == interp.FAULTED then

signals.releaseAll("machine:" .. name)
if not record or not record.enabled then return false end
local ok, why = claimOutputs(name, script)
if not ok then
stopWith(name, {enabled = false, state = scripts.FAULTED, lastError = why})
return false
end
end
return true
end



function scripts.main(name, opts)
local machine = scripts.machine(name)
if not machine or not machine.enabled then return end
local script = scripts.get(machine.script)
if not script then
stopWith(name, {enabled = false, state = scripts.FAULTED,
lastError = "its script " .. tostring(machine.script) .. " is gone"})
return
end


local report = check.check(script.ast, scripts.env())
if not report.ok then
local first = report.errors[1]
stopWith(name, {enabled = false, state = scripts.FAULTED,
lastError = ("no longer checks: line %s: %s"):format(tostring(first.line),
first.message)})
return
end
local owned, why = claimOutputs(name, script)
if not owned then
stopWith(name, {enabled = false, state = scripts.FAULTED, lastError = why})
return
end

local host = scripts.host(name, opts)
local run = interp.new(script.ast, host, name)
local rev = script.rev
run:start(host.now())


local paused, why = scripts.overLimit(machine, false)
if paused then
update(name, function(r) r.state = scripts.PAUSED; r.pausedBy = why end)
else
update(name, function(r) r.state = scripts.RUNNING; r.pausedBy = nil end)
local begin = run:on("start")
if begin and not runOne(name, script, run, host, begin) then return end
end

while true do
machine = scripts.machine(name)
if not machine or not machine.enabled then



local finish = run:on("stop")
if finish and machine and machine.state ~= scripts.FAULTED and not paused then
host.finishing = true
runOne(name, script, run, host, finish)
end
if machine then
stopWith(name, {state = machine.state == scripts.FAULTED
and scripts.FAULTED or scripts.STOPPED, pausedBy = false})
else
signals.releaseAll("machine:" .. name)
end
return
end



local over, overWhy = scripts.overLimit(machine, paused)
if over and not paused then
paused = true
local finish = run:on("stop")
if finish then runOne(name, script, run, host, finish) end
signals.releaseAll("machine:" .. name)
claimOutputs(name, script)
update(name, function(r) r.state = scripts.PAUSED; r.pausedBy = overWhy end)
elseif not over and paused then
paused = false
update(name, function(r) r.state = scripts.RUNNING; r.pausedBy = nil end)
run:start(host.now())
local begin = run:on("start")
if begin and not runOne(name, script, run, host, begin) then return end
end


local latest = scripts.get(machine.script)
if latest and latest.rev ~= rev then
local ok, claimWhy = claimOutputs(name, latest)
if not ok then
stopWith(name, {enabled = false, state = scripts.FAULTED,
lastError = claimWhy})
return
end
script = latest
run = interp.new(script.ast, host, name)
rev = script.rev
run:start(host.now())
end

for _, met in ipairs(paused and {} or run:watch()) do
local keep = scripts.record(name, met.handler,
{status = interp.FAULTED, reason = met.reason}, {})
signals.releaseAll("machine:" .. name)
if not keep or not keep.enabled then return end
claimOutputs(name, script)
end

local h = not paused and run:due(host.now())
if paused then
run:skip(host.now())
host.sleep(interp.POLL)
elseif h then
if not runOne(name, script, run, host, h) then return end
else
local wake = run:nextAt()
local wait = interp.POLL
if wake then wait = math.min(wait, (wake - host.now()) / 1000) end
host.sleep(math.max(0.05, wait))
end
end
end




local function reconcile(live, opts)
for _, record in ipairs(scripts.machines()) do
if record.enabled and not live[record.name] then
local name = record.name
local co = coroutine.create(function()
local ok, err = pcall(scripts.main, name, opts)
if not ok then
printError(("machine %s: %s"):format(name, tostring(err)))
stopWith(name, {enabled = false, state = scripts.FAULTED,
lastError = tostring(err)})
end
end)
local entry = {co = co}
live[name] = entry
local ok, filter = coroutine.resume(co)
if not ok or coroutine.status(co) == "dead" then
live[name] = nil
else
entry.filter = filter
end
end
end
end



function scripts.run(opts)
signals.boot()
local live = {}
local tick = os.startTimer(0)
while true do
local event = table.pack(os.pullEventRaw())
if event[1] == "timer" and event[2] == tick then
local ok, err = pcall(reconcile, live, opts)
if not ok then printError("scripts: " .. tostring(err)) end
tick = os.startTimer(scripts.POLL)
end
for name, entry in pairs(live) do
if entry.filter == nil or entry.filter == event[1]
or event[1] == "terminate" then
local ok, filter = coroutine.resume(entry.co, table.unpack(event, 1, event.n))
if not ok then printError(("machine %s: %s"):format(name, tostring(filter))) end
if not ok or coroutine.status(entry.co) == "dead" then
live[name] = nil
else
entry.filter = filter
end
end
end
end
end

return scripts
]],
["mfg/controller/services.lua"] = [[













local services = require("mfg.common.services")

local controller = {}




local function netReady()
if require("net").ready() then return true end
return false, "the netstack has not come up"
end

local function acknetReady()
if require("acknet").isRunning() then return true end
return false, "acknet is not running"
end




function controller.checkIn(packet)
local body = packet and packet.body
if type(body) ~= "table" or body.kind ~= "checkin" then return false end
local name = packet.from or body.node
if type(name) ~= "string" or name == "" then return false end
require("mfg.controller.configs").observe(name, body, {verified = packet.from ~= nil})
return true
end




function controller.observeSelf(report)
return require("mfg.controller.configs").observe(report.node, report, {verified = true})
end

function controller.declare(manager, ctx)
services.declare(manager, {
name = "enrolld",
requires = {"netstack"},
ready = acknetReady,
start = function()
ctx.shell.run("/mfg/controller/enrolld")
end,
})








services.declare(manager, {
name = "reports",
requires = {"netstack"},
ready = netReady,
start = function()
local net = require("net")


ctx.bind({"mfg-control", "mfg-report", "mfg-scada", "mfg-order"})
while true do
local packet = net.receive("mfg-report", 5)
if packet then
local ok, err = pcall(controller.checkIn, packet)
if not ok then printError("check-in not recorded: " .. tostring(err)) end
end
end
end,
})











services.declare(manager, {
name = "scada",
requires = {"reports"},
start = function()
local actions = require("mfg.common.actions")
local status, fields = actions.invoke("serve_operator", {},
{by = "controller"})


error(("operator surface stopped: %s"):format(
tostring(fields and fields.reason or status)), 0)
end,
})




services.declare(manager, {
name = "alarms",
requires = {"reports"},
start = function()
local scada = require("mfg.controller.scada")
scada.tick({timeout = 2, attempts = 1})
while true do
sleep(1)
if scada.refreshDue() then
scada.tick({timeout = 2, attempts = 1})
end
end
end,
})



services.declare(manager, {
name = "orders",
requires = {"reports"},
start = function()
local net = require("net")
local rpc = require("mfg.common.rpc")
local orders = require("mfg.controller.orders")
while true do
local packet = net.receive("mfg-order", 2)
if packet and type(packet.body) == "table" then
local status, fields = orders.handle(packet.body, packet)
net.send(packet.src, "mfg-order",
rpc.reply(packet.body.rpc, status, fields))
end
end
end,
})




services.declare(manager, {
name = "fulfil",
requires = {"reports"},
start = function()
local orders = require("mfg.controller.orders")
local custody = require("mfg.storage.custody")
while true do
sleep(15)
local open = false
for _, order in pairs(custody.orders()) do
if order.state ~= custody.SETTLED
and order.state ~= custody.RETURNED
and order.state ~= custody.FULFILLED then
open = true
end
end
if open then orders.fulfil() end
end
end,
})





services.declare(manager, {
name = "jobs",
requires = {"reports"},
start = function()
require("mfg.controller.runner").run()
end,
})



services.declare(manager, {
name = "scheduler",
start = function()
require("mfg.controller.schedules").run()
end,
})



services.declare(manager, {
name = "intake",
start = function()
require("mfg.controller.ports").run()
end,
})




services.declare(manager, {
name = "scripts",
start = function()
require("mfg.controller.scripts").run()
end,
})
end

return controller
]],
["mfg/controller/signals.lua"] = [[

















local state = require("mfg.common.state")
local hal = require("mfg.common.hal")
local mount = require("mfg.storage.mount")

local signals = {}

local OWNERS = "signal-owners"


local function levelOf(record, value)
if type(value) == "boolean" then return value and 15 or 0 end
value = math.floor(tonumber(value) or 0)
if value < 0 then value = 0 end
if value > 15 then value = 15 end
if record.kind == "flag" then return value > 0 and 15 or 0 end
return value
end


function signals.get(path)
local record = mount.get(path)
if not record then return nil, ("no such signal: %s"):format(tostring(path)) end
if not mount.isSignal(record) then
return nil, ("%s is a volume, not a signal"):format(path)
end
return record
end


local function wire(path)
local record, why = signals.get(path)
if not record then return nil, why end
local device = record.devices and record.devices[1]
if not device or not record.face then
return nil, ("%s is declared but UNBOUND -- mfgctl bind %s <relay> <face>")
:format(path, path)
end
if not hal.redstone().isPresent(device) then
return nil, ("%s: %s is not on the network"):format(path, device)
end
return record, device, record.face
end


function signals.all()
local out = {}
for _, path in ipairs(mount.list(nil, "signal")) do
out[#out + 1] = mount.get(path)
end
return out
end


function signals.safe(record)
return levelOf(record, record.safe or 0)
end



local function owners()
local data = state.read(OWNERS, {})
if type(data) ~= "table" then return {} end
return data
end

function signals.owner(path)
return owners()[path]
end

function signals.owners()
return owners()
end


function signals.claim(path, holder)
local all = owners()
if all[path] and all[path] ~= holder then return nil, all[path] end
all[path] = holder
state.write(OWNERS, all)
return true
end




function signals.read(path)
local record, device, face = wire(path)
if not record then return nil, device end
local rs = hal.redstone()
local ok, level = pcall(function()
if record.direction == "output" then return rs.getAnalogOutput(device, face) end
if record.kind == "flag" then return rs.getInput(device, face) and 15 or 0 end
return rs.getAnalogInput(device, face)
end)
if not ok then return nil, ("%s: %s"):format(path, tostring(level)) end
level = levelOf(record, level)
return level, level > 0
end

local function drive(record, device, face, level)
local rs = hal.redstone()
return pcall(function()
if record.kind == "flag" then
rs.setOutput(device, face, level > 0)
else
rs.setAnalogOutput(device, face, level)
end
end)
end






function signals.write(path, value, holder)
local record, device, face = wire(path)
if not record then return nil, device end
if record.direction ~= "output" then
return nil, ("%s is an input -- it is read, not driven"):format(path)
end
holder = holder or "operator"
local ok, held = signals.claim(path, holder)
if not ok then return nil, ("%s is held by %s"):format(path, held) end

local rs = hal.redstone()
local was = rs.getAnalogOutput(device, face)
local lived, err = drive(record, device, face, levelOf(record, value))
if not lived then return nil, ("%s: %s"):format(path, tostring(err)) end
return was
end



function signals.pulse(path, value, ticks, holder)
local was, why = signals.write(path, value, holder)
if not was then return nil, why end
sleep(ticks / 20)
local record, device, face = wire(path)
if not record then return nil, device end
local lived, err = drive(record, device, face, was)
if not lived then return nil, ("%s: %s"):format(path, tostring(err)) end
return was
end



function signals.release(path, holder)
local all = owners()
if holder and all[path] and all[path] ~= holder then
return nil, ("%s is held by %s"):format(path, all[path])
end
all[path] = nil
state.write(OWNERS, all)

local record, device, face = wire(path)
if not record then return nil, device end
if record.direction ~= "output" then return true end
local lived, err = drive(record, device, face, signals.safe(record))
if not lived then return nil, ("%s: %s"):format(path, tostring(err)) end
return true
end


function signals.releaseAll(holder)
local released = {}
for path, owner in pairs(owners()) do
if owner == holder then
signals.release(path, holder)
released[#released + 1] = path
end
end
table.sort(released)
return released
end



function signals.boot()
state.write(OWNERS, {})
local written = {}
for _, record in ipairs(signals.all()) do
if record.direction == "output" then
local _, device, face = wire(record.path)
if device and face then
drive(record, device, face, signals.safe(record))
written[#written + 1] = record.path
end
end
end
return written
end

return signals
]],
["mfg/controller/supervisor.lua"] = [[





local dispatch = require("mfg.controller.dispatch")
local store = require("mfg.storage")
local config = require("mfg.common.config")

local supervisor = {}





function supervisor.available(source)
local stock, why = store.stock(source or config.setting("source"))
if not stock then return nil, why end
local claims, byJob = dispatch.claims()
local available = {}
for item, count in pairs(stock) do
available[item] = math.max(0, count - math.floor(claims[item] or 0))
end
return available, {stock = stock, claims = claims, byJob = byJob}
end



function supervisor.describeShort(plan, breakdown)
local items = {}
for item in pairs(plan.short) do items[#items + 1] = item end
table.sort(items)

local parts, short = {}, {}
for _, item in ipairs(items) do
local wanted = (plan.draws[item] or 0) + plan.short[item]
local have = plan.draws[item] or 0
short[item] = {wanted = wanted, have = have}

local text = ("%s: needs %d, pool holds %d"):format(item, wanted,
breakdown.stock[item] or 0)
local promised = {}
for _, claim in ipairs(breakdown.byJob[item] or {}) do
promised[#promised + 1] = ("%d to job %d"):format(
math.floor(claim.count), claim.job)
end
if #promised > 0 then
text = text .. ", " .. table.concat(promised, ", ") .. " promised"
end
parts[#parts + 1] = text
end
return table.concat(parts, "; "), short
end





function supervisor.order(recipeId, quantity, opts)
opts = opts or {}
local available, breakdown = supervisor.available(opts.source)
if not available then return nil, "the pool cannot be read: " .. tostring(breakdown) end

local plan, why = dispatch.plan(recipeId, quantity, available)
if not plan then return nil, why end

if next(plan.short) then
local text, short = supervisor.describeShort(plan, breakdown)
plan.shortfall = short
return nil, text, plan
end

local id = dispatch.commit(plan, {by = opts.by, requested = quantity,
order = opts.order})
return id, plan
end

return supervisor
]],
["mfg/controller/tags.lua"] = [[











local turtles = require("mfg.controller.turtles")
local dispatch = require("mfg.controller.dispatch")
local store = require("mfg.storage")
local custody = require("mfg.storage.custody")
local pointlist = require("mfg.common.points")

local tags = {}

tags.OK = "ok"
tags.STALE = "stale"
tags.UNAVAILABLE = "unavailable"


local STALE_AFTER = 10 * 1000



local function set(snapshot, source, point, value, valid, at)
snapshot[source] = snapshot[source] or {}
snapshot[source][point] = {
value = value,
at = at or os.epoch("utc"),
valid = valid or tags.OK,
}
end

tags.set = set








local function nodeTags(snapshot, turtle, opts, previous)
local source = turtle.id
local points, answer = turtles.points(turtle, opts)

if not points then


local was = previous and previous[source]
if was then
for point, tag in pairs(was) do
set(snapshot, source, point, tag.value, tags.STALE, tag.at)
end
end








local condition = turtles.condition(turtle,
{timeout = 1, attempts = 1})
set(snapshot, source, "comms", condition, tags.OK)
set(snapshot, source, "state", (was and was.state and was.state.value)
or "unknown", tags.STALE)
return answer
end

set(snapshot, source, "comms", "ok")
for point, value in pairs(points) do
set(snapshot, source, point, value, tags.OK)
end



local version = points.points_version or 1
if not pointlist.understood(version) then




set(snapshot, source, "points_version", version, tags.UNAVAILABLE)
else
set(snapshot, source, "points_version", version, tags.OK)
end
return answer
end










local function volumeTags(snapshot, path)
local source = path
local summary = store.summary(path)
if not summary then return end

set(snapshot, source, "bound", summary.bound)
set(snapshot, source, "coherence", summary.coherence)
set(snapshot, source, "degraded", summary.degraded)
if summary.degraded then
set(snapshot, source, "missing", table.concat(summary.missing, ", "))
end
if not summary.bound then


set(snapshot, source, "used", 0, tags.UNAVAILABLE)
set(snapshot, source, "free", 0, tags.UNAVAILABLE)
return
end

local slots = summary.slots
if slots then
set(snapshot, source, "slots", slots.total)
set(snapshot, source, "used", slots.used)
set(snapshot, source, "free", slots.free)
set(snapshot, source, "keys", slots.keys)
set(snapshot, source, "reclaimable", slots.reclaimable)
end
set(snapshot, source, "items", summary.items or 0)
end



local function orderTags(snapshot, id, order)
local source = id
set(snapshot, source, "state", order.state)
set(snapshot, source, "product", order.product)
set(snapshot, source, "quantity", order.quantity)
set(snapshot, source, "from", order.from)

local function total(tbl)
local n = 0
for _, count in pairs(tbl or {}) do n = n + count end
return n
end
set(snapshot, source, "owed", total(order.owed))
set(snapshot, source, "delivered", total(order.delivered))
set(snapshot, source, "received", total(order.received))
set(snapshot, source, "offManifest", total(order.offManifest))
if next(order.offManifest or {}) then
local parts = {}
for item, count in pairs(order.offManifest) do
parts[#parts + 1] = ("%d %s"):format(count, item)
end
set(snapshot, source, "offManifestDetail", table.concat(parts, ", "))
end
end





function tags.snapshot(opts, previous)
opts = opts or {timeout = 2, attempts = 2}
local snapshot = {}

set(snapshot, "cluster", "at", os.epoch("utc"))

local nodeCount, faulted, idle = 0, 0, 0
for _, turtle in pairs(turtles.all()) do
nodeCount = nodeCount + 1
nodeTags(snapshot, turtle, opts, previous)
local node = snapshot[turtle.id]
local state = node and node.state and node.state.value
if state == "faulted" then faulted = faulted + 1 end
if state == "idle" then idle = idle + 1 end
end
set(snapshot, "cluster", "nodes", nodeCount)
set(snapshot, "cluster", "faulted", faulted)
set(snapshot, "cluster", "idle", idle)



volumeTags(snapshot, custody.POOL)
volumeTags(snapshot, custody.IN)
volumeTags(snapshot, custody.OUT)
for _, path in ipairs(store.volumes()) do
if snapshot[path] == nil then volumeTags(snapshot, path) end
end

local orderCount, openCount = 0, 0
for id, order in pairs(custody.orders()) do
orderCount = orderCount + 1
if order.state ~= custody.SETTLED and order.state ~= custody.RETURNED then
openCount = openCount + 1
end
orderTags(snapshot, id, order)
end
set(snapshot, "cluster", "orders", orderCount)
set(snapshot, "cluster", "ordersOpen", openCount)

local queue = dispatch.queue()
set(snapshot, "queue", "jobs", #queue.jobs)
local running = 0
for _, job in ipairs(queue.jobs) do
if job.state == "running" then running = running + 1 end
end
set(snapshot, "queue", "running", running)

return snapshot
end





function tags.staleify(snapshot)
if type(snapshot) ~= "table" then return {} end
for _, points in pairs(snapshot) do
for _, tag in pairs(points) do
tag.valid = tags.STALE
end
end
return snapshot
end


function tags.isStale(tag, now, after)
if not tag then return true end
if tag.valid == tags.STALE then return true end
now = now or os.epoch("utc")
return (now - (tag.at or 0)) > (after or STALE_AFTER)
end

function tags.value(snapshot, source, point, fallback)
local tag = snapshot and snapshot[source] and snapshot[source][point]
if not tag then return fallback end
return tag.value
end

return tags
]],
["mfg/controller/turtles.lua"] = [[












local rpc = require("mfg.common.rpc")
local store = require("mfg.storage")
local state = require("mfg.common.state")

local turtles = {}

local STATE_FILE = "turtles"
local CONTROL = "mfg-control"











function turtles.register(id, opts)
local inPath = ("/%s/in"):format(id)
local outPath = ("/%s/out"):format(id)

store.declare(inPath, {node = id, role = "input"})
store.declare(outPath, {node = id, role = "output"})




if opts.input then
store.bind(inPath, {opts.input}, {node = id, role = "input"})
end
if opts.output then
store.bind(outPath, {opts.output}, {node = id, role = "output"})
end

local all = state.read(STATE_FILE, {})
all[id] = {
id = id,
host = opts.host,
input = inPath,
output = outPath,
source = opts.source,
recipe = opts.recipe,




label = opts.label or id,
labelled = false,
registered = os.epoch("utc"),
}
state.write(STATE_FILE, all)
return all[id]
end

function turtles.all()
return state.read(STATE_FILE, {})
end

function turtles.get(id)
return turtles.all()[id]
end










function turtles.setTransit(id, seconds)
local all = turtles.all()
if not all[id] then return nil, "no such turtle: " .. tostring(id) end
all[id].transit = seconds
state.write(STATE_FILE, all)
return all[id]
end

















function turtles.setPattern(id, patternId, pattern)
local all = turtles.all()
if not all[id] then return nil, "no such turtle: " .. tostring(id) end
all[id].pattern_id = patternId
all[id].pattern = pattern
state.write(STATE_FILE, all)
return all[id]
end



local function command(turtle, body, opts)
return rpc.request(turtle.host, CONTROL, body, opts)
end

function turtles.points(turtle, opts)
local answer = command(turtle, {command = "points"}, opts)
if answer.status ~= rpc.COMPLETED then return nil, answer end
return answer.points, answer
end











function turtles.setLabel(turtle, opts)
opts = opts or {}
local label = opts.label or turtle.label or turtle.id
if not label then return false, "no label to set" end

local answer = command(turtle, {command = "set_label", label = label}, opts)
if not answer or answer.status ~= rpc.COMPLETED then
return false, (answer and (answer.reason or answer.status)) or "no reply"
end

local confirmed = answer.label or label
local all = turtles.all()
if all[turtle.id] then
all[turtle.id].label = confirmed
all[turtle.id].labelled = true
state.write(STATE_FILE, all)
end
return true, confirmed
end

function turtles.clearFault(turtle, opts)
return command(turtle, {command = "clear_fault"}, opts)
end




function turtles.stop(turtle, opts)
return command(turtle, {command = "stop"}, opts)
end






function turtles.observe(turtle, opts)
local answer = command(turtle, {command = "probe_observe"}, opts)
if answer.status ~= rpc.COMPLETED then return nil, answer end
return answer.observed, answer
end

function turtles.emitMarker(turtle, marker, opts)
local answer = command(turtle, {command = "probe_emit", marker = marker}, opts)
if answer.status ~= rpc.COMPLETED then
return false, answer.reason or answer.status
end
return true
end













function turtles.reachable(turtle, opts)
opts = opts or {}
local icmp = require("icmp")
local net = require("net")

local address = turtle.address
if not address then
address = net.resolve(turtle.host)
if not address then return false, "cannot resolve " .. tostring(turtle.host) end
end

return icmp.reachable(address, {
timeout = opts.timeout or 2,
attempts = opts.attempts or 3,
})
end











function turtles.condition(turtle, opts)
local points = turtles.points(turtle, opts)
if points then return "ok", points end

local reachable = turtles.reachable(turtle, opts)
if reachable then return "silent" end
return "unreachable"
end













local busy = {}


function turtles.claim(id, holder)
if busy[id] then return nil, busy[id] end
busy[id] = tostring(holder or "a batch")
return true
end

function turtles.release(id)
busy[id] = nil
end

return turtles
]],
