["mfg/hmi/app.lua"] = [[







local doc = require("mfg.hmi.doc")

local app = {}

app.COMPLETED = "completed"
app.REJECTED = "rejected"
app.TIMED_OUT = "timed_out"


app.STEPS = {1, 8, 64}
local KEYS = {[1] = {"-", "+"}, [8] = {"[", "]"}}

function app.clock(view)
if view.now then return view.now() end
return os.epoch("utc")
end

function app.shortName(item)
if type(item) ~= "string" then return "" end
return item:match("[^:]+$") or item
end

function app.parameter(view, name)
if not view.offer then return nil end
for _, param in ipairs(view.offer.parameters or {}) do
if param.name == name then return param end
end
return nil
end


function app.ask(view, job)
for _, queued in ipairs(view.queue) do
if queued.kind == job.kind then return false end
end
view.queue[#view.queue + 1] = job
return true
end


function app.noteLink(view, answer)
local now = app.clock(view)
if answer.src then
view.link = {state = "ok", at = now}
elseif answer.status == app.TIMED_OUT or answer.status == app.REJECTED then
view.link = {state = "down", reason = answer.reason, at = now}
end
end

function app.header(view, title)
local link = view.link or {}
local text, colour = view.host .. " ...", "dim"
if link.state == "ok" then
text, colour = view.host .. " ok", "good"
elseif link.state == "down" then
text, colour = ("%s down: %s"):format(view.host, tostring(link.reason)), "bad"
end
return doc.row({
doc.text(title, {colour = "title", keep = doc.REQUIRED, name = "title"}),
doc.spacer({min = 1}),
doc.text(text, {colour = colour, keep = doc.REQUIRED, truncate = doc.TRUNCATED,
name = "link"}),
}, {keep = doc.REQUIRED, name = "header"})
end



















function app.newList()
return {from = 1, shown = 0, listed = 0, back = {}, query = ""}
end



local function fold(text)
return (tostring(text or ""):lower():gsub("[_ ]", " "))
end




function app.matches(query, entry)
if not query or query == "" then return true end
local q = fold(query)
return fold(entry.value):find(q, 1, true) ~= nil
or fold(entry.label):find(q, 1, true) ~= nil
end


local function requery(list, query)
list.query = query
list.from, list.shown, list.back = 1, 0, {}
end

local function searchRow(list, matched, total, prefix, keep)
local children
if list.query == "" then
children = {doc.text("type to search", {colour = "dim", width = "fill",
truncate = doc.TRUNCATED, name = prefix .. "-query"})}
else
children = {
doc.text(("find: %s_"):format(list.query), {colour = "title",
width = "fill", truncate = doc.TRUNCATED, name = prefix .. "-query"}),
doc.gap(1),
doc.text(("%d of %d"):format(matched, total), {colour = "dim", keep = 2,
name = prefix .. "-count"}),
doc.gap(1),
doc.button("clear", {key = "delete", keyLabel = "del", colour = "bad",
action = {kind = "clear-search"}, keep = 3,
name = prefix .. "-clear"}),
}
end
return doc.row(children, {keep = keep, name = prefix .. "-search"})
end








function app.listRows(list, entries, prefix, action)
local matched = {}
for _, entry in ipairs(entries) do
if app.matches(list.query, entry) then matched[#matched + 1] = entry end
end
local last = #matched
list.total = last
list.top = matched[list.from] and action(matched[list.from]) or nil
if #entries == 0 then
list.listed = 0
return {}
end



local rows = {searchRow(list, last, #entries, prefix, 22 + #entries)}
if last == 0 then
rows[#rows + 1] = doc.text(("nothing matches \"%s\""):format(list.query),
{colour = "warn", wrap = true, keep = 20, name = prefix .. "-none"})
end

list.listed = math.max(0, last - list.from + 1)
local position = 0
for index = list.from, last do
position = position + 1
local entry = matched[index]
local children = {
doc.button(entry.label, {
width = "fill", align = "left",
colour = entry.selected and "selected" or "action",
action = action(entry),
key = position <= 9 and tostring(position) or nil,
name = prefix .. ":" .. index,
}),
}
if entry.note then
children[#children + 1] = doc.gap(1)
children[#children + 1] = doc.text(tostring(entry.note), {colour = "dim",
name = prefix .. "-note:" .. index})
end
rows[#rows + 1] = doc.row(children,
{keep = 20 + (last - index), name = prefix .. ":" .. index})
end

local nav = {}
if #list.back > 0 then
nav[#nav + 1] = doc.button("prev", {key = "left", keyLabel = "<",
action = {kind = "prev"}, keep = 18, name = "prev"})
nav[#nav + 1] = doc.gap(1)
end
if list.from + list.shown <= last then
nav[#nav + 1] = doc.button("next", {key = "right", keyLabel = ">",
action = {kind = "next"}, keep = 18, name = "next"})
end



if #nav > 0 then
rows[#rows + 1] = doc.row(nav, {keep = 21 + (last - list.from),
name = prefix .. "-nav"})
end
return rows
end


function app.settle(list, report, prefix)
if not report then return false end
local dropped = 0
for _, entry in ipairs(report.dropped or {}) do
if type(entry.name) == "string" and entry.name:find("^" .. prefix .. ":") then
dropped = dropped + 1
end
end
local shown = (list.listed or 0) - dropped
if shown == list.shown then return false end
list.shown = shown
return true
end


function app.page(list, kind)
if kind == "next" then
if list.total and list.from + math.max(list.shown, 1) > list.total then
return false
end
list.back[#list.back + 1] = list.from
list.from = list.from + math.max(list.shown, 1)
list.shown = 0
return true
elseif kind == "prev" then
if #list.back == 0 then return false end
list.from = table.remove(list.back) or 1
list.shown = 0
return true
elseif kind == "clear-search" then
requery(list, "")
return true
end
return false
end








function app.type(list, event)
if not list or not event then return false end
if event.kind == "char" then
local ch = event.char
if type(ch) ~= "string" or not ch:match("^[%a_: ]$") then return false end
requery(list, list.query .. ch:lower())
return true
end
if event.kind ~= "key" or not keys then return false end
local key = event.key
if key == keys.backspace and list.query ~= "" then
requery(list, list.query:sub(1, -2))
return true
elseif key == keys.delete and list.query ~= "" then
requery(list, "")
return true
elseif key == keys.pageDown then
app.page(list, "next")
return true
elseif key == keys.pageUp then
app.page(list, "prev")
return true
end
return false
end



function app.quantityRow(value, usable, label)
local children = {doc.text(label or "Qty", {colour = "label", keep = doc.REQUIRED,
name = "qty-label"}), doc.gap(1)}
for i = #app.STEPS, 1, -1 do
local step = app.STEPS[i]
children[#children + 1] = doc.button("-" .. step, {
key = usable and KEYS[step] and KEYS[step][1] or nil,
colour = usable and "action" or "dim",
action = usable and {kind = "delta", n = -step} or nil,
keep = (step == 1) and doc.REQUIRED or (6 - i), name = "less" .. step})
children[#children + 1] = doc.gap(1)
end
children[#children + 1] = doc.text(tostring(value), {width = 4, align = "right",
colour = usable and "text" or "dim", keep = doc.REQUIRED, name = "quantity"})
for i, step in ipairs(app.STEPS) do
children[#children + 1] = doc.gap(1)
children[#children + 1] = doc.button("+" .. step, {
key = usable and KEYS[step] and KEYS[step][2] or nil,
colour = usable and "action" or "dim",
action = usable and {kind = "delta", n = step} or nil,
keep = (step == 1) and doc.REQUIRED or (6 - i), name = "more" .. step})
end
return doc.row(children, {keep = doc.REQUIRED, name = "qty"})
end


function app.clamp(value, min, max)
value = math.floor(tonumber(value) or min)
if value < min then value = min end
if max and value > max then value = max end
return value
end

return app
]],
["mfg/hmi/doc.lua"] = [[
















local doc = {}






doc.REQUIRED = "required"




doc.TRUNCATED = ".."

local function element(kind, fields)
local e = fields or {}
e.kind = kind
if e.keep == nil then e.keep = 1 end
return e
end

function doc.text(value, opts)
opts = opts or {}
return element("text", {
value = tostring(value == nil and "" or value),
colour = opts.colour or "text",
width = opts.width or "auto",
align = opts.align or "left",
truncate = opts.truncate,



wrap = opts.wrap,
keep = opts.keep,
name = opts.name,
action = opts.action,
when = opts.when,
})
end

function doc.stack(children, opts)
opts = opts or {}
return element("stack", {children = children or {}, keep = opts.keep,
name = opts.name, when = opts.when, height = opts.height,
width = opts.width})
end

function doc.row(children, opts)
opts = opts or {}
return element("row", {children = children or {}, keep = opts.keep,
name = opts.name, when = opts.when, width = opts.width})
end


function doc.gap(cells)
return element("gap", {size = cells or 1, keep = doc.REQUIRED})
end






function doc.spacer(opts)
opts = opts or {}
return element("spacer", {width = "fill", keep = doc.REQUIRED,
min = opts.min or 0})
end




















function doc.button(label, opts)
opts = opts or {}
return element("button", {
label = tostring(label),
key = opts.key and tostring(opts.key) or nil,




keyLabel = opts.keyLabel and tostring(opts.keyLabel) or nil,
colour = opts.colour or "action",
width = opts.width or "auto",


align = opts.align or (opts.width == "fill" and "centre" or "left"),
keep = opts.keep,
name = opts.name or tostring(label),
action = opts.action,
when = opts.when,
})
end











function doc.slider(opts)
opts = opts or {}
local min = tonumber(opts.min) or 0
local max = tonumber(opts.max) or min
if max < min then max = min end
local value = tonumber(opts.value) or min
if value < min then value = min end
if value > max then value = max end
return element("slider", {
min = min, max = max, value = value,
width = opts.width or "fill",
colour = opts.colour or "selected",
restColour = opts.restColour or "dim",
keep = opts.keep,
name = opts.name or "slider",

action = opts.action,
when = opts.when,
})
end








local showKeys = false












local contested = {}



local function buttonInner(e)
if showKeys and e.key and not contested[e.key] then
return ("%s %s"):format(e.keyLabel or e.key, e.label)
end
return e.label
end


local function buttonText(e)
return "[" .. buttonInner(e) .. "]"
end

function doc.rule(opts)
opts = opts or {}
return element("rule", {char = opts.char or "-", colour = opts.colour or "dim",
keep = opts.keep, name = opts.name, when = opts.when})
end


function doc.field(opts)
return element("field", {
label = tostring(opts.label or ""),
value = tostring(opts.value == nil and "" or opts.value),
colour = opts.colour or "text",
labelColour = opts.labelColour or "label",
leader = opts.leader,
width = opts.width or "auto",
keep = opts.keep,
name = opts.name or opts.label,
action = opts.action,
when = opts.when,
})
end



function doc.table(opts)
return element("table", {
columns = opts.columns or {},
rows = opts.rows or {},
headColour = opts.headColour or "label",
keep = opts.keep,
name = opts.name,
when = opts.when,
gap = opts.gap or 1,
})
end



local function truncateTo(text, width, marker)
if width <= 0 then return "" end
if #text <= width then return text end
marker = marker or ""
if #marker >= width then return text:sub(1, width) end
return text:sub(1, width - #marker) .. marker
end

local function pad(text, width, align)
local short = width - #text
if short <= 0 then return text end
if align == "right" then return (" "):rep(short) .. text end
if align == "centre" or align == "center" then
local left = math.floor(short / 2)
return (" "):rep(left) .. text .. (" "):rep(short - left)
end
return text .. (" "):rep(short)
end


local function naturalWidth(e)
if e.kind == "text" then return #e.value end
if e.kind == "button" then return #buttonText(e) end
if e.kind == "gap" then return e.size end
if e.kind == "spacer" then return e.min end
if e.kind == "rule" then return 1 end


if e.kind == "slider" then return 3 end
if e.kind == "field" then
return #e.label + 1 + #e.value
end
if e.kind == "table" then
local total = 0
for i, column in ipairs(e.columns) do
total = total + (tonumber(column.width) or #tostring(column.head or ""))
if i > 1 then total = total + e.gap end
end
return total
end
if e.kind == "row" then
local total = 0
for _, child in ipairs(e.children) do total = total + naturalWidth(child) end
return total
end
if e.kind == "stack" then
local widest = 0
for _, child in ipairs(e.children) do
widest = math.max(widest, naturalWidth(child))
end
return widest
end
return 0
end





local function naturalHeight(e, width)



if e.kind == "spacer" then return 0 end
if e.kind == "text" and e.wrap and width and width > 0 then
return math.max(1, math.ceil(#e.value / width))
end
if e.kind == "stack" then
local total = 0
for _, child in ipairs(e.children) do
total = total + naturalHeight(child, tonumber(e.width) or width)
end
return total
end
if e.kind == "row" then
local tallest = 1
for _, child in ipairs(e.children) do
tallest = math.max(tallest, naturalHeight(child, width))
end
return tallest
end
if e.kind == "table" then
local rows = #e.rows
local head = 0
for _, column in ipairs(e.columns) do
if column.head then head = 1 break end
end
return rows + head
end
return 1
end




local function leastHeight(e, width)
if e.kind ~= "stack" then return naturalHeight(e, width) end
local total = 0
for _, child in ipairs(e.children) do
if child.keep == doc.REQUIRED then
total = total + leastHeight(child, tonumber(e.width) or width)
end
end
return total
end








local function widthOf(e)
return tonumber(e.width) or naturalWidth(e)
end



local function newReport()
return {dropped = {}, truncated = {}, collisions = {}, failed = nil, ok = true}
end

local function nameOf(e, fallback)
return e.name or (e.kind == "text" and e.value) or e.kind or fallback or "?"
end





local function visible(e, width, height)
if not e.when then return true end
if e.when.minWidth and width < e.when.minWidth then return false end
if e.when.minHeight and height < e.when.minHeight then return false end
if e.when.maxWidth and width > e.when.maxWidth then return false end
return true
end







local function newGrid(width, height)
return {width = width, height = height, rows = {}, targets = {},
keys = {}}
end

local function put(grid, x, y, text, colour)
if y < 1 or y > grid.height then return end
if text == "" then return end



if x < 1 then
text = text:sub(2 - x)
x = 1
end
local room = grid.width - x + 1
if room <= 0 then return end
if #text > room then text = text:sub(1, room) end

grid.rows[y] = grid.rows[y] or {}
local row = grid.rows[y]
row[#row + 1] = {x = x, text = text, colour = colour or "text"}
end

local function target(grid, x, y, w, h, action)
if not action or w <= 0 or h <= 0 then return end
grid.targets[#grid.targets + 1] = {x1 = x, y1 = y, x2 = x + w - 1,
y2 = y + h - 1, action = action}
end



local MARKER = {bad = "!", warn = "*", stale = "~"}

local function markerFor(colour, mono)
if not mono then return nil end
return MARKER[colour]
end

local drawElement


local function drawRow(e, grid, x, y, width, height, report, mono)
local kids = {}
for _, child in ipairs(e.children) do
if visible(child, grid.width, grid.height) then kids[#kids + 1] = child end
end


local function fixedTotal(list)
local total = 0
for _, child in ipairs(list) do
if child.width ~= "fill" then total = total + widthOf(child) end
end
return total
end

while fixedTotal(kids) > width do

local worst, worstAt = nil, nil
for index, child in ipairs(kids) do
if child.keep ~= doc.REQUIRED then
if not worst or child.keep < worst.keep then
worst, worstAt = child, index
end
end
end
if not worst then


for _, child in ipairs(kids) do
if child.keep == doc.REQUIRED and widthOf(child) > width then
report.failed = {name = nameOf(child),
why = ("needs %d cells, has %d"):format(
widthOf(child), width)}
report.ok = false
return 1
end
end
report.failed = {name = nameOf(e, "row"),
why = ("required children need %d cells, row has %d"):format(
fixedTotal(kids), width)}
report.ok = false
return 1
end
report.dropped[#report.dropped + 1] = {name = nameOf(worst),
why = ("row is %d cells; would have needed %d"):format(
width, fixedTotal(kids))}
table.remove(kids, worstAt)




local before = kids[worstAt - 1]
if before and before.kind == "gap" then
table.remove(kids, worstAt - 1)
elseif worstAt == 1 and kids[1] and kids[1].kind == "gap" then
table.remove(kids, 1)
end
end


local fills = 0
for _, child in ipairs(kids) do
if child.width == "fill" then fills = fills + 1 end
end
local remainder = width - fixedTotal(kids)
if remainder < 0 then remainder = 0 end

local cursor = x
local tallest = 1
local given = 0
local seen = 0
for _, child in ipairs(kids) do
local childWidth
if child.width == "fill" then
seen = seen + 1
if seen == fills then
childWidth = remainder - given
else
childWidth = math.floor(remainder / fills)
given = given + childWidth
end
else
childWidth = widthOf(child)
end

local used = drawElement(child, grid, cursor, y, childWidth, height,
report, mono)
tallest = math.max(tallest, used or 1)
cursor = cursor + childWidth
end

return tallest
end

local function drawStack(e, grid, x, y, width, height, report, mono)
local kids = {}
for _, child in ipairs(e.children) do
if visible(child, grid.width, grid.height) then kids[#kids + 1] = child end
end









local function heightTotal(list)
local total = 0
for _, child in ipairs(list) do
total = total + leastHeight(child, width)
end
return total
end

while heightTotal(kids) > height do
local worst, worstAt = nil, nil
for index, child in ipairs(kids) do
if child.keep ~= doc.REQUIRED then
if not worst or child.keep < worst.keep then
worst, worstAt = child, index
end
end
end
if not worst then
report.failed = {name = nameOf(e, "stack"),
why = ("required rows need %d lines, has %d"):format(
heightTotal(kids), height)}
report.ok = false
return 0
end
report.dropped[#report.dropped + 1] = {name = nameOf(worst),
why = ("only %d lines available"):format(height)}
table.remove(kids, worstAt)
end







local spacers, fixed = 0, 0
for _, child in ipairs(kids) do
if child.kind == "spacer" then
spacers = spacers + 1
else
fixed = fixed + naturalHeight(child, width)
end
end

local slack = height - fixed
if slack < 0 then slack = 0 end



local after = {}
local below = 0
for index = #kids, 1, -1 do
after[index] = below
below = below + leastHeight(kids[index], width)
end

local cursor = y
local given, seen = 0, 0
for index, child in ipairs(kids) do
if report.failed then break end
local used
if child.kind == "stack" then
used = drawElement(child, grid, x, cursor, width,
height - (cursor - y) - after[index], report, mono)
elseif child.kind == "spacer" then
seen = seen + 1
if seen == spacers then
used = slack - given
else
used = math.floor(slack / spacers)
given = given + used
end
if used < 0 then used = 0 end
else
used = drawElement(child, grid, x, cursor, width,
height - (cursor - y), report, mono)
end
cursor = cursor + (used or 1)
end
return cursor - y
end

local function drawTable(e, grid, x, y, width, height, report, mono)
local widths = {}
for index, column in ipairs(e.columns) do
widths[index] = tonumber(column.width) or #tostring(column.head or "")
end

local line = y
local hasHead = false
for _, column in ipairs(e.columns) do
if column.head then hasHead = true break end
end

if hasHead then
local cursor = x
for index, column in ipairs(e.columns) do
local head = truncateTo(tostring(column.head or ""), widths[index])
put(grid, cursor, line, pad(head, widths[index], column.align),
e.headColour)
cursor = cursor + widths[index] + e.gap
end
line = line + 1
end

for _, row in ipairs(e.rows) do
if (line - y) >= height then
report.truncated[#report.truncated + 1] = {
name = nameOf(e, "table"),
from = ("%d rows"):format(#e.rows),
to = ("%d shown"):format(line - y - (hasHead and 1 or 0)),
}
break
end
local cursor = x
for index, column in ipairs(e.columns) do
local cell = row[index]
local value, colour
if type(cell) == "table" then
value, colour = tostring(cell.value or ""), cell.colour
else
value, colour = tostring(cell == nil and "" or cell), nil
end

local marker = markerFor(colour, mono)
if marker then value = marker .. value end

local shown = truncateTo(value, widths[index], doc.TRUNCATED)
if #value > widths[index] then
report.truncated[#report.truncated + 1] = {
name = column.head or ("column " .. index),
from = value, to = shown,
}
end
put(grid, cursor, line, pad(shown, widths[index], column.align),
colour or "text")
cursor = cursor + widths[index] + e.gap
end
if row.action then
target(grid, x, line, width, 1, row.action)
end
line = line + 1
end

return line - y
end

function drawElement(e, grid, x, y, width, height, report, mono)
if report.failed then return 0 end
if not visible(e, grid.width, grid.height) then return 0 end

if e.kind == "gap" or e.kind == "spacer" then
return 1
end

if e.kind == "rule" then
put(grid, x, y, (e.char):rep(math.max(0, width)), e.colour)
return 1
end

if e.kind == "text" then
local value = e.value
local marker = markerFor(e.colour, mono)
if marker then value = marker .. value end



if e.wrap and #value > width and width > 0 then
local lines, rest = {}, value
while #rest > width do
local cut = rest:sub(1, width + 1):match(".*%s()")
if not cut or cut <= 1 then cut = width + 1 end
lines[#lines + 1] = (rest:sub(1, cut - 1):gsub("%s+$", ""))
rest = (rest:sub(cut):gsub("^%s+", ""))
end
if #rest > 0 then lines[#lines + 1] = rest end

local room = math.min(#lines, math.max(height, 1))
for i = 1, room do
put(grid, x, y + i - 1, pad(lines[i], width, e.align), e.colour)
end
if room < #lines then
report.truncated[#report.truncated + 1] = {name = nameOf(e),
from = value, to = ("%d of %d lines"):format(room, #lines)}
end
target(grid, x, y, width, room, e.action)
return room
end

if #value > width then
if e.keep == doc.REQUIRED and not e.truncate then
report.failed = {name = nameOf(e),
why = ("needs %d cells, has %d"):format(#value, width)}
report.ok = false
return 1
end
local shown = truncateTo(value, width, e.truncate or doc.TRUNCATED)
report.truncated[#report.truncated + 1] = {name = nameOf(e),
from = value, to = shown}
value = shown
end

put(grid, x, y, pad(value, width, e.align), e.colour)
target(grid, x, y, width, 1, e.action)
return 1
end

if e.kind == "button" then
local value = buttonText(e)
if #value > width then
if e.keep == doc.REQUIRED then
report.failed = {name = nameOf(e),
why = ("needs %d cells, has %d"):format(#value, width)}
report.ok = false
return 1
end
local inner = buttonInner(e)
local shown = width >= 2
and ("[" .. truncateTo(inner, width - 2, doc.TRUNCATED) .. "]")
or truncateTo(value, width, doc.TRUNCATED)
report.truncated[#report.truncated + 1] = {name = nameOf(e),
from = value, to = shown}
value = shown
elseif e.width == "fill" and width > #value then


value = "[" .. pad(buttonInner(e), width - 2, e.align) .. "]"
end

put(grid, x, y, pad(value, width, e.align), e.colour)
target(grid, x, y, width, 1, e.action)





if e.key and e.action and not contested[e.key] then
grid.keys[e.key] = e.action
end
return 1
end

if e.kind == "field" then
local label, value = e.label, e.value
local marker = markerFor(e.colour, mono)
if marker then value = marker .. value end

local need = #label + 1 + #value
if need > width then

local room = width - #value - 1
if room >= 1 then
local shown = truncateTo(label, room, "")
report.truncated[#report.truncated + 1] = {name = nameOf(e),
from = label, to = shown}
label = shown
else
if e.keep == doc.REQUIRED then
report.failed = {name = nameOf(e),
why = ("needs %d cells, has %d"):format(need, width)}
report.ok = false
return 1
end
local shown = truncateTo(value, width, doc.TRUNCATED)
report.truncated[#report.truncated + 1] = {name = nameOf(e),
from = value, to = shown}
put(grid, x, y, shown, e.colour)
target(grid, x, y, width, 1, e.action)
return 1
end
end

put(grid, x, y, label, e.labelColour)
local leaderStart = x + #label
local valueAt = x + width - #value
if e.leader and valueAt > leaderStart then
put(grid, leaderStart, y, (e.leader):rep(valueAt - leaderStart), "dim")
end
put(grid, valueAt, y, value, e.colour)
target(grid, x, y, width, 1, e.action)
return 1
end

if e.kind == "slider" then
if width < 1 then return 1 end
local span = e.max - e.min




local function valueAt(cell)
if width == 1 or span == 0 then return e.min end
return e.min + math.floor((cell - 1) / (width - 1) * span + 0.5)
end
local at = 1
if width > 1 and span > 0 then
at = 1 + math.floor((e.value - e.min) / span * (width - 1) + 0.5)
end



if at > 1 then
put(grid, x, y, ("="):rep(at - 1), e.colour)
end
put(grid, x + at - 1, y, "|", e.colour)
if at < width then
put(grid, x + at, y, ("-"):rep(width - at), e.restColour)
end

if e.action then
for cell = 1, width do
local each = {}
for k, v in pairs(e.action) do each[k] = v end
each.value = valueAt(cell)
target(grid, x + cell - 1, y, 1, 1, each)
end
end
return 1
end

if e.kind == "row" then
return drawRow(e, grid, x, y, width, height, report, mono)
end
if e.kind == "stack" then
return drawStack(e, grid, x, y, width, height, report, mono)
end
if e.kind == "table" then
return drawTable(e, grid, x, y, width, height, report, mono)
end

report.failed = {name = tostring(e.kind), why = "unknown element"}
report.ok = false
return 0
end

















local function claimKeys(e, width, height, claims)
if not e or not e.kind then return claims end
if not visible(e, width, height) then return claims end

if e.kind == "button" and e.key then
claims[e.key] = (claims[e.key] or 0) + 1
end
for _, child in ipairs(e.children or {}) do
claimKeys(child, width, height, claims)
end
return claims
end

function doc.render(document, width, height, opts)
opts = opts or {}
local report = newReport()

if type(document) ~= "table" or not document.kind then
report.failed = {name = "document", why = "not a document"}
report.ok = false
return nil, report
end
if not width or not height or width < 1 or height < 1 then
report.failed = {name = "screen", why = "a screen needs a positive size"}
report.ok = false
return nil, report
end

showKeys = opts.keys == true

contested = {}
for key, count in pairs(claimKeys(document, width, height, {})) do
if count > 1 then
contested[key] = true
report.collisions[#report.collisions + 1] = {key = key, claims = count}
end
end

local grid = newGrid(width, height)
grid.showsKeys = showKeys
drawElement(document, grid, 1, 1, width, height, report,
opts.colour == false)
showKeys = false
contested = {}

if report.failed then return nil, report end
return grid, report
end




function doc.hit(grid, x, y)
if not grid then return nil end


local found = nil
for _, t in ipairs(grid.targets) do
if x >= t.x1 and x <= t.x2 and y >= t.y1 and y <= t.y2 then
found = t.action
end
end
return found
end






function doc.picture(grid)
if not grid then return "" end
local out = {}
for y = 1, grid.height do
local cells = {}
for x = 1, grid.width do cells[x] = " " end
for _, run in ipairs(grid.rows[y] or {}) do
for i = 1, #run.text do
local at = run.x + i - 1
if at >= 1 and at <= grid.width then
cells[at] = run.text:sub(i, i)
end
end
end
out[y] = (table.concat(cells):gsub("%s+$", ""))
end
return table.concat(out, "\n")
end



local LETTER = {
text = "t", title = "T", label = "l", dim = ".", good = "g", warn = "w",
bad = "b", stale = "s", action = "a", selected = "S", flow = "f",
}

function doc.colourPicture(grid)
if not grid then return "" end
local out = {}
for y = 1, grid.height do
local cells = {}
for x = 1, grid.width do cells[x] = " " end
for _, run in ipairs(grid.rows[y] or {}) do
local letter = LETTER[run.colour] or "?"
for i = 1, #run.text do
local at = run.x + i - 1
if at >= 1 and at <= grid.width then cells[at] = letter end
end
end
out[y] = (table.concat(cells):gsub("%s+$", ""))
end
return table.concat(out, "\n")
end


function doc.explain(report)
if not report then return "no report" end
if report.failed then
return ("FAILED: %s -- %s"):format(tostring(report.failed.name),
tostring(report.failed.why))
end
local parts = {}
for _, d in ipairs(report.dropped) do
parts[#parts + 1] = ("dropped %s"):format(tostring(d.name))
end
for _, t in ipairs(report.truncated) do
parts[#parts + 1] = ("truncated %s"):format(tostring(t.name))
end
for _, c in ipairs(report.collisions or {}) do
parts[#parts + 1] = ("key %s claimed %d times, so it does nothing")
:format(tostring(c.key), c.claims)
end
if #parts == 0 then return "fits" end
return table.concat(parts, ", ")
end

return doc
]],
["mfg/hmi/hal/display_real.lua"] = [[










local backend = {}

backend.name = "real"



local PALETTE = {
text = colours.white,
title = colours.white,
label = colours.lightGrey,
dim = colours.grey,
good = colours.lime,
warn = colours.yellow,
bad = colours.red,
stale = colours.grey,
action = colours.lightBlue,
selected = colours.white,
flow = colours.grey,
}

local target = nil
local isMonitor = false
local painted = nil

local SCALE = 0.5





local function forget()
target, isMonitor, painted = nil, false, nil
end

local function resolve()
if target then return target end

for _, name in ipairs(peripheral.getNames()) do
if peripheral.getType(name) == "monitor" then
target = peripheral.wrap(name)
isMonitor = true



if target.setTextScale then pcall(target.setTextScale, SCALE) end
return target
end
end

target = term.current()
isMonitor = false
return target
end

function backend.attached()
resolve()
return isMonitor and "monitor" or "terminal"
end

function backend.size()
local screen = resolve()


if isMonitor and screen.getTextScale then
local ok, scale = pcall(screen.getTextScale)
if ok and scale ~= SCALE then
pcall(screen.setTextScale, SCALE)
painted = nil
end
end
local width, height = screen.getSize()
return width, height
end




















local function cellsOf(grid)
local cells = {}
for y = 1, grid.height do
local row = {}
for _, run in ipairs(grid.rows[y] or {}) do
for i = 1, #run.text do
row[run.x + i - 1] = {char = run.text:sub(i, i),
colour = run.colour}
end
end
cells[y] = row
end
return cells
end

function backend.paint(grid)
local screen = resolve()
local colour = screen.isColour and screen.isColour() or false
local width, height = screen.getSize()

local cells = cellsOf(grid)



if not painted or painted.width ~= width or painted.height ~= height then
screen.setBackgroundColour(colours.black)
screen.clear()
painted = {width = width, height = height, cells = {}}
end

for y = 1, math.min(grid.height, height) do
local now = cells[y] or {}
local before = painted.cells[y] or {}
local x = 1
while x <= width do
local a, b = now[x], before[x]
local same = (a == nil and b == nil)
or (a and b and a.char == b.char and a.colour == b.colour)
if same then
x = x + 1
else


local from = x
local text, runColour = {}, (a and a.colour) or "text"
while x <= width do
local m, n = now[x], before[x]
local matched = (m == nil and n == nil)
or (m and n and m.char == n.char and m.colour == n.colour)
if matched then break end
if m and m.colour ~= runColour then break end
text[#text + 1] = m and m.char or " "
x = x + 1
end
if #text > 0 then
screen.setTextColour(colour
and (PALETTE[runColour] or colours.white) or colours.white)
screen.setCursorPos(from, y)
screen.write(table.concat(text))
end
end
end
painted.cells[y] = now
end

screen.setTextColour(colours.white)
end






function backend.invalidate()
painted = nil
end











function backend.touchable()
local screen = resolve()
if isMonitor then
return screen.isColour and screen.isColour() or false
end
return term.isColour and term.isColour() or false
end


function backend.colour()
local screen = resolve()
return screen.isColour and screen.isColour() or false
end






function backend.input(seconds)
local timer = os.startTimer(seconds or 2)
while true do
local event, a, b, c = os.pullEvent()

if event == "timer" and a == timer then
return nil
elseif event == "monitor_touch" then
return {kind = "touch", x = b, y = c}
elseif event == "mouse_click" and not isMonitor then


return {kind = "touch", x = b, y = c}
elseif event == "key" then
return {kind = "key", key = a}
elseif event == "char" then
return {kind = "char", char = a}
elseif event == "monitor_resize" or event == "peripheral"
or event == "peripheral_detach" then


forget()
return nil
end
end
end

return backend
]],
["mfg/hmi/host.lua"] = [[















local doc = require("mfg.hmi.doc")
local input = require("mfg.hmi.input")
local panes = require("mfg.hmi.panes")
local app = require("mfg.hmi.app")
local panel = require("mfg.hmi.panel")
local order = require("mfg.hmi.orderpanel")
local storage = require("mfg.hmi.storagepanel")

local APPS = {
{name = "order", label = "Order"},
{name = "register", label = "Register"},
{name = "batch", label = "Batch"},
{name = "storage", label = "Storage"},
}

local host = {}



function host.new(opts)
opts = opts or {}
local shared = {host = opts.host, display = opts.display,
transport = opts.transport, now = opts.now, source = opts.source}
local function with(extra)
local out = {}
for k, v in pairs(shared) do out[k] = v end
for k, v in pairs(extra) do out[k] = v end
return out
end

local screen = panes.new({title = "MFG"})
screen.display = opts.display
screen.views = {
order = order.new(shared),
register = panel.new(with({action = "register_recipe", verb = "Register",
title = "REGISTER",
note = "Crafts one set to learn what it makes. The product stays in the "
.. "pool."})),
batch = panel.new(with({action = "run_batch", verb = "Run", title = "BATCH"})),
storage = storage.new(shared),
}
screen.modules = {order = order, register = panel, batch = panel, storage = storage}

for index, entry in ipairs(APPS) do
local name = entry.name
local view, module = screen.views[name], screen.modules[name]
panes.add(screen, {
name = name,
label = entry.label,
key = tostring(index),
render = function(width, height) return module.document(view, width, height) end,
handle = function(action) return module.act(view, action) end,
ready = function() return view.offer ~= nil end,
})
end
return screen
end

function host.view(screen, name)
return screen.views[name or screen.current]
end



local function chosen(screen)
local module = screen.modules[screen.current]
if module.refresh then module.refresh(screen.views[screen.current]) end
end

function host.select(screen, name)
local ok, why = panes.select(screen, name)
if ok then chosen(screen) end
return ok, why
end




function host.render(screen)
local display = screen.display
local width, height = display.size()
local opts = {keys = not display.touchable(), colour = display.colour()}

local grid, report = panes.render(screen, width, height, opts)
local view, module = host.view(screen), screen.modules[screen.current]
if grid and module.settle and module.settle(view, report) then
grid, report = panes.render(screen, width, height, opts)
end

if not grid then
local diagnostic = doc.text("screen too small: " .. doc.explain(report),
{colour = "bad", wrap = true, keep = doc.REQUIRED, name = "diagnostic"})
grid = doc.render(diagnostic, width, height, opts)
end
screen.lastReport = report
if grid then display.paint(grid) end
return grid
end











function host.handle(screen, event, grid)
if not event then return false end
local isLeader = event.kind == "key" and keys and event.key == keys[panes.LEADER]
local module = screen.modules[screen.current]
local list = module.searching and module.searching(host.view(screen))
if list and not isLeader and not screen.leaderPending and app.type(list, event) then
return true
end
if not isLeader and not input.heard(event) then
return false
end
local before = screen.current
local outcome = panes.handle(screen, event, grid)
if screen.current ~= before then chosen(screen) end
return outcome
end





function host.pass(screen)
local names = {screen.current}
for _, name in ipairs(screen.order) do
if name ~= screen.current then names[#names + 1] = name end
end
for _, name in ipairs(names) do
local view, module = screen.views[name], screen.modules[name]
local job = module.nextJob(view)
if job then
module.exchange(view, job)
return true
end
end
return false
end

function host.serve(screen, opts)
opts = opts or {}
while true do
if not host.pass(screen) then sleep(opts.idle or 0.2) end
end
end

function host.run(screen, opts)
opts = opts or {}
parallel.waitForAny(
function() host.serve(screen, opts) end,
function()
input.drive(screen.display,
function() return host.render(screen) end,
function(event, grid) return host.handle(screen, event, grid) end,
{wait = opts.wait or 1})
end)
end

return host
]],
["mfg/hmi/input.lua"] = [[





















local doc = require("mfg.hmi.doc")

local input = {}












function input.normalise(event, a, b, c)
if type(event) == "table" then return event end

if event == "monitor_touch" then
return {kind = "touch", x = b, y = c, side = a}
elseif event == "mouse_click" then
return {kind = "touch", x = b, y = c, button = a}
elseif event == "key" then
return {kind = "key", key = a}
elseif event == "char" then
return {kind = "char", char = a}
end
return nil
end




function input.keys(grid)
if not grid then return {} end
return grid.keys or {}
end







function input.scoped(leader, key)
if not leader then return tostring(key) end
return ("%s %s"):format(tostring(leader), tostring(key))
end



local DIGITS = {
one = "1", two = "2", three = "3", four = "4", five = "5",
six = "6", seven = "7", eight = "8", nine = "9", zero = "0",

numPadEnter = "enter",
}


function input.keyName(event)
if not event then return nil end
if event.kind == "char" then return event.char end
if event.kind == "key" and event.key and keys then
local name = keys.getName and keys.getName(event.key)
if not name then return nil end
return DIGITS[name] or name
end
return nil
end






input.NAMED = {
enter = true, backspace = true, delete = true, left = true, right = true,
up = true, down = true, pageUp = true, pageDown = true, home = true,
["end"] = true,
}



function input.heard(event)
if not event then return false end
if event.kind ~= "key" then return true end
return input.NAMED[input.keyName(event)] == true
end







function input.actionFor(grid, event, opts)
if not grid or not event then return nil end
opts = opts or {}

if event.kind == "touch" then
if not event.x or not event.y then return nil end
return doc.hit(grid, event.x, event.y)
end

local name = input.keyName(event)
if not name then return nil end





if opts.leader then
return input.keys(grid)[input.scoped(opts.leader, name)]
end

return input.keys(grid)[name]
end











function input.drive(display, render, handle, opts)
opts = opts or {}
local wait = opts.wait or 1

while true do
local grid = render and render() or nil
local event = display.input(wait)
if event then
local outcome = handle(event, grid)
if outcome == "quit" then return "quit" end
end
end
end

return input
]],
["mfg/hmi/orderpanel.lua"] = [[













local doc = require("mfg.hmi.doc")
local input = require("mfg.hmi.input")
local app = require("mfg.hmi.app")
local validate = require("mfg.common.actions.validate")

local order = {}

order.ACTION = "make"

order.OFFER_RETRY = 5
order.OFFER_REFRESH = 30
order.JOBS_EVERY = 5




order.READ = {timeout = 3, attempts = 2}
order.MAKE = {timeout = 10, attempts = 1}



function order.new(opts)
opts = opts or {}
return {
host = opts.host or "mfg",
display = opts.display,
transport = opts.transport,
now = opts.now,

offer = nil,
offerWhy = nil,
offerAskedAt = nil,
recipes = {},
recipe = nil,
quantity = 1,
list = app.newList(),

confirming = nil,
sending = nil,
result = nil,

jobs = nil,
jobsWhy = nil,
jobsAt = nil,

link = {state = "unknown"},
queue = {},
}
end

order.parameter = app.parameter

local function clampQuantity(view, value)
local param = app.parameter(view, "quantity")
return app.clamp(value, param and param.min or 1, param and param.max or 4096)
end

local function labelOf(view, id)
for _, entry in ipairs(view.recipes) do
if entry.value == id then return entry.label end
end
return tostring(id)
end


function order.params(view)
if not view.offer then return nil, "the controller has not said what it offers" end
if #view.recipes == 0 then return nil, "no recipes yet -- register one" end
if not view.recipe then return nil, "pick a recipe" end
local checked, why = validate.check(view.offer,
{recipe = view.recipe, quantity = view.quantity})
if not checked then return nil, why end
return checked
end

function order.blocked(view)
if view.sending then return "an order is being sent" end
local _, why = order.params(view)
return why
end



function order.offerDue(view)
if not view.offerAskedAt then return true end
local every = view.offer and order.OFFER_REFRESH or order.OFFER_RETRY
return (app.clock(view) - view.offerAskedAt) >= every * 1000
end

function order.jobsDue(view)
if not view.offer then return false end
if not view.jobsAt then return true end
return (app.clock(view) - view.jobsAt) >= order.JOBS_EVERY * 1000
end



function order.refresh(view)
view.offerAskedAt = nil
view.jobsAt = nil
end

function order.nextJob(view)
local job = table.remove(view.queue, 1)
if job then return job end
if order.offerDue(view) then return {kind = "offer"} end
if order.jobsDue(view) then return {kind = "jobs"} end
return nil
end



local function recipeRows(view)
if #view.recipes == 0 then
return {doc.text("no recipes yet -- register one in the Register app",
{colour = "warn", wrap = true, keep = 20, name = "no-recipes"})}
end
local entries = {}
for _, entry in ipairs(view.recipes) do
entries[#entries + 1] = {value = entry.value, label = entry.label or entry.value,
selected = view.recipe == entry.value}
end
return app.listRows(view.list, entries, "recipe",
function(entry) return {kind = "recipe", recipe = entry.value} end)
end

local function actionRow(view)
local blocked = order.blocked(view)
return doc.row({
doc.button("Make", {key = (not blocked) and "enter" or nil,
colour = blocked and "dim" or "good",
action = (not blocked) and {kind = "make"} or nil,
keep = doc.REQUIRED, name = "make"}),
doc.gap(1),
doc.text(blocked or "", {colour = "dim", truncate = doc.TRUNCATED, keep = 4,
name = "why-blocked"}),
}, {keep = doc.REQUIRED, name = "actions"})
end

local function confirmRows(view)
local question
if view.confirming.cancel then
question = ("Cancel job %d?"):format(view.confirming.cancel)
else
local params = view.confirming.make
question = ("Make %d of %s?"):format(params.quantity, labelOf(view, params.recipe))
end
local note = view.confirming.cancel
and "A batch already running finishes first; nothing after it runs."
or "Queues a job. The controller crafts it, and the ingredients it makes too."
return {
doc.text(question, {colour = "title", wrap = true, keep = doc.REQUIRED,
name = "confirm"}),
doc.text(note, {colour = "text", wrap = true, keep = 6, name = "note"}),
doc.row({
doc.button("yes", {key = "y", colour = "good", action = {kind = "yes"},
keep = doc.REQUIRED, name = "yes"}),
doc.gap(1),
doc.button("no", {key = "n", colour = "bad", action = {kind = "no"},
keep = doc.REQUIRED, name = "no"}),
}, {keep = doc.REQUIRED, name = "confirm-actions"}),
}
end


local function statusRow(view)
if view.sending then
local seconds = math.floor((app.clock(view) - view.sending.since) / 1000)
return doc.text(("ordering %d of %s.. %ds"):format(view.sending.params.quantity,
labelOf(view, view.sending.params.recipe), seconds),
{colour = "warn", wrap = true, keep = 8, name = "status"})
end
local result = view.result
if not result then return doc.text("", {colour = "dim", keep = 1, name = "status"}) end

local fields = result.fields or {}
if result.status == app.COMPLETED and result.kind == "make" then
local steps = {}
for _, step in ipairs(fields.steps or {}) do
steps[#steps + 1] = ("%s x%d"):format(tostring(step.label), step.sets)
end
return doc.text(("job %d queued: %d sets -> %d %s (%s)"):format(
fields.job or 0, fields.sets or 0, fields.yield or 0,
app.shortName(fields.product), table.concat(steps, ", ")),
{colour = "good", wrap = true, keep = 8, name = "status"})
elseif result.status == app.COMPLETED then
return doc.text(("job %d cancelled"):format(result.job or 0),
{colour = "good", wrap = true, keep = 8, name = "status"})
elseif result.status == app.TIMED_OUT then
return doc.text(("no answer from %s -- it may or may not have been queued; "
.. "the jobs below will say"):format(view.host),
{colour = "warn", wrap = true, keep = 8, name = "status"})
end
return doc.text("refused: " .. tostring(result.reason),
{colour = "bad", wrap = true, keep = 8, name = "status"})
end


local function describeJob(job)
local state = tostring(job.state)
if job.state == "blocked" then
return ("blocked: %s"):format(tostring(job.reason))
elseif job.state == "queued" or job.state == "running" then
local step = job.step
return ("%s step %d/%d%s"):format(state, job.position or 1, job.steps or 1,
step and (" %s %d/%d"):format(tostring(step.label), step.done or 0,
step.sets or 0) or "")
end
return state
end

local OPEN = {queued = true, running = true, blocked = true}

local function jobRows(view)
local rows = {}
if view.jobsWhy and not view.jobs then
rows[#rows + 1] = doc.text("jobs: " .. view.jobsWhy, {colour = "bad",
truncate = doc.TRUNCATED, keep = 2, name = "jobs-why"})
return rows
end
if not view.jobs or #view.jobs == 0 then return rows end

rows[#rows + 1] = doc.rule({keep = 3})
local shown = 0
for index = #view.jobs, 1, -1 do
local job = view.jobs[index]
shown = shown + 1
local children = {
doc.text(("#%d %s %s"):format(job.id, tostring(job.label or
app.shortName(job.product)), describeJob(job)),
{width = "fill", truncate = doc.TRUNCATED,
colour = job.state == "blocked" and "warn"
or (OPEN[job.state] and "text" or "dim"),
name = "job:" .. job.id}),
}
if OPEN[job.state] then
children[#children + 1] = doc.gap(1)
children[#children + 1] = doc.button("x", {colour = "bad",
action = {kind = "cancel", job = job.id}, name = "cancel:" .. job.id})
end

rows[#rows + 1] = doc.row(children, {keep = math.max(1, 3 - shown),
name = "jobrow:" .. job.id})
end
return rows
end

function order.document(view, width, height)
local rows = {app.header(view, "ORDER"), doc.rule({keep = 2})}

if not view.offer then
rows[#rows + 1] = doc.text(view.offerWhy
and ("the controller refused: " .. tostring(view.offerWhy))
or "asking the controller what it offers..",
{colour = view.offerWhy and "bad" or "dim", wrap = true,
keep = doc.REQUIRED, name = "offer-state"})
elseif view.confirming then
for _, row in ipairs(confirmRows(view)) do rows[#rows + 1] = row end
else
for _, row in ipairs(recipeRows(view)) do rows[#rows + 1] = row end
rows[#rows + 1] = app.quantityRow(view.quantity, not view.sending)
rows[#rows + 1] = actionRow(view)
end

rows[#rows + 1] = statusRow(view)
for _, row in ipairs(jobRows(view)) do rows[#rows + 1] = row end
rows[#rows + 1] = doc.spacer()
return doc.stack(rows, {name = "order"})
end

function order.settle(view, report)
return app.settle(view.list, report, "recipe")
end



function order.act(view, action)
local kind = action and action.kind

if app.page(view.list, kind) then return true end
if kind == "recipe" then
view.recipe = action.recipe
return true
elseif kind == "delta" then
view.quantity = clampQuantity(view, view.quantity + (action.n or 0))
return true
elseif kind == "make" then
local params, why = order.params(view)
if not params then
view.result = {status = app.REJECTED, reason = why}
return true
end
view.confirming = {make = params}
return true
elseif kind == "cancel" then
view.confirming = {cancel = action.job}
return true
elseif kind == "yes" then
local confirmed = view.confirming
view.confirming = nil
if confirmed and confirmed.make then
app.ask(view, {kind = "make", params = confirmed.make})
elseif confirmed and confirmed.cancel then
app.ask(view, {kind = "cancel", job = confirmed.cancel})
end
return true
elseif kind == "no" then
view.confirming = nil
return true
end
return false
end


function order.searching(view)
if view.offer and not view.confirming and #view.recipes > 0 then return view.list end
return nil
end


function order.handle(view, event, grid)
if order.searching(view) and app.type(view.list, event) then return true end
if not input.heard(event) then return false end
local action = input.actionFor(grid, event)
if not action then return false end
return order.act(view, action)
end



function order.exchange(view, job)
local body, opts
if job.kind == "offer" then
view.offerAskedAt = app.clock(view)
body, opts = {command = "offer", name = order.ACTION}, order.READ
elseif job.kind == "jobs" then
view.jobsAt = app.clock(view)
body, opts = {command = "jobs"}, order.READ
elseif job.kind == "make" then
body = {command = "make", recipe = job.params.recipe,
quantity = job.params.quantity}
opts = order.MAKE
view.sending = {params = job.params, since = app.clock(view)}
view.result = nil
elseif job.kind == "cancel" then
body, opts = {command = "cancel_job", job = job.job}, order.MAKE
else
return false
end

local answer = view.transport.request(body, opts) or {}
order.apply(view, job, answer)
return true
end

function order.apply(view, job, answer)
app.noteLink(view, answer)

if job.kind == "offer" then
local decl = answer.status == app.COMPLETED
and type(answer.actions) == "table" and answer.actions[1]
if not decl then


if not view.offer then
view.offerWhy = answer.reason or answer.status or "no answer"
end
return
end
view.offer, view.offerWhy = decl, nil

view.recipes = {}
local param = app.parameter(view, "recipe")
if param and type(param.choices) == "table" and not param.choices.source then
for _, entry in ipairs(param.choices) do
if type(entry) == "table" then
view.recipes[#view.recipes + 1] = {value = entry.value,
label = entry.label or entry.value}
else
view.recipes[#view.recipes + 1] = {value = entry, label = entry}
end
end
end
local still = false
for _, entry in ipairs(view.recipes) do
if entry.value == view.recipe then still = true end
end
if not still then view.recipe = nil end
if not view.recipe and #view.recipes == 1 then
view.recipe = view.recipes[1].value
end
view.quantity = clampQuantity(view, view.quantity)

elseif job.kind == "jobs" then
if answer.status == app.COMPLETED and type(answer.jobs) == "table" then
view.jobs, view.jobsWhy = answer.jobs, nil
else
view.jobsWhy = tostring(answer.reason or answer.status or "no answer")
end

elseif job.kind == "make" or job.kind == "cancel" then
view.sending = nil
view.result = {kind = job.kind, status = answer.status or app.REJECTED,
reason = answer.reason, fields = answer, job = job.job,
at = app.clock(view)}

view.jobsAt = nil
end
end

return order
]],
["mfg/hmi/panel.lua"] = [[
































local doc = require("mfg.hmi.doc")
local input = require("mfg.hmi.input")
local app = require("mfg.hmi.app")
local pattern = require("mfg.common.pattern")
local validate = require("mfg.common.actions.validate")

local panel = {}



panel.ACTION = "run_batch"



panel.COMPLETED = "completed"
panel.REJECTED = "rejected"
panel.TIMED_OUT = "timed_out"



panel.OFFER_RETRY = 5






panel.READ = {timeout = 3, attempts = 2}
panel.RUN = {timeout = 60, attempts = 1}



function panel.new(opts)
opts = opts or {}
return {


action = opts.action or panel.ACTION,
verb = opts.verb or "Run",
title = opts.title or "CRAFT",
note = opts.note,

host = opts.host or "mfg",




source = opts.source or require("mfg.common.config").setting("source"),
display = opts.display,
transport = opts.transport,
now = opts.now,

offer = nil,
offerWhy = nil,
offerAskedAt = nil,
nodes = {},
target = nil,

stock = nil,
stockWhy = nil,

cells = {},
amount = 1,
output = nil,


picking = nil,
pickList = app.newList(),

confirming = nil,
running = nil,
result = nil,




link = {state = "unknown"},

queue = {},
}
end

local function clock(view)
if view.now then return view.now() end
return os.epoch("utc")
end



function panel.parameter(view, name)
if not view.offer then return nil end
for _, param in ipairs(view.offer.parameters or {}) do
if param.name == name then return param end
end
return nil
end


function panel.amountRange(view)
local param = panel.parameter(view, "amount")
if not param then return nil end
return param.min or 1, param.max or param.min or 1
end

local function clampAmount(view, value)
local min, max = panel.amountRange(view)
if not min then return value end
value = math.floor(tonumber(value) or min)
if value < min then value = min end
if value > max then value = max end
return value
end





function panel.slotOf(cell)
return pattern.GRID[cell]
end

function panel.pattern(view)
local out, any = {}, false
for cell = 1, 9 do
local item = view.cells[cell]
if item then
out[panel.slotOf(cell)] = item
any = true
end
end
if not any then return nil end
return out
end

local function sortedSlots(slots)
local out = {}
for slot in pairs(slots) do out[#out + 1] = slot end
table.sort(out)
return out
end



local function shortName(item)
if type(item) ~= "string" then return "" end
return item:match("[^:]+$") or item
end





function panel.params(view)
if not view.offer then
return nil, "the controller has not said what it offers"
end
if not view.target then return nil, "pick a node" end
local slots = panel.pattern(view)
if not slots then return nil, "the grid is empty" end




local params = {target = view.target, pattern = slots}
if panel.parameter(view, "pattern_id") then params.pattern_id = pattern.id(slots) end
if panel.parameter(view, "amount") then params.amount = view.amount end
if panel.parameter(view, "source") then params.source = view.source end
if panel.parameter(view, "output") and view.output then params.output = view.output end
local checked, why = validate.check(view.offer, params)
if not checked then return nil, why end
return checked
end


function panel.blocked(view)
if view.running then return "a batch is running" end
local _, why = panel.params(view)
return why
end





function panel.ask(view, job)
for _, queued in ipairs(view.queue) do
if queued.kind == job.kind then return false end
end
view.queue[#view.queue + 1] = job
return true
end

function panel.offerDue(view)
if view.offer then return false end
if not view.offerAskedAt then return true end
return (clock(view) - view.offerAskedAt) >= panel.OFFER_RETRY * 1000
end



local function linkElement(view)
local link = view.link
if link.state == "ok" then
return doc.text(view.host .. " ok", {colour = "good", keep = doc.REQUIRED,
truncate = doc.TRUNCATED, name = "link"})
elseif link.state == "down" then
return doc.text(("%s down: %s"):format(view.host, tostring(link.reason)),
{colour = "bad", keep = doc.REQUIRED, truncate = doc.TRUNCATED,
name = "link"})
end
return doc.text(view.host .. " ...", {colour = "dim", keep = doc.REQUIRED,
truncate = doc.TRUNCATED, name = "link"})
end

local function header(view)
return doc.row({
doc.text(view.title, {colour = "title", keep = doc.REQUIRED, name = "title"}),
doc.spacer({min = 1}),
linkElement(view),
}, {keep = doc.REQUIRED, name = "header"})
end

local function nodeRow(view)
local children = {
doc.text("Node", {colour = "label", keep = doc.REQUIRED, name = "node-label"}),
doc.gap(1),
}

if not view.offer then
children[#children + 1] = doc.text(view.offerWhy
and ("the controller refused: " .. tostring(view.offerWhy))
or "asking the controller what it offers..",
{colour = view.offerWhy and "bad" or "dim", truncate = doc.TRUNCATED,
keep = doc.REQUIRED, name = "offer-state"})
elseif #view.nodes == 0 then
children[#children + 1] = doc.text("no nodes registered",
{colour = "warn", keep = doc.REQUIRED, name = "no-nodes"})
else
for index, node in ipairs(view.nodes) do
if index > 1 then children[#children + 1] = doc.gap(1) end
children[#children + 1] = doc.button(node.label or node.value, {
colour = (view.target == node.value) and "selected" or "action",
action = {kind = "node", node = node.value},


keep = (view.target == node.value) and doc.REQUIRED or (9 - index),
name = "node:" .. node.value,
})
end
children[#children + 1] = doc.spacer()
children[#children + 1] = doc.button("next node", {key = "t",
action = {kind = "cycle-node"}, colour = "dim", keep = 2,
name = "cycle-node", when = {minWidth = 40}})
end

return doc.row(children, {keep = doc.REQUIRED, name = "nodes"})
end

local function cellButton(view, cell)
local item = view.cells[cell]
local usable = view.offer ~= nil and not view.running
return doc.button(item and shortName(item) or "", {
width = "fill",
colour = not usable and "dim" or (item and "action" or "dim"),
action = usable and {kind = "cell", cell = cell} or nil,
key = usable and tostring(cell) or nil,
name = "cell:" .. cell,
})
end




local function gridRows(view)
local rows = {}
for r = 0, 2 do
rows[#rows + 1] = doc.row({
cellButton(view, r * 3 + 1), doc.gap(1),
cellButton(view, r * 3 + 2), doc.gap(1),
cellButton(view, r * 3 + 3),
}, {keep = doc.REQUIRED, name = "grid-row-" .. (r + 1)})
end
return rows
end

local function sliderRow(view)
local min, max = panel.amountRange(view)
local usable = min ~= nil and not view.running
return doc.row({
doc.text("Sets", {colour = "label", keep = doc.REQUIRED, name = "sets-label"}),
doc.gap(1),
doc.button("-", {key = usable and "-" or nil,
colour = usable and "action" or "dim",
action = usable and {kind = "delta", n = -1} or nil, name = "less",
keep = doc.REQUIRED}),
doc.gap(1),
doc.slider({min = min or 1, max = max or 1, value = view.amount,
action = usable and {kind = "amount"} or nil,
colour = usable and "selected" or "dim", name = "amount-bar"}),
doc.gap(1),
doc.button("+", {key = usable and "+" or nil,
colour = usable and "action" or "dim",
action = usable and {kind = "delta", n = 1} or nil, name = "more",
keep = doc.REQUIRED}),
doc.gap(1),


doc.text(tostring(view.amount), {width = #tostring(max or 1),
align = "right", colour = usable and "text" or "dim",
keep = doc.REQUIRED, name = "amount"}),
}, {keep = doc.REQUIRED, name = "sets"})
end

local function actionRow(view)
local blocked = panel.blocked(view)
local label = view.verb
if view.offer and panel.amountRange(view) then
label = ("%s %d sets"):format(view.verb, view.amount)
elseif view.output then
label = ("%s as %s"):format(view.verb, shortName(view.output))
end
return doc.row({


doc.button(label, {key = (not blocked) and "r" or nil,
colour = blocked and "dim" or "good",
action = (not blocked) and {kind = "run"} or nil,
keep = doc.REQUIRED, name = "run"}),
doc.gap(1),
doc.text(blocked or "", {colour = "dim", truncate = doc.TRUNCATED,
keep = 4, name = "why-blocked"}),
doc.spacer(),
doc.button("Clear", {key = "c", action = {kind = "clear"},
keep = 5, name = "clear"}),
}, {keep = doc.REQUIRED, name = "actions"})
end







local function pickerRows(view)
local rows = {}
local cell = view.picking
local current = view.cells[cell]

rows[#rows + 1] = doc.row({
doc.text(("Slot %d"):format(panel.slotOf(cell)), {colour = "title",
keep = doc.REQUIRED, name = "pick-title"}),
doc.gap(1),
doc.text(current and shortName(current) or "empty",
{colour = current and "text" or "dim", truncate = doc.TRUNCATED,
keep = 3, name = "pick-current"}),
doc.spacer(),
doc.text(view.stock and view.source or (view.stockWhy or "reading stock.."),
{colour = view.stockWhy and "bad" or "dim", truncate = doc.TRUNCATED,
keep = 2, name = "pick-source"}),
}, {keep = doc.REQUIRED, name = "pick-head"})

local items = {}
for item in pairs(view.stock or {}) do items[#items + 1] = item end
table.sort(items)



local entries = {}
for _, item in ipairs(items) do
entries[#entries + 1] = {value = item, label = item,
note = tostring(view.stock[item]), selected = current == item}
end
for _, row in ipairs(app.listRows(view.pickList, entries, "pick",
function(entry) return {kind = "pick", item = entry.value} end)) do
rows[#rows + 1] = row
end

if view.stock and #items == 0 then
rows[#rows + 1] = doc.text(view.source .. " holds nothing",
{colour = "warn", keep = 10, name = "pick-empty"})
end



local nav = {
doc.button("back", {key = "backspace", keyLabel = "bksp",
action = {kind = "back"}, keep = doc.REQUIRED, name = "back"}),
doc.gap(1),
doc.button("none", {key = "0", action = {kind = "pick-none"},
keep = 8, name = "none"}),
doc.spacer(),
}
local top = view.pickList.query ~= "" and view.pickList.top
if top then
nav[#nav + 1] = doc.button("pick " .. shortName(top.item), {key = "enter",
colour = "good", action = top, keep = 9, name = "pick-top"})
end
rows[#rows + 1] = doc.row(nav, {keep = doc.REQUIRED, name = "pick-nav"})

return rows
end


local function confirmRows(view)
local params = view.confirming
local parts = {}
for _, slot in ipairs(sortedSlots(params.pattern)) do
parts[#parts + 1] = ("%d=%s"):format(slot, shortName(params.pattern[slot]))
end

local question = params.amount
and ("%s %d sets on %s?"):format(view.verb, params.amount, params.target)
or ("%s on %s?"):format(view.verb, params.target)
local rows = {
doc.text(question,
{colour = "title", wrap = true, keep = doc.REQUIRED, name = "confirm"}),
doc.text(table.concat(parts, " "), {colour = "text", wrap = true, keep = 6,
name = "confirm-pattern"}),
}
if view.note then
rows[#rows + 1] = doc.text(view.note, {colour = "text", wrap = true, keep = 5,
name = "note"})
end
if view.offer and view.offer.destructive then
rows[#rows + 1] = doc.text("This crafts. Material consumed cannot be "
.. "uncrafted.", {colour = "warn", wrap = true, keep = 7,
name = "consequence"})
end
rows[#rows + 1] = doc.row({
doc.button("yes", {key = "y", colour = "good", action = {kind = "yes"},
keep = doc.REQUIRED, name = "yes"}),
doc.gap(1),
doc.button("no", {key = "n", colour = "bad", action = {kind = "no"},
keep = doc.REQUIRED, name = "no"}),
}, {keep = doc.REQUIRED, name = "confirm-actions"})
return rows
end



local function statusRow(view)
if view.running then
local seconds = math.floor((clock(view) - view.running.since) / 1000)
local params = view.running.params
local doing = params.amount and ("running %d sets"):format(params.amount)
or (view.verb:lower() .. "ing")
return doc.text(("%s on %s.. %ds"):format(doing, params.target, seconds),
{colour = "warn", wrap = true, keep = 3, name = "status"})
end

local result = view.result
if not result then
return doc.text("", {colour = "dim", keep = 1, name = "status"})
end

if result.status == panel.COMPLETED and result.fields.recipe then
local recipe = result.fields.recipe
return doc.text(("registered %s: %d %s a set"):format(recipe.label,
recipe.output.count, shortName(recipe.output.item)),
{colour = "good", wrap = true, keep = 3, name = "status"})
elseif result.status == panel.COMPLETED then
local made = {}
for item, count in pairs(result.fields.produced or {}) do
made[#made + 1] = ("%d %s"):format(count, shortName(item))
end
table.sort(made)
return doc.text(("done: %s from %d sets on %s"):format(
#made > 0 and table.concat(made, ", ") or "nothing",
result.params.amount, result.params.target),
{colour = "good", wrap = true, keep = 3, name = "status"})
elseif result.status == panel.TIMED_OUT then
return doc.text(("no answer from %s -- the batch may or may not have "
.. "run: %s"):format(view.host, tostring(result.reason)),
{colour = "warn", wrap = true, keep = 3, name = "status"})
end

local refused = doc.text("refused: " .. tostring(result.reason),
{colour = "bad", wrap = true, keep = 3, name = "status"})
if not (result.fields and result.fields.ambiguous) then return refused end



local kinds = {}
for item in pairs(result.fields.produced or {}) do kinds[#kinds + 1] = item end
table.sort(kinds)
local choices = {doc.text("output:", {colour = "label", keep = doc.REQUIRED,
name = "output-label"})}
for index, item in ipairs(kinds) do
choices[#choices + 1] = doc.gap(1)
choices[#choices + 1] = doc.button(shortName(item), {
colour = (view.output == item) and "selected" or "action",
action = {kind = "output", item = item}, keep = 10 - index,
name = "output:" .. index})
end
return doc.stack({refused, doc.row(choices, {keep = 3, name = "outputs"})},
{keep = 3, name = "status-stack"})
end


function panel.document(view, width, height)
local rows = {header(view), nodeRow(view), doc.rule({keep = 2})}

local body
if view.confirming then
body = confirmRows(view)
elseif view.picking then
body = pickerRows(view)
else
body = gridRows(view)


body[#body + 1] = doc.text("", {keep = 1, name = "breath"})


if not view.offer or panel.amountRange(view) then
body[#body + 1] = sliderRow(view)
end
body[#body + 1] = actionRow(view)
end
for _, row in ipairs(body) do rows[#rows + 1] = row end

rows[#rows + 1] = doc.spacer()
rows[#rows + 1] = statusRow(view)
return doc.stack(rows, {name = "panel"})
end







function panel.settle(view, report)
if not view.picking then return false end
return app.settle(view.pickList, report, "pick")
end







function panel.render(view)
local display = view.display
local width, height = display.size()
local opts = {keys = not display.touchable(), colour = display.colour()}

local document = panel.document(view, width, height)
local grid, report = doc.render(document, width, height, opts)

if grid and panel.settle(view, report) then

grid, report = doc.render(panel.document(view, width, height),
width, height, opts)
end

if not grid then



local diagnostic = doc.text("screen too small: " .. doc.explain(report),
{colour = "bad", wrap = true, keep = doc.REQUIRED, name = "diagnostic"})
grid = doc.render(diagnostic, width, height, opts)
view.lastReport = report
if grid then display.paint(grid) end
return grid
end

view.lastReport = report
display.paint(grid)
return grid
end




function panel.searching(view)
return view.picking and view.pickList or nil
end


function panel.act(view, action)
local kind = action and action.kind
if view.picking and app.page(view.pickList, kind) then return true end

if kind == "node" then
view.target = action.node
return true

elseif kind == "cycle-node" then
if #view.nodes == 0 then return false end
local at = 0
for index, node in ipairs(view.nodes) do
if node.value == view.target then at = index end
end
view.target = view.nodes[(at % #view.nodes) + 1].value
return true

elseif kind == "cell" then
view.picking = action.cell
view.pickList = app.newList()


panel.ask(view, {kind = "stock"})
return true

elseif kind == "pick" then
if not view.picking then return false end
view.cells[view.picking] = action.item
view.picking = nil
view.output = nil
return true

elseif kind == "pick-none" then
if not view.picking then return false end
view.cells[view.picking] = nil
view.picking = nil
return true

elseif kind == "back" then
view.picking = nil
return true

elseif kind == "amount" then
view.amount = clampAmount(view, action.value)
return true

elseif kind == "delta" then
view.amount = clampAmount(view, view.amount + (action.n or 0))
return true

elseif kind == "clear" then
view.cells = {}
view.result = nil
view.output = nil
return true

elseif kind == "output" then
view.output = action.item
return true

elseif kind == "run" then
local params, why = panel.params(view)
if not params then
view.result = {status = panel.REJECTED, reason = why, at = clock(view)}
return true
end
if view.offer.destructive then
view.confirming = params
else
panel.ask(view, {kind = "run", params = params})
end
return true

elseif kind == "yes" then
local params = view.confirming
view.confirming = nil
if params then panel.ask(view, {kind = "run", params = params}) end
return true

elseif kind == "no" then
view.confirming = nil
return true
end

return false
end








function panel.handle(view, event, grid)
if panel.searching(view) and app.type(view.pickList, event) then return true end
if not input.heard(event) then return false end
local action = input.actionFor(grid, event)
if not action then return false end
return panel.act(view, action)
end









function panel.exchange(view, job)
local body, opts

if job.kind == "offer" then
view.offerAskedAt = clock(view)
body = {command = "offer", name = view.action}
opts = panel.READ
elseif job.kind == "stock" then
body = {command = "stock", path = view.source}
opts = panel.READ
elseif job.kind == "run" then
body = {command = view.action, operator = true}
for key, value in pairs(job.params) do body[key] = value end
opts = panel.RUN
view.running = {params = job.params, since = clock(view)}
view.result = nil
else
return false
end

local answer = view.transport.request(body, opts) or {}
panel.apply(view, job, answer)
return true
end


function panel.apply(view, job, answer)
local now = clock(view)

if answer.src then
view.link = {state = "ok", at = now}
elseif answer.status == panel.TIMED_OUT or answer.status == panel.REJECTED then
view.link = {state = "down", reason = answer.reason, at = now}
end

if job.kind == "offer" then
local decl = answer.status == panel.COMPLETED
and type(answer.actions) == "table" and answer.actions[1]
if not decl then
view.offerWhy = answer.reason or answer.status or "no answer"
return
end
view.offer = decl
view.offerWhy = nil

local target = panel.parameter(view, "target")
view.nodes = {}
if target and type(target.choices) == "table" and not target.choices.source then
for _, entry in ipairs(target.choices) do
if type(entry) == "table" then
view.nodes[#view.nodes + 1] = {value = entry.value,
label = entry.label or entry.value}
else
view.nodes[#view.nodes + 1] = {value = entry, label = entry}
end
end
end

local stillThere = false
for _, node in ipairs(view.nodes) do
if node.value == view.target then stillThere = true end
end
if not stillThere then view.target = nil end
if not view.target and #view.nodes == 1 then
view.target = view.nodes[1].value
end
view.amount = clampAmount(view, view.amount)

elseif job.kind == "stock" then
if answer.status == panel.COMPLETED and type(answer.stock) == "table" then
view.stock = answer.stock
view.stockWhy = nil
else
view.stockWhy = ("%s: %s"):format(view.source,
tostring(answer.reason or answer.status or "no answer"))
end

elseif job.kind == "run" then
view.running = nil
view.result = {
status = answer.status or panel.REJECTED,
reason = answer.reason,
fields = answer,
params = job.params,
at = now,
}
end
end



function panel.nextJob(view)
local job = table.remove(view.queue, 1)
if not job and panel.offerDue(view) then job = {kind = "offer"} end
return job
end


function panel.serve(view, opts)
opts = opts or {}
while true do
local job = panel.nextJob(view)
if job then
panel.exchange(view, job)
else
sleep(opts.idle or 0.2)
end
end
end










function panel.transport(host)
local actions = require("mfg.common.actions")
return {
request = function(body, opts)
local status, fields = actions.invoke("transmit", {
target = host,
protocol = "mfg-scada",
content = textutils.serialize(body),
timeout = opts and opts.timeout,
attempts = opts and opts.attempts,
}, {by = "hmi"})

local reply = fields and fields.reply
if type(reply) ~= "table" then



reply = {status = status, reason = fields and fields.reason}
end
return reply
end,
}
end




function panel.run(view, opts)
opts = opts or {}
parallel.waitForAny(
function() panel.serve(view, opts) end,
function()
input.drive(view.display,
function() return panel.render(view) end,
function(event, grid) return panel.handle(view, event, grid) end,
{wait = opts.wait or 1})
end)
end

return panel
]],
["mfg/hmi/panes.lua"] = [[
















local doc = require("mfg.hmi.doc")
local input = require("mfg.hmi.input")

local panes = {}











panes.TOP = "top"
panes.LEFT = "left"























panes.LEADER = "tab"


panes.CYCLE = panes.LEADER

function panes.new(opts)
opts = opts or {}
return {
title = opts.title,
edge = opts.edge or panes.TOP,
width = opts.width or 12,
apps = {},
order = {},
current = nil,
}
end









function panes.add(host, app)
if type(app) ~= "table" or type(app.name) ~= "string" then
return nil, "an app needs a name"
end
if type(app.render) ~= "function" then
return nil, ("app %s needs a render function"):format(app.name)
end
if host.apps[app.name] then
return nil, ("app %s is already declared"):format(app.name)
end

host.apps[app.name] = app
host.order[#host.order + 1] = app.name
if not host.current then host.current = app.name end
return app
end

function panes.select(host, name)
if not host.apps[name] then return false, "no such app: " .. tostring(name) end
host.current = name
return true
end

function panes.app(host)
return host.apps[host.current]
end



local function indexElement(host, across)
local children = {}





local heading = host.title
if host.leaderPending then
heading = (heading and (heading .. " ") or "") .. "TAB.."
elseif heading then
heading = heading .. " tab+"
end

if heading and across then
children[#children + 1] = doc.text(heading, {
colour = host.leaderPending and "warn" or "label",
keep = 3, name = "title"})
children[#children + 1] = doc.gap(1)
end

for i, name in ipairs(host.order) do
local app = host.apps[name]
if across and i > 1 then children[#children + 1] = doc.gap(1) end

local usable = (app.ready == nil) or app.ready()
children[#children + 1] = doc.button(app.label or name, {


key = input.scoped(panes.LEADER, app.key or tostring(i)),
keyLabel = app.key or tostring(i),
colour = (host.current == name) and "selected"
or (usable and "action" or "dim"),
action = {kind = "app", app = name},


keep = (host.current == name) and doc.REQUIRED or (9 - i),
name = name,
})
end

if across then
return doc.row(children, {keep = doc.REQUIRED, name = "index"})
end
return doc.stack(children, {width = host.width, keep = doc.REQUIRED,
name = "index"})
end

panes.indexElement = indexElement








function panes.document(host, width, height)
local app = panes.app(host)
if not app then
return doc.stack({
doc.text("NO APPS", {colour = "bad", keep = doc.REQUIRED}),
}, {name = "empty"})
end

if host.edge == panes.LEFT then
local paneWidth = math.max(1, width - host.width - 1)
return doc.row({
indexElement(host, false),
doc.gap(1),
app.render(paneWidth, height),
}, {name = "host"})
end

local paneHeight = math.max(1, height - 1)
return doc.stack({
indexElement(host, true),
app.render(width, paneHeight),
}, {name = "host"})
end

function panes.render(host, width, height, opts)
return doc.render(panes.document(host, width, height), width, height, opts)
end








function panes.shadowed(host, grid)
local out = {}
for _, name in ipairs(host.order) do
local app = host.apps[name]
if app.key then
local bound = (grid.keys or {})[input.scoped(panes.LEADER, app.key)]
if not bound or bound.kind ~= "app" or bound.app ~= name then
out[#out + 1] = {app = name, key = app.key}
end
end
end
return out
end





function panes.handle(host, event, grid)
if not event then return false end

local isLeader = event.kind == "key" and keys
and event.key == keys[panes.LEADER]


if isLeader and host.leaderPending then
host.leaderPending = false
local at = 1
for i, name in ipairs(host.order) do
if name == host.current then at = i end
end
local nextName = host.order[(at % #host.order) + 1]
if nextName then panes.select(host, nextName) end
return true, {kind = "app", app = host.current}
end



if isLeader then
host.leaderPending = true
return true, {kind = "leader"}
end





if host.leaderPending then
host.leaderPending = false
local scoped = input.actionFor(grid, event, {leader = panes.LEADER})
if scoped and scoped.kind == "app" then
panes.select(host, scoped.app)
return true, scoped
end
return false
end

local action = input.actionFor(grid, event)
if not action then



local app = panes.app(host)
if app and app.handle then return app.handle(nil, event) end
return false
end

if action.kind == "app" then
panes.select(host, action.app)
return true, action
end

local app = panes.app(host)
if app and app.handle then return app.handle(action, event), action end
return false, action
end

return panes
]],
["mfg/hmi/services.lua"] = [[



























local services = require("mfg.common.services")

local hmi = {}



local function displayBackend()
local hal = require("mfg.common.hal")
if hal.mode() == "mock" then return require("mfg.hmi.hal.display_mock") end
return require("mfg.hmi.hal.display_real")
end

function hmi.declare(manager, ctx)




local onTerminal = displayBackend().attached() == "terminal"




services.declare(manager, {
name = "panel",
requires = {"netstack"},
ready = ctx.admitted,
terminal = onTerminal,
start = function()
local panel = require("mfg.hmi.panel")
local hostmod = require("mfg.hmi.host")
local config = require("mfg.common.config")



local host = config.setting("controller")
local display = displayBackend()
services.log(manager, "panel",
("driving %s on a %s"):format(host, display.attached()))



if display.invalidate then display.invalidate() end





ctx.bind({"mfg-scada"})

local screen = hostmod.new({
host = host,
source = config.setting("source"),
display = display,
transport = panel.transport(host),
})
hostmod.run(screen)
end,
})
end

return hmi
]],
["mfg/hmi/storagepanel.lua"] = [[











local doc = require("mfg.hmi.doc")
local input = require("mfg.hmi.input")
local app = require("mfg.hmi.app")

local storage = {}

storage.EVERY = 5
storage.READ = {timeout = 3, attempts = 2}

storage.TAKE = {timeout = 20, attempts = 1}

function storage.new(opts)
opts = opts or {}
return {
host = opts.host or "mfg",
display = opts.display,
transport = opts.transport,
now = opts.now,

items = nil,
pending = {}, waiting = {},
bound = {},
readWhy = nil,
readAt = nil,

offer = nil,

item = nil,
count = 1,
list = app.newList(),

sending = nil,
result = nil,
link = {state = "unknown"},
queue = {},
}
end

local function sortedItems(view)
local names = {}
for item in pairs(view.items or {}) do names[#names + 1] = item end
table.sort(names)
return names
end

local function freeOf(view, item)
local entry = view.items and view.items[item]
return entry and entry.free or 0
end

function storage.blocked(view)
if view.sending then return "a withdrawal is being sent" end
if not view.items then return "reading the pool.." end
if view.bound.output == false then return "bind /io/out on the controller" end
if not view.item then return "pick an item" end
if freeOf(view, view.item) < 1 then return "none of it is free" end
return nil
end




function storage.refresh(view)
view.readAt = nil
end

function storage.nextJob(view)
local job = table.remove(view.queue, 1)
if job then return job end
if not view.readAt or (app.clock(view) - view.readAt) >= storage.EVERY * 1000 then
return {kind = "read"}
end
return nil
end

function storage.exchange(view, job)
local body, opts
if job.kind == "read" then
view.readAt = app.clock(view)
body, opts = {command = "available"}, storage.READ
elseif job.kind == "withdraw" then
body = {command = "withdraw", item = job.item, count = job.count, operator = true}
opts = storage.TAKE
view.sending = {item = job.item, count = job.count, since = app.clock(view)}
view.result = nil
else
return false
end
storage.apply(view, job, view.transport.request(body, opts) or {})
return true
end

function storage.apply(view, job, answer)
app.noteLink(view, answer)
if job.kind == "read" then
if answer.status == app.COMPLETED and type(answer.items) == "table" then
view.items, view.readWhy = answer.items, nil
view.pending, view.waiting = answer.pending or {}, answer.waiting or {}
view.bound = answer.bound or {}
view.offer = view.offer or {name = "available"}

if view.item then
view.count = app.clamp(view.count, 1, math.max(1, freeOf(view, view.item)))
end
else
view.readWhy = tostring(answer.reason or answer.status or "no answer")
end
elseif job.kind == "withdraw" then
view.sending = nil
view.result = {status = answer.status or app.REJECTED, reason = answer.reason,
fields = answer, item = job.item, count = job.count}
view.readAt = nil
end
end



local function summary(label, items, name)
local parts = {}
for item, count in pairs(items or {}) do
parts[#parts + 1] = ("%d %s"):format(count, app.shortName(item))
end
table.sort(parts)
if #parts == 0 then return nil end
return doc.text(("%s: %s"):format(label, table.concat(parts, ", ")),
{colour = "dim", truncate = doc.TRUNCATED, keep = 5, name = name})
end

local function statusRow(view)
if view.sending then
return doc.text(("withdrawing %d %s.."):format(view.sending.count,
app.shortName(view.sending.item)),
{colour = "warn", wrap = true, keep = 8, name = "status"})
end
local result = view.result
if not result then return doc.text("", {keep = 1, name = "status"}) end
local fields = result.fields or {}
if result.status == app.COMPLETED then
local text = ("%d %s in /io/out"):format(fields.moved or 0,
app.shortName(result.item))
if fields.short then text = text .. " -- " .. tostring(fields.reason) end
return doc.text(text, {colour = fields.short and "warn" or "good", wrap = true,
keep = 8, name = "status"})
elseif result.status == app.TIMED_OUT then
return doc.text(("no answer from %s -- look in /io/out before asking again")
:format(view.host), {colour = "warn", wrap = true, keep = 8, name = "status"})
end
return doc.text("refused: " .. tostring(result.reason),
{colour = "bad", wrap = true, keep = 8, name = "status"})
end

function storage.document(view, width, height)
local rows = {app.header(view, "STORAGE"), doc.rule({keep = 2})}

if not view.items then
rows[#rows + 1] = doc.text(view.readWhy and ("the controller refused: "
.. view.readWhy) or "reading the pool..", {colour = view.readWhy and "bad"
or "dim", wrap = true, keep = doc.REQUIRED, name = "read-state"})
else
local entries = {}
for _, item in ipairs(sortedItems(view)) do
local entry = view.items[item]
local label = ("%s  %d free"):format(app.shortName(item), entry.free)
if entry.promised > 0 then
label = label .. (" (%d promised)"):format(entry.promised)
end
entries[#entries + 1] = {value = item, label = label,
selected = view.item == item}
end
if #entries == 0 then
rows[#rows + 1] = doc.text("the pool is empty -- put things in /io/in",
{colour = "warn", wrap = true, keep = 20, name = "empty"})
end
for _, row in ipairs(app.listRows(view.list, entries, "item",
function(entry) return {kind = "item", item = entry.value} end)) do
rows[#rows + 1] = row
end

local blocked = storage.blocked(view)
rows[#rows + 1] = app.quantityRow(view.count, not view.sending, "Take")
rows[#rows + 1] = doc.row({
doc.button("Withdraw", {key = (not blocked) and "enter" or nil,
colour = blocked and "dim" or "good",
action = (not blocked) and {kind = "withdraw"} or nil,
keep = doc.REQUIRED, name = "withdraw"}),
doc.gap(1),
doc.text(blocked or "", {colour = "dim", truncate = doc.TRUNCATED,
keep = 4, name = "why-blocked"}),
}, {keep = doc.REQUIRED, name = "actions"})
end

rows[#rows + 1] = statusRow(view)
rows[#rows + 1] = summary("coming in", view.pending, "pending")
or doc.text("", {keep = 1, name = "pending"})
rows[#rows + 1] = summary("in /io/out", view.waiting, "waiting")
or doc.text("", {keep = 1, name = "waiting"})
rows[#rows + 1] = doc.spacer()
return doc.stack(rows, {name = "storage"})
end

function storage.settle(view, report)
return app.settle(view.list, report, "item")
end



function storage.act(view, action)
local kind = action and action.kind
if app.page(view.list, kind) then return true end
if kind == "item" then
view.item = action.item
view.count = app.clamp(view.count, 1, math.max(1, freeOf(view, action.item)))
return true
elseif kind == "delta" then
local max = view.item and math.max(1, freeOf(view, view.item)) or nil
view.count = app.clamp(view.count + (action.n or 0), 1, max)
return true
elseif kind == "withdraw" then
local why = storage.blocked(view)
if why then
view.result = {status = app.REJECTED, reason = why}
return true
end

app.ask(view, {kind = "withdraw", item = view.item, count = view.count})
return true
end
return false
end


function storage.searching(view)
return view.items and view.list or nil
end


function storage.handle(view, event, grid)
if storage.searching(view) and app.type(view.list, event) then return true end
if not input.heard(event) then return false end
local action = input.actionFor(grid, event)
if not action then return false end
return storage.act(view, action)
end

return storage
]],
["mfg/station/broker.lua"] = [[

















local store = require("mfg.storage")
local ledger = require("mfg.station.ledger")

local broker = {}

broker.POOL = "/pool"




function broker.inboundOf(node)
return ("/%s/in"):format(node)
end

function broker.outboundOf(node)
return ("/%s/out"):format(node)
end








function broker.place(link, spec)
local id = spec.id or ledger.nextId()

local record, err = ledger.open({
id = id, node = spec.node, product = spec.product,
quantity = spec.quantity, supplied = spec.supplied,
owed = spec.owed or {[spec.product] = spec.quantity},
})
if not record then return nil, err end

local answer = link.request(spec.node, {
command = "place",
order = {
id = id, product = spec.product, quantity = spec.quantity,
supplied = record.promised, owed = record.owed,
},
})

if not answer or answer.status ~= "completed" then
ledger.advance(id, ledger.WITHDRAWN,
"the node did not accept it: "
.. tostring(answer and answer.reason or "no reply"))
return nil, ("%s did not accept the order: %s"):format(spec.node,
tostring(answer and answer.reason or "no reply"))
end

return record
end







function broker.supply(link, id)
local record = ledger.get(id)
if not record then return nil, "no such order: " .. tostring(id) end

local inbound = broker.inboundOf(record.node)
if not store.isBound(inbound) then
return nil, ("%s is not bound -- that is the boundary this station pushes "
.. "into"):format(inbound)
end

local outstanding = ledger.outstandingSupply(record)
if not next(outstanding) then return {sent = {}, complete = true} end

local sent, short = {}, {}
for item, wanted in pairs(outstanding) do
local moved = store.move(broker.POOL, inbound, item, wanted)
if moved and moved > 0 then sent[item] = moved end
if (moved or 0) < wanted then
short[item] = wanted - (moved or 0)
end
end

if next(sent) then ledger.pushed(id, sent) end



local answer = link.request(record.node, {command = "receive", order = id})
local accepted = answer and answer.status == "completed"

record = ledger.get(id)
if not next(ledger.outstandingSupply(record)) then
ledger.advance(id, ledger.AWAITING, "supplied in full")
else
ledger.advance(id, ledger.SUPPLYING, "part supplied")
end

return {
sent = sent,
short = next(short) and short or nil,
complete = not next(ledger.outstandingSupply(ledger.get(id))),
acknowledged = accepted,
statement = answer and answer.statement,
}
end








function broker.collect(link, id)
local record = ledger.get(id)
if not record then return nil, "no such order: " .. tostring(id) end

local outbound = broker.outboundOf(record.node)
if not store.isBound(outbound) then
return nil, ("%s is not bound -- that is where this station collects")
:format(outbound)
end

local outstanding = ledger.outstandingProduct(record)
local got = {}
for item, wanted in pairs(outstanding) do
local moved = store.move(outbound, broker.POOL, item, wanted)
if moved and moved > 0 then got[item] = moved end
end

if next(got) then
ledger.collected(id, got)
ledger.advance(id, ledger.COLLECTING,
"collected from " .. outbound)
end

record = ledger.get(id)
local remaining = ledger.outstandingProduct(record)

if not next(remaining) then


local answer = link.request(record.node, {command = "settle", order = id})
if answer and answer.status == "completed" then
ledger.advance(id, ledger.CLOSED, "settled with " .. record.node)
return {got = got, closed = true, settled = answer.settled}
end
return {got = got, closed = false,
reason = answer and answer.reason or "no reply to settle"}
end

return {got = got, closed = false, outstanding = remaining}
end




function broker.check(link, id)
local record = ledger.get(id)
if not record then return nil, "no such order: " .. tostring(id) end

local answer = link.request(record.node, {command = "statement", order = id})
if not answer or answer.status ~= "completed" or not answer.statement then
return nil, ("no statement from %s: %s"):format(record.node,
tostring(answer and answer.reason or "no reply"))
end

local reconciliation = ledger.reconcile(id, answer.statement)
return answer.statement, reconciliation
end





function broker.step(link)
local acted = {}

for _, record in ipairs(ledger.open_orders()) do
local id = record.id
local statement, reconciliation = broker.check(link, id)

if not statement then
acted[#acted + 1] = {order = id, did = "unreachable"}
else

if next(ledger.outstandingSupply(record)) then
local supplied = broker.supply(link, id)
acted[#acted + 1] = {order = id, did = "supplied",
detail = supplied}
end


if statement.state == "fulfilled"
or next(statement.delivered or {}) then
local collected = broker.collect(link, id)
acted[#acted + 1] = {order = id, did = "collected",
detail = collected}
end


if reconciliation and not reconciliation.agrees then
acted[#acted + 1] = {order = id, did = "DISAGREES",
detail = reconciliation.findings}
end
end
end

return acted
end

function broker.withdraw(link, id, why)
local record = ledger.get(id)
if not record then return nil, "no such order: " .. tostring(id) end

local answer = link.request(record.node,
{command = "cancel", order = id, why = why})
if not answer or answer.status ~= "completed" then
return nil, ("%s did not accept the cancellation: %s"):format(record.node,
tostring(answer and answer.reason or "no reply"))
end

ledger.advance(id, ledger.WITHDRAWN, why or "withdrawn")


return {returned = answer.cancelled and answer.cancelled.returned}
end

return broker
]],
["mfg/station/ledger.lua"] = [[












local state = require("mfg.common.state")

local ledger = {}

local FILE = "orders"




ledger.PLACED = "placed"
ledger.SUPPLYING = "supplying"
ledger.AWAITING = "awaiting"
ledger.COLLECTING = "collecting"
ledger.CLOSED = "closed"
ledger.WITHDRAWN = "withdrawn"

function ledger.all()
local stored = state.read(FILE, {})
if type(stored) ~= "table" then return {} end
return stored
end

function ledger.get(id)
return ledger.all()[id]
end

local function put(record)
local all = ledger.all()
all[record.id] = record
state.write(FILE, all)
return record
end

ledger.put = put




function ledger.nextId(prefix)
prefix = prefix or "ord"
local all = ledger.all()
local n = 1
while all[("%s-%d"):format(prefix, n)] do n = n + 1 end
return ("%s-%d"):format(prefix, n)
end


function ledger.open(spec)
if not spec.id then return nil, "an order needs an id" end
if ledger.get(spec.id) then
return nil, ("we already have an order called %s"):format(spec.id)
end
if not spec.node then return nil, "an order needs a node to place it with" end

return put({
id = spec.id,
node = spec.node,
product = spec.product,
quantity = spec.quantity,



promised = spec.supplied or {},
pushed = {},
owed = spec.owed or {},
collected = {},
state = ledger.PLACED,
opened = os.epoch("utc"),
history = {{state = ledger.PLACED, at = os.epoch("utc"),
why = "placed with " .. tostring(spec.node)}},
})
end

function ledger.advance(id, to, why)
local record = ledger.get(id)
if not record then return nil, "no such order: " .. tostring(id) end
record.state = to
record.history = record.history or {}
record.history[#record.history + 1] = {state = to, at = os.epoch("utc"), why = why}
return put(record)
end

function ledger.pushed(id, items)
local record = ledger.get(id)
if not record then return nil, "no such order: " .. tostring(id) end
for item, count in pairs(items or {}) do
record.pushed[item] = (record.pushed[item] or 0) + count
end
return put(record)
end

function ledger.collected(id, items)
local record = ledger.get(id)
if not record then return nil, "no such order: " .. tostring(id) end
for item, count in pairs(items or {}) do
record.collected[item] = (record.collected[item] or 0) + count
end
return put(record)
end


function ledger.outstandingSupply(record)
local out = {}
for item, promised in pairs(record.promised or {}) do
local sent = (record.pushed or {})[item] or 0
if promised > sent then out[item] = promised - sent end
end
return out
end


function ledger.outstandingProduct(record)
local out = {}
for item, owed in pairs(record.owed or {}) do
local got = (record.collected or {})[item] or 0
if owed > got then out[item] = owed - got end
end
return out
end

function ledger.open_orders()
local out = {}
for _, record in pairs(ledger.all()) do
if record.state ~= ledger.CLOSED and record.state ~= ledger.WITHDRAWN then
out[#out + 1] = record
end
end
table.sort(out, function(a, b) return a.id < b.id end)
return out
end











function ledger.reconcile(id, statement)
local record = ledger.get(id)
if not record then return nil, "no such order: " .. tostring(id) end
if type(statement) ~= "table" then
return nil, "no statement from the node to compare against"
end

local findings = {}

local function compare(what, ours, theirs)
local items = {}
for item in pairs(ours or {}) do items[item] = true end
for item in pairs(theirs or {}) do items[item] = true end
for item in pairs(items) do
local mine = (ours or {})[item] or 0
local yours = (theirs or {})[item] or 0
if mine ~= yours then
findings[#findings + 1] = {
what = what, item = item, ours = mine, theirs = yours,
}
end
end
end



compare("supplied", record.pushed, statement.received)

compare("collected", record.collected, statement.delivered)

compare("owed", record.owed, statement.owed)



local offManifest = nil
if statement.offManifest and next(statement.offManifest) then
offManifest = statement.offManifest
end

return {
order = id,
agrees = #findings == 0,
findings = findings,
offManifest = offManifest,
theirState = statement.state,
ourState = record.state,
}
end

return ledger
]],
["mfg/station/stationctl.lua"] = [[
















if not package.path:find("^/%?") then
package.path = "/?.lua;/?/init.lua;" .. package.path
end

local store = require("mfg.storage")
local cli = require("mfg.storage.cli")
local ledger = require("mfg.station.ledger")
local broker = require("mfg.station.broker")
local rpc = require("mfg.common.rpc")

local args = {...}
local cmd = args[1]



local link = {
request = function(node, body)
return rpc.request(node, "mfg-order", body, {timeout = 4, attempts = 2})
end,
}

local function usage()
print("stationctl nodes | orders | show <id> | check <id>")
print("stationctl order <node> <product> <qty> [item=count ...]")
print("stationctl supply <id> | collect <id> | withdraw <id>")
print("stationctl bind <path> <device...> | bindings | store <path>")
print("stationctl step                one turn of the loop")
end

local lines = cli.lines

if cmd == nil or cmd == "help" then
usage()

elseif cmd == "nodes" then


local names = {}
for i = 2, #args do names[#names + 1] = args[i] end
if #names == 0 then

local seen = {}
for _, record in pairs(ledger.all()) do seen[record.node] = true end
for node in pairs(seen) do names[#names + 1] = node end
if #names == 0 then
print("no nodes known -- try: stationctl nodes mfg")
return
end
end

for _, node in ipairs(names) do
local answer = link.request(node, {command = "hello"})
if answer and answer.status == "completed" then
print(("%-10s %s  %d order(s) open"):format(node,
tostring(answer.kind), answer.ordersOpen or 0))
print(("           inbound %s  outbound %s"):format(
tostring(answer.inbound), tostring(answer.outbound)))
if answer.products then
print("           makes: " .. table.concat(answer.products, ", "))
end
print(("           we address these as %s and %s"):format(
broker.inboundOf(node), broker.outboundOf(node)))
else
printError(("%-10s UNREACHABLE (%s)"):format(node,
tostring(answer and answer.reason or "no reply")))
end
end

elseif cmd == "bind" then
cli.bind("stationctl", args)

elseif cmd == "bindings" then
cli.bindings()

elseif cmd == "store" then
cli.store("stationctl", args[2])

elseif cmd == "order" then
local node, product, qty = args[2], args[3], tonumber(args[4] or "1")
if not (node and product) then
printError("usage: stationctl order <node> <product> <qty> [item=count ...]")
print("items listed are what THIS station supplies for the job")
return
end

local supplied = {}
for i = 5, #args do
local item, count = args[i]:match("^(.+)=(%d+)$")
if item then supplied[item] = tonumber(count) end
end



local short = {}
for item, count in pairs(supplied) do
local held = store.count(broker.POOL, item) or 0
if held < count then short[item] = {promised = count, held = held} end
end
if next(short) then
printError("this station does not hold what the order promises:")
for item, detail in pairs(short) do
printError(("  %s: promising %d, holding %d"):format(item,
detail.promised, detail.held))
end
return
end

local record, err = broker.place(link, {
node = node, product = product, quantity = qty, supplied = supplied,
})
if not record then printError(tostring(err)) return end

print(("%s placed with %s: %d %s"):format(record.id, node, qty, product))
lines("we supply", record.promised)
if next(record.promised) then
print("  the loop will push it across and tell them it arrived")
else
print("  supplying nothing -- they build it from their own stock")
end

elseif cmd == "orders" then
local all = ledger.all()
local any = false
for id, record in pairs(all) do
any = true
local supply = ledger.outstandingSupply(record)
local product = ledger.outstandingProduct(record)
print(("%-8s %-11s %-10s %d %s"):format(id, record.state,
record.node, record.quantity or 0, tostring(record.product)))
if next(supply) then
local parts = {}
for item, count in pairs(supply) do
parts[#parts + 1] = ("%d %s"):format(count, item)
end
print("         still to supply: " .. table.concat(parts, ", "))
end
if next(product) then
local parts = {}
for item, count in pairs(product) do
parts[#parts + 1] = ("%d %s"):format(count, item)
end
print("         still owed us:   " .. table.concat(parts, ", "))
end
end
if not any then print("no orders") end

elseif cmd == "show" then
local record = ledger.get(args[2] or "")
if not record then printError("no such order: " .. tostring(args[2])) return end
print(("%s  %s  with %s"):format(record.id, record.state, record.node))
lines("we promised", record.promised)
lines("we pushed", record.pushed)
lines("they owe us", record.owed)
lines("we collected", record.collected)
if record.history then
print("  history")
for _, entry in ipairs(record.history) do
print(("    %-11s %s"):format(entry.state, tostring(entry.why)))
end
end

elseif cmd == "check" then
local id = args[2]
if not id then printError("usage: stationctl check <id>") return end
local statement, reconciliation = broker.check(link, id)
if not statement then printError(tostring(reconciliation)) return end

print(("their state: %s    ours: %s"):format(tostring(reconciliation.theirState),
tostring(reconciliation.ourState)))
lines("they received", statement.received)
lines("they delivered", statement.delivered)
lines("off manifest (held, unspendable)", statement.offManifest)

if reconciliation.agrees then
print("  the two ledgers AGREE")
else


printError("  the two ledgers DISAGREE:")
for _, finding in ipairs(reconciliation.findings) do
printError(("    %s %s: we say %d, they say %d"):format(
finding.what, finding.item, finding.ours, finding.theirs))
end
end

elseif cmd == "supply" then
local result, err = broker.supply(link, args[2] or "")
if not result then printError(tostring(err)) return end
lines("pushed", result.sent)
if result.short then lines("still short", result.short) end
print(result.complete and "  supplied in full" or "  part supplied")

elseif cmd == "collect" then
local result, err = broker.collect(link, args[2] or "")
if not result then printError(tostring(err)) return end
lines("collected", result.got)
if result.closed then
print("  settled -- the order is closed")
elseif result.reason then
printError("  not settled: " .. tostring(result.reason))
elseif result.outstanding then
lines("still owed us", result.outstanding)
end

elseif cmd == "withdraw" then
local result, err = broker.withdraw(link, args[2] or "", args[3])
if not result then printError(tostring(err)) return end
print("withdrawn")
lines("they are returning", result.returned)
print("  the loop will collect it from their outbound point")

elseif cmd == "step" then
local acted = broker.step(link)
if #acted == 0 then print("nothing to do") return end
for _, entry in ipairs(acted) do
print(("%-8s %s"):format(entry.order, entry.did))
end

else
printError("unknown command: " .. tostring(cmd))
usage()
end
]],
["mfg/station/stationd.lua"] = [[








if not package.path:find("^/%?") then
package.path = "/?.lua;/?/init.lua;" .. package.path
end

local args = {...}

local services = require("mfg.common.services")
local join = require("mfg.common.join")
local console = require("mfg.common.console")
local broker = require("mfg.station.broker")

print("station starting")

local manager = services.new({name = "station"})










services.declare(manager, {
name = "netstack",
critical = true,
start = function()
shell.run("/netstart", args[1] or join.bootstrapPeer())
end,
})












services.declare(manager, {
name = "enroll",
requires = {"netstack"},
restart = false,
ready = function()
local acknet = require("acknet")
if acknet.isRunning() then return true end
return false, "waiting for acknet, which enrollment rides"
end,
start = function()
local admitted, why = join.bootstrap()
print(("enrollment: %s"):format(tostring(why)))
if not admitted then
printError("not admitted -- no counterparty will be reachable")
end
end,
})









services.declare(manager, {
name = "contracts",
requires = {"netstack"},
ready = function()
local net = require("net")
if net.ready() then return true end
return false, "the netstack has not come up"
end,
start = function()
local rpc = require("mfg.common.rpc")
local link = {
request = function(node, body)
return rpc.request(node, "mfg-order", body,
{timeout = 4, attempts = 2})
end,
}

print("working contracts")
while true do
local acted = broker.step(link)
for _, entry in ipairs(acted) do



if entry.did == "DISAGREES" then
printError(("%s: the ledgers disagree"):format(entry.order))
for _, finding in ipairs(entry.detail or {}) do
printError(("  %s %s: we say %d, they say %d"):format(
finding.what, finding.item, finding.ours,
finding.theirs))
end
elseif entry.did ~= "unreachable" then
print(("%s %s"):format(entry.order, entry.did))
end
end
sleep(5)
end
end,
})

console.declare(manager, {prompt = "station"})

local halted = services.run(manager)
if halted then
printError(halted)
else
print("station stopped")
end
]],
