["mfg/storage/cli.lua"] = [[






local store = require("mfg.storage")

local cli = {}


function cli.lines(label, tbl)
if not tbl or not next(tbl) then return end
print("  " .. label)
for item, count in pairs(tbl) do
print(("    %-34s %s"):format(item, tostring(count)))
end
end


function cli.slots(text)
if type(text) ~= "string" or text == "" then return nil end
local out = {}
for part in text:gmatch("[^,]+") do
local a, b = part:match("^(%d+)%-(%d+)$")
if a then
a, b = tonumber(a), tonumber(b)
if a > b then return nil end
for slot = a, b do out[#out + 1] = slot end
elseif part:match("^%d+$") then
out[#out + 1] = tonumber(part)
else
return nil
end
end
return #out > 0 and out or nil
end




local function bindSignal(tool, path, args)
local device, face = args[3], args[4]
if not device or not face then
printError(("usage: %s bind %s <relay|local> <face>"):format(tool, path))
return
end
if device ~= "local" and not peripheral.isPresent(device) then
printError("not on the network: " .. device)
print("a relay is named like redstone_relay_0; `local` is this computer")
return
end
local record, err = store.bind(path, {device}, {face = face})
if not record then printError(tostring(err)) return end
print(("bound %s -> %s %s (%s %s)"):format(path, device, face,
tostring(record.direction), tostring(record.kind)))
end



function cli.bind(tool, args)
local path = args[2]
if not path or not args[3] then
printError(("usage: %s bind <path> <device...> [--slots 1-3] "
.. "[--interface]"):format(tool))
print("paths look like /pool or /t1/in")
print(("a signal: %s bind <path> <relay|local> <face>"):format(tool))
return
end

local declared = require("mfg.storage.mount").get(path)
if declared and (declared.kind == "level" or declared.kind == "flag") then
return bindSignal(tool, path, args)
end

local devices, slots, via = {}, nil, nil
local i = 3
while i <= #args do
local word = args[i]
if word == "--slots" then
slots = cli.slots(args[i + 1])
if not slots then
printError("--slots takes a list or a range: 1,2 or 1-9")
return
end
i = i + 2
elseif word == "--interface" then
via = "interface"
i = i + 1
else
devices[#devices + 1] = word
i = i + 1
end
end
if #devices == 0 then printError("no device given") return end




local absent = {}
for _, device in ipairs(devices) do
if not peripheral.isPresent(device) then absent[#absent + 1] = device end
end
if #absent > 0 then
printError("not on the network: " .. table.concat(absent, ", "))
print("names are namespaced, e.g. minecraft:chest_0")
print("and check the wired modem on each is ACTIVATED (right-click it)")
return
end




local exclusive = (path == "/pool" or path == "/cache")
if exclusive and (slots or via) then
printError(path .. " is the pool: whole chests only")
return
end
local record, err = store.bind(path, devices,
{coherence = exclusive and store.EXCLUSIVE or store.RELAYED,
slots = slots, via = via})
if not record then printError(tostring(err)) return end
print(("bound %s -> %s%s (%s%s)"):format(path, table.concat(devices, ", "),
slots and (" slots " .. table.concat(slots, ",")) or "",
record.coherence, via and ", interface" or ""))
end



local function where(status)
if #status.devices == 0 then return "UNBOUND" end
local text = table.concat(status.devices, ", ")
local record = require("mfg.storage.mount").get(status.path) or {}
if record.face then text = text .. " " .. record.face end
if record.slots then text = text .. " slots " .. table.concat(record.slots, ",") end
if record.via == "interface" then text = text .. " (interface)" end
return text
end

function cli.bindings()
local paths = store.list()
if #paths == 0 then print("nothing bound") return end
for _, path in ipairs(paths) do
local status = store.status(path)
local record = require("mfg.storage.mount").get(path) or {}
local kind = record.kind and record.kind ~= "volume"
and (record.direction or "") .. " " .. record.kind or status.coherence
print(("%-14s %-10s %s"):format(path, kind, where(status)))
if status.degraded then


printError("               DEGRADED, missing: "
.. table.concat(status.missing, ", "))
end
end
end



function cli.store(tool, path, defrag)
if not path then printError(("usage: %s store <path>"):format(tool)) return end

local status, sErr = store.status(path)
if not status then printError(tostring(sErr)) return end

print(("%s  %s"):format(path, status.coherence))
print("  devices: " .. (#status.devices > 0
and table.concat(status.devices, ", ") or "UNBOUND"))
if status.degraded then
printError("  DEGRADED, missing: " .. table.concat(status.missing, ", "))
end
if not status.bound then return end

local manifest, degraded = store.manifest(path)
if not manifest then printError(tostring(degraded)) return end




local slots = store.slots(path)
if slots then
print(("  slots: %d used, %d free of %d   keys: %d")
:format(slots.used, slots.free, slots.total, slots.keys))
if slots.reclaimable > 0 and defrag then



print(("  up to %d slot(s) reclaimable -- run '%s %s'")
:format(slots.reclaimable, defrag, path))
end
end
local any = false
for key, count in pairs(manifest) do
print(("    %-34s %d"):format(key, count))
any = true
end
if not any then print("    (empty)") end
end

return cli
]],
["mfg/storage/custody.lua"] = [[


















local store = require("mfg.storage")
local state = require("mfg.common.state")

local custody = {}

local ORDERS = "orders"



custody.IN = "/in"
custody.OUT = "/out"
custody.POOL = "/pool"

custody.ACCEPTED = "accepted"
custody.RECEIVING = "receiving"
custody.READY = "ready"
custody.RUNNING = "running"
custody.BLOCKED = "blocked"
custody.FULFILLED = "fulfilled"
custody.SETTLED = "settled"
custody.RETURNED = "returned"
custody.FAULTED = "faulted"




local COMMIT_TTL = 15 * 60 * 1000



function custody.orders()
local all = state.read(ORDERS, {})
if type(all) ~= "table" then return {} end
return all
end

function custody.get(id)
return custody.orders()[id]
end

local function put(order)
local all = custody.orders()
all[order.id] = order
state.write(ORDERS, all)
return order
end



local function transition(order, to, why)
order.state = to
order.history = order.history or {}
order.history[#order.history + 1] = {
state = to, why = why, at = os.epoch("utc"),
}
return put(order)
end





function custody.accept(spec)
spec = spec or {}
if not spec.id then return nil, "an order needs an id" end
if custody.get(spec.id) then
return nil, ("order %s already exists"):format(spec.id)
end
if type(spec.owed) ~= "table" or next(spec.owed) == nil then
return nil, "an order must declare what it owes the station"
end

local order = {
id = spec.id,
from = spec.from,
product = spec.product,
quantity = spec.quantity,



supplied = spec.supplied or {},
owed = spec.owed,
received = {},
offManifest = {},
committed = {},
delivered = {},
resolved = {},
opened = os.epoch("utc"),
state = custody.ACCEPTED,
}
return transition(order, custody.ACCEPTED, "manifest recorded")
end







function custody.classes()
local consigned, owedTotal = {}, {}

for id, order in pairs(custody.orders()) do
local open = order.state ~= custody.SETTLED
and order.state ~= custody.RETURNED

if open then
for item, count in pairs(order.received or {}) do
local used = (order.consumed and order.consumed[item]) or 0
local left = count - used
if left > 0 then
consigned[item] = consigned[item] or {}
consigned[item][id] = (consigned[item][id] or 0) + left
end
end



for item, count in pairs(order.owed or {}) do
local delivered = (order.delivered and order.delivered[item]) or 0
local produced = (order.produced and order.produced[item]) or 0
local holding = math.min(produced - delivered, count - delivered)
if holding > 0 then
owedTotal[item] = (owedTotal[item] or 0) + holding
end
end
end
end

return consigned, owedTotal
end












function custody.available(item, orderId)
local physical = store.count(custody.POOL, item) or 0
local consigned, owed = custody.classes()

local consignedTotal = 0
for _, count in pairs(consigned[item] or {}) do
consignedTotal = consignedTotal + count
end

local free = physical - consignedTotal - (owed[item] or 0)
if free < 0 then



free = 0
end

if not orderId then return free end

local mine = (consigned[item] or {})[orderId] or 0
local order = custody.get(orderId)
local committed = order and order.committed and order.committed[item] or 0
local usable = free + mine - committed
if usable < 0 then usable = 0 end
return usable
end


function custody.explain(item)
local consigned, owed = custody.classes()
local byOrder = {}
local consignedTotal = 0
for id, count in pairs(consigned[item] or {}) do
byOrder[id] = count
consignedTotal = consignedTotal + count
end
local physical = store.count(custody.POOL, item) or 0
return {
item = item,
physical = physical,
consigned = consignedTotal,
consignedBy = byOrder,
owed = owed[item] or 0,
localFree = custody.available(item, nil),
}
end









function custody.receive(orderId)
local order = custody.get(orderId)
if not order then return nil, "no such order: " .. tostring(orderId) end

if not store.isBound(custody.IN) then
return nil, ("%s is not bound -- the station's inbound point is where a "
.. "manifest is reconciled (K2.1)"):format(custody.IN)
end

local arriving = store.manifest(custody.IN)
if not arriving then return nil, "cannot read " .. custody.IN end

local statement = {order = orderId, took = {}, offManifest = {}, short = {}}

for selector, declared in pairs(order.supplied) do



local item = selector
if type(selector) == "string" and selector:sub(1, 1) == "#" then
local resolvedKey = store.resolve(custody.IN, selector)
if resolvedKey then
item = resolvedKey
order.resolved[selector] = resolvedKey
end
end

local already = order.received[item] or 0
local outstanding = declared - already

if outstanding > 0 then
local present = store.count(custody.IN, item) or 0
local take = math.min(outstanding, present)
if take > 0 then
local moved = store.move(custody.IN, custody.POOL, item, take)
if moved and moved > 0 then
order.received[item] = already + moved
statement.took[item] = moved
end
end
local nowHave = order.received[item] or 0
if nowHave < declared then
statement.short[item] = declared - nowHave
end
end
end



local leftover = store.manifest(custody.IN) or {}
for item, count in pairs(leftover) do
statement.offManifest[item] = count
order.offManifest[item] = count
end

local complete = true
for selector, declared in pairs(order.supplied) do
local item = order.resolved[selector] or selector
if (order.received[item] or 0) < declared then complete = false end
end




if complete then
transition(order, custody.READY, "all declared material received")
else
transition(order, custody.RECEIVING, "awaiting the remainder")
end

statement.state = order.state
statement.complete = complete
return statement
end









function custody.commit(orderId, requirements, opts)
opts = opts or {}
local order = custody.get(orderId)
if not order then return nil, "no such order: " .. tostring(orderId) end

local short = {}
for item, wanted in pairs(requirements) do
local usable = custody.available(item, orderId)
if usable < wanted then
short[item] = {wanted = wanted, available = usable}
end
end
if next(short) then return nil, short end

order.committed = order.committed or {}
local lines = {}
for item, wanted in pairs(requirements) do
order.committed[item] = (order.committed[item] or 0) + wanted
lines[item] = wanted
end

order.commitments = order.commitments or {}
local handle = ("%s-%d"):format(orderId, os.epoch("utc"))
order.commitments[handle] = {
handle = handle,
lines = lines,
expires = os.epoch("utc") + (opts.ttl or COMMIT_TTL),
}
put(order)
return handle
end





function custody.consume(orderId, handle, actual)
local order = custody.get(orderId)
if not order then return nil, "no such order: " .. tostring(orderId) end
local commitment = order.commitments and order.commitments[handle]
if not commitment then return nil, "no such commitment: " .. tostring(handle) end

order.consumed = order.consumed or {}
for item, committed in pairs(commitment.lines) do
local used = (actual and actual[item]) or 0
if used > committed then used = committed end
order.consumed[item] = (order.consumed[item] or 0) + used
order.committed[item] = math.max(0, (order.committed[item] or 0) - committed)
end

order.commitments[handle] = nil
put(order)
return true
end





function custody.release(orderId, handle)
local order = custody.get(orderId)
if not order then return nil, "no such order: " .. tostring(orderId) end
local commitment = order.commitments and order.commitments[handle]
if not commitment then return false end

for item, committed in pairs(commitment.lines) do
order.committed[item] = math.max(0, (order.committed[item] or 0) - committed)
end
order.commitments[handle] = nil
put(order)
return true
end


function custody.sweep(now)
now = now or os.epoch("utc")
local swept = {}
for id, order in pairs(custody.orders()) do
for handle, commitment in pairs(order.commitments or {}) do
if commitment.expires and now >= commitment.expires then
custody.release(id, handle)
swept[#swept + 1] = {order = id, handle = handle}
end
end
end
return swept
end




function custody.produced(orderId, items)
local order = custody.get(orderId)
if not order then return nil, "no such order: " .. tostring(orderId) end
order.produced = order.produced or {}
for item, count in pairs(items or {}) do
order.produced[item] = (order.produced[item] or 0) + count
end
return put(order)
end






function custody.deliver(orderId)
local order = custody.get(orderId)
if not order then return nil, "no such order: " .. tostring(orderId) end
if not store.isBound(custody.OUT) then
return nil, ("%s is not bound -- it is where the station collects (K2.1)")
:format(custody.OUT)
end

local sent = {}
for item, owed in pairs(order.owed) do
local already = (order.delivered and order.delivered[item]) or 0
local outstanding = owed - already
if outstanding > 0 then
local moved = store.move(custody.POOL, custody.OUT, item, outstanding)
if moved and moved > 0 then
order.delivered = order.delivered or {}
order.delivered[item] = already + moved
sent[item] = moved
end
end
end

local complete = true
for item, owed in pairs(order.owed) do
if ((order.delivered or {})[item] or 0) < owed then complete = false end
end



if complete then
transition(order, custody.FULFILLED, "all owed output is in " .. custody.OUT)
end

order.deliveries = order.deliveries or {}
if next(sent) then
order.deliveries[#order.deliveries + 1] = {at = os.epoch("utc"), sent = sent}
end
put(order)

return {sent = sent, complete = complete, state = order.state}
end


function custody.settle(orderId)
local order = custody.get(orderId)
if not order then return nil, "no such order: " .. tostring(orderId) end
if order.state ~= custody.FULFILLED then
return nil, ("order %s is %s, not fulfilled"):format(orderId, order.state)
end

for item in pairs(order.owed) do
local left = store.count(custody.OUT, item) or 0
if left > 0 then
return nil, ("%d %s is still in %s -- the station has not collected")
:format(left, item, custody.OUT)
end
end





local released = {}
for item, received in pairs(order.received) do
local used = (order.consumed or {})[item] or 0
local leftover = received - used
if leftover > 0 then released[item] = leftover end
end
order.releasedToLocal = released

transition(order, custody.SETTLED, "station collected")
return {released = released, state = order.state}
end





function custody.cancel(orderId, why)
local order = custody.get(orderId)
if not order then return nil, "no such order: " .. tostring(orderId) end

local returned = {}
if store.isBound(custody.OUT) then
for item, received in pairs(order.received) do
local used = (order.consumed or {})[item] or 0
local leftover = received - used
if leftover > 0 then
local moved = store.move(custody.POOL, custody.OUT, item, leftover)
if moved and moved > 0 then returned[item] = moved end
end
end
end

for handle in pairs(order.commitments or {}) do
custody.release(orderId, handle)
end

order = custody.get(orderId)
order.returnedToStation = returned
transition(order, custody.RETURNED, why or "cancelled")
return {returned = returned, state = order.state}
end






function custody.statement(orderId)
local order = custody.get(orderId)
if not order then return nil, "no such order: " .. tostring(orderId) end

return {
id = order.id,
from = order.from,
state = order.state,
supplied = order.supplied,
received = order.received,
offManifest = order.offManifest,
owed = order.owed,
produced = order.produced or {},
delivered = order.delivered or {},
consumed = order.consumed or {},
committed = order.committed or {},
deliveries = order.deliveries or {},
releasedToLocal = order.releasedToLocal,
returnedToStation = order.returnedToStation,
history = order.history,
}
end

return custody
]],
["mfg/storage/hal/inv_real.lua"] = [[











local backend = {}

backend.name = "real"

function backend.isPresent(name)
return peripheral.isPresent(name) and peripheral.hasType(name, "inventory") == true
end


local function wrap(name)
local inv = peripheral.wrap(name)
if not inv then return nil, "no inventory named " .. tostring(name) end
return inv
end

function backend.size(name)
local inv, why = wrap(name)
if not inv then return nil, why end
return inv.size()
end










function backend.names()
local found = {}
for _, name in ipairs(peripheral.getNames()) do
if peripheral.hasType(name, "inventory") == true then
found[#found + 1] = name
end
end
return found
end







function backend.list(name)
local inv, why = wrap(name)
if not inv then return nil, why end
return inv.list()
end











function backend.detail(name, slot)
local inv, why = wrap(name)
if not inv then return nil, why end
local ok, detail = pcall(inv.getItemDetail, slot)
if not ok then return nil, tostring(detail) end
return detail
end




function backend.push(from, to, fromSlot, limit, toSlot)
local inv, why = wrap(from)
if not inv then return nil, why end
local ok, moved = pcall(inv.pushItems, to, fromSlot, limit, toSlot)
if not ok then return nil, tostring(moved) end
return moved
end

function backend.pull(to, from, fromSlot, limit, toSlot)
local inv, why = wrap(to)
if not inv then return nil, why end
local ok, moved = pcall(inv.pullItems, from, fromSlot, limit, toSlot)
if not ok then return nil, tostring(moved) end
return moved
end

return backend
]],
["mfg/storage/handoff.lua"] = [[










local store = require("mfg.storage")

local handoff = {}





local config = require("mfg.common.config")

local CONFIRM_FLOOR = 4
local POLL = 0.5

local function inputOf(node)
return node.input or ("/%s/in"):format(node.id)
end

local function outputOf(node)
return node.output or ("/%s/out"):format(node.id)
end





local function legacyPath(node)
for _, path in ipairs({inputOf(node), outputOf(node)}) do
if path:sub(1, 1) ~= "/" then
return ("%s is a device name, not a mount path: this record for %s "
.. "predates the storage layer. Re-register it: mfgctl register.")
:format(path, tostring(node.id))
end
end
return nil
end

local function sourceOf(node, opts)
return node.source or (opts and opts.source) or config.setting("source")
end





handoff.inputOf = inputOf
handoff.outputOf = outputOf
handoff.sourceOf = sourceOf
handoff.legacyPath = legacyPath











local function alreadyWith(node, held, item)
local inInput = store.count(inputOf(node), item) or 0
return inInput + (held and (held[item] or 0) or 0)
end











local function resolve(source, selector)
if type(selector) ~= "string" or selector:sub(1, 1) ~= "#" then
return selector, nil
end
return store.resolve(source, selector)
end


























function handoff.deliver(node, requirements, opts)
opts = opts or {}

local stale = legacyPath(node)
if stale then
return false, {}, {[tostring(node.id)] = {reason = stale}},
{stale = stale, confirmed = false}
end

local source = sourceOf(node, opts)
local input = inputOf(node)

local report = nil
if type(opts.report) == "function" then report = opts.report() end
local held = report and report.held or nil
local feed = report and report.feed or nil

local delivered, shortfall, resolved = {}, {}, {}
local complete = true

for selector, wanted in pairs(requirements) do
local item, err = resolve(source, selector)
if not item then
complete = false
shortfall[selector] = {wanted = wanted, got = 0, reason = err}
else
if item ~= selector then resolved[selector] = item end

local present = alreadyWith(node, held, item)
local need = wanted - present

if need <= 0 then
delivered[item] = present
else
local moved, moveErr = store.move(source, input, item, need)
delivered[item] = present + (moved or 0)
if (moved or 0) < need then
complete = false
shortfall[item] = {wanted = wanted, got = delivered[item],
reason = moveErr}
end
end
end
end

local info = {source = source, input = input, resolved = resolved,
confirmed = false, feed = feed}



if not complete or feed ~= "push" or type(opts.report) ~= "function" then
info.confirmed = (feed == "pull") or false
return complete, delivered, shortfall, info
end

local confirmed, stranded, transit = handoff.confirm(node, requirements,
resolved, opts)
info.confirmed = confirmed
info.transit = transit

if not confirmed then




info.relayStalled = true
info.stranded = stranded
for item, count in pairs(stranded) do
shortfall[item] = {wanted = requirements[item], got = 0,
reason = ("relay stalled: %d stranded in %s"):format(count, input)}
end
return false, delivered, shortfall, info
end

return true, delivered, shortfall, info
end






function handoff.confirm(node, requirements, resolved, opts)
opts = opts or {}
local input = inputOf(node)





local timeout = opts.confirmTimeout
if not timeout and node.transit then timeout = node.transit * 3 end
if not timeout then timeout = CONFIRM_FLOOR * 2 end
if timeout < CONFIRM_FLOOR then timeout = CONFIRM_FLOOR end


local awaiting = {}
for selector, wanted in pairs(requirements) do
awaiting[resolved[selector] or selector] = wanted
end

local started = os.epoch("utc")
local deadline = started + timeout * 1000

repeat
local report = opts.report()
local held = (report and report.held) or {}
local satisfied = true
for item, wanted in pairs(awaiting) do
if (held[item] or 0) < wanted then satisfied = false end
end
if satisfied then
return true, nil, (os.epoch("utc") - started) / 1000
end
sleep(POLL)
until os.epoch("utc") >= deadline


local stranded = {}
for item in pairs(awaiting) do
local left = store.count(input, item) or 0
if left > 0 then stranded[item] = left end
end
return false, stranded, nil
end









function handoff.collect(node, opts)
local stale = legacyPath(node)
if stale then return nil, stale end
return store.drain(outputOf(node), sourceOf(node, opts))
end






function handoff.returnUnused(node, opts)
local stale = legacyPath(node)
if stale then return nil, stale end
return store.drain(inputOf(node), sourceOf(node, opts))
end

return handoff
]],
["mfg/storage/index.lua"] = [[















local index = {}

local listings = {}

function index.reset()
listings = {}
end

function index.get(device)
return listings[device]
end

function index.put(device, listing, size)
listings[device] = {listing = listing, size = size}
end

function index.drop(device)
listings[device] = nil
end








function index.consumed(device, slot, count)
local entry = listings[device]
if not entry or not entry.listing then return end

local stack = entry.listing[slot]
if not stack then return end

stack.count = stack.count - count
if stack.count <= 0 then entry.listing[slot] = nil end
end

return index
]],
["mfg/storage/init.lua"] = [[












local hal = require("mfg.common.hal")
local mount = require("mfg.storage.mount")
local index = require("mfg.storage.index")

local store = {}

store.EXCLUSIVE = mount.EXCLUSIVE
store.RELAYED = mount.RELAYED





local YIELD_EVERY = 8




local ASSUMED_STACK = 64








function store.key(name, nbt)
if nbt == nil or nbt == "" then return name end
return name .. "#" .. nbt
end

function store.parse(key)
local name, nbt = key:match("^([^#]+)#(.+)$")
if name then return name, nbt end
return key, nil
end














function store.selector(sel)
if type(sel) == "table" then return sel end
if type(sel) ~= "string" then return nil end
if sel:sub(1, 1) == "#" then
return {kind = "tag", tag = sel:sub(2)}
end
local name, nbt = sel:match("^([^#]+)#(.+)$")
if name then return {kind = "key", name = name, nbt = nbt, key = sel} end
return {kind = "id", name = sel}
end












local attrs = {}

function store.forget()
attrs = {}
index.reset()
end







local function learn(key, device, slot)
if attrs[key] then return attrs[key] end
if not device or not slot then return nil end

local detail = hal.inventory().detail(device, slot)
if not detail then return nil end

attrs[key] = {
maxCount = detail.maxCount,
tags = detail.tags or {},
displayName = detail.displayName,
}
return attrs[key]
end



local function stackLimit(key, sample)
local known = attrs[key]
if not known and sample then known = learn(key, sample.device, sample.slot) end
if known and known.maxCount then return known.maxCount, true end
return ASSUMED_STACK, false
end

local function tagsOf(key, sample)
local known = attrs[key]
if not known and sample then known = learn(key, sample.device, sample.slot) end
return known and known.tags or nil
end






local function satisfies(selector, key, sample)
if selector.kind == "id" then
local name = store.parse(key)
return name == selector.name, true
elseif selector.kind == "key" then
return key == selector.key, true
elseif selector.kind == "tag" then
local tags = tagsOf(key, sample)
if not tags then return false, false end
return tags[selector.tag] == true, true
end
return false, true
end






local function cacheable(record)
return record.coherence == mount.EXCLUSIVE
end

local function listingOf(device, useCache)
if useCache then
local entry = index.get(device)
if entry then return entry.listing, entry.size end
end

local inv = hal.inventory()
local listing = inv.list(device)
if not listing then return nil, nil end
local size = inv.size(device) or 0

if useCache then index.put(device, listing, size) end
return listing, size
end













local function survey(path)
local record = mount.get(path)
if not record then return nil, "no such storage: " .. tostring(path) end
if mount.isSignal(record) then
return nil, ("%s is a signal, not a volume"):format(path)
end
if #record.devices == 0 then
return nil, ("%s is declared but UNBOUND"):format(path)
end

local present, missing = mount.devices(path)
local useCache = cacheable(record)

local out = {
path = path,
record = record,
devices = present,
missing = missing,
listings = {},
sizes = {},
manifest = {},
sample = {},
freeSlots = 0,
only = {},
}

for _, device in ipairs(present) do
local listing, size = listingOf(device, useCache)
if listing and record.slots then

local slots, kept = {}, {}
for _, slot in ipairs(record.slots) do
if slot <= (size or 0) then
slots[#slots + 1] = slot
kept[slot] = listing[slot]
end
end
listing, size = kept, #slots
out.only[device] = slots
end
if listing then
out.listings[device] = listing
out.sizes[device] = size

local occupied = 0
for slot, stack in pairs(listing) do
occupied = occupied + 1
local key = store.key(stack.name, stack.nbt)
out.manifest[key] = (out.manifest[key] or 0) + stack.count
if not out.sample[key] then
out.sample[key] = {device = device, slot = slot}
end
end
out.freeSlots = out.freeSlots + math.max(0, (size or 0) - occupied)
end
end

return out
end






function store.manifest(path)
local view, err = survey(path)
if not view then return nil, err end
return view.manifest, (#view.missing > 0) and view.missing or nil
end






function store.stock(path)
local manifest, degraded = store.manifest(path)
if not manifest then return nil, degraded end

local totals = {}
for key, count in pairs(manifest) do
local name = store.parse(key)
totals[name] = (totals[name] or 0) + count
end
return totals, degraded
end

function store.count(path, sel)
local view, err = survey(path)
if not view then return nil, err end
if not sel then
local total = 0
for _, count in pairs(view.manifest) do total = total + count end
return total
end

local selector = store.selector(sel)
if not selector then return nil, "not a selector: " .. tostring(sel) end

local total = 0
for key, count in pairs(view.manifest) do
if satisfies(selector, key, view.sample[key]) then total = total + count end
end
return total
end

function store.freeSlots(path)
local view, err = survey(path)
if not view then return nil, err end
return view.freeSlots
end














function store.room(path, sel)
local view, err = survey(path)
if not view then return nil, err end

local selector = store.selector(sel)
if not selector then return nil, "not a selector: " .. tostring(sel) end

local best, bestExact = nil, true
local considered = false

for key in pairs(view.manifest) do
if satisfies(selector, key, view.sample[key]) then
considered = true
local limit, known = stackLimit(key, view.sample[key])


local headroom = 0
for _, listing in pairs(view.listings) do
for _, stack in pairs(listing) do
if store.key(stack.name, stack.nbt) == key
and stack.count < limit then
headroom = headroom + (limit - stack.count)
end
end
end

local total = headroom + view.freeSlots * limit
if best == nil or total > best then
best, bestExact = total, known
end
end
end

if considered then return best, bestExact end




local limit = ASSUMED_STACK
local exact = false
if selector.kind ~= "tag" then
local key = selector.key or selector.name
if attrs[key] and attrs[key].maxCount then
limit, exact = attrs[key].maxCount, true
end
end
return view.freeSlots * limit, exact
end









function store.resolve(path, sel)
local view, err = survey(path)
if not view then return nil, err end

local selector = store.selector(sel)
if not selector then return nil, "not a selector: " .. tostring(sel) end

local best, bestCount = nil, -1
for key, count in pairs(view.manifest) do
if satisfies(selector, key, view.sample[key]) and count > bestCount then
best, bestCount = key, count
end
end

if not best then
return nil, ("nothing matching %s is in %s"):format(tostring(sel), path)
end
return best, nil
end



function store.locate(sel)
local found = {}
for _, path in ipairs(mount.volumes()) do
if mount.isBound(path) then
local n = store.count(path, sel)
if n and n > 0 then
found[#found + 1] = {path = path, count = n}
end
end
end
table.sort(found, function(a, b) return a.count > b.count end)
return found
end

function store.status(path)
local record = mount.get(path)
if not record then return nil, "no such storage: " .. tostring(path) end

local present, missing = mount.devices(path)
return {
path = path,
node = record.node,
role = record.role,
coherence = record.coherence,
bound = #record.devices > 0,
devices = present or {},
missing = missing or {},
degraded = (missing and #missing > 0) or false,
}
end











function store.audit()
local points, degraded, unbound = {}, {}, {}

for path in pairs(mount.all()) do
points[#points + 1] = path
end
table.sort(points)

local report = {points = {}, degraded = degraded, unbound = unbound}
for _, path in ipairs(points) do
local view = store.status(path)
report.points[#report.points + 1] = view
if not view.bound then
unbound[#unbound + 1] = path
elseif view.degraded then
degraded[#degraded + 1] = {path = path, missing = view.missing}
end
end

report.ok = (#degraded == 0)
return report
end








local function destinations(view, key, limit)
local holding, empty = {}, {}

for _, device in ipairs(view.devices) do
local listing = view.listings[device]
local headroom, occupied = 0, 0
for _, stack in pairs(listing or {}) do
occupied = occupied + 1
if store.key(stack.name, stack.nbt) == key and stack.count < limit then
headroom = headroom + (limit - stack.count)
end
end
local free = math.max(0, (view.sizes[device] or 0) - occupied)

if headroom > 0 then
holding[#holding + 1] = {device = device, headroom = headroom, free = free}
else
empty[#empty + 1] = {device = device, free = free}
end
end

table.sort(holding, function(a, b) return a.headroom > b.headroom end)
table.sort(empty, function(a, b) return a.free > b.free end)

local order = {}
for _, entry in ipairs(holding) do order[#order + 1] = entry.device end
for _, entry in ipairs(empty) do order[#order + 1] = entry.device end
return order
end




















local function sources(view, key)
local found = {}
for device, listing in pairs(view.listings) do
for slot, stack in pairs(listing) do
if store.key(stack.name, stack.nbt) == key then
found[#found + 1] = {device = device, slot = slot, count = stack.count}
end
end
end
table.sort(found, function(a, b) return a.count < b.count end)
return found
end







local function pushInto(dest, device, src, key, limit, remaining)
local inv = hal.inventory()
local only = dest.only and dest.only[device]
if not only then
local n, err = inv.push(src.device, device, src.slot, remaining)
return n, err, 1
end

local listing = dest.listings[device] or {}
local moved, calls, lastErr = 0, 0, nil
local want = math.min(remaining, src.count or remaining)
for _, slot in ipairs(only) do
if moved >= want then break end
local held = listing[slot]
if not held or (store.key(held.name, held.nbt) == key and held.count < limit) then
local n, err = inv.push(src.device, device, src.slot, want - moved, slot)
calls = calls + 1
if not n then
lastErr = err
elseif n > 0 then
moved = moved + n
local name, nbt = store.parse(key)
listing[slot] = {name = name, nbt = nbt,
count = (held and held.count or 0) + n}
end
end
end
if src.count then src.count = src.count - moved end
if moved == 0 and lastErr then return nil, lastErr, calls end
return moved, nil, math.max(calls, 1)
end







function store.move(from, to, sel, wanted)
local source, sErr = survey(from)
if not source then return 0, sErr end
local dest, dErr = survey(to)
if not dest then return 0, dErr end

if #source.devices == 0 then
return 0, ("%s has no reachable devices"):format(from)
end
if #dest.devices == 0 then
return 0, ("%s has no reachable devices"):format(to)
end

local selector = store.selector(sel)
if not selector then return 0, "not a selector: " .. tostring(sel) end




local candidates = {}
for key, count in pairs(source.manifest) do
if satisfies(selector, key, source.sample[key]) then
candidates[#candidates + 1] = {key = key, count = count}
end
end
table.sort(candidates, function(a, b) return a.count > b.count end)

local moved, calls = 0, 0
local blocked = {}
local lastErr = nil

for _, candidate in ipairs(candidates) do
if moved >= wanted then break end
local key = candidate.key
local limit = stackLimit(key, source.sample[key])
local order = destinations(dest, key, limit)
blocked = {}

for _, src in ipairs(sources(source, key)) do
if moved >= wanted then break end

local remaining = wanted - moved
local placedAny = false

for _, device in ipairs(order) do
if remaining <= 0 then break end
if not blocked[device] then
local n, err, used = pushInto(dest, device, src, key, limit,
remaining)
calls = calls + (used or 1)

if not n then
lastErr = tostring(err)
elseif n == 0 then



blocked[device] = true
else
moved = moved + n
remaining = remaining - n
placedAny = true
index.consumed(src.device, src.slot, n)
index.drop(device)
end

if calls % YIELD_EVERY == 0 then sleep(0) end
end
end

if not placedAny then

return moved, lastErr or ("%s is full"):format(to)
end
end
end

if moved == 0 and #candidates == 0 then
return 0, ("%s holds nothing matching %s"):format(from, tostring(sel))
end
return moved, lastErr
end














function store.slots(path)
local view, err = survey(path)
if not view then return nil, err end

local total, occupied = 0, 0
local perKey = {}

for device, listing in pairs(view.listings) do
total = total + (view.sizes[device] or 0)
for _, stack in pairs(listing) do
occupied = occupied + 1
local key = store.key(stack.name, stack.nbt)
perKey[key] = (perKey[key] or 0) + 1
end
end

local keys, reclaimable = 0, 0
for _, count in pairs(perKey) do
keys = keys + 1
reclaimable = reclaimable + (count - 1)
end

return {
total = total,
used = occupied,
free = total - occupied,
keys = keys,
reclaimable = reclaimable,
degraded = #view.missing > 0,
}
end











function store.summary(path)
local record = mount.get(path)
if not record then return nil, "no such storage: " .. tostring(path) end

local out = {
path = path,
coherence = record.coherence,
node = record.node,
role = record.role,
bound = #record.devices > 0,
devices = {},
missing = {},
degraded = false,
}

if not out.bound then return out end





local view, err = survey(path)
if not view then return out, err end

out.devices = view.devices or {}
out.missing = view.missing or {}
out.degraded = #out.missing > 0

local total, occupied, items = 0, 0, 0
local perKey = {}
for device, listing in pairs(view.listings) do
total = total + (view.sizes[device] or 0)
for _, stack in pairs(listing) do
occupied = occupied + 1
items = items + stack.count
local key = store.key(stack.name, stack.nbt)
perKey[key] = (perKey[key] or 0) + 1
end
end

local keys, reclaimable = 0, 0
for _, count in pairs(perKey) do
keys = keys + 1
reclaimable = reclaimable + (count - 1)
end

out.manifest = view.manifest
out.items = items
out.slots = {total = total, used = occupied, free = total - occupied,
keys = keys, reclaimable = reclaimable, degraded = out.degraded}
return out
end


























function store.defrag(path, opts)
opts = opts or {}
local record = mount.get(path)
if not record then return nil, "no such storage: " .. tostring(path) end



if record.coherence ~= mount.EXCLUSIVE then
return nil, ("%s is %s -- only an exclusive volume may be defragmented "
.. "(S8.2)"):format(path, tostring(record.coherence))
end

local view, err = survey(path)
if not view then return nil, err end

local inv = hal.inventory()
local result = {merged = 0, slotsFreed = 0, calls = 0, keys = 0}


local byKey = {}
for device, listing in pairs(view.listings) do
for slot, stack in pairs(listing) do
local key = store.key(stack.name, stack.nbt)
byKey[key] = byKey[key] or {}
table.insert(byKey[key], {device = device, slot = slot, count = stack.count})
end
end

for key, slots in pairs(byKey) do
if #slots > 1 then
result.keys = result.keys + 1


table.sort(slots, function(a, b) return a.count < b.count end)

local lo, hi = 1, #slots
while lo < hi do
local from, to = slots[lo], slots[hi]

if from.count <= 0 then
lo = lo + 1
else
local moved = inv.push(from.device, to.device, from.slot,
from.count, to.slot)
result.calls = result.calls + 1

if not moved or moved == 0 then





hi = hi - 1
else
from.count = from.count - moved
to.count = to.count + moved
result.merged = result.merged + moved
index.consumed(from.device, from.slot, moved)
index.drop(to.device)

if from.count <= 0 then
result.slotsFreed = result.slotsFreed + 1
lo = lo + 1
end
end

if result.calls % YIELD_EVERY == 0 then sleep(0) end
end
end
end
end

return result
end


function store.drain(from, to)
local manifest, err = store.manifest(from)
if not manifest then return nil, err end

local drained = {}
for key, count in pairs(manifest) do
local moved = store.move(from, to, key, count)
if moved > 0 then
local name = store.parse(key)
drained[name] = (drained[name] or 0) + moved
end
end
return drained
end






store.bind = mount.bind
store.unbind = mount.unbind
store.declare = mount.declare
store.mounts = mount.all
store.list = mount.list
store.volumes = mount.volumes
store.isBound = mount.isBound
store.unclaimed = mount.unclaimed
store.pathOf = mount.pathOf
store.valid = mount.valid

return store
]],
["mfg/storage/mount.lua"] = [[











local state = require("mfg.common.state")
local hal = require("mfg.common.hal")

local mount = {}

local STATE_FILE = "mounts"








local SEGMENT = "^[a-z0-9_%-]+$"

mount.EXCLUSIVE = "exclusive"
mount.RELAYED = "relayed"






mount.VOLUME = "volume"
mount.KINDS = {volume = true, level = true, flag = true}
mount.FACES = {top = true, bottom = true, left = true, right = true,
front = true, back = true}

function mount.kindOf(record)
return record and record.kind or mount.VOLUME
end

function mount.isSignal(record)
local kind = mount.kindOf(record)
return kind == "level" or kind == "flag"
end

function mount.valid(path)
if type(path) ~= "string" then return false end
if path:sub(1, 1) ~= "/" then return false end
if #path < 2 then return false end
if path:sub(-1) == "/" then return false end
if path:find("//", 1, true) then return false end

for segment in path:gmatch("[^/]+") do
if not segment:match(SEGMENT) then return false end
end
return true
end

function mount.all()
local records = state.read(STATE_FILE, {})
if type(records) ~= "table" then return {} end
return records
end

function mount.get(path)
return mount.all()[path]
end






function mount.list(prefix, kind)
local out = {}
for path, record in pairs(mount.all()) do
if not prefix or prefix == "/" or path == prefix
or path:sub(1, #prefix + 1) == prefix .. "/" then
if not kind or (kind == "signal") == mount.isSignal(record) then
out[#out + 1] = path
end
end
end
table.sort(out)
return out
end



function mount.volumes(prefix)
return mount.list(prefix, mount.VOLUME)
end





local function conflict(path, records)
for existing in pairs(records) do
if existing ~= path then
if existing:sub(1, #path + 1) == path .. "/" then
return existing .. " is already bound below " .. path
end
if path:sub(1, #existing + 1) == existing .. "/" then
return existing .. " is already bound above " .. path
end
end
end
return nil
end







function mount.declare(path, opts)
opts = opts or {}
if not mount.valid(path) then
return nil, "not a valid mount path: " .. tostring(path)
end

local records = mount.all()
local clash = conflict(path, records)
if clash then return nil, clash end

local existing = records[path]
local function keep(field)
if opts[field] ~= nil then return opts[field] end
return existing and existing[field]
end

local kind = keep("kind")
if kind ~= nil and not mount.KINDS[kind] then
return nil, ("not a kind of port: %s"):format(tostring(kind))
end


local kept = existing
if existing and mount.isSignal(existing) ~= mount.isSignal({kind = kind}) then
kept = nil
end

records[path] = {
path = path,
node = keep("node"),
role = keep("role"),
devices = kept and kept.devices or {},
coherence = keep("coherence") or mount.RELAYED,
position = keep("position"),
bound = kept and kept.bound,
by = kept and kept.by,



kind = kind,
direction = keep("direction"),
safe = keep("safe"),
machine = keep("machine"),
script = keep("script"),
face = kept and kept.face,
slots = kept and kept.slots,
via = kept and kept.via,
}
state.write(STATE_FILE, records)
return records[path]
end

local function parentOf(path)
return path:match("^(.*)/[^/]+$") or ""
end




local function shareConflict(path, device, slots, records)
for other, record in pairs(records) do
if other ~= path and not mount.isSignal(record) then
for _, held in ipairs(record.devices or {}) do
if held == device then
if not slots or not record.slots then
return ("%s is already bound to %s"):format(device, other)
end
if parentOf(other) ~= parentOf(path) then
return ("%s is already bound to %s, another machine's")
:format(device, other)
end
local mine = {}
for _, slot in ipairs(slots) do mine[slot] = true end
for _, slot in ipairs(record.slots) do
if mine[slot] then
return ("slot %d of %s is already bound to %s")
:format(slot, device, other)
end
end
end
end
end
end
return nil
end


local function cleanSlots(given)
local slots, seen = {}, {}
for _, slot in ipairs(given) do
if type(slot) ~= "number" or slot < 1 or math.floor(slot) ~= slot then
return nil, "slots are whole numbers from 1, not " .. tostring(slot)
end
if not seen[slot] then
slots[#slots + 1] = slot
seen[slot] = true
end
end
if #slots == 0 then return nil, "no slots given" end
table.sort(slots)
return slots
end







function mount.bind(path, devices, opts)
opts = opts or {}
if type(devices) == "string" then devices = {devices} end
if type(devices) ~= "table" or #devices == 0 then
return nil, "bind needs at least one device"
end

local existing = mount.get(path)
local signal = mount.isSignal({kind = opts.kind or (existing and existing.kind)})


if signal then
if #devices ~= 1 then return nil, "a signal binds to one device" end
if not mount.FACES[opts.face or ""] then
return nil, ("a signal needs a face -- top, bottom, left, right, front "
.. "or back -- not %s"):format(tostring(opts.face))
end
if opts.slots then return nil, "a signal has no slots" end
elseif opts.face then
return nil, ("%s is a volume, and a volume has no face"):format(path)
end


local slots = nil
if opts.slots then
if #devices ~= 1 then return nil, "a slot-scoped volume has one device" end
local why
slots, why = cleanSlots(opts.slots)
if not slots then return nil, why end
end

if not signal then
local records = mount.all()
for _, device in ipairs(devices) do
local clash = shareConflict(path, device, slots, records)
if clash then return nil, clash end
end
end

local declared, err = mount.declare(path, opts)
if not declared then return nil, err end

local records = mount.all()
local record = records[path]
record.devices = {}
for _, device in ipairs(devices) do record.devices[#record.devices + 1] = device end
record.face = signal and opts.face or nil
record.slots = slots
record.via = (not signal) and opts.via or nil
record.bound = os.epoch("utc")
record.by = opts.by or "manual"
state.write(STATE_FILE, records)
return record
end



function mount.unbind(path)
local records = mount.all()
local record = records[path]
if not record then return false, "not bound: " .. tostring(path) end
if record.machine then
record.devices, record.face, record.slots, record.via = {}, nil, nil, nil
record.bound, record.by = nil, nil
else
records[path] = nil
end
state.write(STATE_FILE, records)
return true
end



function mount.forget(path)
local records = mount.all()
if not records[path] then return false, "no such point: " .. tostring(path) end
records[path] = nil
state.write(STATE_FILE, records)
return true
end

function mount.isBound(path)
local record = mount.get(path)
return record ~= nil and #record.devices > 0
end








function mount.devices(path)
local record = mount.get(path)
if not record then return nil, nil, "not bound: " .. tostring(path) end


local backend = mount.isSignal(record) and hal.redstone() or hal.inventory()
local present, missing = {}, {}
for _, device in ipairs(record.devices) do
if backend.isPresent(device) then
present[#present + 1] = device
else
missing[#missing + 1] = device
end
end
return present, missing
end


function mount.claimed()
local claimed = {}
for _, record in pairs(mount.all()) do
for _, device in ipairs(record.devices) do claimed[device] = record.path end
end
return claimed
end







function mount.unclaimed()
local inv = hal.inventory()
local claimed = mount.claimed()
local out = {}
for _, device in ipairs(inv.names()) do
if not claimed[device] then out[#out + 1] = device end
end
table.sort(out)
return out
end



function mount.pathOf(device)
return mount.claimed()[device]
end

function mount.holders(device)
local out = {}
for path, record in pairs(mount.all()) do
for _, held in ipairs(record.devices or {}) do
if held == device then out[#out + 1] = path end
end
end
table.sort(out)
return out
end

return mount
]],
["mfg/storage/probe.lua"] = [[
























local mount = require("mfg.storage.mount")
local store = require("mfg.storage")
local hal = require("mfg.common.hal")

local probe = {}




local ROLE_BY_SIDE = {front = "input", top = "input", bottom = "output"}

local DEFAULT_SETTLE = 8
local POLL = 0.5

local function countIn(counts, marker)
if type(counts) ~= "table" then return 0 end
return counts[marker] or 0
end










function probe.markerIsClear(marker, candidates, source)
for _, path in ipairs(mount.volumes()) do
if mount.isBound(path) and path ~= source then
local n = store.count(path, marker)
if n and n > 0 then
return false, ("%s already holds %d %s"):format(path, n, marker)
end
end
end

local inv = hal.inventory()
for _, device in ipairs(candidates or {}) do
local listing = inv.list(device)
for _, stack in pairs(listing or {}) do
if stack.name == marker then
return false, ("%s already holds %s"):format(device, marker)
end
end
end
return true
end







local function pushMarker(source, device, marker)
local view = store.locate(marker)
local from = nil
for _, entry in ipairs(view) do
if entry.path == source then from = entry end
end
if not from then
return false, ("%s holds no %s to probe with"):format(source, marker)
end

local present = mount.devices(source)
local inv = hal.inventory()

for _, sourceDevice in ipairs(present or {}) do
local listing = inv.list(sourceDevice)
for slot, stack in pairs(listing or {}) do
if stack.name == marker then
local n, err = inv.push(sourceDevice, device, slot, 1)
if n and n > 0 then return true end
if err then return false, tostring(err) end
end
end
end
return false, "could not move a marker"
end


local function recoverFrom(device, marker, into)
local inv = hal.inventory()
local present = mount.devices(into)
if not present or #present == 0 then return 0 end

local listing = inv.list(device)
local recovered = 0
for slot, stack in pairs(listing or {}) do
if stack.name == marker then
for _, target in ipairs(present) do
if recovered == 0 then
local n = inv.push(device, target, slot, stack.count)
if n and n > 0 then recovered = recovered + n end
end
end
end
end
return recovered
end






local function await(observe, marker, settle)
local started = os.epoch("utc")
local deadline = started + settle * 1000

repeat
local seen, err = observe()
if seen then
local elapsed = (os.epoch("utc") - started) / 1000

for side, counts in pairs(seen.sides or {}) do
if countIn(counts, marker) > 0 and ROLE_BY_SIDE[side] then
return {where = "side", side = side,
role = ROLE_BY_SIDE[side], elapsed = elapsed}
end
end

if countIn(seen.held, marker) > 0 then
return {where = "held", role = "input", elapsed = elapsed,
transit = elapsed}
end
elseif err then
return nil, tostring(err)
end
sleep(POLL)
until os.epoch("utc") >= deadline

return nil
end














function probe.identify(opts)
opts = opts or {}
local marker = opts.marker
local source = opts.source
local observe = opts.observe
local settle = opts.settle or DEFAULT_SETTLE

if not marker then return nil, "a marker item is required" end
if not source then return nil, "a marker source volume is required" end
if type(observe) ~= "function" then return nil, "an observe function is required" end

local candidates = opts.candidates or mount.unclaimed()
if #candidates == 0 then return nil, "no unclaimed inventories to probe" end

local clear, why = probe.markerIsClear(marker, candidates, source)
if not clear then return nil, why end

local found = {input = nil, output = nil, transit = nil}
local tried = {}

for _, device in ipairs(candidates) do
if found.input and found.output then break end

local pushed, pushErr = pushMarker(source, device, marker)
if not pushed then return nil, pushErr end

local seen, obsErr = await(observe, marker, settle)
if obsErr then
recoverFrom(device, marker, source)
return nil, obsErr
end

tried[#tried + 1] = device

if seen and seen.where == "side" then

found[seen.role] = found[seen.role] or device
local back = recoverFrom(device, marker, source)
if back < 1 then
return nil, ("marker unaccounted for in %s -- refusing to bind on "
.. "a guess (S7.14)"):format(device)
end

elseif seen and seen.where == "held" then



found.input = found.input or device
found.transit = seen.transit

if type(opts.emit) ~= "function" then
return nil, ("marker reached the node but no emit function was "
.. "given, so it cannot be recovered -- refusing (S7.14)")
end
local emitted, emitErr = opts.emit(marker)
if not emitted then
return nil, ("node could not return the marker: %s")
:format(tostring(emitErr))
end





local landed = probe.findMarker(marker, candidates, device)
if not landed then
return nil, ("the node reported emitting the marker and it was not "
.. "found anywhere else -- refusing to bind on a guess (S7.14)")
end
found.output = found.output or landed
local back = recoverFrom(landed, marker, source)
if back < 1 then
return nil, ("marker unaccounted for in %s (S7.14)"):format(landed)
end

else

local back = recoverFrom(device, marker, source)
if back < 1 then
return nil, ("marker left %s unaccounted for (S7.14)"):format(device)
end
end
end

found.tried = tried
if not found.input and not found.output then
return nil, "probed every candidate and the node saw nothing"
end
return found
end






function probe.findMarker(marker, candidates, except)
local inv = hal.inventory()
for _, device in ipairs(candidates or {}) do
if device ~= except then
local listing = inv.list(device)
for _, stack in pairs(listing or {}) do
if stack.name == marker then return device end
end
end
end
return nil
end






function probe.bind(nodeId, opts)
opts = opts or {}
local inPath = ("/%s/in"):format(nodeId)
local outPath = ("/%s/out"):format(nodeId)

for _, path in ipairs({inPath, outPath}) do
if not mount.get(path) then
return nil, ("%s is not declared -- register the node first"):format(path)
end
end

local found, err = probe.identify(opts)
if not found then return nil, err end

local bound = {}
if found.input then
local ok, bindErr = mount.bind(inPath, {found.input},
{node = nodeId, role = "input", by = "probe"})
if not ok then return nil, bindErr end
bound[inPath] = found.input
end
if found.output then
local ok, bindErr = mount.bind(outPath, {found.output},
{node = nodeId, role = "output", by = "probe"})
if not ok then return nil, bindErr end
bound[outPath] = found.output
end

return {bound = bound, transit = found.transit, tried = found.tried,
unbound = (not found.input and inPath) or (not found.output and outPath)}
end

return probe
]],
["mfg/tools/docpreview.lua"] = [[

















if not package.path:find("^/%?") then
package.path = "/?.lua;/?/init.lua;" .. package.path
end

local doc = require("mfg.hmi.doc")

local args = {...}
local opts = {}
local i = 1
while i <= #args do
local a = args[i]
if a == "--term" then opts.term = true
elseif a == "--mono" then opts.mono = true
elseif a == "--scale" then opts.scale = tonumber(args[i + 1]) i = i + 1
elseif a == "--size" then
local w, h = tostring(args[i + 1]):match("^(%d+)x(%d+)$")
if w then opts.width, opts.height = tonumber(w), tonumber(h) end
i = i + 1
end
i = i + 1
end



local PALETTE = {
text = colours.white, title = colours.white, label = colours.lightGrey,
dim = colours.grey, good = colours.lime, warn = colours.yellow,
bad = colours.red, stale = colours.grey, action = colours.lightBlue,
selected = colours.white, flow = colours.grey,
}

local screen, what = term.current(), "terminal"
if not opts.term then
for _, name in ipairs(peripheral.getNames()) do
if peripheral.getType(name) == "monitor" then
screen = peripheral.wrap(name)
what = name
break
end
end
end

if opts.scale and screen.setTextScale then
pcall(screen.setTextScale, opts.scale)
end

local sw, sh = screen.getSize()
local width = opts.width or sw
local height = opts.height or sh
local colour = screen.isColour and screen.isColour() or false
if opts.mono then colour = false end



local function sample(w)
return doc.stack({
doc.row({
doc.text("DOCPREVIEW", {colour = "title", keep = doc.REQUIRED}),
doc.gap(2),
doc.text(("%dx%d"):format(w, height), {colour = "label", keep = 7}),
doc.spacer(),
doc.text(colour and "COLOUR" or "MONO",
{colour = colour and "good" or "warn", keep = 6, name = "mode"}),
}, {keep = doc.REQUIRED}),
doc.rule({keep = 9}),


doc.row({
doc.text("text", {colour = "text"}), doc.gap(1),
doc.text("title", {colour = "title"}), doc.gap(1),
doc.text("label", {colour = "label"}), doc.gap(1),
doc.text("dim", {colour = "dim"}), doc.gap(1),
doc.text("stale", {colour = "stale"}),
}, {keep = 8}),
doc.row({
doc.text("good", {colour = "good"}), doc.gap(1),
doc.text("warn", {colour = "warn"}), doc.gap(1),
doc.text("bad", {colour = "bad"}), doc.gap(1),
doc.text("action", {colour = "action"}),
}, {keep = 8}),
doc.rule({keep = 5}),


doc.field{label = "nodes", value = "3", keep = 7},
doc.field{label = "stock", value = "1204", leader = ".", keep = 7},
doc.rule({keep = 4}),


doc.table{
columns = {
{head = "NODE", width = 9},
{head = "STATE", width = 9},
{head = "QTY", width = 5, align = "right"},
},
rows = {
{"t1", {value = "crafting", colour = "good"}, 64},
{"t2", {value = "faulted", colour = "bad"}, 0},
{"builder1", {value = "idle", colour = "stale"}, 12},
},
keep = 6,
},
doc.rule({keep = 3}),
doc.row({
doc.text("[ORDERS]", {colour = "action", keep = 2}),
doc.gap(1),
doc.text("[ALARMS]", {colour = "action", keep = 2}),
doc.spacer(),
doc.text("[QUIT]", {colour = "action", keep = 1, name = "quit"}),
}, {keep = 2}),
})
end



local grid, report = doc.render(sample(width), width, height,
{colour = colour})

screen.setBackgroundColour(colours.black)
screen.setTextColour(colours.white)
screen.clear()

if not grid then
screen.setCursorPos(1, 1)
screen.setTextColour(colours.red)
screen.write("layout failed")
screen.setCursorPos(1, 2)
screen.setTextColour(colours.white)
screen.write(doc.explain(report))
else
for y = 1, grid.height do
for _, run in ipairs(grid.rows[y] or {}) do
screen.setCursorPos(run.x, y)
screen.setTextColour(colour and (PALETTE[run.colour] or colours.white)
or colours.white)
screen.write(run.text)
end
end
end



if screen ~= term.current() then
print(("docpreview -> %s"):format(what))
print(("  screen %dx%d, rendered at %dx%d"):format(sw, sh, width, height))
print(("  colour: %s%s"):format(tostring(colour),
opts.mono and "  (forced mono)" or ""))
if screen.getTextScale then
print(("  text scale: %s"):format(tostring(screen.getTextScale())))
end
else


term.setCursorPos(1, math.min(height, sh))
end

print(("  fitting: %s"):format(doc.explain(report)))
if grid and #report.dropped > 0 then
print("  ^ dropped elements are EXPECTED on a small screen -- that is T4.3")
end
]],
["mfg/tools/mfgctl.lua"] = [=[























if not package.path:find("^/%?") then
package.path = "/?.lua;/?/init.lua;" .. package.path
end

local recipes = require("mfg.controller.recipes")
local dispatch = require("mfg.controller.dispatch")
local supervisor = require("mfg.controller.supervisor")
local turtles = require("mfg.controller.turtles")
local store = require("mfg.storage")
local cli = require("mfg.storage.cli")
local probe = require("mfg.storage.probe")
local custody = require("mfg.storage.custody")
local state = require("mfg.common.state")
local pointlist = require("mfg.common.points")

local args = {...}
local cmd = args[1]






local function source()
local cfg = state.read("cluster", {})
return cfg.source or require("mfg.common.config").setting("source")
end

local function marker()
local cfg = state.read("cluster", {})
return cfg.marker or "minecraft:name_tag"
end

local function requireSource()
local path = source()
if not store.isBound(path) then
printError(path .. " is not bound to any device")
print("run: mfgctl bind " .. path .. " <device...>")
print("list candidates with: mfgctl peripherals")
return nil
end
return path
end



local function usage()
textutils.pagedPrint(table.concat({
"mfgctl turtles | recipes | stock",
"mfgctl bind <path> <device...>  attach devices to a mount point",
"mfgctl unbind <path>",
"mfgctl bindings               the mount table",
"mfgctl unclaimed              inventories no mount point owns",
"mfgctl store <path>           one volume in detail",
"mfgctl defrag <path>          merge fragmented stacks",
"mfgctl orders | order-show <id>",
"mfgctl receive <id> | deliver <id> | settle <id> | cancel <id>",
"mfgctl custody <item>         physical vs spendable",
"mfgctl probe <id>             discover a node's storage",
"mfgctl marker [<item>]        the probe's marker item",
"mfgctl pool <name...>         alias for bind /pool",
"mfgctl peripherals            what is on the wired network",
"mfgctl register <id> <host> [<input> <output>]",
"mfgctl label <id> [<label>]   assign the node its identity",
"mfgctl recover <id>           climb the fix ladder",
"mfgctl plan <recipe|item> <qty>  dry run",
"mfgctl mint <name> [--role turtle|builder|station|hmi]",
"mfgctl clear-fault <id>",
"mfgctl role <node> <role>     decide what a node should be",
"mfgctl config <node> [<setting> [<value>]]  show, set or clear",
"mfgctl publish <role>         check and sign a role's firmware",
"mfgctl bind --script <file> /<machine> [<inventory>]",
"mfgctl script check|load <file> | forget <script> | scripts",
"mfgctl machine enable|disable|forget|show <machine> | machines",
"mfgctl machine limit <machine> <item> <at> [resume <n>] | off",
"mfgctl signals                every signal port",
"mfgctl signal <path> [<level> | pulse <ticks> | release]",
}, "\n"))
end




local function operatorInvoke(name, params)
local actions = require("mfg.common.actions")
if not actions.get or not actions.get(name) then actions.load("controller") end
return actions.invoke(name, params, {by = "mfgctl", operator = "console"})
end




local function scriptFile(path)
if not path or not fs.exists(shell.resolve(path)) then
printError("no such file: " .. tostring(path))
return nil
end
local handle = fs.open(shell.resolve(path), "r")
local text = handle.readAll()
handle.close()
return text
end


local function problems(list, label, toError)
for _, p in ipairs(list or {}) do
local line = ("  %s line %s:%s  %s"):format(label, tostring(p.line),
tostring(p.col), p.message)
if toError then printError(line) else print(line) end
end
end


local function footprint(f)
if not f then return end
local function list(name, values)
if values and #values > 0 then
print(("  %-9s %s"):format(name, table.concat(values, ", ")))
end
end
list("supplies", f.supplies)
list("writes", f.writes)
list("collects", f.collects)
list("drives", f.drives)
end


local function loadScript(path)
local source = scriptFile(path)
if not source then return nil end
local status, fields = operatorInvoke("register_script", {source = source})
if status ~= "completed" then
problems(fields and fields.errors, "error", true)
if not (fields and fields.errors) then printError(tostring(fields and fields.reason)) end
return nil
end
problems(fields.warnings, "warning")
print(("script %s, revision %d%s"):format(fields.script, fields.rev,
#fields.machines > 0 and ("; followed by " .. table.concat(fields.machines, ", "))
or ""))
for machine, why in pairs(fields.problems or {}) do
printError(("  %s could not be refitted: %s"):format(machine, tostring(why)))
end
return fields.script
end



local function bindScript(args)
local file, path, device = args[3], args[4], args[5]
if not file or not path or path:sub(1, 1) ~= "/" then
printError("usage: mfgctl bind --script <file> /<machine> [<inventory>]")
return
end
local script = loadScript(file)
if not script then return end
local machine = path:sub(2)
local status, fields = operatorInvoke("add_machine", {machine = machine,
script = script, device = device})
if status ~= "completed" then printError(tostring(fields and fields.reason)) return end
print(("machine %s, made from %s"):format(path, script))
for _, bound in ipairs(fields.bound or {}) do print("  bound " .. bound) end
if fields.unbound and #fields.unbound > 0 then
print("still to bind:")
for _, port in ipairs(fields.unbound) do
print(("  mfgctl bind %s <device> ..."):format(port))
end
end
print(("then: mfgctl machine enable %s"):format(machine))
end

if cmd == nil or cmd == "help" then
usage()

elseif cmd == "peripherals" then



local found = 0
