source = from,
observe = function()
local observed, answer = turtles.observe(turtle,
{timeout = 3, attempts = 2})
if observed then return observed end





if answer and answer.status == "rejected" then
return nil, ("%s rejected probe_observe: %s"):format(id,
tostring(answer.reason or "unknown command"))
end
return nil
end,
emit = function(item)
return turtles.emitMarker(turtle, item, {timeout = 4, attempts = 2})
end,
})
if not found then printError(tostring(err)) return end

for path, device in pairs(found.bound) do
