["mfg/turtle/nav.lua"] = [[














local schematic = require("mfg.turtle.schematic")
local odometry = require("mfg.turtle.odometry")

local nav = {}

local map = nil

function nav.use(loaded)
map = loaded
return map
end

function nav.map()
return map
end







function nav.at()
if not map then return nil end
local here = odometry.position()

for name, entry in pairs(map.places) do
if entry.stand and schematic.same(entry.stand, here) then
return name, "stand"
end
end
for name, entry in pairs(map.places) do
if entry.approach and schematic.same(entry.approach, here) then
return name, "approach"
end
end
return nil
end






local function findRoute(from, to)
if from == to then return {from} end

local seen = {[from] = true}
local queue = {{from}}
local head = 1

while head <= #queue do
local path = queue[head]
head = head + 1
local last = path[#path]

local neighbours = {}
for target in pairs(map.corridors[last] or {}) do
neighbours[target] = true
end


for source, targets in pairs(map.corridors) do
if targets[last] then neighbours[source] = true end
end

for neighbour in pairs(neighbours) do
if not seen[neighbour] then
seen[neighbour] = true
local extended = {}
for _, step in ipairs(path) do extended[#extended + 1] = step end
extended[#extended + 1] = neighbour
if neighbour == to then return extended end
queue[#queue + 1] = extended
end
end
end

return nil
end



local function cellsFor(hops)
local cells, floors = {}, {}

for i = 2, #hops do
local waypoints, floor = schematic.route(map, hops[i - 1], hops[i])
if not waypoints then
return nil, ("no corridor between %s and %s"):format(hops[i - 1], hops[i])
end

local expanded, why = schematic.expand(waypoints)
if not expanded then return nil, why end

for _, cell in ipairs(expanded) do


local previous = cells[#cells]
if not (previous and schematic.same(previous, cell)) then
cells[#cells + 1] = cell
floors[#cells] = floor
end
end
end

return cells, floors
end













function nav.travel(cells, floors)
if not cells or #cells == 0 then return false, "nothing to travel" end

for index, cell in ipairs(cells) do
local here = odometry.position()

if not schematic.same(here, cell) then
local direction = schematic.directionFrom(here, cell)
if not direction then



odometry.distrust("route stepped to a non-adjacent cell")
return false, ("cannot step from %d,%d,%d to %d,%d,%d -- not adjacent")
:format(here.x, here.y, here.z, cell.x, cell.y, cell.z)
end

local moved, why = odometry.go(direction)
if not moved then
return false, ("blocked at cell %d of %d: %s"):format(index,
#cells, tostring(why))
end
end

local expected = floors and floors[index]
if expected then
local under = odometry.floor()
if under ~= expected then


odometry.distrust("floor did not match the corridor")
return false, ("off path at %d,%d,%d: floor is %s, corridor declares %s")
:format(cell.x, cell.y, cell.z, tostring(under), expected)
end
end
end

return true
end



local function plan(destination)
if not map then return nil, "no schematic loaded" end



if not odometry.trusted() then
return nil, "position is untrusted -- re-localise before planning a route"
end

local here = nav.at()
if not here then
local p = odometry.position()
return nil, ("not at a named place (%d,%d,%d) -- routes run between declared "
.. "places"):format(p.x, p.y, p.z)
end

local hops = findRoute(here, destination)
if not hops then
return nil, ("no declared corridor route from %s to %s"):format(here,
destination)
end
return hops
end

nav.plan = plan


function nav.goto(name)
local target, why = schematic.standAt(map, name)
if not target then return false, why end

local hops, planErr = plan(name)
if not hops then return false, planErr end

local cells, floors = cellsFor(hops)
if cells then
local travelled, travelErr = nav.travel(cells, floors)
if not travelled then return false, travelErr end
end



local here = odometry.position()
if not schematic.same(here, target) then
local direction = schematic.directionFrom(here, target)
if not direction then
return false, ("arrived at %d,%d,%d, which is not beside %s")
:format(here.x, here.y, here.z, name)
end
local moved, moveErr = odometry.go(direction)
if not moved then return false, moveErr end
end

return true
end



function nav.approach(name)
local target, facing = schematic.approachTo(map, name)
if not target then return false, facing end

local hops, planErr = plan(name)
if not hops then return false, planErr end

local cells, floors = cellsFor(hops)
if cells then
local travelled, travelErr = nav.travel(cells, floors)
if not travelled then return false, travelErr end
end

local here = odometry.position()
if not schematic.same(here, target) then
return false, ("route ended at %d,%d,%d, not at %s's approach %d,%d,%d")
:format(here.x, here.y, here.z, name, target.x, target.y, target.z)
end

local turned, turnErr = odometry.face(facing)
if not turned then return false, turnErr end
return true
end












local function fixFrom(side, label)
local candidates = schematic.landmarkCells(map, label)
if not candidates then return nil end

local viable, seen = {}, {}
for _, candidate in ipairs(candidates) do
local deduced = odometry.deduce(side, candidate.cell)
if deduced then


local options = deduced.position and {deduced} or deduced
for _, option in ipairs(options) do
local facing = option.facing or odometry.facing()
if schematic.navigable(map, option.position) then
local mark = schematic.key(option.position.x, option.position.y,
option.position.z) .. "/" .. tostring(facing)
if not seen[mark] then
seen[mark] = true
viable[#viable + 1] = {position = option.position,
facing = facing, what = candidate.what}
end
end
end
end
end

if #viable ~= 1 then return nil end
return viable[1]
end


local function scanOnce()
for side, peer in pairs(odometry.neighbours()) do
local fix = fixFrom(side, peer.label)
if fix then
odometry.fix(fix.position, fix.facing,
("landmark %s (%s) on %s"):format(peer.label, fix.what, side))
return true, "fixed by " .. peer.label
end
end
return false
end





function nav.relocalise(opts)
opts = opts or {}
if not map then return false, "no schematic loaded" end
if odometry.trusted() then return true, "already trusted" end



for _ = 1, 4 do
local fixed, how = scanOnce()
if fixed then return true, how end
odometry.face(schematic.right(odometry.facing()))
end







local floors = opts.floors or {}
local steps = opts.search or 8

if opts.direction and floors.expected then
for _ = 1, steps do
local under = odometry.floor()
if under ~= floors.expected then


return false, ("off path: floor is %s, expected %s"):format(
tostring(under), floors.expected)
end

local moved = odometry.go(opts.direction)
if not moved then break end

local fixed, how = scanOnce()
if fixed then return true, how end
end
end


return false, "no landmark found -- stopped rather than searching blind"
end

return nav
]],
["mfg/turtle/node.lua"] = [[















local hal = require("mfg.common.hal")
local state = require("mfg.common.state")
local pattern = require("mfg.common.pattern")
local journal = require("mfg.common.actions.journal")
local pointlist = require("mfg.common.points")
local bootinfo = require("mfg.common.bootinfo")
local equipment = require("mfg.common.equipment")

local node = {}

local STATE_FILE = "turtle"







node.IDLE = "idle"
node.FAULTED = "faulted"

local current = nil

local function fresh()
return {
state = node.IDLE,




pattern = nil,
pattern_id = nil,
fault = nil,
heartbeat = os.epoch("utc"),
}
end











local STATE_OPTS = {schema = 1, migrate = function(value) return value end}

function node.load()
local why
current, why = state.read(STATE_FILE, nil, STATE_OPTS)
if type(current) ~= "table" then
current = fresh()
if why then
current.state = node.FAULTED
current.fault = "persisted state refused: " .. why
end
end
return current
end











node.POINTS_VERSION = pointlist.VERSION

function node.points()
if not current then node.load() end
current.heartbeat = os.epoch("utc")
local hw = hal.turtle()



local boot = bootinfo.points()
return {
points_version = node.POINTS_VERSION,
firmware = boot.firmware,
config_rev = boot.config_rev,
boot_state = boot.boot_state,
equipment_missing = boot.equipment_missing,
state = current.state,
fault = current.fault,
heartbeat = current.heartbeat,











pattern_id = current.pattern_id,
fuel = hw.fuelLevel(),





held = hw.held and hw.held() or nil,
feed = hw.feedMode and hw.feedMode() or nil,
}
end






function node.observe()
local hw = hal.turtle()
return {
held = hw.held and hw.held() or {},
sides = hw.adjacent and hw.adjacent() or {},
feed = hw.feedMode and hw.feedMode() or nil,
}
end







function node.emitMarker(marker)
if not marker then return false, "no marker item named" end
if node.state() ~= node.IDLE then
return false, "not idle: " .. tostring(node.state())
end

local hw = hal.turtle()




if hw.hasOutput and not hw.hasOutput() then
return false, "nothing to drop into BELOW -- refusing to drop into the world"
end

for slot, stack in pairs(hw.slots()) do
if stack.name == marker then
hw.select(slot)
if hw.dropOutput(1) then return true end
return false, "the inventory below would not take it"
end
end
return false, ("not holding %s"):format(tostring(marker))
end

local function persist()
state.write(STATE_FILE, current, STATE_OPTS)
end

local function setState(name, fault)
current.state = name
current.fault = fault
persist()
end

function node.state()
if not current then node.load() end
return current.state
end






function node.selfCheck()
local hw = hal.turtle()
local problems = {}

if hw.hasInput and not hw.hasInput() then
problems[#problems + 1] =
"nothing to pull from in FRONT -- the input chest goes there"
end
if hw.hasOutput and not hw.hasOutput() then
problems[#problems + 1] =
"nothing to drop into BELOW -- the output chest goes there"
end

local fuel = hw.fuelLevel()
if fuel ~= "unlimited" and fuel == 0 then
problems[#problems + 1] = "out of fuel"
end





local seen = hw.surroundings and hw.surroundings() or {}
local fitted, unread = equipment.read(hw)
if fitted then
local doc = require("mfg.common.config").current()
local required = doc and doc.equipment or require("mfg.common.roles").turtle.equipment
seen.equipment = fitted
seen.missing = equipment.missing(required, fitted)
for _, id in ipairs(seen.missing) do
problems[#problems + 1] = "not fitted: " .. id
end
else
problems[#problems + 1] = "cannot read equipment: " .. tostring(unread)
end

return #problems == 0, problems, seen
end



function node.clearFault()
if not current then node.load() end
if current.state ~= node.FAULTED then return false, "not faulted" end
setState(node.IDLE, nil)
return true
end
















function node.reconcile()
if not current then node.load() end

local last = journal.recent(1)[1]
if not last then return true end

local hw = hal.turtle()
local held = 0
for _, stack in pairs(hw.slots()) do held = held + stack.count end
if held == 0 then return true end

local exposed = false
if last.action == "pattern_fill" or last.action == "craft" then
exposed = last.status == "completed"
elseif last.action == "deposit" then
exposed = last.status ~= "completed"
end
if not exposed then return true end

local discrepancy = ("restarted after %s %s, holding %d item(s) -- "
.. "product or an arrangement, and nothing here can say which")
:format(last.action, tostring(last.status), held)

setState(node.FAULTED, discrepancy)
return false, discrepancy
end


























function node.fill(opts)
opts = opts or {}
if not current then node.load() end

local hw = hal.turtle()
if hw.hasInput and not hw.hasInput() then
return false, "nothing to pull from in FRONT -- the input chest goes there"
end

local pulled = 0
for _ = 1, opts.maxCalls or 32 do
if not hw.suckInput() then break end
pulled = pulled + 1
end

return true, {held = pattern.totals(hw.slots()), pulled = pulled}
end

















function node.returnUnused(keep)
if not current then node.load() end

local hw = hal.turtle()
if hw.hasInput and not hw.hasInput() then
return false, "no inventory in front -- refusing to drop items into the world"
end




local allowance = {}
for item, count in pairs(keep or {}) do allowance[item] = count end

local returned = {}
for slot, stack in pairs(hw.slots()) do
local spare = stack.count
local allowed = allowance[stack.name]
if allowed then
local held = math.min(allowed, stack.count)
allowance[stack.name] = allowed - held
spare = stack.count - held
end

if spare > 0 then
hw.select(slot)
if not hw.dropInput(spare) then
return false, ("cannot return %s from slot %d"):format(
stack.name, slot)
end
returned[stack.name] = (returned[stack.name] or 0) + spare
end
end

return true, {returned = returned}
end










function node.patternFill(want, opts)
opts = opts or {}
if not current then node.load() end




















local id = opts.id
if type(id) ~= "string" or id == "" then
return false, "a pattern id is required"
end

if type(want) ~= "table" or next(want) == nil then
if current.pattern_id ~= id then
return false, ("no pattern sent for %s and the cache holds %s"):format(
id, tostring(current.pattern_id or "nothing"))
end
want = current.pattern
if type(want) ~= "table" or next(want) == nil then
return false, "no pattern sent and none cached -- the first arrangement "
.. "to a node must carry one"
end
end




local inGrid, outside = pattern.inGrid(want)
if not inGrid then return false, outside end



if current.pattern ~= want or current.pattern_id ~= id then
current.pattern = want
current.pattern_id = id
persist()
end

local hw = hal.turtle()
local before = hw.slots()
local depth, short = pattern.depth(pattern.totals(before), want,
{depth = opts.depth, stack = opts.stack})

if depth < 1 then



local why = "not enough material to fill the pattern once"
if short and short.item then
why = ("%s: holding %d, one set needs %d"):format(
short.item, short.have, short.needed)
end
return false, why, {depth = 0, short = short}
end

local target = pattern.target(want, depth)

local staging = {}
for slot = 1, 16 do
if not want[slot] then staging[#staging + 1] = slot end
end

local plan = pattern.plan(before, target, {staging = staging})

for _, move in ipairs(plan.moves) do
hw.select(move.from)
if not hw.transferTo(move.to, move.count) then
return false, ("could not move %d %s from slot %d to slot %d"):format(
move.count, move.name, move.from, move.to)
end
end



if #plan.evict > 0 then
if hw.hasInput and not hw.hasInput() then
return false, "no inventory in front -- refusing to drop leftovers into the world"
end
for _, chunk in ipairs(plan.evict) do
hw.select(chunk.slot)
if not hw.dropInput(chunk.count) then
return false, ("cannot return leftovers from slot %d"):format(
chunk.slot)
end
end
end




local after = hw.slots()
local ok, mismatch = pattern.matches(after, target)
if not ok then
return false, ("the arrangement did not take: %s"):format(tostring(mismatch))
end

return true, {depth = depth, placed = target, moves = #plan.moves,
returned = #plan.evict, pattern_id = id}
end











function node.craft()
if not current then node.load() end

local hw = hal.turtle()
local before = pattern.totals(hw.slots())
if next(before) == nil then return false, "holding nothing to craft" end

local valid, validErr = hw.craft(0)
if not valid then


return false, "rejected: " .. tostring(validErr)
end

local crafted, craftErr = hw.craft()
if not crafted then
return false, tostring(craftErr)
end

local after = pattern.totals(hw.slots())

local produced, consumed = {}, {}
for item, count in pairs(after) do
local had = before[item] or 0
if count > had then produced[item] = count - had end
end
for item, count in pairs(before) do
local left = after[item] or 0
if left < count then consumed[item] = count - left end
end

return true, {produced = produced, consumed = consumed}
end










function node.deposit()
if not current then node.load() end

local hw = hal.turtle()
if hw.hasOutput and not hw.hasOutput() then
return false, "no inventory below -- cannot deposit output"
end

local deposited = {}
for slot, stack in pairs(hw.slots()) do
hw.select(slot)
if not hw.dropOutput() then
return false, "output blocked -- cannot deposit"
end
deposited[stack.name] = (deposited[stack.name] or 0) + stack.count
end

return true, {deposited = deposited}
end

return node
]],
["mfg/turtle/odometry.lua"] = [[














local hal = require("mfg.common.hal")
local schematic = require("mfg.turtle.schematic")
local state = require("mfg.common.state")

local odometry = {}





local FILE = "/mfg/odometry"

local model = nil



local function blank()
return {x = 0, y = 0, z = 0, facing = "north", pending = nil, trusted = false}
end



local function write()
return state.writeFile(FILE, model)
end

function odometry.load()
local parsed, why = state.readFile(FILE)
if parsed == nil and not why then
model = blank()
return model
end

if type(parsed) ~= "table" then




model = blank()
return model, "unreadable odometry -- position is untrusted"
end

model = parsed




if model.pending then
model.trusted = false
end
return model
end

local function ensure()
if not model then odometry.load() end
return model
end



function odometry.position()
local m = ensure()
return {x = m.x, y = m.y, z = m.z}
end

function odometry.facing()
return ensure().facing
end

function odometry.trusted()
local m = ensure()
return m.trusted and not m.pending
end

function odometry.pending()
return ensure().pending
end



function odometry.ambiguity()
local m = ensure()
if not m.pending then return nil end
return {direction = m.pending, from = {x = m.x, y = m.y, z = m.z}}
end









function odometry.fix(position, facing, why)
local m = ensure()
if not position or not schematic.CARDINALS[facing] then
return false, "a fix needs a position and a cardinal facing"
end
m.x, m.y, m.z = position.x, position.y, position.z
m.facing = facing
m.pending = nil
m.trusted = true
m.fixedBy = why
write()
return true
end




function odometry.distrust(why)
local m = ensure()
m.trusted = false
m.why = why
write()
return true
end








function odometry.face(direction)
local m = ensure()
if not schematic.CARDINALS[direction] then
return false, ("not a cardinal direction: %s"):format(tostring(direction))
end
if m.facing == direction then return true end

local turns = schematic.turnsBetween(m.facing, direction)
local hw = hal.turtle()

if turns == -1 then
if not hw.turnLeft() then return false, "turnLeft failed" end
m.facing = schematic.left(m.facing)
else
for _ = 1, turns do
if not hw.turnRight() then return false, "turnRight failed" end
m.facing = schematic.right(m.facing)
end
end

write()
return m.facing == direction
end









function odometry.go(direction)
local m = ensure()
local hw = hal.turtle()

local vertical = (direction == "up" or direction == "down")
if not vertical then
local turned, why = odometry.face(direction)
if not turned then return false, why end
elseif not schematic.STEP[direction] then
return false, ("not a direction: %s"):format(tostring(direction))
end


m.pending = direction
write()

local moved
if vertical then
moved = (direction == "up") and hw.up() or hw.down()
else
moved = hw.forward()
end

if moved then
local delta = schematic.STEP[direction]
m.x = m.x + delta.x
m.y = m.y + delta.y
m.z = m.z + delta.z
end



m.pending = nil
write()

if not moved then
return false, ("blocked going %s"):format(direction)
end
return true
end




function odometry.reverse()
local m = ensure()
local behind = schematic.opposite(m.facing)

m.pending = behind
write()

local moved = hal.turtle().back()
if moved then
local delta = schematic.STEP[behind]
m.x = m.x + delta.x
m.y = m.y + delta.y
m.z = m.z + delta.z
end

m.pending = nil
write()

if not moved then return false, "blocked going backwards" end
return true
end








function odometry.floor()
local seen = hal.turtle().inspectDown()
if not seen then return nil end
return seen.name
end





function odometry.neighbours()
local hw = hal.turtle()
local found = {}
for _, side in ipairs({"front", "left", "right", "top", "bottom"}) do
local peer = hw.peer and hw.peer(side)
if peer and peer.label then found[side] = peer end
end
return found
end



function odometry.sideCell(side)
local m = ensure()
local here = {x = m.x, y = m.y, z = m.z}

if side == "front" then return schematic.step(here, m.facing) end
if side == "top" then return schematic.step(here, "up") end
if side == "bottom" then return schematic.step(here, "down") end
if side == "left" then return schematic.step(here, schematic.left(m.facing)) end
if side == "right" then return schematic.step(here, schematic.right(m.facing)) end
return nil
end





function odometry.deduce(side, knownCell)
if not knownCell then return nil end

if side == "top" then
return {position = schematic.step(knownCell, "down")}
end
if side == "bottom" then
return {position = schematic.step(knownCell, "up")}
end
if side ~= "front" then return nil end




local options = {}
for _, direction in ipairs({"north", "east", "south", "west"}) do
local from = schematic.step(knownCell, schematic.opposite(direction))
options[#options + 1] = {position = from, facing = direction}
end
return options
end

function odometry.reset()
model = blank()
if fs.exists(FILE) then fs.delete(FILE) end
return model
end

return odometry
]],
["mfg/turtle/rtu.lua"] = [[



















local rpc = require("mfg.common.rpc")
local node = require("mfg.turtle.node")

local rtu = {}

local COMMANDS = {}

function COMMANDS.points()
return rpc.COMPLETED, {points = node.points()}
end

function COMMANDS.stop()




return rpc.COMPLETED, {stopped = true, note = "nothing runs between requests"}
end

function COMMANDS.clear_fault()
local ok, err = node.clearFault()
if not ok then return rpc.REJECTED, {reason = tostring(err)} end
return rpc.COMPLETED, {state = node.state()}
end







function COMMANDS.probe_observe()
return rpc.COMPLETED, {observed = node.observe()}
end



function COMMANDS.probe_emit(body)
local ok, err = node.emitMarker(body.marker)
if not ok then return rpc.REJECTED, {reason = tostring(err)} end
return rpc.COMPLETED, {emitted = body.marker}
end










function COMMANDS.set_label(body)
local label = body.label
if type(label) ~= "string" or label == "" then
return rpc.REJECTED, {reason = "a label is required"}
end


if label:find("%s") then
return rpc.REJECTED, {reason = "a label cannot contain whitespace"}
end

local ok, err = pcall(os.setComputerLabel, label)
if not ok then return rpc.REJECTED, {reason = tostring(err)} end

return rpc.COMPLETED, {label = os.getComputerLabel()}
end

function rtu.handle(body, packet)
local command = body.command
local handler = COMMANDS[command]

if not handler then


print(("rejected unknown command '%s' from %s"):format(
tostring(command), tostring(packet and packet.src)))
return rpc.REJECTED, {reason = "unknown command: " .. tostring(command)}
end

return handler(body, packet)
end

return rtu
]],
["mfg/turtle/schematic.lua"] = [[
















local schematic = {}



local STEP = {
north = {x = 0, y = 0, z = -1},
south = {x = 0, y = 0, z = 1},
east = {x = 1, y = 0, z = 0},
west = {x = -1, y = 0, z = 0},
up = {x = 0, y = 1, z = 0},
down = {x = 0, y = -1, z = 0},
}

schematic.STEP = STEP

local CARDINALS = {north = true, east = true, south = true, west = true}

schematic.CARDINALS = CARDINALS


local ORDER = {"north", "east", "south", "west"}
local INDEX = {}
for i, name in ipairs(ORDER) do INDEX[name] = i end

function schematic.right(facing)
local i = INDEX[facing]
if not i then return nil end
return ORDER[(i % 4) + 1]
end

function schematic.left(facing)
local i = INDEX[facing]
if not i then return nil end
return ORDER[((i + 2) % 4) + 1]
end

function schematic.opposite(facing)
if facing == "up" then return "down" end
if facing == "down" then return "up" end
local i = INDEX[facing]
if not i then return nil end
return ORDER[((i + 1) % 4) + 1]
end



function schematic.turnsBetween(from, to)
local a, b = INDEX[from], INDEX[to]
if not a or not b then return nil end
local diff = (b - a) % 4
if diff == 3 then return -1 end
return diff
end



local function key(x, y, z)
return ("%d,%d,%d"):format(x, y, z)
end

schematic.key = key

function schematic.same(a, b)
if not a or not b then return false end
return a.x == b.x and a.y == b.y and a.z == b.z
end

function schematic.step(position, direction)
local delta = STEP[direction]
if not delta or not position then return nil end
return {x = position.x + delta.x, y = position.y + delta.y,
z = position.z + delta.z}
end

function schematic.adjacent(a, b)
if not a or not b then return false end
local dx = math.abs(a.x - b.x)
local dy = math.abs(a.y - b.y)
local dz = math.abs(a.z - b.z)
return (dx + dy + dz) == 1
end


function schematic.directionFrom(from, to)
if not schematic.adjacent(from, to) then return nil end
for name, delta in pairs(STEP) do
if from.x + delta.x == to.x and from.y + delta.y == to.y
and from.z + delta.z == to.z then
return name
end
end
return nil
end



local function words(line)
local out = {}
for word in line:gmatch("%S+") do out[#out + 1] = word end
return out
end



local function coordsAfter(tokens, from)
local x = tonumber(tokens[from + 1])
local y = tonumber(tokens[from + 2])
local z = tonumber(tokens[from + 3])
if not (x and y and z) then return nil end
return {x = x, y = y, z = z}
end







local function fail(number, line, why)
return nil, ("line %d: %s\n  %s"):format(number, why, line)
end

function schematic.parse(text)
if type(text) ~= "string" then return nil, "no schematic text" end

local map = {
name = nil,
origin = nil,
places = {},
byLabel = {},
corridors = {},
occupied = {},
}

local number = 0
for line in (text .. "\n"):gmatch("([^\n]*)\n") do
number = number + 1
local trimmed = line:gsub("#.*$", ""):gsub("^%s+", ""):gsub("%s+$", "")

if trimmed ~= "" then
local t = words(trimmed)
local kind = t[1]

if kind == "schematic" then
if not t[2] then return fail(number, line, "schematic needs a name") end
map.name = t[2]

elseif kind == "origin" then
local position = coordsAfter(t, 1)
if not position then
return fail(number, line, "origin needs x y z")
end
local facing = t[5]
if not facing or not CARDINALS[facing] then
return fail(number, line,
"origin needs a cardinal facing (north/east/south/west)")
end
map.origin = {x = position.x, y = position.y, z = position.z,
facing = facing}

elseif kind == "bay" or kind == "node" then
local name = t[2]
if not name then return fail(number, line, kind .. " needs a name") end
if map.places[name] then
return fail(number, line, "duplicate name: " .. name)
end

local entry = {name = name, kind = kind}

local i = 3
while i <= #t do
local field = t[i]

if field == "at" or field == "stand" then
local position = coordsAfter(t, i)
if not position then
return fail(number, line, field .. " needs x y z")
end
entry[field] = position
i = i + 4

elseif field == "approach" then
local position = coordsAfter(t, i)
if not position then
return fail(number, line, "approach needs x y z")
end
entry.approach = position
i = i + 4

elseif field == "facing" then
local facing = t[i + 1]
if not facing or not CARDINALS[facing] then
return fail(number, line,
"facing needs a cardinal direction")
end
entry.approachFacing = facing
i = i + 2

elseif field == "label" then
if not t[i + 1] then
return fail(number, line, "label needs a value")
end
entry.label = t[i + 1]
i = i + 2

elseif field == "modem" then
local side = t[i + 1]
if not side or not STEP[side] then
return fail(number, line,
"modem needs a side (up/down/north/...)")
end
entry.modem = side
i = i + 2

elseif field == "builder" then
entry.builder = true
i = i + 1

else
return fail(number, line, "unknown field: " .. tostring(field))
end
end




if kind == "bay" and not entry.stand then
return fail(number, line, "a bay needs `stand x y z`")
end
if kind == "node" and not entry.at then
return fail(number, line, "a node needs `at x y z`")
end
if entry.approach and not entry.approachFacing then
return fail(number, line,
"an approach needs a facing -- arriving pointed the wrong "
.. "way cannot interact with anything (W3.4)")
end

map.places[name] = entry
if entry.label then
if map.byLabel[entry.label] then
return fail(number, line,
"duplicate label: " .. entry.label)
end
map.byLabel[entry.label] = name
end


if entry.at then
map.occupied[key(entry.at.x, entry.at.y, entry.at.z)] = name
end

elseif kind == "corridor" then
local from, to = t[2], t[3]
if not (from and to) then
return fail(number, line, "corridor needs two endpoints")
end

local i = 4
local floor = nil
if t[i] == "floor" then
floor = t[i + 1]
if not floor then
return fail(number, line, "floor needs a block name")
end
i = i + 2
end


local cells = {}
local rest = {}
for j = i, #t do rest[#rest + 1] = t[j] end
local joined = table.concat(rest, " ")
for chunk in joined:gmatch("[^:]+") do
local parts = words(chunk)
local x, y, z = tonumber(parts[1]), tonumber(parts[2]),
tonumber(parts[3])
if not (x and y and z) then
return fail(number, line,
"corridor cells are `x y z : x y z`")
end
cells[#cells + 1] = {x = x, y = y, z = z}
end
if #cells == 0 then
return fail(number, line, "a corridor needs at least one cell")
end

map.corridors[from] = map.corridors[from] or {}
map.corridors[from][to] = {cells = cells, floor = floor}

else
return fail(number, line, "unknown record: " .. tostring(kind))
end
end
end

if not map.name then return nil, "no `schematic <name>` line" end
if not map.origin then return nil, "no `origin x y z facing` line" end

return map
end

function schematic.load(path)
local text, why = require("mfg.common.state").readText(path)
if not text then return nil, why or ("no schematic at " .. tostring(path)) end
return schematic.parse(text)
end



function schematic.place(map, name)
if not map then return nil end
return map.places[name]
end



function schematic.byLabel(map, label)
if not map or not label then return nil end
local name = map.byLabel[label]
if not name then return nil end
return map.places[name], name
end



function schematic.standAt(map, name)
local entry = schematic.place(map, name)
if not entry then return nil, "no such place: " .. tostring(name) end
if not entry.stand then
return nil, ("%s is a %s -- a turtle cannot stand where a block is (W3.1)")
:format(name, entry.kind)
end
return entry.stand
end


function schematic.approachTo(map, name)
local entry = schematic.place(map, name)
if not entry then return nil, "no such place: " .. tostring(name) end
if not entry.approach then
return nil, ("%s declares no approach"):format(name)
end
return entry.approach, entry.approachFacing
end












function schematic.landmarkCells(map, label)
local entry, name = schematic.byLabel(map, label)
if not entry then return nil end

local out = {}
if entry.at then
out[#out + 1] = {cell = entry.at, what = "block", place = name}
end
if entry.stand then
out[#out + 1] = {cell = entry.stand, what = "resident", place = name}
if entry.modem then
local cell = schematic.step(entry.stand, entry.modem)
if cell then
out[#out + 1] = {cell = cell, what = "modem", place = name}
end
end
end
return out, entry, name
end








function schematic.navigableCells(map)
if not map then return {} end
if map._navigable then return map._navigable end

local set = {}
for _, entry in pairs(map.places) do
if entry.stand then
set[key(entry.stand.x, entry.stand.y, entry.stand.z)] = true
end
if entry.approach then
set[key(entry.approach.x, entry.approach.y, entry.approach.z)] = true
end
end
for _, targets in pairs(map.corridors) do
for _, corridor in pairs(targets) do
for _, cell in ipairs(schematic.expand(corridor.cells) or {}) do
set[key(cell.x, cell.y, cell.z)] = true
end
end
end

map._navigable = set
return set
end

function schematic.navigable(map, cell)
if not map or not cell then return false end

if schematic.isOccupied(map, cell) then return false end
return schematic.navigableCells(map)[key(cell.x, cell.y, cell.z)] == true
end

function schematic.isOccupied(map, position)
if not map or not position then return false end
return map.occupied[key(position.x, position.y, position.z)] ~= nil
end

function schematic.corridor(map, from, to)
if not map or not map.corridors[from] then return nil end
return map.corridors[from][to]
end




function schematic.route(map, from, to)
local forward = schematic.corridor(map, from, to)
if forward then return forward.cells, forward.floor end

local back = schematic.corridor(map, to, from)
if back then
local reversed = {}
for i = #back.cells, 1, -1 do reversed[#reversed + 1] = back.cells[i] end
return reversed, back.floor
end
return nil
end




function schematic.absolute(map, position)
if not map or not map.origin or not position then return nil end
return {
x = map.origin.x + position.x,
y = map.origin.y + position.y,
z = map.origin.z + position.z,
}
end











function schematic.expand(cells)
if type(cells) ~= "table" or #cells == 0 then return nil, "no cells" end

local out = {{x = cells[1].x, y = cells[1].y, z = cells[1].z}}

for i = 2, #cells do
local from, to = cells[i - 1], cells[i]
local dx, dy, dz = to.x - from.x, to.y - from.y, to.z - from.z

local moving = 0
if dx ~= 0 then moving = moving + 1 end
if dy ~= 0 then moving = moving + 1 end
if dz ~= 0 then moving = moving + 1 end

if moving > 1 then
return nil, ("segment %d,%d,%d -> %d,%d,%d changes more than one axis; "
.. "there is no unambiguous line between them"):format(
from.x, from.y, from.z, to.x, to.y, to.z)
end

if moving == 1 then
local step = {
x = (dx > 0 and 1) or (dx < 0 and -1) or 0,
y = (dy > 0 and 1) or (dy < 0 and -1) or 0,
z = (dz > 0 and 1) or (dz < 0 and -1) or 0,
}
local cursor = {x = from.x, y = from.y, z = from.z}
while not (cursor.x == to.x and cursor.y == to.y and cursor.z == to.z) do
cursor = {x = cursor.x + step.x, y = cursor.y + step.y,
z = cursor.z + step.z}
out[#out + 1] = {x = cursor.x, y = cursor.y, z = cursor.z}
end
end
end

return out
end

function schematic.places(map)
local out = {}
for name in pairs(map and map.places or {}) do out[#out + 1] = name end
table.sort(out)
return out
end

return schematic
]],
["mfg/turtle/services.lua"] = [[
















local services = require("mfg.common.services")

local turtle = {}

function turtle.declare(manager, ctx)
local node = require("mfg.turtle.node")
node.load()

local ok, discrepancy = node.reconcile()
if not ok then
printError("restarted mid-sequence: " .. tostring(discrepancy))
printError("clear it with: mfgctl clear-fault <id>")
end



services.declare(manager, {
name = "control",
critical = true,
requires = {"netstack"},
ready = ctx.admitted,
start = function()
local net = require("net")
local actions = require("mfg.common.actions")
local rtu = require("mfg.turtle.rtu")



ctx.bind({"mfg-control", "mfg-report"})
print("serving -- state: " .. node.state())





while true do
actions.invoke("serve_control", {once = true}, {legacy = rtu.handle})
end
end,
})
end

return turtle
]],
["net.lua"] = [[















local routing = require("routing")
local netcrypt = require("netcrypt")
local netkeys = require("netkeys")
local ip = require("ip")

local net = {}

local REGISTRY = "/services"

local registry = nil
local reverse = nil

local function load()
if registry then return registry end

registry, reverse = {}, {}
if not fs.exists(REGISTRY) then return registry end

local handle = fs.open(REGISTRY, "r")
if not handle then return registry end
local data = handle.readAll()
handle.close()

for line in data:gmatch("[^\r\n]+") do

local name, port = line:match("^%s*([%w_%-]+)%s+(%d+)")
if name and not line:match("^%s*#") then
registry[name] = tonumber(port)
reverse[tonumber(port)] = name
end
end
return registry
end

function net.services()
return load()
end

function net.port(name)
return load()[name]
end

function net.nameOf(port)
load()
return reverse[port]
end


function net.reload()
registry, reverse = nil, nil
return load()
end

local function portFor(name)
if type(name) ~= "string" then
return nil, "service name must be a string"
end
local port = net.port(name)
if not port then
return nil, ("unknown service '%s' -- add it to %s"):format(name, REGISTRY)
end
return port
end




function net.serve(name)
local port, err = portFor(name)
if not port then return false, err end
return routing.bind(port)
end

function net.unserve(name)
local port = net.port(name)
if port then routing.unbind(port) end
end






function net.parseAddress(text)
return ip.parse(text)
end

function net.formatAddress(address)
return ip.format(address)
end









local function resolveName(name)
local record, err = routing.lookupName(name)
if not record then return nil, err end

local voucher = netkeys.fromHex(record.voucher or "")
if not voucher then return nil, ("no voucher for '%s'"):format(name) end



local address, pk, vouchedName = netkeys.verifyVoucher(
voucher, netkeys.decodeChain(record.chain))
if not address then return nil, "voucher rejected: " .. tostring(pk) end
if vouchedName ~= name then
return nil, ("voucher names '%s', not '%s'"):format(
tostring(vouchedName), name)
end

return address
end








local function candidates(name)
if name:find(".", 1, true) then return {name} end

local zone = net.zone()
if zone == "" then return {name} end

local out = {}
while zone ~= "" do
out[#out + 1] = name .. "." .. zone
zone = zone:match("%.(.+)$") or ""
end
out[#out + 1] = name
return out
end


local function addressFor(target)
if type(target) == "number" then return target end
if type(target) ~= "string" then
return nil, "expected an address or a hostname"
end



local literal = ip.parse(target)
if literal then return literal end

local err
for _, candidate in ipairs(candidates(target)) do
local address
address, err = resolveName(candidate)
if address then return address end
end
return nil, err
end



function net.resolve(target)
local address, err = addressFor(target)
if not address then return nil, err end
return ip.format(address)
end



function net.send(target, name, body)
local port, err = portFor(name)
if not port then return false, err end

local address, resolveErr = addressFor(target)
if not address then return false, resolveErr end


return netcrypt.send(address, port, body, port)
end


function net.receive(name, timeout)
local port = nil
if name ~= nil then
local err
port, err = portFor(name)
if not port then return nil, err end
end

local packet = netcrypt.receive(port, timeout)
if not packet then return nil end

return {

src = ip.format(packet.src),
service = net.nameOf(packet.dport) or packet.dport,
body = packet.body,


encrypted = packet.encrypted,


from = packet.name,
}
end




function net.nameFor(target)
local address, addrErr = addressFor(target)
if not address then return nil, addrErr end

local record, err = routing.lookup(address)
if not record then return nil, err end

local voucher = netkeys.fromHex(record.voucher or "")
if not voucher then return nil, "no voucher for that address" end

local vouchedAddress, pk, name = netkeys.verifyVoucher(
voucher, netkeys.decodeChain(record.chain))
if not vouchedAddress then return nil, "voucher rejected: " .. tostring(pk) end
if vouchedAddress ~= address then
return nil, "voucher describes a different address"
end

return name ~= "" and name or nil
end

function net.isEncrypted(name)
local port = net.port(name)
return port ~= nil and netcrypt.isEncrypted(port)
end


function net.address()
local address = routing.address()
return address and ip.format(address) or nil
end



function net.hostname()
return routing.localName()
end






function net.zone()
local own = netkeys.zone()
if own ~= "" then return own end

local name = routing.localName()
if not name then return "" end
return name:match("%.(.+)$") or ""
end


function net.whoami()
return net.hostname() or net.address() or "unassigned"
end

function net.ready()
return netcrypt.isRunning() and routing.address() ~= nil
end

return net
]],
["netadmin.lua"] = [[

































local random = require("ccryptolib.random")
local netkeys = require("netkeys")
local ip = require("ip")
local band = require("band")

local args = {...}
local cmd = args[1]


if not random.isInit() then
write("seeding crypto rng... ")
random.initWithTiming()
print("done")
end

netkeys.init()

local function findDisk()
for i = 0, 5 do
local path = i == 0 and "/disk" or ("/disk%d"):format(i)
if fs.exists(path) and fs.isDir(path) then return path end
end
return nil
end




local function parseKeyFile(path)
local f = fs.open(path, "r")
if not f then return nil, "could not open " .. path end
local data = f.readAll()
f.close()

local bare = data:gsub("%s", "")
if #bare == 64 and not bare:find("%X") then
return {exchange = bare}
end

local keys = {}
for label, hex in data:gmatch("(%a+)%s+(%x+)") do
if #hex == 64 then keys[label] = hex end
end


keys.name = data:match("name%s+([%w_%-]+)")
if not keys.exchange then
return nil, path .. " has no exchange key"
end
return keys
end

local function readKeyFile(path)
local keys, err = parseKeyFile(path)
if not keys then return nil, err end
return keys.exchange
end



local function resolveKey(arg)
if type(arg) ~= "string" or arg == "" then
return nil, "expected a key or a file path"
end

local trimmed = arg:gsub("%s", "")
if #trimmed == 64 and not trimmed:find("%X") then return trimmed end

if not fs.exists(arg) then
return nil, ("no such file: %s (and it is not a 64-character key)"):format(arg)
end
if fs.isDir(arg) then return nil, arg .. " is a directory" end

return readKeyFile(arg)
end




local function usage()
local lines = {
"netadmin key",
"netadmin role <server|client|both>",
"netadmin hostname [name]    what this computer asks to be called",
"netadmin substrate <rednet|hopnet>",
"",
"addressing",
"  netadmin ip               this computer's addressing",
"  netadmin iface [<addr>/<len> [modem] | del <addr>]",
"  netadmin subnet [<cidr> [via <ip>] [band <base> <size>] | del <cidr>]",
"  netadmin address <hex|path> <ip>              (server)",
"  netadmin band [<base> <size> | del]  hop channels this subnet uses",
"",
"identity",
"  netadmin export [path]    write our public key out",
"  netadmin pin <hex|path>                       (client)",
"  netadmin allow <hex|path>                     (server)",
"  netadmin name <hex|path> <hostname>           (server)",
"  netadmin revoke <hex>",
"  netadmin chain            the delegation this computer holds",
"  netadmin list",
"",
"ports",
"  netadmin encrypt <service|port>   require encryption",
"  netadmin plain <service|port>     stop requiring it",
}
textutils.pagedPrint(table.concat(lines, "\n"))
end

if cmd == "key" then
print(netkeys.toHex(netkeys.publicKey()))

elseif cmd == "role" then
if args[2] ~= "server" and args[2] ~= "client" and args[2] ~= "both" then
printError("role must be 'server', 'client' or 'both'")
print("'both' is a sub-server: it admits its own subnet and is")
print("itself a client of its parent")
return
end
netkeys.setRole(args[2])
print("role set to " .. args[2])

elseif cmd == "hostname" then
if not args[2] then
print("hostname: " .. (netkeys.hostname() or "(unset)"))
return
end
local ok, reason = pcall(netkeys.setHostname, args[2])
if not ok then
printError(tostring(reason))
return
end
print("hostname set to " .. args[2])
print("re-export so the server sees it: netadmin export")

elseif cmd == "substrate" then
if args[2] ~= "rednet" and args[2] ~= "hopnet" then
printError("substrate must be 'rednet' or 'hopnet'")
print("current: " .. netkeys.substrate())
return
end
netkeys.setSubstrate(args[2])
print("substrate set to " .. args[2])
print("restart netstart for it to take effect")

elseif cmd == "encrypt" or cmd == "plain" then


local target = args[2] or ""
local port = tonumber(target)
if not port then
local ok, net = pcall(require, "net")
port = ok and net.port(target) or nil
end
if not port then
printError(("expected a port number or a known service, got '%s'"):format(target))
return
end
netkeys.setPortEncrypted(port, cmd == "encrypt")
if cmd == "encrypt" then
print(("port %d now requires encryption"):format(port))
print("plaintext arriving on it will be refused")
else
print(("port %d no longer requires encryption"):format(port))
end
print("restart netstart for it to take effect")

elseif cmd == "chain" then
local chain = netkeys.chain()
local network, prefix = netkeys.authority()

print("grant: " .. ip.formatCidr(network, prefix))
if #chain == 0 then
print("no certificates -- this computer is the root authority")
return
end



for i, cert in ipairs(chain) do
local fields = netkeys.parseCert(cert)
if fields then
print(("%d. %-18s %s"):format(i,
ip.formatCidr(fields.network, fields.prefix),
fields.name ~= "" and fields.name or "(unnamed)"))
print(("   signs with %s..."):format(
netkeys.toHex(fields.signer):sub(1, 16)))
end
end

elseif cmd == "ip" then


local ipnet = require("ipnet")

print("link-local: " .. ip.format(ip.linkLocal(os.getComputerID())))

local ifaces = ipnet.interfaces()
if #ifaces == 0 then
print("address:    (none -- run netstart, or declare one with 'iface')")
else
for _, iface in ipairs(ifaces) do
print(("address:    %s  %s"):format(
ip.formatCidr(iface.address, iface.prefix), iface.modem or "(all modems)"))
end
end

local gateway = ipnet.gateway()
print("gateway:    " .. (gateway and ip.format(gateway) or "(none)"))

local routes = ipnet.routes()
if #routes > 0 then
print()
print("routes:")
for _, route in ipairs(routes) do
print(("  %-18s via %s"):format(
ip.formatCidr(route.network, route.prefix), ip.format(route.via)))
end
end

print()
print("declared in /net/interfaces:")
local declared = netkeys.interfaces()
if #declared == 0 then
print("  (none -- this computer takes what the server assigns)")
end
for _, iface in ipairs(declared) do
print(("  %s %s"):format(
ip.formatCidr(iface.address, iface.prefix), iface.modem or ""))
end

elseif cmd == "iface" then
if not args[2] then
local declared = netkeys.interfaces()
if #declared == 0 then print("no interfaces declared") end
for _, iface in ipairs(declared) do
print(("%s %s"):format(
ip.formatCidr(iface.address, iface.prefix), iface.modem or ""))
end
return
end

if args[2] == "del" then
local addr = ip.parse(args[3] or "")
if not addr then
printError("expected an address to remove")
return
end
if netkeys.removeInterface(addr) then
print("removed " .. ip.format(addr))
else
printError("no interface at " .. ip.format(addr))
end
return
end

local addr, prefix = ip.parseCidr(args[2])
if not addr then
printError(tostring(prefix))
print("expected something like 10.0.1.1/24")
return
end

local modem = args[3]
if modem and peripheral.getType(modem) ~= "modem" then
printError(("'%s' is not a modem on this computer"):format(modem))
return
end

netkeys.addInterface(addr, prefix, modem)
print(("interface %s on %s"):format(
ip.formatCidr(addr, prefix), modem or "every modem"))
print("restart netstart for it to take effect")

elseif cmd == "subnet" then
if not args[2] then
for _, subnet in ipairs(netkeys.subnets()) do
print(("%-18s %s"):format(ip.formatCidr(subnet.network, subnet.prefix),
subnet.via and ("via " .. ip.format(subnet.via)) or "(ours)"))
end
return
end

if args[2] == "del" then
local network, prefix = ip.parseCidr(args[3] or "")
if not network then
printError("expected a subnet to remove, like 10.0.1.0/24")
return
end
if netkeys.removeSubnet(network, prefix) then
print("removed " .. ip.formatCidr(ip.network(network, prefix), prefix))
else
printError("no such subnet")
end
return
end

local network, prefix = ip.parseCidr(args[2])
if not network then
printError(tostring(prefix))
print("expected something like 10.0.1.0/24")
return
end



local via = nil
if args[3] == "via" then
via = ip.parse(args[4] or "")
if not via then
printError("expected an address after 'via'")
return
end
end



local delegated = nil
for i = 3, #args - 2 do
if args[i] == "band" then
local parsed, bandErr = band.parse(args[i + 1], args[i + 2])
if not parsed then
printError(tostring(bandErr))
return
end
delegated = parsed
end
end






if delegated then
local own = netkeys.band()
if not band.contains(own, delegated) then
printError(("band %s is outside our own %s"):format(
band.format(delegated), band.format(own)))
print("set this computer's band first: netadmin band <base> <size>")
return
end
end

netkeys.setSubnet(network, prefix, via, delegated)
print(("subnet %s %s"):format(
ip.formatCidr(ip.network(network, prefix), prefix),
via and ("via " .. ip.format(via)) or "served here"))
if delegated then print("  band " .. band.format(delegated)) end
print("clients pick up new routes on their next handshake")

elseif cmd == "band" then
if not args[2] then
local own = netkeys.band()
print("this computer serves: " .. band.format(own))
print(("valid range is %d..%d"):format(band.FLOOR, band.CEILING))
print("below " .. band.FLOOR .. " is fixed-channel space (computer ids)")
for _, subnet in ipairs(netkeys.subnets()) do
if subnet.band then
print(("  %-18s %s"):format(
ip.formatCidr(subnet.network, subnet.prefix),
band.format(subnet.band)))
end
end
return
end

if args[2] == "del" then
netkeys.setBand(nil)
print("band cleared -- links derive over the whole channel space again")
return
end

local parsed, bandErr = band.parse(args[2], args[3])
if not parsed then
printError(tostring(bandErr))
print("usage: netadmin band <base> <size>")
print(("  root is normally %d %d"):format(band.ROOT.base, band.ROOT.size))
return
end

netkeys.setBand(parsed)
print("band " .. band.format(parsed))
print("restart netstart for it to take effect")

elseif cmd == "address" then
local hex, keyErr = resolveKey(args[2])
if not hex then
printError(tostring(keyErr))
return
end

local addr = ip.parse(args[3] or "")
if not addr then
printError("expected an address, like 10.0.0.7")
return
end

netkeys.setAddress(hex, addr)
print(("%s... pinned to %s"):format(hex:sub(1, 16), ip.format(addr)))
print("it takes effect on that computer's next handshake")

elseif cmd == "export" then
local target = args[2] or findDisk()
if not target then
printError("no disk found -- give a path, or insert a floppy")
return
end


local path = target
if fs.exists(target) and fs.isDir(target) then
path = fs.combine(target, ("key-%d.hex"):format(os.getComputerID()))
end

local out = {"exchange " .. netkeys.toHex(netkeys.publicKey())}




if netkeys.isServer() then
out[#out + 1] = "sign " .. netkeys.toHex(netkeys.signingKey())
end





local anchor = netkeys.signerKey()
if anchor then out[#out + 1] = "root " .. netkeys.toHex(anchor) end


local hostname = netkeys.hostname()
if hostname then out[#out + 1] = "name " .. hostname end

local f = fs.open(path, "w")
if not f then
printError("could not write " .. path)
return
end
f.write(table.concat(out, "\n"))
f.close()

print("public keys written to " .. path)
for _, line in ipairs(out) do print("  " .. line:sub(1, 24) .. "...") end
print("all public data -- no secret ever leaves this computer")

elseif cmd == "pin" then
local keys, err
local arg = args[2] or ""
local trimmed = arg:gsub("%s", "")

if #trimmed == 64 and not trimmed:find("%X") then
keys = {exchange = trimmed}
elseif fs.exists(arg) and not fs.isDir(arg) then
keys, err = parseKeyFile(arg)
else
err = ("no such file: %s (and it is not a 64-character key)"):format(arg)
end

if not keys then
printError(tostring(err))
return
end

netkeys.setServerKey(keys.exchange)
print("exchange key pinned: " .. keys.exchange:sub(1, 16) .. "...")






local anchor = keys.root or keys.sign
if anchor then
netkeys.setSignerKey(anchor)
print("trust anchor pinned: " .. anchor:sub(1, 16) .. "...")
if keys.root and keys.sign and keys.root ~= keys.sign then
print("(that server is itself a delegate of this anchor)")
end
else
printError("no signer key in that file -- peer sessions will not work")
print("re-export from the server once its role is set")
end

print("a server without the matching private keys can no longer")
print("complete a handshake with this computer")

elseif cmd == "allow" then
local target = args[2]





local function admit(hex, proposed, source)
netkeys.allow(hex)
print(("allowed %s...%s"):format(hex:sub(1, 16), source and "  (" .. source .. ")" or ""))

if not proposed then return end

local assigned, reason = netkeys.assignName(hex, proposed)
if not assigned then
printError("  " .. tostring(reason))
print("  admitted anyway; assign a name with 'netadmin name'")
elseif assigned ~= proposed then


print(("  named '%s'  (asked for '%s')"):format(assigned, proposed))
else
print(("  named '%s'"):format(assigned))
end
end


if type(target) == "string" and fs.exists(target) and fs.isDir(target) then
local count = 0
for _, file in ipairs(fs.list(target)) do
if file:match("%.hex$") then
local keys, err = parseKeyFile(fs.combine(target, file))
if keys then
admit(keys.exchange, keys.name, file)
count = count + 1
else
printError(tostring(err))
end
end
end
if count == 0 then printError("no .hex key files in " .. target) end
return
end


local override = args[3]
local proposed = override

if not override and fs.exists(target or "") and not fs.isDir(target) then
local keys = parseKeyFile(target)
proposed = keys and keys.name or nil
end

local hex, err = resolveKey(target)
if not hex then
printError(tostring(err))
return
end
admit(hex, proposed)

elseif cmd == "name" then
local hex, err = resolveKey(args[2])
if not hex then
printError(tostring(err))
return
end
local ok, reason = pcall(netkeys.setName, hex, args[3] or "")
if not ok then
printError(tostring(reason))
return
end
print(("%s... is now '%s'"):format(hex:sub(1, 16), args[3]))
print("restart the server for it to appear in new vouchers")

elseif cmd == "revoke" then
local hex, err = resolveKey(args[2])
if not hex then
printError(tostring(err))
return
end
netkeys.revoke(hex)
print("revoked " .. hex:sub(1, 16) .. "...")

elseif cmd == "list" then
print("role:    " .. tostring(netkeys.role()))
print("subst:   " .. netkeys.substrate())

local ports = {}
for port in pairs(netkeys.encryptedPorts()) do ports[#ports + 1] = port end
table.sort(ports)
print("crypt:   " .. (#ports > 0 and table.concat(ports, " ") or "no ports"))
print("our key: " .. netkeys.toHex(netkeys.publicKey()))

if netkeys.isServer() then
print("signer:  " .. netkeys.toHex(netkeys.signingKey()))

local network, prefix = netkeys.authority()
local chain = netkeys.chain()
print(("grant:   %s%s"):format(ip.formatCidr(network, prefix),
#chain == 0 and "   (root -- nothing above us)" or ""))
end

local pinned = netkeys.serverKey()
print("pinned:  " .. (pinned and netkeys.toHex(pinned) or "none"))

local signer = netkeys.signerKey()
print("verify:  " .. (signer and netkeys.toHex(signer) or "none"))

print()
print("allowlist:")
local any = false
for hex in pairs(netkeys.allowed()) do
print("  " .. hex)
any = true
end
if not any then print("  (empty)") end

print()
print("subnets:")
for _, subnet in ipairs(netkeys.subnets()) do
print(("  %-18s %s"):format(ip.formatCidr(subnet.network, subnet.prefix),
subnet.via and ("via " .. ip.format(subnet.via)) or "(ours)"))
end

print()
print("addresses:")
any = false
local names = netkeys.names()
for hex, addr in pairs(netkeys.addresses()) do
print(("  %-15s %-16s %s..."):format(
ip.format(addr), names[hex] or "(unnamed)", hex:sub(1, 16)))
any = true
end
if not any then print("  (none assigned)") end

else
usage()
end
]],
["netcrypt.lua"] = [[




















local routing = require("routing")
local peersession = require("peersession")

local netcrypt = {}

local SEND_TIMEOUT = 30

local state = _G.__netcrypt
if not state then
state = {running = false, debug = false}
_G.__netcrypt = state
end

state.encrypted = state.encrypted or {}

local pendingSends = {}
local nextRequest = 0

local function log(...)
if state.debug then os.queueEvent("netcrypt_debug", ...) end
end

function netcrypt.setDebug(enabled)
state.debug = enabled
end



function netcrypt.setEncrypted(port, enabled)
state.encrypted[port] = enabled and true or nil
end





function netcrypt.setPolicy(ports)
local replacement = {}
for port in pairs(ports) do replacement[port] = true end
state.encrypted = replacement
end

function netcrypt.isEncrypted(port)
return state.encrypted[port] == true
end

function netcrypt.encryptedPorts()
return state.encrypted
end



local function toHex(s)
return (s:gsub(".", function(c) return ("%02x"):format(c:byte()) end))
end

local function fromHex(h)
if type(h) ~= "string" or #h % 2 ~= 0 or h:find("%X") then return nil end
return (h:gsub("%x%x", function(b) return string.char(tonumber(b, 16)) end))
end



local function deliver(request)
local port = request.dstPort

if not netcrypt.isEncrypted(port) then
return routing.send(request.dst, port,
{enc = false, d = request.body}, request.srcPort)
end

local sealed, counter = peersession.seal(request.dst, textutils.serialize(request.body))
if not sealed then return false, counter end

log("sealed", request.dst, port, counter)
return routing.send(request.dst, port,
{enc = true, n = counter, d = toHex(sealed)}, request.srcPort)
end

local function finish(request, ok, err)
os.queueEvent("net_send_result", request.id, ok and true or false, err)
end




function netcrypt.send(dstAddress, dstPort, body, srcPort)
nextRequest = nextRequest + 1
local id = ("%d:%d"):format(os.getComputerID(), nextRequest)

os.queueEvent("net_send", id, dstAddress, dstPort, body, srcPort)

local timer = os.startTimer(SEND_TIMEOUT)
while true do
local event, p1, p2, p3 = os.pullEvent()
if event == "net_send_result" and p1 == id then
if p2 then return true end
return false, p3
elseif event == "timer" and p1 == timer then
return false, "timed out waiting for the crypto daemon"
end
end
end



function netcrypt.receive(port, timeout)
local timer = nil
local filter = nil
if timeout then
timer = os.startTimer(timeout)
else
filter = "net_data"
end

while true do
local event, p1, p2, p3, p4, p5, p6 = os.pullEvent(filter)
if event == "net_data" then
local src, sport, dport, body, encrypted, name = p1, p2, p3, p4, p5, p6
if port == nil or dport == port then
if timer then os.cancelTimer(timer) end
return {
src = src, sport = sport, dport = dport,
body = body, encrypted = encrypted, name = name,
}
end
elseif event == "timer" and p1 == timer then
return nil
end
end
end



local function handleInbound(packet)
local env = packet.body
if type(env) ~= "table" then return end

local port = packet.dport

if env.enc ~= true then


if netcrypt.isEncrypted(port) then
log("downgrade", packet.src, port)
return
end
os.queueEvent("net_data", packet.src, packet.sport, port, env.d, false)
return
end

local ciphertext = fromHex(env.d)
if not ciphertext then
log("malformed", packet.src, port)
return
end

local plaintext, err = peersession.open(packet.src, env.n, ciphertext)
if not plaintext then


log("rejected", packet.src, port, tostring(err))
return
end

local ok, body = pcall(textutils.unserialize, plaintext)
if not ok then
log("unserialize", packet.src, port)
return
end




os.queueEvent("net_data", packet.src, packet.sport, port, body, true,
peersession.nameOf(packet.src))
end

local function attempt(request)
local ok, err = deliver(request)
if ok then
finish(request, true)
return true
end
return false, err
end






local function inboundLoop()
while true do
local _, src, sport, dport, body = os.pullEvent("net_message")
handleInbound({src = src, sport = sport, dport = dport, body = body})
end
end

local function outboundLoop()
while true do
local event, p1, p2, p3, p4, p5 = os.pullEvent()

if event == "net_send" then
local request = {
id = p1, dst = p2, dstPort = p3, body = p4, srcPort = p5,
}

if not netcrypt.isEncrypted(request.dstPort)
or peersession.get(request.dst) then
local ok, err = attempt(request)
if not ok then finish(request, false, err) end
else



log("awaiting session", request.dst, request.dstPort)
pendingSends[request.dst] = pendingSends[request.dst] or {}
table.insert(pendingSends[request.dst], request)
os.queueEvent("peer_connect", request.dst)
end

elseif event == "peer_session" then
local address, established, detail = p1, p2, p3
local waiting = pendingSends[address]
pendingSends[address] = nil

for _, request in ipairs(waiting or {}) do
if established then
local ok, err = attempt(request)
if not ok then finish(request, false, err) end
else
finish(request, false, "no session: " .. tostring(detail))
end
end
end
end
end

function netcrypt.runtime()
if state.running then
error("netcrypt: daemon already running", 0)
end
state.running = true

local ok, err = pcall(parallel.waitForAny, inboundLoop, outboundLoop)

state.running = false
if not ok then error(err, 0) end
end

function netcrypt.isRunning()
return state.running == true
end

function netcrypt.shutdown()
state.running = false
pendingSends = {}
end

return netcrypt
