["routing.lua"] = [[














local acknet = require("acknet")

local routing = {}

local PROTOCOL = "acknet_route"

local RESERVED_PORT_MAX = 99
local PORT_DIRECTORY = 1

local RESOLVE_TIMEOUT = 3
local CACHE_TTL = 60



local REFERRAL_MAX = 4

local state = _G.__routing
if not state then
state = {running = false, debug = false}
_G.__routing = state
end




local resolver = nil
state.ports = state.ports or {}
state.cache = state.cache or {}

local function log(...)
if state.debug then os.queueEvent("routing_debug", ...) end
end

function routing.setDebug(enabled)
state.debug = enabled
end

routing.PORT_DIRECTORY = PORT_DIRECTORY




function routing.serverAddress()
return state.parentAddress
end



function routing.setLocal(address)
state.address = address
end








function routing.setParent(address)
state.parentAddress = address
end

function routing.parent()
return state.parentAddress
end

function routing.address()
return state.address
end




function routing.setName(name)
state.name = name
end

function routing.localName()
return state.name
end







function routing.bind(port, system)
if type(port) ~= "number" or port < 1 then
return false, "port must be a positive number"
end
if port <= RESERVED_PORT_MAX and not system then
return false, ("port %d is reserved for system services"):format(port)
end
if state.ports[port] then
return false, ("port %d is already bound"):format(port)
end
state.ports[port] = true
return true
end

function routing.unbind(port)
state.ports[port] = nil
end

function routing.bound()
return state.ports
end






local function cacheGet(address)
local hit = state.cache[address]
if hit and os.epoch("utc") < hit.expires then return hit.record end
return nil
end

local function cachePut(address, record)
state.cache[address] = {
record = record,
expires = os.epoch("utc") + CACHE_TTL * 1000,
}
end

local function envelope(dst, dport, body, sport)
return {
src = state.address,
dst = dst,
sport = sport,
dport = dport,
body = body,
}
end


local function askOnce(query, directory)
local key = query.address or query.name

acknet.send(directory,
envelope(directory, PORT_DIRECTORY,
{op = "resolve", address = query.address, name = query.name},
PORT_DIRECTORY),
PROTOCOL)

local deadline = os.epoch("utc") + RESOLVE_TIMEOUT * 1000
while true do
local remaining = (deadline - os.epoch("utc")) / 1000
if remaining <= 0 then return nil, "directory timed out" end

local packet = acknet.receive(PROTOCOL, remaining)
if packet and type(packet.body) == "table"
and type(packet.body.body) == "table" then
local reply = packet.body.body
if reply.key == key then return reply end
end
end
end









local function askDirectory(query, directory)
if not directory then return nil, "no directory known" end

for _ = 1, REFERRAL_MAX do
local reply, err = askOnce(query, directory)
if not reply then return nil, err end

if reply.op == "resolve_ok" and type(reply.record) == "table" then
return reply.record

elseif reply.op == "resolve_refer" and type(reply.to) == "number" then
directory = reply.to

else
return nil, reply.reason or "not found"
end
end

return nil, "too many referrals"
end





function routing.lookup(address)
local hit = cacheGet(address)
if hit then return hit end





local directory = state.parentAddress

if resolver then
local record, referral = resolver({address = address})
if record then
cachePut(address, record)
return record
end
if referral then directory = referral end

elseif state.directory then



directory = state.address
end

if not directory then
if address == state.address then return {address = address} end
return nil, "not online"
end

local record, err = askDirectory({address = address}, directory)
if not record then return nil, err end

cachePut(address, record)
return record
end





function routing.lookupName(name)
if type(name) ~= "string" then return nil, "name must be a string" end

local hit = cacheGet(name)
if hit then return hit end

local directory = state.parentAddress

if resolver then
local record, referral = resolver({name = name})
if record then
cachePut(name, record)
return record
end




if referral then directory = referral end

elseif state.directory then

directory = state.address
end

if not directory then return nil, "no such name" end

local record, err = askDirectory({name = name}, directory)
if not record then return nil, err end

cachePut(name, record)
return record
end

function routing.forget(address)
state.cache[address] = nil
end



function routing.send(dstAddress, dstPort, body, srcPort)
if not state.address then
return false, "no local address -- has the handshake completed?"
end



log("send", dstAddress, dstPort)
acknet.send(dstAddress, envelope(dstAddress, dstPort, body, srcPort), PROTOCOL)
return true
end


function routing.receive(port, timeout)
local timer = nil
local filter = nil
if timeout then
timer = os.startTimer(timeout)
else
filter = "net_message"
end

while true do
local event, p1, p2, p3, p4 = os.pullEvent(filter)
if event == "net_message" then
local src, sport, dport, body = p1, p2, p3, p4
if port == nil or dport == port then
if timer then os.cancelTimer(timer) end
return {src = src, sport = sport, dport = dport, body = body}
end
elseif event == "timer" and p1 == timer then
return nil
end
end
end









function routing.setDirectory(fn)
resolver = fn
state.directory = fn ~= nil
end

local function answerDirectory(sender, env)
if not resolver then return end
local req = env.body
if type(req) ~= "table" or req.op ~= "resolve" then return end

local key = req.address or req.name
local record, referral = resolver(req)
local reply

if record then
reply = {op = "resolve_ok", key = key, record = record}
log("directory", tostring(key), record.address)

else




local to = referral or state.parentAddress
if to then
reply = {op = "resolve_refer", key = key, to = to}
log("directory", tostring(key), "refer")
else
reply = {op = "resolve_err", key = key, reason = "not online"}
log("directory", tostring(key), "miss")
end
end

acknet.send(sender, envelope(env.src, env.sport, reply, PORT_DIRECTORY), PROTOCOL)
end

local function daemonLoop()
while true do
local packet = acknet.receive(PROTOCOL)
local env = packet.body

if type(env) == "table" and type(env.dport) == "number" then
if env.dport == PORT_DIRECTORY and resolver then
answerDirectory(packet.sender_id, env)






elseif state.ports[env.dport] then
os.queueEvent("net_message", env.src, env.sport, env.dport, env.body)

else
log("unbound", env.dport, env.src)
end
end
end
end

function routing.runtime()
if state.running then
error("routing: daemon already running", 0)
end
state.running = true

local ok, err = pcall(daemonLoop)

state.running = false
if not ok then error(err, 0) end
end

function routing.isRunning()
return state.running == true
end



function routing.shutdown()
state.running = false
end

return routing
]],
["services"] = "# Service registry: what name maps to which port.\013\010#\013\010# Applications name a service and never handle a port number. This file is the\013\010# translation, and because sync pushes one tree to every computer it is\013\010# effectively global by construction -- there is nothing to keep in step.\013\010#\013\010# Ports below 100 are reserved for OS services and cannot be bound by an\013\010# application, so user services start at 100.\013\010#\013\010#   name        port\013\010\013\010chat            100\013\010echo            101\013\010\013\010# Manufacturer node (spec/manufacturer-controller.md, spec/node-software.md).\013\010# Both are marked encrypted with `netadmin encrypt`.\013\010mfg-control     110\013\010mfg-report      111\013\010\013\010# 112 and 113 are FREE. They held `mfg-enroll` and `icmp-echo`, and neither was ever\013\010# resolved by name:\013\010#\013\010#   enrollment runs before the turtle has been admitted, so it has no session and no\013\010#   route -- it rides acknet with its own protocol name and its own MAC\013\010#   (scada-design.md R9.11a), never a routed service port;\013\010#   icmp is a layer of its own and dispatches on a message field, not a port.\013\010#\013\010# Both were registered on the assumption they would be needed and never were. Left\013\010# free deliberately rather than backfilled, so the next service takes a number nobody\013\010# has old policy for -- a stale `/net/ports` entry marking 112 encrypted would refuse\013\010# plaintext on whatever landed there next.\013\010\013\010# Supervisory and contract traffic. TWO services rather than one, deliberately\013\010# (mfg/controller/orders.lua): they answer to different actors.\013\010#\013\010#   mfg-scada   a local OPERATOR at an HMI -- supervisory actions on our own plant\013\010#   mfg-order   a STATION across the boundary -- the contract between two ledgers\013\010#\013\010# Collapsing them would give a station an operator's reach into the queue. Both\013\010# should be encrypted on BOTH ends (`netadmin encrypt mfg-scada`); a port marked\013\010# encrypted refuses plaintext, and one end marking it alone is how an HMI ends up\013\010# showing NO CONTROLLER with nothing obviously wrong.\013\010mfg-scada       114\013\010mfg-order       115\013\010\013\010# Alarms are PUSHED to an HMI rather than waiting for its poll (H3.1, H3.5), so an\013\010# HMI binds this and keeps it bound -- a push that finds nobody listening is lost.\013\010#\013\010# NOTE: nothing sends to it yet. The controller raises and stores alarms, and an HMI\013\010# picks them up on its next `mfg-scada` poll, so alarms work with up to one poll\013\010# interval of latency. Registering the name is what lets the HMI bind it at all; the\013\010# sender is still to be written.\013\010mfg-alarm       116\013\010",
["startup.lua"] = [[



















local L = {}

L.MAX_TRIES = 3
L.JOURNAL_VERSION = 1

local function P(root, path) return fs.combine(root or "/", path) end






function L.readTable(path)
if not fs.exists(path) then
local temp = path .. ".new"
if not fs.exists(temp) then return nil end
fs.move(temp, path)
end
local handle = fs.open(path, "r")
if not handle then return nil end
local text = handle.readAll()
handle.close()
local ok, value = pcall(textutils.unserialize, text)
if ok then return value end
return nil
end

function L.writeTable(path, value)
local dir = fs.getDir(path)
if dir ~= "" and not fs.exists(dir) then fs.makeDir(dir) end
local temp = path .. ".new"
if fs.exists(temp) then fs.delete(temp) end
local handle = fs.open(temp, "w")
handle.write(textutils.serialize(value))
handle.close()
if fs.exists(path) then fs.delete(path) end
fs.move(temp, path)
end

function L.record(root) return L.readTable(P(root, "boot/record")) end
function L.writeRecord(root, record) L.writeTable(P(root, "boot/record"), record) end



function L.manifestPaths(path)
local set = {}
if not fs.exists(path) then return nil end
local handle = fs.open(path, "r")
if not handle then return nil end
for line in handle.readAll():gmatch("[^\r\n]+") do
local file = line:match("^file%s+(%S+)")
if file then set[file] = true end
end
handle.close()
return set
end

local function listFiles(dir, prefix, out)
out = out or {}
if not fs.isDir(dir) then return out end
for _, name in ipairs(fs.list(dir)) do
local full = fs.combine(dir, name)
local rel = prefix and (prefix .. "/" .. name) or name
if fs.isDir(full) then listFiles(full, rel, out) else out[#out + 1] = rel end
end
table.sort(out)
return out
end
L.listFiles = listFiles



















local function journalPath(root) return P(root, "boot/journal") end
local function progressPath(root) return P(root, "boot/journal.at") end

function L.writeJournal(root, steps, kind)
L.writeTable(journalPath(root), {v = L.JOURNAL_VERSION, kind = kind, steps = steps})
if fs.exists(progressPath(root)) then fs.delete(progressPath(root)) end
end

function L.hasJournal(root)
return fs.exists(journalPath(root)) or fs.exists(journalPath(root) .. ".new")
end

local function doStep(root, step, notes)
local op = step[1]
if op == "move" then
local from, to = P(root, step[2]), P(root, step[3])
if fs.exists(from) then
local dir = fs.getDir(to)
if dir ~= "" and not fs.exists(dir) then fs.makeDir(dir) end
if fs.exists(to) then fs.delete(to) end
fs.move(from, to)
elseif not fs.exists(to) then
notes[#notes + 1] = "nothing to move: " .. step[2]
end
elseif op == "delete" then
local path = P(root, step[2])
if fs.exists(path) then fs.delete(path) end
else
error("journal step this stage 0 does not understand: " .. tostring(op), 0)
end
end



function L.replay(root, limit)
local journal = L.readTable(journalPath(root))
if not journal then return true, {} end
if journal.v ~= L.JOURNAL_VERSION then
error(("journal version %s; this stage 0 understands %d"):format(
tostring(journal.v), L.JOURNAL_VERSION), 0)
end
local at = L.readTable(progressPath(root)) or 0
local notes, done = {}, 0
for i = at + 1, #journal.steps do
if limit and done >= limit then return false, notes end
doStep(root, journal.steps[i], notes)
L.writeTable(progressPath(root), i)
done = done + 1
end
fs.delete(journalPath(root))
if fs.exists(progressPath(root)) then fs.delete(progressPath(root)) end
return true, notes
end




function L.canRollBack(root)
return fs.exists(P(root, "boot/prev/record"))
end





function L.rollbackSteps(root, why)
local prevRecord = L.readTable(P(root, "boot/prev/record"))
if not prevRecord then return nil, "no previous generation to roll back to" end
local current = L.record(root) or {}
local steps = {}

local active = L.manifestPaths(P(root, "boot/firmware")) or {}
local previous = L.manifestPaths(P(root, "boot/prev/firmware"))
if previous then
local added = {}
for path in pairs(active) do
if not previous[path] then added[#added + 1] = path end
end
table.sort(added)
for _, path in ipairs(added) do steps[#steps + 1] = {"delete", path} end
end

for _, rel in ipairs(listFiles(P(root, "boot/prev/files"))) do
steps[#steps + 1] = {"move", "boot/prev/files/" .. rel, rel}
end

if fs.isDir(P(root, "boot/prev/state")) then
for _, rel in ipairs(listFiles(P(root, "mfg/state"))) do
if rel ~= "actions" and rel ~= "actions.new" then
steps[#steps + 1] = {"delete", "mfg/state/" .. rel}
end
end
for _, rel in ipairs(listFiles(P(root, "boot/prev/state"))) do
steps[#steps + 1] = {"move", "boot/prev/state/" .. rel, "mfg/state/" .. rel}
end
end

for _, name in ipairs({"firmware", "config"}) do
if fs.exists(P(root, "boot/prev/" .. name)) then
steps[#steps + 1] = {"move", "boot/prev/" .. name, "boot/" .. name}
end
end

prevRecord.state = "committed"
prevRecord.tries = 0
prevRecord.rolled_back_from = current.active
prevRecord.rolled_back_because = why
L.writeTable(P(root, "boot/rollback.record"), prevRecord)
steps[#steps + 1] = {"move", "boot/rollback.record", "boot/record"}
steps[#steps + 1] = {"delete", "boot/prev"}
return steps
end

function L.rollback(root, why)
local steps, bad = L.rollbackSteps(root, why)
if not steps then return nil, bad end
L.writeJournal(root, steps, "rollback")
return L.replay(root)
end



local function lastError(root, text)
L.writeTable(P(root, "boot/last_error"), {at = os.epoch("utc"), error = text})
end






function L.boot(root, hooks)
hooks = hooks or {}
local say = hooks.say or print
local warn = hooks.warn or printError
local reboot = hooks.reboot or function() sleep(3) os.reboot() end
local run = hooks.run or function()
return require("mfg.boot").run(root, {shell = shell})
end

if L.hasJournal(root) then
local ok, finished = pcall(L.replay, root)
if not ok then
lastError(root, "journal: " .. tostring(finished))
warn("could not finish the boot journal: " .. tostring(finished))
return "recovery"
end
end

local record = L.record(root)
if not record then
warn("no boot record: this computer is not managed by the bootloader")
return "unmanaged"
end

if record.state == "trial" then
record.tries = (record.tries or 0) + 1
L.writeRecord(root, record)
if record.tries > L.MAX_TRIES then



local prior = L.readTable(P(root, "boot/last_error"))
local why = ("boot set failed %d trial boots"):format(record.tries - 1)
local cause = type(prior) == "table" and type(prior.error) == "string" and prior.error or nil


if cause and cause:find("trial boots", 1, true) then cause = cause:match("%(last: (.*)%)") end
if cause then why = why .. " (last: " .. cause .. ")" end
if not L.canRollBack(root) then
lastError(root, why .. ", and there is nothing to roll back to")
warn(why .. ", and there is nothing to roll back to -- recovery")
return "recovery"
end
warn(why .. " -- rolling back to the previous generation")
local ok, err = pcall(L.rollback, root, why)
if not ok then
lastError(root, "rollback: " .. tostring(err))
warn("rollback failed: " .. tostring(err))
return "recovery"
end
reboot()
return "rolledback"
end
say(("boot set on trial, attempt %d of %d"):format(record.tries, L.MAX_TRIES))
end

local ok, err = pcall(run, root)





if not ok and tostring(err):find("Terminated$") then
say("stopped by operator -- run /startup to boot again")
return "stopped"
end

local why = ok and "the boot stages returned; the node stopped" or tostring(err)
lastError(root, why)


record = L.record(root) or record
if record.state == "trial" then
warn("boot failed on trial: " .. why)
reboot()
return "reboot"
end
warn("boot failed on a COMMITTED boot set -- recovery: " .. why)
warn("see /boot/last_error. The previous generation is kept in /boot/prev.")
return "recovery"
end

if select(1, ...) == "--lib" then return L end

if not package.path:find("^/%?") then
package.path = "/?.lua;/?/init.lua;" .. package.path
end
L.boot("/")
]],
}

local ROLE, SOURCE, FILES, BYTES = "controller", "mfg-6fa9849 netstack-a7bc070", 195, 819620

print(("mfg installer: %s, %d files, %d bytes"):format(ROLE, FILES, BYTES))
print(SOURCE)

-- Space: what the files need, less what the copies they replace already hold.
local need = 0
for path, data in pairs(files) do
    need = need + #data
    if fs.exists(path) and not fs.isDir(path) then need = need - fs.getSize(path) end
end
local free = fs.getFreeSpace("/")
if need > free then
    printError(("not enough space: need %d more bytes, %d free"):format(need, free))
    return
end

-- /boot is replaced whole (a stale journal would replay over this install), except
-- the firmware anchor mint pinned.
local signer
if fs.exists("/boot/signer") then
    local h = fs.open("/boot/signer", "rb"); signer = h.readAll(); h.close()
end
fs.delete("/boot")

local paths = {}
for path in pairs(files) do paths[#paths + 1] = path end
table.sort(paths)

local bad = 0
for i, path in ipairs(paths) do
    local dir = fs.getDir(path)
    if dir ~= "" then fs.makeDir(dir) end
    local h, err = fs.open(path, "wb")
    if not h then error(("cannot write %s: %s"):format(path, err)) end
    h.write(files[path])
    h.close()
    if fs.getSize(path) ~= #files[path] then
        printError("size mismatch: " .. path)
        bad = bad + 1
    end
    if i % 20 == 0 then
        print(("  %d/%d"):format(i, #paths))
        -- Yield now and then: the watchdog is uncatchable. An event, not sleep(0),
        -- which would cost a tick each time in world.
        os.queueEvent("mfg_install"); os.pullEvent("mfg_install")
    end
end

if signer then
    local h = fs.open("/boot/signer", "wb"); h.write(signer); h.close()
end
if fs.exists("/net/hostname") then
    local h = fs.open("/net/hostname", "r"); local name = h.readAll(); h.close()
    name = name:gsub("%s", "")
    if name ~= "" then
        h = fs.open("/boot/intent", "a"); h.write("node " .. name .. "\n"); h.close()
    end
end

if bad > 0 then
    printError(("%d files did not write correctly; do not reboot"):format(bad))
    return
end
print(("installed %d files. Reboot to start."):format(#paths))
